import { normalizeLocationFix } from './provider.js';

/** @returns {import('./provider.js').LocationProvider} */
export function createWebLocationProvider({ navigator = globalThis.navigator } = {}) {
  return {
    sourceType: 'web-geolocation',
    watch(onFix, onError) {
      const geolocation = navigator?.geolocation;
      if (!geolocation?.watchPosition) {
        onError({ code: 'unsupported' });
        return () => {};
      }
      let active = true,
        watchId;
      const stop = () => {
        if (!active) return;
        active = false;
        geolocation.clearWatch(watchId);
      };
      watchId = geolocation.watchPosition(
        (position) => {
          if (!active) return;
          const coords = position?.coords;
          const fix = normalizeLocationFix({
            lat: coords?.latitude,
            lon: coords?.longitude,
            elevation: coords?.altitude,
            time: position?.timestamp,
            accuracy: coords?.accuracy,
            altitudeAccuracy: coords?.altitudeAccuracy,
          });
          if (fix) onFix(fix);
        },
        (error) => {
          if (active)
            onError({
              code:
                error?.code === 1
                  ? 'permission-denied'
                  : error?.code === 2
                    ? 'position-unavailable'
                    : 'timeout',
            });
        },
        { enableHighAccuracy: true, maximumAge: 5000, timeout: 20000 },
      );
      return stop;
    },
  };
}
