import { smartPanel } from './smart-view.js';
import { button, esc } from '../../ui/html.js';
const duration = (seconds) =>
  Number.isFinite(seconds) ? `${Math.ceil(seconds / 60)} 分` : '不可用';

export function reroutePanel(state) {
  const data = state.itinerary.reroute;
  const options = (items, field) =>
    items
      .map(
        (item) =>
          `<option value="${esc(item.id)}" ${String(item.id) === state.itinerary.rerouteForm?.[field] ? 'selected' : ''}>${esc(item.name)}</option>`,
      )
      .join('');
  const preview = data?.preview;
  return `<details id="reroute-panel" class="panel panel-body stack"><summary data-action="smart-reroute-open">一鍵智慧改道／折返</summary>
    ${smartPanel(state)}
    <details id="reroute-advanced"><summary>進階：手動選路線與方向</summary>
    <p class="small muted">GPS 持續紀錄。從可信定位選擇 GPX 路段及方向，再選目的地；岔路依既有 GPX 幾何規劃。可選登山口直接折返，或選山頂再返回。請核對完整站序。</p>
    <label for="reroute-source">參考 GPX</label><select id="reroute-source">${options(
      state.library.filter((f) => f.kind !== 'recording').map((f) => ({ id: f.id, name: f.name })),
      'reroute-source',
    )}</select>
    ${button('載入改道選項', 'reroute-load')}
    ${
      data?.starts?.length
        ? `<label for="reroute-start">目前所在路段與行走方向（重複路段須核對）</label><select id="reroute-start">${options(data.starts, 'reroute-start')}</select>
    <label for="reroute-destination">新目的地／折返終點</label><select id="reroute-destination">${options(data.destinations, 'reroute-destination')}</select>
    <label for="reroute-return">抵達後返回（選填）</label><select id="reroute-return"><option value="">抵達目的地結束</option>${options(data.destinations, 'reroute-return')}</select>
    ${button('預覽剩餘路線', 'reroute-preview')}`
        : ''
    }
    ${
      preview
        ? `<section aria-label="改道預覽"><h3>${esc(preview.file.name)}</h3><p>GPX 已知片段 ${preview.file.stats.km.toFixed(2)} km · 爬升／下降 ${preview.file.points.every((p) => Number.isFinite(p.elevation)) ? `${Math.round(preview.file.stats.up)}／${Math.round(preview.file.stats.down)} m` : '未知'}</p>
    <p>上河基準：${duration(preview.plan.timeModel.totalSeconds)}。新路線無有效即時倍率時，明確回退設定倍率 ${(state.gps.itinerary?.factor ?? state.itinerary.factor).toFixed(2)}。</p>
    <ol>${preview.plan.rows
      .slice(1)
      .map((r) => `<li>${esc(r.station.name)}${r.reason ? `：${esc(r.reason)}` : ''}</li>`)
      .join('')}</ol>
    ${preview.warnings.map((w) => `<p class="error-message">${esc(w)}</p>`).join('')}
    <p class="small muted">分段接點不畫連線；未知時間保留不可用。原始 GPX、原計畫、到站及改道前倍率將保留。</p>${button('套用改道，繼續紀錄', 'reroute-apply', 'primary')}</section>`
        : ''
    }
    </details>
    ${data?.applied ? '<p role="status">改道已套用，GPS 持續紀錄；無有效新倍率時使用設定倍率。</p>' : ''}
    ${data?.error ? `<p class="error-message" role="status">${esc(data.error)}</p>` : ''}
    ${state.gps.navigation ? `<p class="small muted">已改道 ${state.gps.navigation.revisions.length} 次；原計畫：${esc(state.gps.navigation.original.file.name)}。原始與每版站序、到站及倍率保存在本次紀錄。</p><details id="reroute-history"><summary>查看原計畫與歷次改道</summary>${state.gps.navigation.revisions.map((revision, i) => `<section><h3>版本 ${i} · ${esc(revision.file.name)}</h3><p>${new Date(revision.endedAt).toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' })} 前 · 已確認 ${Object.keys(revision.journey?.arrivals ?? {}).length} 次到站</p><p>即時倍率：${revision.live?.total?.factor?.toFixed(2) ?? '不可用'}（封存，供查閱）</p><ol>${(revision.plan?.rows ?? revision.file.reroutePlan?.rows ?? []).map((row) => `<li>${esc(row.station.name)} · ${Number.isFinite(revision.journey?.arrivals?.[row.index]) ? new Date(revision.journey.arrivals[row.index]).toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' }) : '未確認到站'}</li>`).join('')}</ol></section>`).join('')}</details>` : ''}
  </details>`;
}
