import { distanceM } from '../../../../packages/route-stations/index.js';
import { normalizeLocationFix } from '../location/provider.js';
import { routeMatcherFor } from './matching.js';
import { shangheTimeAt } from './time-interpolation.js';

export const LIVE_FACTOR_VERSION = 4;
export const LIVE_FACTOR_DEFAULTS = Object.freeze({
  windowMs: 30 * 60 * 1000,
  endpointToleranceMs: 30000,
  maxAgeMs: 60000,
  futureToleranceMs: 5000,
  maxAccuracyM: 50,
  maxOffsetM: 50,
  mergeWithinM: 25,
  maxSpeedMps: 12,
  maxObservationGapMs: 300000,
  startDelayMs: 60000,
  startToleranceM: 50,
  confirmedStartToleranceM: 75,
  confirmationAgeMs: 120000,
  progressToleranceM: 25,
  minBaselineSeconds: 60,
  minProgressM: 25,
  maxLimitedAccuracyM: 80,
  routeErrorAllowanceM: 10,
  maxAdaptiveOffsetM: 80,
  stabilityMs: 5000,
  stabilityWindowMs: 30000,
  retainLastValidMs: 120000,
  startAlignmentMs: 5000,
});
const missing = (reason) => ({
  factor: null,
  reason,
  actualSeconds: null,
  baselineSeconds: null,
  source: null,
});

/** A recording-scoped engine. Wall time includes rests/pauses; never changes ETA or the model.
 * Queries use actual GPS endpoint times, not arrival events or a synthesized position at now.
 * Route edges are prepared once. Unknown prefixes are never silently rebased to zero.
 */
export function createLiveShangheFactor({
  file,
  timeModel,
  startedAt,
  departureAvailable = true,
  startStation = null,
  options = {},
}) {
  const config = { ...LIVE_FACTOR_DEFAULTS, ...options };
  for (const [name, value] of Object.entries(config)) {
    if (!Object.hasOwn(LIVE_FACTOR_DEFAULTS, name))
      throw new TypeError('Unknown live factor option: ' + name);
    if (!Number.isFinite(value) || value <= 0) throw new RangeError(name + ' must be positive');
  }
  if (
    config.maxLimitedAccuracyM < config.maxAccuracyM ||
    config.maxAdaptiveOffsetM < config.maxOffsetM ||
    config.stabilityWindowMs < config.stabilityMs
  )
    throw new RangeError('Inconsistent live GPS quality limits');
  const matcher = file?.segments?.length ? routeMatcherFor(file) : null;
  let first = departureAvailable,
    origin = null,
    originReason = departureAvailable ? 'missing-start-fix' : 'session-history-unavailable',
    continuityReason = null;
  let last = null,
    lastTime = -Infinity,
    peakM = -Infinity,
    history = [],
    current = null;
  let failure = 'missing-gps-fix';
  let departureCandidate = null,
    peakSample = null,
    confirmation = null,
    restoredBoundary = null,
    restoration = null;
  let restorationCount = 0;
  let clock = startedAt,
    transientFailure = false,
    needsStability = false,
    stability = null,
    retained = {};
  const query = (position) =>
    shangheTimeAt(timeModel, position.routeProgressM, { segmentIndex: position.segmentIndex });
  function reject(reason, transient = false) {
    failure = reason;
    current = null;
    transientFailure = transient;
    needsStability = transient;
    stability = null;
    if (!transient) {
      history = [];
      retained = {};
    }
    return snapshot({ now: clock });
  }
  function interrupt(reason, now = Date.now()) {
    clock = now;
    return reject(
      reason === 'gps-signal-unavailable'
        ? reason
        : reason === 'gps-time-quality-exclusion'
          ? 'stale-gps-fix'
          : 'gps-quality',
      ['gps-signal-unavailable', 'rejected-gps-fix', 'gps-time-quality-exclusion'].includes(reason),
    );
  }
  function retainedMetric(key, reason, now, allow) {
    const metric = { ...missing(reason), state: 'unavailable', asOf: null };
    const saved = retained[key];
    if (
      allow &&
      saved &&
      Number.isFinite(now) &&
      now >= saved.asOf &&
      now - saved.asOf <= config.retainLastValidMs
    ) {
      metric.lastValid = {
        ...structuredClone(saved),
        state: 'stale',
        ageMs: now - saved.asOf,
        expiresAt: saved.asOf + config.retainLastValidMs,
      };
    }
    return metric;
  }
  function distributionSource(fromM, toM) {
    return timeModel.legs
      .filter((leg) => Math.min(toM, leg.toM) - Math.max(fromM, leg.fromM) > 1e-6)
      .map((leg) => ({
        index: leg.index,
        method: leg.method,
        baselineSeconds: leg.baselineSeconds,
        source: leg.source,
      }));
  }
  function ratio(from, to, actualSeconds, baselineSeconds) {
    if (!Number.isFinite(baselineSeconds) || baselineSeconds < config.minBaselineSeconds)
      return missing('baseline-too-small');
    if (
      to.position.routeProgressM - from.position.routeProgressM <=
      Math.max(config.minProgressM, from.fix.accuracy + to.fix.accuracy)
    )
      return missing('progress-too-small');
    if (!Number.isFinite(actualSeconds) || actualSeconds <= 0)
      return missing('invalid-elapsed-time');
    return {
      factor: actualSeconds / baselineSeconds,
      reason: null,
      actualSeconds,
      baselineSeconds,
      source: {
        version: LIVE_FACTOR_VERSION,
        routeId: file.id ?? null,
        direction: file.direction === 'reverse' ? 'reverse' : 'forward',
        modelVersion: timeModel.version,
        processingVersion: file.processing?.version ?? null,
        timeBasis: 'gps-wall-clock-including-pauses',
        from: { ...from.fix, ...from.position },
        to: { ...to.fix, ...to.position },
        distributions: distributionSource(from.position.routeProgressM, to.position.routeProgressM),
      },
    };
  }
  function snapshot({ now = Date.now(), status = 'tracking' } = {}) {
    const unavailable = (reason, allow = false) => ({
      version: LIVE_FACTOR_VERSION,
      asOf: current?.fix.time ?? null,
      total: retainedMetric('total', reason, now, allow),
      recent: retainedMetric('recent', reason, now, allow),
    });
    if (status !== 'tracking' && !(status === 'requesting' && current?.quality === 'limited'))
      return unavailable(
        status === 'paused'
          ? 'paused-awaiting-fix'
          : status === 'requesting' && transientFailure
            ? failure
            : 'gps-not-tracking',
        status === 'requesting' && transientFailure,
      );
    if (!current) return unavailable(failure, transientFailure);
    if (
      !Number.isFinite(now) ||
      now - current.fix.time > config.maxAgeMs ||
      current.fix.time > now + config.futureToleranceMs
    )
      return unavailable('stale-gps-fix', true);
    const total = continuityReason
      ? missing(continuityReason)
      : !origin
        ? missing(originReason)
        : ratio(
            origin,
            current,
            (current.fix.time - (confirmation ? startedAt : Math.max(startedAt, origin.fix.time))) /
              1000,
            current.baseline.elapsedSeconds - origin.baseline.elapsedSeconds,
          );
    if (total.source) {
      total.source.departureTime = startedAt;
      total.source.startAlignment = confirmation
        ? 'user-confirmed-known-route-departure'
        : 'gps-time-and-accuracy-compatible-departure';
      total.source.startTimeOffsetMs = origin.fix.time - startedAt;
      total.source.observationStartTime = confirmation
        ? startedAt
        : Math.max(startedAt, origin.fix.time);
      total.source.startAlignmentToleranceMs = config.startAlignmentMs;
      total.source.departureConfirmation = confirmation;
      total.source.unobservedDepartureInterval =
        origin.fix.time > startedAt
          ? {
              fromTime: startedAt,
              toTime: origin.fix.time,
              basis: confirmation
                ? 'user-declaration-no-earlier-travel'
                : 'excluded-before-first-fix',
            }
          : null;
      total.source.startStation = startStation;
      total.source.restoration = restoration;
      total.source.limitations = [
        'local-device-observations-not-independently-verified',
        ...(confirmation ? ['user-declaration-only', 'station-coordinate-error-not-measured'] : []),
      ];
      total.source.baselineOriginM = origin.position.routeProgressM;
      total.source.stationModelOriginM = timeModel.originM;
      total.source.startFixBaselineSeconds = origin.baseline.elapsedSeconds;
      total.source.startAlignmentToleranceM = Math.min(config.startToleranceM, origin.fix.accuracy);
    }
    const target = current.fix.time - config.windowMs;
    // No invented boundary timestamp/position: choose a real fix near the requested boundary.
    let endpoint = null;
    for (const sample of history) {
      if (
        sample.fix.time <= target &&
        Math.abs(sample.fix.time - target) <= config.endpointToleranceMs &&
        (!endpoint || Math.abs(sample.fix.time - target) < Math.abs(endpoint.fix.time - target))
      )
        endpoint = sample;
    }
    const recent = endpoint
      ? ratio(
          endpoint,
          current,
          (current.fix.time - endpoint.fix.time) / 1000,
          current.baseline.elapsedSeconds - endpoint.baseline.elapsedSeconds,
        )
      : missing('window-start-missing');
    if (recent.source) {
      recent.source.requestedWindowMs = config.windowMs;
      recent.source.requestedStartTime = target;
      recent.source.endpointToleranceMs = config.endpointToleranceMs;
    }
    for (const [key, metric] of Object.entries({ total, recent })) {
      if (Number.isFinite(metric.factor)) {
        metric.state = 'live';
        metric.asOf = current.fix.time;
        metric.quality = current.quality;
        retained[key] = structuredClone(metric);
      } else metric.state = 'unavailable';
    }
    return { version: LIVE_FACTOR_VERSION, asOf: current.fix.time, total, recent };
  }
  function update(input, { now = Date.now(), status = 'tracking' } = {}) {
    clock = now;
    if (!['tracking', 'requesting'].includes(status)) {
      return snapshot({ now, status });
    }
    if (!Number.isFinite(startedAt) || !timeModel?.legs?.length || !matcher)
      return reject('missing-reference');
    const fix = normalizeLocationFix(input);
    if (!fix) return reject('gps-quality', true);
    if (input.excluded && input.qualityReason !== 'horizontal-accuracy')
      return reject('gps-quality');
    if (fix.accuracy > config.maxLimitedAccuracyM) return reject('gps-quality', true);
    const limited = fix.accuracy > config.maxAccuracyM;
    if (limited && !last) return reject('gps-quality', true);
    if (
      !Number.isFinite(now) ||
      now - fix.time > config.maxAgeMs ||
      fix.time > now + config.futureToleranceMs ||
      fix.time < startedAt - config.startAlignmentMs
    )
      return reject('stale-gps-fix', true);
    if (fix.time <= lastTime) return reject('nonmonotonic-gps-time', true);
    lastTime = fix.time;
    const wasFirst = first;
    first = false;
    if (wasFirst) originReason = 'start-not-aligned';
    const found = matcher.match(
      [{ ...fix, stationId: 'live-factor', coordinateStatus: 'located' }],
      {
        maxOffsetM: Math.min(
          config.maxAdaptiveOffsetM,
          Math.max(config.maxOffsetM, fix.accuracy + config.routeErrorAllowanceM),
        ),
        mergeWithinM: config.mergeWithinM,
        preserveReversals: true,
      },
    );
    let candidates = found.matches[0]?.routePositions ?? [];
    if (!candidates.length) return reject('off-route');
    const nearestOffset = found.matches[0].nearestTrackDistanceM;
    candidates = candidates.filter((p) => p.offsetM <= nearestOffset + fix.accuracy);
    if (last) {
      const dt = (fix.time - last.fix.time) / 1000;
      const reach = config.maxSpeedMps * dt + last.fix.accuracy + fix.accuracy;
      candidates = candidates.filter(
        (p) =>
          p.segmentIndex === last.position.segmentIndex &&
          Math.abs(p.routeProgressM - last.position.routeProgressM) <= reach,
      );
      if (!candidates.length) return reject('unreachable-route-position');
      if (distanceM(last.fix, fix) > reach) return reject('abnormal-gps-speed');
    }
    // A time-aligned departure at the known model origin can identify the initial
    // occurrence of an O/out-and-back route. Never use this to jump between branches later.
    if (
      wasFirst &&
      candidates.length > 1 &&
      Math.abs(fix.time - startedAt) <= config.startAlignmentMs &&
      now - startedAt <= config.startAlignmentMs
    ) {
      const starts = candidates.filter(
        (position) =>
          departureDistance({ fix, position }) <=
          Math.min(config.startToleranceM, Math.max(5, fix.accuracy)),
      );
      if (starts.length === 1) candidates = starts;
    }
    if (candidates.length !== 1) return reject('ambiguous-route-position');
    const position = candidates[0],
      baseline = query(position);
    const sample = {
      fix,
      position,
      baseline,
      observedAt: now,
      quality: limited ? 'limited' : 'normal',
    };
    if (!Number.isFinite(baseline.elapsedSeconds))
      return reject(baseline.reason ?? 'unknown-shanghe-time');
    const tolerance = Math.max(
      config.progressToleranceM,
      Math.min(50, fix.accuracy + (last?.fix.accuracy ?? 0)),
    );
    if (position.routeProgressM < peakM - tolerance) return reject('backtracking');
    // Limited precision is accepted only after a stable run on one unambiguous
    // occurrence. The original raw-track quality rules remain stricter and unchanged.
    if (last && (needsStability || (limited && last.quality !== 'limited'))) {
      const previous = stability?.last;
      const dt = previous && fix.time - previous.fix.time;
      const compatible =
        previous &&
        dt > 0 &&
        dt <= config.stabilityWindowMs &&
        previous.position.segmentIndex === position.segmentIndex &&
        Math.abs(previous.position.routeProgressM - position.routeProgressM) <=
          (config.maxSpeedMps * dt) / 1000 + Math.min(50, previous.fix.accuracy + fix.accuracy);
      stability = compatible ? { ...stability, last: sample } : { first: sample, last: sample };
      if (fix.time - stability.first.fix.time < config.stabilityMs) {
        failure = 'gps-stabilizing';
        current = null;
        transientFailure = true;
        needsStability = true;
        return snapshot({ now, status });
      }
      needsStability = false;
      stability = null;
    }
    if (restoredBoundary) {
      const bound = Math.max(
        5,
        Math.min(config.maxAdaptiveOffsetM, fix.accuracy + restoredBoundary.fix.accuracy),
      );
      if (
        position.segmentIndex !== restoredBoundary.position.segmentIndex ||
        Math.abs(position.routeProgressM - restoredBoundary.position.routeProgressM) > bound ||
        distanceM(fix, restoredBoundary.fix) > bound
      )
        continuityReason = 'restored-continuity-unconfirmed';
      restoration = {
        kind: 'local-sha256-checkpoint',
        restorationCount,
        limitations: ['unobserved-reload-intervals-not-a-continuous-gps-record'],
        verification: 'unverified',
        unobservedInterval: { fromTime: restoredBoundary.fix.time, toTime: fix.time },
        boundaryCompatible: !continuityReason,
      };
      restoredBoundary = null;
    }
    if (
      last &&
      fix.time - last.fix.time > config.maxObservationGapMs &&
      Math.abs(position.routeProgressM - last.position.routeProgressM) >
        Math.max(config.progressToleranceM, Math.min(50, fix.accuracy + last.fix.accuracy))
    ) {
      continuityReason = 'gps-observation-gap';
      history = [];
      retained = {};
    }
    last = sample;
    if (position.routeProgressM > peakM) peakSample = sample;
    peakM = Math.max(peakM, position.routeProgressM);
    if (wasFirst) departureCandidate = sample;
    if (
      wasFirst &&
      Math.abs(fix.time - startedAt) <= config.startAlignmentMs &&
      now - startedAt <= config.startAlignmentMs &&
      departureDistance(sample) <= Math.min(config.startToleranceM, fix.accuracy)
    ) {
      origin = sample;
      originReason = null;
    }
    current = sample;
    failure = null;
    transientFailure = false;
    needsStability = false;
    history.push(sample);
    const cutoff = fix.time - config.windowMs - config.endpointToleranceMs;
    const firstKept = history.findIndex((item) => item.fix.time >= cutoff);
    if (firstKept > 0) history.splice(0, firstKept);
    return snapshot({ now, status });
  }
  function departureDistance(sample) {
    return Math.max(
      Math.hypot(sample.position.routeProgressM - timeModel.originM, sample.position.offsetM),
      Number.isFinite(startStation?.lat) && Number.isFinite(startStation?.lon)
        ? distanceM(sample.fix, startStation)
        : 0,
    );
  }
  function departureStatus(now = Date.now()) {
    const sample = departureCandidate;
    const distance = sample && departureDistance(sample);
    const canConfirm =
      !origin &&
      !continuityReason &&
      sample &&
      current &&
      sample.fix.time - startedAt <= config.startDelayMs &&
      sample.observedAt - startedAt <= config.startDelayMs &&
      now >= sample.observedAt &&
      now - sample.observedAt <= config.confirmationAgeMs &&
      now - current.fix.time <= config.maxAgeMs &&
      current.fix.time <= now + config.futureToleranceMs &&
      now >= current.observedAt &&
      distance <= config.confirmedStartToleranceM &&
      Math.abs(current.position.routeProgressM - sample.position.routeProgressM) <=
        Math.max(config.progressToleranceM, sample.fix.accuracy + current.fix.accuracy);
    return {
      canConfirm: Boolean(canConfirm),
      stationName: startStation?.name ?? null,
      coordinateSource: startStation?.coordinateSource ?? null,
      stationCoordinateAccuracy: 'unknown',
      distanceM: distance ?? null,
      gpsAccuracyM: sample?.fix.accuracy ?? null,
      maxDeclarationOffsetM: config.confirmedStartToleranceM,
      confirmed: Boolean(confirmation),
    };
  }
  function confirmDeparture(statements, now = Date.now()) {
    if (
      statements?.departedHere !== true ||
      statements?.noEarlierTravel !== true ||
      !departureStatus(now).canConfirm
    )
      return false;
    confirmation = {
      confirmedAt: now,
      departedHere: true,
      noEarlierTravel: true,
      verification: 'unverified',
    };
    origin = departureCandidate;
    originReason = null;
    return true;
  }
  const pack = (sample) =>
    sample
      ? {
          fix: sample.fix,
          position: sample.position,
          observedAt: sample.observedAt,
          quality: sample.quality,
        }
      : null;
  function checkpoint() {
    return structuredClone({
      version: LIVE_FACTOR_VERSION,
      config,
      origin: pack(origin),
      departureCandidate: pack(departureCandidate),
      last: pack(last),
      peak: pack(peakSample),
      lastTime: Number.isFinite(lastTime) ? lastTime : null,
      originReason,
      continuityReason,
      confirmation,
      restorationCount,
    });
  }
  function restoreCheckpoint(state, savedAt, now = Date.now()) {
    try {
      if (
        state?.version !== LIVE_FACTOR_VERSION ||
        JSON.stringify(state.config) !== JSON.stringify(config) ||
        !Number.isFinite(savedAt) ||
        savedAt < startedAt ||
        savedAt > now + config.futureToleranceMs ||
        !Number.isFinite(state.lastTime) ||
        state.lastTime > savedAt + config.futureToleranceMs
      )
        return false;
      const unpack = (data) => {
        if (!data) return null;
        const fix = normalizeLocationFix(data.fix);
        if (
          !fix ||
          fix.accuracy > config.maxLimitedAccuracyM ||
          data.quality !== (fix.accuracy > config.maxAccuracyM ? 'limited' : 'normal') ||
          fix.time < startedAt - config.startAlignmentMs ||
          fix.time > state.lastTime ||
          !Number.isFinite(data.observedAt) ||
          data.observedAt > savedAt ||
          data.observedAt < startedAt ||
          fix.time > data.observedAt + config.futureToleranceMs ||
          data.observedAt - fix.time > config.maxAgeMs
        )
          throw new Error('invalid saved observation');
        const found = matcher.match(
          [{ ...fix, stationId: 'checkpoint', coordinateStatus: 'located' }],
          {
            maxOffsetM: Math.min(
              config.maxAdaptiveOffsetM,
              Math.max(config.maxOffsetM, fix.accuracy + config.routeErrorAllowanceM),
            ),
            mergeWithinM: config.mergeWithinM,
            preserveReversals: true,
          },
        );
        const position = found.matches[0]?.routePositions.find(
          (p) =>
            p.segmentIndex === data.position?.segmentIndex &&
            Math.abs(p.routeProgressM - data.position.routeProgressM) < 1e-6 &&
            Math.abs(p.offsetM - data.position.offsetM) < 1e-6,
        );
        if (!position) throw new Error('changed route position');
        return {
          fix,
          position,
          baseline: query(position),
          observedAt: data.observedAt,
          quality: fix.accuracy > config.maxAccuracyM ? 'limited' : 'normal',
        };
      };
      if (
        !Number.isInteger(state.restorationCount) ||
        state.restorationCount < 0 ||
        state.restorationCount >= 500
      )
        return false;
      const candidate = unpack(state.departureCandidate),
        savedOrigin = unpack(state.origin),
        savedLast = unpack(state.last),
        peak = unpack(state.peak);
      if (
        !savedLast ||
        !peak ||
        peak.position.routeProgressM < savedLast.position.routeProgressM - 1e-6 ||
        peak.fix.time > savedLast.fix.time
      )
        return false;
      const savedConfirmation = state.confirmation;
      if (
        savedConfirmation &&
        (!savedOrigin ||
          !candidate ||
          savedConfirmation.departedHere !== true ||
          savedConfirmation.noEarlierTravel !== true ||
          !Number.isFinite(savedConfirmation.confirmedAt) ||
          savedConfirmation.confirmedAt < candidate.observedAt ||
          savedConfirmation.confirmedAt >
            Math.min(savedAt, candidate.observedAt + config.confirmationAgeMs))
      )
        return false;
      if (savedOrigin) {
        if (
          !candidate ||
          JSON.stringify(pack(savedOrigin)) !== JSON.stringify(pack(candidate)) ||
          !Number.isFinite(savedOrigin.baseline.elapsedSeconds) ||
          (!savedConfirmation &&
            (Math.abs(savedOrigin.fix.time - startedAt) > config.startAlignmentMs ||
              savedOrigin.observedAt - startedAt > config.startAlignmentMs ||
              savedOrigin.fix.accuracy > config.maxAccuracyM)) ||
          savedOrigin.fix.time - startedAt > config.startDelayMs ||
          savedOrigin.observedAt - startedAt > config.startDelayMs ||
          departureDistance(savedOrigin) >
            (savedConfirmation
              ? config.confirmedStartToleranceM
              : Math.min(config.startToleranceM, savedOrigin.fix.accuracy))
        )
          return false;
      }
      if (
        ![null, 'gps-observation-gap', 'restored-continuity-unconfirmed'].includes(
          state.continuityReason,
        ) ||
        ![null, 'missing-start-fix', 'start-not-aligned', 'session-history-unavailable'].includes(
          state.originReason,
        )
      )
        return false;
      restorationCount = state.restorationCount + 1;
      origin = savedOrigin;
      departureCandidate = candidate;
      last = savedLast;
      peakSample = peak;
      peakM = peak.position.routeProgressM;
      lastTime = state.lastTime;
      first = false;
      confirmation = savedConfirmation
        ? {
            confirmedAt: savedConfirmation.confirmedAt,
            departedHere: true,
            noEarlierTravel: true,
            verification: 'unverified',
          }
        : null;
      continuityReason = state.continuityReason;
      originReason = origin ? null : (state.originReason ?? 'session-history-unavailable');
      history = [];
      current = null;
      failure = 'restored-awaiting-fix';
      retained = {};
      transientFailure = false;
      needsStability = false;
      stability = null;
      restoredBoundary = savedLast;
      return true;
    } catch {
      return false;
    }
  }
  return {
    update,
    snapshot,
    interrupt,
    departureStatus,
    confirmDeparture,
    checkpoint,
    restoreCheckpoint,
  };
}
