import { button, esc } from '../../ui/html.js';
export const megabytes = (bytes) => `${(bytes / 1048576).toFixed(1)} MB`;
export function offlineMapPanel(controller, file) {
  const data = controller?.snapshot();
  if (!data || !file?.points?.length) return '';
  const busy = ['downloading', 'saving', 'checking'].includes(data.phase);
  const current = controller.forRoute(file);
  const progress = data.total ? Math.min(100, Math.round((data.received / data.total) * 100)) : 0;
  return `<div class="offline-map-panel" id="offline-map-panel">
    <div class="offline-map-heading"><div><strong>離線地圖</strong><span>台灣標準底圖 · 2D</span></div><span class="chip">${data.pack ? '已下載' : '尚未下載'}</span></div>
    <p id="offline-map-message" role="status">${esc(data.message)}</p>
    ${data.pack && !current ? '<p class="offline-warning">這條 GPX 超出目前圖資範圍，仍使用線上底圖。</p>' : ''}
    ${data.pack && !data.shellReady ? '<p class="offline-warning">底圖已在本機；離線頁面尚未準備好，請連線後重新開啟此網站。</p>' : ''}
    <div id="offline-map-progress" ${data.phase === 'downloading' ? '' : 'hidden'}><progress max="100" value="${progress}" aria-label="離線地圖下載進度"></progress><span>${progress}% · ${megabytes(data.received)} / ${megabytes(data.total)}</span></div>
    <div class="offline-map-actions">${data.phase === 'downloading' ? button('取消下載', 'offline-cancel', 'ghost') : button(data.pack ? '重新下載' : '下載離線地圖', 'offline-download', data.pack ? 'ghost' : 'primary', '', busy || data.phase === 'unavailable' ? 'disabled' : '')}${data.pack ? button('刪除離線地圖', 'offline-delete', 'ghost', '', busy ? 'disabled' : '') : ''}<small>${data.pack ? `${megabytes(data.pack.bytes)} · ${esc(data.pack.version)}` : data.total ? `約 ${megabytes(data.total)}` : '下載前會顯示大小'}</small></div>
    <p class="offline-map-note">地圖儲存在此裝置、此瀏覽器的 App 空間。出發前請下載完成並試開；清除網站資料會移除地圖。涵蓋台灣本島，放大可看道路與步道；不含等高線或 3D。</p>
  </div>`;
}
export function updateOfflineProgress(document, data) {
  const panel = document.getElementById('offline-map-progress');
  if (!panel) return;
  const progress = data.total ? Math.min(100, Math.round((data.received / data.total) * 100)) : 0;
  panel.querySelector('progress').value = progress;
  panel.querySelector('span').textContent =
    `${progress}% · ${megabytes(data.received)} / ${megabytes(data.total)}`;
}
