import { normalizeDirection } from './direction.js';
export function createDirectionController({
  state,
  current,
  gpsPending,
  repository,
  render,
  feedback,
}) {
  let revision = 0;
  let disposed = false,
    saving = Promise.resolve();
  async function restore() {
    if (!repository.getRouteDirections) return;
    try {
      const saved = await repository.getRouteDirections();
      if (disposed) return;
      const entries = state.library
        .filter((file) => file.kind !== 'recording')
        .map((file) => [file.id, normalizeDirection(saved?.directions?.[file.id])]);
      state.routeDirections = Object.fromEntries(entries);
    } catch {
      if (!disposed) state.directionError = '行走方向設定無法讀取，先使用 GPX 原向。';
    }
  }
  async function set(value) {
    const file = current();
    if (disposed || !file || file.kind === 'recording' || file.recording) return;
    if (gpsPending() || state.starting || state.timeSourceBusy) {
      feedback.toast('此趟行走方向已固定，請結束紀錄後再切換。');
      return;
    }
    if (!['forward', 'reverse'].includes(value)) return;
    state.correctionPage = null;
    state.routeDirections = { ...state.routeDirections, [file.id]: value };
    const thisRevision = ++revision;
    state.directionError = '';
    render();
    if (!repository.saveRouteDirections) return;
    const directions = Object.fromEntries(
      state.library
        .filter((entry) => entry.kind !== 'recording')
        .map((entry) => [entry.id, normalizeDirection(state.routeDirections[entry.id])]),
    );
    // Rapid toggles are committed in order; another settings module has its own storage slot.
    const write = saving.then(async () => {
      try {
        await repository.saveRouteDirections({ directions });
        if (!disposed && thisRevision === revision) state.directionError = '';
      } catch {
        if (!disposed && thisRevision === revision)
          state.directionError = '行走方向未能保存，重新開啟可能回到原向。';
      }
      if (!disposed) render();
    });
    saving = write;
    await write;
  }
  return {
    restore,
    set,
    dispose: async () => {
      disposed = true;
      await saving;
    },
  };
}
