// Public ETA entry point. Keep this import path stable for callers.
import { MAX_DATE_MS, STATUS_REASONS, validateInput } from './internal/input.js';
import { decimal, add, multiply, asNumber, roundedMs } from './internal/decimal.js';
export { EtaInputError } from './internal/input.js';
export const MODEL_VERSION = 'fixed-multiplier-v1';

/**
 * Predict a selected, ordered directed path. No GPX, storage, clock, network,
 * condition selection, distance inference or additional rest budget is used.
 * The multiplier predicts elapsed time including rests; source rest metadata
 * remains independent. The legacy *MoveSeconds names do not exclude rests.
 * Malformed contracts throw EtaInputError; incomplete data returns issues.
 */
export function predictEta(request) {
  const { departureUtcMs, segments, multiplier, mode } = validateInput(request);
  const factor = decimal(multiplier);
  const issues = [];
  const warnings = new Set(['fixed_multiplier_model_unvalidated']);
  const legs = [];
  const waypoints = [{ sequence: 0, waypointId: segments[0].fromWaypointId,
    cumulativeSeconds: 0, predictedArrivalUtcMs: departureUtcMs,
    confidence: 'low', reason: null }];
  let baselineTotal = decimal(0);
  let predictedTotal = decimal(0);
  let blocked = false;

  segments.forEach((segment, index) => {
    const reasons = [];
    const { baselineMoveSeconds: baseline } = segment;
    const restIncluded = segment.restIncluded ?? 'unknown';
    if (restIncluded === 'unknown') warnings.add('rest_inclusion_unknown');
    if (index && segments[index - 1].toWaypointId !== segment.fromWaypointId) {
      reasons.push('route_discontinuous');
    }
    if (segment.mode !== 'walk' && !(mode === 'walking' && segment.mode === 'road_walk')) {
      reasons.push('mode_excluded');
    }
    if (segment.timeStatus !== 'known') reasons.push(STATUS_REASONS[segment.timeStatus]);
    if (baseline === null) reasons.push('baseline_unavailable');
    else if (!Number.isFinite(baseline) || baseline <= 0) reasons.push('invalid_baseline_time');
    if (segment.sourceIds.length === 0) reasons.push('baseline_source_missing');

    let predictedSeconds = null;
    let arrival = null;
    let cumulativeSeconds = null;
    let cumulativeBaselineSeconds = null;
    if (reasons.length === 0) {
      const base = decimal(baseline);
      const predicted = multiply(base, factor);
      predictedSeconds = asNumber(predicted);
      if (!Number.isFinite(predictedSeconds) || predictedSeconds <= 0) {
        reasons.push('duration_out_of_range');
        predictedSeconds = null;
      } else if (!blocked) {
        const nextBaseline = add(baselineTotal, base);
        const nextPredicted = add(predictedTotal, predicted);
        const nextArrival = BigInt(departureUtcMs) + roundedMs(nextPredicted);
        if (!Number.isFinite(asNumber(nextBaseline))) reasons.push('baseline_total_out_of_range');
        else if (nextArrival > BigInt(MAX_DATE_MS)) reasons.push('arrival_out_of_range');
        else {
          baselineTotal = nextBaseline;
          predictedTotal = nextPredicted;
          cumulativeBaselineSeconds = asNumber(baselineTotal);
          cumulativeSeconds = asNumber(predictedTotal);
          arrival = Number(nextArrival);
        }
      }
    }
    const uniqueReasons = [...new Set(reasons)];
    for (const code of uniqueReasons) {
      issues.push({ code, segmentIndex: index, segmentId: segment.id,
        fromWaypointId: segment.fromWaypointId, toWaypointId: segment.toWaypointId,
        sourceIds: [...segment.sourceIds] });
    }
    const reason = uniqueReasons[0] ?? (blocked ? 'upstream_unavailable' : null);
    if (uniqueReasons.length) blocked = true;
    const confidence = arrival === null ? 'unavailable' : 'low';
    legs.push({ segmentIndex: index, segmentId: segment.id,
      fromWaypointId: segment.fromWaypointId, toWaypointId: segment.toWaypointId,
      sourceIds: [...segment.sourceIds], mode: segment.mode, timeStatus: segment.timeStatus,
      restIncluded, baselineMoveSeconds: Number.isFinite(baseline) ? baseline : null,
      predictedMoveSeconds: predictedSeconds,
      cumulativeBaselineSeconds, cumulativeSeconds,
      predictedArrivalUtcMs: arrival, confidence, reason, reasons: uniqueReasons });
    waypoints.push({ sequence: index + 1, waypointId: segment.toWaypointId,
      cumulativeSeconds, predictedArrivalUtcMs: arrival, confidence, reason });
  });

  return {
    modelVersion: MODEL_VERSION, complete: !blocked,
    status: blocked ? 'unavailable' : 'complete',
    confidence: blocked ? 'unavailable' : 'low',
    reason: issues[0]?.code ?? null,
    departureUtcMs, multiplier, mode,
    timeBasis: 'elapsed_including_rest', additionalRestSeconds: 0,
    totalBaselineSeconds: blocked ? null : asNumber(baselineTotal),
    totalPredictedSeconds: blocked ? null : asNumber(predictedTotal),
    predictedArrivalUtcMs: blocked ? null : waypoints.at(-1).predictedArrivalUtcMs,
    segments: legs, waypoints, issues, warnings: [...warnings],
  };
}
