import { button, esc } from '../../ui/html.js';
import { downloadGpx } from '../../ui/download.js';
import { DIAGNOSTIC_PAGE_SIZE } from './diagnostics.js';
export function createLibraryActions({
  state,
  library,
  current,
  render,
  feedback,
  document = globalThis.document,
}) {
  const { modal } = feedback;
  return {
    select: (target) => library.selectFile(target.dataset.id),
    'time-source-confirm': (target) =>
      library.confirmTimeSource(target.dataset.id, {
        actualGps: document.querySelector('#gpx-actual-gps')?.checked === true,
        originalTime: document.querySelector('#gpx-original-time')?.checked === true,
      }),
    'time-source-revoke': (target) => library.revokeTimeSource(target.dataset.id),
    'use-recording-route': (target) => library.useRecordingAsRoute(target.dataset.id),
    'correction-page': (target) => {
      const file = current?.();
      const page = Number(target.dataset.page);
      const pages = Math.ceil((file?.processing?.diagnostics?.length ?? 0) / DIAGNOSTIC_PAGE_SIZE);
      if (!file || !Number.isInteger(page) || page < 0 || page >= pages) return;
      state.correctionPage = { file, page };
      render();
    },
    'file-download': (target) => {
      const file = state.library.find((file) => file.id === target.dataset.id);
      if (file) downloadGpx(file.raw, file.fileName);
    },
    'library-filter': (target) => {
      state.libraryFilter = target.dataset.filter === 'recordings' ? 'recordings' : 'all';
      render();
    },
    delete: (target) => {
      const id = target.dataset.id,
        file = state.library.find((file) => file.id === id);
      if (!file) return;
      modal(
        '移除此 GPX？',
        `<p>${esc(file.name)}</p><p>${file.kind === 'recording' ? '這是你在 Ridgewise 錄製並保存於此瀏覽器的 GPX。如果沒有另外下載備份，移除後可能無法恢復。請先確認已保存需要的備份。' : '僅移除此瀏覽器內的 GPX 副本，不會刪除你在裝置上另外保存的來源檔。請自行確認來源檔仍有保留。'}</p>`,
        button('移除', 'delete-confirm', 'danger', '', `data-id="${id}"`),
      );
    },
    'delete-confirm': (target) => library.removeFile(target.dataset.id),
  };
}
