import { haversine, indexTrack } from './track-math.js';
import { positionReliable, TRACK_FILTER_DEFAULTS } from './track-filter.js';

export const TRACK_TIME_VERSION = 1;
export const TRACK_TIME_DEFAULTS = Object.freeze({
  maxGapMs: 300000,
  maxSpeedMps: TRACK_FILTER_DEFAULTS.maxSpeedMps,
  stationaryRadiusM: TRACK_FILTER_DEFAULTS.stationaryRadiusM,
  stationaryDurationMs: TRACK_FILTER_DEFAULTS.stationaryDurationS * 1000,
  stationarySpeedMps: 0.3,
});
const nonrecorded = new Set(['synthetic', 'interpolated', 'estimated']);
const key = (segment, index) => `${segment}:${index}`;
const validTime = (point) =>
  Number.isFinite(point.time) && Math.abs(point.time) <= 8640000000000000;

/** Candidate timing on the existing corrected kilometre axis. Never authenticates a GPX.
 * Adjacent source points only: missing fixes, quality exclusions and segments are not bridged.
 * All durations are milliseconds; coordinates/timestamps and the caller's arrays are read-only.
 */
export function prepareTimeWeights(
  segments,
  {
    indexedPoints = indexTrack(segments),
    diagnostics = [],
    filterOptions = TRACK_FILTER_DEFAULTS,
    source = 'track',
    options = {},
  } = {},
) {
  if (!['track', 'route', 'synthetic', 'reverse-planning'].includes(source))
    throw new TypeError('Unknown time weight source');
  const config = { ...TRACK_TIME_DEFAULTS, ...options };
  for (const [name, value] of Object.entries(config)) {
    if (!Object.hasOwn(TRACK_TIME_DEFAULTS, name))
      throw new TypeError('Unknown time option: ' + name);
    if (!Number.isFinite(value) || value <= 0) throw new RangeError(name + ' must be positive');
  }
  const positions = new Map(indexedPoints.map((p) => [key(p.segment, p.sourceIndex), p]));
  const corrections = new Map(diagnostics.map((d) => [key(d.segment, d.sourceIndex), d.reasons]));
  const intervals = [];
  let timedPoints = 0,
    missingPoints = 0,
    nonrecordedPoints = 0,
    last = null;

  segments.forEach((segment, segmentIndex) => {
    let highTime = null,
      dwell = [],
      anchor = null;
    const flushDwell = () => {
      const duration = dwell.reduce((sum, item) => sum + item.elapsedMs, 0);
      for (const item of dwell) {
        item.status =
          duration >= config.stationaryDurationMs ? 'stationary' : 'uncertain-stationary';
        item.movingMs = item.status === 'stationary' ? 0 : null;
      }
      dwell = [];
      anchor = null;
    };
    segment.forEach((point, index) => {
      const at = positions.get(key(segmentIndex, index));
      if (validTime(point)) timedPoints++;
      else missingPoints++;
      if (nonrecorded.has(point.timeSource)) nonrecordedPoints++;
      if (!index && last) {
        intervals.push({
          from: last,
          to: { segment: segmentIndex, index },
          fromKm: at?.km ?? 0,
          toKm: at?.km ?? 0,
          elapsedMs: null,
          speedMps: null,
          status: 'segment-break',
          issues: ['segment-break'],
          movingMs: null,
        });
      }
      if (index) {
        const previous = segment[index - 1],
          before = positions.get(key(segmentIndex, index - 1));
        const elapsedMs =
          validTime(previous) && validTime(point) ? point.time - previous.time : null;
        const metres = haversine(previous, point) * 1000;
        const speedMps = elapsedMs > 0 ? metres / (elapsedMs / 1000) : null;
        const issues = [];
        if (source !== 'track') issues.push(source === 'route' ? 'planned-route' : source);
        if ([previous, point].some((p) => nonrecorded.has(p.timeSource)))
          issues.push('nonrecorded-time');
        if (elapsedMs === null)
          issues.push(
            [previous, point].some((p) => p.timeSource === 'invalid')
              ? 'invalid-time'
              : 'missing-time',
          );
        else if (elapsedMs === 0) issues.push('duplicate-time');
        else if (elapsedMs < 0) issues.push('time-reversal');
        else {
          if (highTime !== null && previous.time < highTime) issues.push('time-overlap');
          if (elapsedMs > config.maxGapMs) issues.push('gps-gap');
          if (speedMps > config.maxSpeedMps) issues.push('abnormal-speed');
        }
        if (
          !before ||
          !at ||
          !positionReliable(previous, filterOptions) ||
          !positionReliable(point, filterOptions) ||
          before.excluded ||
          at.excluded
        )
          issues.push('gps-quality-gap');
        if (
          [index - 1, index].some((i) =>
            corrections
              .get(key(segmentIndex, i))
              ?.some((reason) =>
                ['isolated-position-spike', 'unconfirmed-position-jump'].includes(reason),
              ),
          )
        )
          issues.push('corrected-position');
        const item = {
          from: { segment: segmentIndex, index: index - 1 },
          to: { segment: segmentIndex, index },
          fromKm: before?.km ?? 0,
          toKm: at?.km ?? before?.km ?? 0,
          elapsedMs,
          speedMps,
          status: issues[0] ?? 'moving',
          issues,
          movingMs: issues.length ? null : elapsedMs,
        };
        intervals.push(item);
        const stationaryDrift = [index - 1, index].every((i) =>
          corrections.get(key(segmentIndex, i))?.includes('stationary-drift'),
        );
        const dwellPoint = stationaryDrift ? at : point;
        if (
          !issues.length &&
          (stationaryDrift ||
            (speedMps <= config.stationarySpeedMps && metres <= config.stationaryRadiusM))
        ) {
          if (anchor && haversine(anchor, dwellPoint) * 1000 > config.stationaryRadiusM)
            flushDwell();
          anchor ??= stationaryDrift ? before : previous;
          dwell.push(item);
        } else flushDwell();
      }
      if (validTime(point)) highTime = Math.max(highTime ?? -Infinity, point.time);
      last = { segment: segmentIndex, index };
    });
    flushDwell();
  });
  // A zero-length corrected edge cannot carry a spatial movement weight.
  for (const item of intervals) {
    if (item.status === 'moving' && item.toKm <= item.fromKm) {
      item.status = 'unresolved-distance';
      item.issues.push('unresolved-distance');
      item.movingMs = null;
    }
  }
  const moving = intervals.filter((item) => item.status === 'moving');
  const candidateMovingMs = moving.reduce((sum, item) => sum + item.movingMs, 0);
  const candidateKm = moving.reduce((sum, item) => sum + item.toKm - item.fromKm, 0);
  let cumulativeMovingMs = 0;
  for (const item of intervals) {
    cumulativeMovingMs += item.movingMs ?? 0;
    item.cumulativeMovingMs = cumulativeMovingMs;
    item.weight = item.status === 'moving' ? item.movingMs / candidateMovingMs : null;
    item.msPerKm = item.status === 'moving' ? item.movingMs / (item.toKm - item.fromKm) : null;
  }
  const limitations = ['unverified-time-source'];
  if (missingPoints) limitations.push('missing-or-invalid-time');
  if (nonrecordedPoints || source === 'synthetic') limitations.push('nonrecorded-time');
  if (source === 'route') limitations.push('planned-route');
  if (source === 'reverse-planning') limitations.push('reverse-planning');
  if (intervals.some((item) => item.movingMs === null))
    limitations.push('incomplete-time-coverage');
  return {
    version: TRACK_TIME_VERSION,
    options: config,
    source: { kind: source, verification: 'unverified', reliable: false, limitations },
    // Syntactically valid timing is never proof of an actual recorded walk.
    usableForPrediction: false,
    status: !moving.length ? 'unavailable' : limitations.length > 1 ? 'partial' : 'candidate',
    intervals,
    summary: {
      timedPoints,
      missingPoints,
      nonrecordedPoints,
      candidateMovingMs,
      candidateStationaryMs: intervals.reduce(
        (sum, item) => sum + (item.status === 'stationary' ? item.elapsedMs : 0),
        0,
      ),
      candidateKm,
      totalKm: indexedPoints.at(-1)?.km ?? 0,
    },
  };
}
