import { haversine, trackStats, indexTrack } from './track-math.js';

export const TRACK_FILTER_VERSION = 4;

// Hiking defaults calibrated against two local field GPX tracks; route-level validation still matters.
export const TRACK_FILTER_DEFAULTS = Object.freeze({
  horizontalToleranceM: 10,
  stationaryRadiusM: 5,
  stationaryDurationS: 60,
  maxSpeedMps: 12,
  spikeLegM: 50,
  elevationWindow: 17,
  elevationWindowSeconds: 48,
  elevationHysteresisM: 15,
  maxHorizontalAccuracyM: 50,
  maxAltitudeAccuracyM: 30,
});

const distance = (a, b) => haversine(a, b) * 1000;
const longitudeDelta = (a, b) => ((((b - a) % 360) + 540) % 360) - 180;
const longitude = (value) => ((((value + 180) % 360) + 360) % 360) - 180;
const median = (values) => {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
};

function settings(options) {
  for (const key of Object.keys(options)) {
    if (!Object.hasOwn(TRACK_FILTER_DEFAULTS, key))
      throw new TypeError('Unknown track filter option: ' + key);
  }
  const result = { ...TRACK_FILTER_DEFAULTS, ...options };
  for (const [key, value] of Object.entries(result)) {
    if (!Number.isFinite(value) || value < 0) throw new RangeError(key + ' must be non-negative');
  }
  if (
    !Number.isInteger(result.elevationWindow) ||
    result.elevationWindow < 1 ||
    result.elevationWindow > 31 ||
    result.elevationWindow % 2 === 0
  ) {
    throw new RangeError('elevationWindow must be an odd integer from 1 to 31');
  }
  return result;
}

function snapshot(segments) {
  if (!Array.isArray(segments)) throw new TypeError('Expected an array of track segments');
  return segments.map((segment) => {
    if (!Array.isArray(segment)) throw new TypeError('Expected a segment array');
    return segment.map((point) => {
      if (
        !point ||
        !Number.isFinite(point.lat) ||
        !Number.isFinite(point.lon) ||
        Math.abs(point.lat) > 90 ||
        Math.abs(point.lon) > 180
      ) {
        throw new TypeError('Track points must contain valid latitude and longitude');
      }
      // The engine only writes top-level coordinates/elevation, never metadata or input objects.
      return { ...point };
    });
  });
}

function interpolate(a, b, fraction) {
  return {
    lat: a.lat + (b.lat - a.lat) * fraction,
    lon: longitude(a.lon + longitudeDelta(a.lon, b.lon) * fraction),
  };
}

export function positionReliable(point, config = TRACK_FILTER_DEFAULTS) {
  return (
    !point.excluded &&
    (!config.maxHorizontalAccuracyM ||
      point.accuracy == null ||
      (Number.isFinite(point.accuracy) &&
        point.accuracy >= 0 &&
        point.accuracy <= config.maxHorizontalAccuracyM))
  );
}
export function elevationReliable(point, config = TRACK_FILTER_DEFAULTS) {
  return (
    !config.maxAltitudeAccuracyM ||
    point.altitudeAccuracy == null ||
    (Number.isFinite(point.altitudeAccuracy) &&
      point.altitudeAccuracy >= 0 &&
      point.altitudeAccuracy <= config.maxAltitudeAccuracyM)
  );
}

function removeSpikes(raw, corrected, flags, config) {
  if (!config.maxSpeedMps) return;
  for (let i = 1; i < raw.length - 1; i++) {
    const a = raw[i - 1],
      b = raw[i],
      c = raw[i + 1];
    const ab = distance(a, b),
      bc = distance(b, c),
      ac = distance(a, c);
    if (Math.min(ab, bc) < config.spikeLegM || ab + bc < 4 * Math.max(ac, 1)) continue;
    const timed =
      [a, b, c].every((point) => Number.isFinite(point.time)) && a.time < b.time && b.time < c.time;
    if (!timed) {
      flags[i].push('suspect-spike-without-time');
      continue;
    }
    if (
      ab / ((b.time - a.time) / 1000) <= config.maxSpeedMps ||
      bc / ((c.time - b.time) / 1000) <= config.maxSpeedMps ||
      ac / ((c.time - a.time) / 1000) > config.maxSpeedMps
    )
      continue;
    Object.assign(corrected[i], interpolate(a, c, (b.time - a.time) / (c.time - a.time)));
    flags[i].push('isolated-position-spike');
  }
}

// Only collapse bounded, oscillating clouds with trustworthy dwell timestamps.
// Each cloud is visited once; no timestamps means no stationary classification.
function removeStationaryDrift(points, flags, config) {
  if (!config.stationaryRadiusM) return;
  let start = 0;
  while (start < points.length - 1) {
    const origin = points[start];
    let end = start + 1,
      length = 0;
    let minX = 0,
      maxX = 0,
      minY = 0,
      maxY = 0;
    for (; end < points.length; end++) {
      const point = points[end],
        previous = points[end - 1];
      if (
        !Number.isFinite(previous.time) ||
        !Number.isFinite(point.time) ||
        point.time <= previous.time
      )
        break;
      const { x, y } = project(origin, point);
      const bounds = [Math.min(minX, x), Math.max(maxX, x), Math.min(minY, y), Math.max(maxY, y)];
      if (Math.hypot(bounds[1] - bounds[0], bounds[3] - bounds[2]) > 2 * config.stationaryRadiusM)
        break;
      [minX, maxX, minY, maxY] = bounds;
      length += distance(previous, point);
    }
    const last = end - 1;
    if (
      end - start >= 5 &&
      (points[last].time - origin.time) / 1000 >= config.stationaryDurationS &&
      length > 4 * config.stationaryRadiusM &&
      distance(origin, points[last]) <= config.stationaryRadiusM
    ) {
      const cloud = points.slice(start, end);
      const centre = {
        lat: median(cloud.map((point) => point.lat)),
        lon: longitude(
          origin.lon + median(cloud.map((point) => longitudeDelta(origin.lon, point.lon))),
        ),
      };
      for (let i = start; i < end; i++) {
        Object.assign(points[i], centre);
        flags[i].push('stationary-drift');
      }
    }
    start = Math.max(start + 1, last);
  }
}

function project(origin, point) {
  const scale = (6371000 * Math.PI) / 180;
  return {
    x: longitudeDelta(origin.lon, point.lon) * scale * Math.cos((origin.lat * Math.PI) / 180),
    y: (point.lat - origin.lat) * scale,
  };
}

function chordProjection(a, b, point) {
  const end = project(a, b),
    at = project(a, point);
  const squared = end.x ** 2 + end.y ** 2;
  const fraction = squared ? Math.max(0, Math.min(1, (at.x * end.x + at.y * end.y) / squared)) : 0;
  return { fraction, error: Math.hypot(at.x - fraction * end.x, at.y - fraction * end.y) };
}

// RDP with protected, well-resolved turns. Output retains one sample per source point;
// skipped positions are interpolated on the chord, keeping source indices/time/elevation aligned.
function smoothHorizontal(points, flags, tolerance) {
  if (!tolerance || points.length < 3) return;
  const original = points.map((point) => ({ ...point }));
  const anchors = [0];
  for (let i = 1; i < points.length - 1; i++) {
    const inbound = project(points[i - 1], points[i]),
      outbound = project(points[i], points[i + 1]);
    const first = Math.hypot(inbound.x, inbound.y),
      second = Math.hypot(outbound.x, outbound.y);
    if (
      Math.min(first, second) >= Math.min(3 * tolerance, 9) &&
      (inbound.x * outbound.x + inbound.y * outbound.y) / (first * second) < 0.5
    )
      anchors.push(i);
  }
  anchors.push(points.length - 1);
  const keep = new Set(anchors),
    stack = [];
  for (let i = 1; i < anchors.length; i++) stack.push([anchors[i - 1], anchors[i]]);
  while (stack.length) {
    const [start, end] = stack.pop();
    let error = tolerance,
      selected = -1;
    for (let i = start + 1; i < end; i++) {
      const candidate = chordProjection(original[start], original[end], original[i]).error;
      if (candidate > error) {
        error = candidate;
        selected = i;
      }
    }
    if (selected !== -1) {
      keep.add(selected);
      stack.push([start, selected], [selected, end]);
    }
  }
  const indices = [...keep].sort((a, b) => a - b);
  for (let j = 1; j < indices.length; j++) {
    const start = indices[j - 1],
      end = indices[j];
    for (let i = start + 1; i < end; i++) {
      Object.assign(
        points[i],
        interpolate(
          original[start],
          original[end],
          chordProjection(original[start], original[end], original[i]).fraction,
        ),
      );
      flags[i].push('horizontal-smoothing');
    }
  }
}

// Tiny priority queue for offline extrema cancellation (O(n log n)).
function queue() {
  const heap = [];
  return {
    push(item) {
      let index = heap.length;
      heap.push(item);
      while (index) {
        const parent = (index - 1) >> 1;
        if (heap[parent].delta <= item.delta) break;
        heap[index] = heap[parent];
        index = parent;
      }
      heap[index] = item;
    },
    pop() {
      const first = heap[0],
        last = heap.pop();
      if (heap.length) {
        let index = 0;
        while (index * 2 + 1 < heap.length) {
          let child = index * 2 + 1;
          if (child + 1 < heap.length && heap[child + 1].delta < heap[child].delta) child++;
          if (last.delta <= heap[child].delta) break;
          heap[index] = heap[child];
          index = child;
        }
        heap[index] = last;
      }
      return first;
    },
    get length() {
      return heap.length;
    },
  };
}

// Cancel small *reversals*, not small per-sample gains. Endpoints and sustained ramps survive.
function elevationTrend(values, positions, threshold) {
  if (!threshold || values.length < 2) return [...values];
  let low = Infinity,
    high = -Infinity;
  for (const value of values) {
    low = Math.min(low, value);
    high = Math.max(high, value);
  }
  let variation = 0;
  for (let i = 1; i < values.length; i++) variation += Math.abs(values[i] - values[i - 1]);
  if (high - low < threshold && variation > 2 * (high - low)) {
    const level = median(values);
    return values.map(() => level);
  }
  const indices = [0];
  let direction = 0;
  for (let i = 1; i < values.length; i++) {
    const next = Math.sign(values[i] - values[i - 1]);
    if (next && direction && next !== direction) indices.push(i - 1);
    if (next) direction = next;
  }
  indices.push(values.length - 1);
  const nodes = indices.map((index, order) => ({
    index,
    order,
    value: values[index],
    alive: true,
  }));
  nodes.forEach((node, i) => {
    node.prev = nodes[i - 1];
    node.next = nodes[i + 1];
  });
  const candidates = queue();
  function offer(left) {
    const right = left?.next;
    if (!left?.prev || !right?.next) return;
    const delta = Math.abs(right.value - left.value);
    if (
      delta < threshold &&
      delta <= Math.abs(left.value - left.prev.value) &&
      delta <= Math.abs(right.next.value - right.value)
    )
      candidates.push({ left, right, delta });
  }
  nodes.forEach(offer);
  while (candidates.length) {
    const { left, right } = candidates.pop();
    if (!left.alive || !right.alive || left.next !== right) continue;
    const before = left.prev,
      after = right.next;
    left.alive = false;
    right.alive = false;
    before.next = after;
    after.prev = before;
    offer(before.prev);
    offer(before);
    offer(after);
  }
  const result = [...values];
  for (let node = nodes[0]; node.next; node = node.next) {
    const end = node.next;
    // Untouched monotone spans retain their actual slope and plateau shape.
    if (end.order === node.order + 1) continue;
    for (let i = node.index; i <= end.index; i++) {
      const span = positions[end.index] - positions[node.index];
      const fraction =
        span > 0
          ? (positions[i] - positions[node.index]) / span
          : (i - node.index) / (end.index - node.index);
      result[i] = node.value + (end.value - node.value) * fraction;
    }
  }
  return result;
}

// A wider median should not shave a sustained slope or a resolved summit/valley.
function resolvedElevation(values, index, half, threshold) {
  const first = Math.max(0, index - half);
  const last = Math.min(values.length - 1, index + half);
  let rises = 0,
    falls = 0;
  for (let i = first + 1; i <= last; i++) {
    const delta = values[i] - values[i - 1];
    if (delta > 0) rises++;
    if (delta < 0) falls++;
  }
  if (!rises || !falls) return true;

  const value = values[index];
  let plateauStart = index,
    plateauEnd = index;
  while (plateauStart > first && values[plateauStart - 1] === value) plateauStart--;
  while (plateauEnd < last && values[plateauEnd + 1] === value) plateauEnd++;
  const left = Math.max(0, plateauStart - half),
    right = Math.min(values.length - 1, plateauEnd + half);
  let leftRises = 0,
    leftFalls = 0,
    rightRises = 0,
    rightFalls = 0;
  for (let i = left + 1; i <= plateauStart; i++) {
    const delta = values[i] - values[i - 1];
    if (delta > 0) leftRises++;
    if (delta < 0) leftFalls++;
  }
  for (let i = plateauEnd + 1; i <= right; i++) {
    const delta = values[i] - values[i - 1];
    if (delta > 0) rightRises++;
    if (delta < 0) rightFalls++;
  }
  const rise = value - values[left],
    drop = value - values[right];
  return (
    (leftRises >= 2 &&
      !leftFalls &&
      rightFalls >= 2 &&
      !rightRises &&
      rise >= 2 * threshold &&
      drop >= 2 * threshold) ||
    (leftFalls >= 2 &&
      !leftRises &&
      rightRises >= 2 &&
      !rightFalls &&
      -rise >= 2 * threshold &&
      -drop >= 2 * threshold)
  );
}

function smoothElevation(points, flags, config) {
  let start = 0;
  while (start < points.length) {
    if (!Number.isFinite(points[start].elevation)) {
      start++;
      continue;
    }
    let end = start + 1;
    while (end < points.length && Number.isFinite(points[end].elevation)) end++;
    const values = points.slice(start, end).map((point) => point.elevation);
    const positions = [0];
    let wideSteps = 0;
    for (let i = start + 1; i < end; i++) {
      const step = distance(points[i - 1], points[i]);
      positions.push(positions.at(-1) + step);
      if (step > 20) wideSteps++;
    }
    // Use a similar time span across recording cadences. With missing/slow timestamps,
    // retain the original seven-point fallback; explicit zero seconds fixes the point window.
    let half = (config.elevationWindow - 1) / 2;
    if (config.elevationWindowSeconds && half > 3) {
      const intervals = [];
      for (let i = start + 1; i < end; i++) {
        if (!Number.isFinite(points[i - 1].time) || !Number.isFinite(points[i].time)) continue;
        const seconds = (points[i].time - points[i - 1].time) / 1000;
        if (Number.isFinite(seconds) && seconds > 0) intervals.push(seconds);
      }
      const cadence = intervals.length ? median(intervals) : null;
      half = Math.min(
        half,
        cadence ? Math.max(3, Math.round(config.elevationWindowSeconds / (2 * cadence))) : 3,
      );
    }
    if (wideSteps > (values.length - 1) / 2) half = Math.min(1, half);
    const smoothed = values.map((value, i) =>
      i === 0 ||
      i === values.length - 1 ||
      resolvedElevation(values, i, half, config.elevationHysteresisM)
        ? value
        : median(values.slice(Math.max(0, i - half), Math.min(values.length, i + half + 1))),
    );
    const trend = elevationTrend(smoothed, positions, config.elevationHysteresisM);
    for (let i = start; i < end; i++) {
      if (smoothed[i - start] !== values[i - start]) flags[i].push('elevation-median');
      if (trend[i - start] !== smoothed[i - start]) flags[i].push('elevation-hysteresis');
      points[i].elevation = trend[i - start];
    }
    start = end;
  }
}

/** Batch-only stage-one engine. Does not parse GPX, write storage, or modify live recording.
 * Distances are kilometres, elevation/prefix gains metres, timestamps original milliseconds.
 * Raw and corrected point arrays preserve order, cardinality, segment boundaries and metadata.
 * Missing elevations remain missing; their global up/down values remain null.
 */
export function filterTrack(segments, options = {}) {
  const config = settings(options),
    rawSegments = snapshot(segments);
  const correctedSegments = rawSegments.map((segment) => segment.map((point) => ({ ...point })));
  const diagnostics = [];
  correctedSegments.forEach((points, segment) => {
    const flags = points.map(() => []);
    points.forEach((point, i) => {
      if (!positionReliable(point, config)) {
        point.excluded = true;
        point.elevation = null;
        flags[i].push('low-horizontal-accuracy');
      } else if (!elevationReliable(point, config)) {
        point.elevation = null;
        flags[i].push('low-altitude-accuracy');
      }
    });
    // Quality gaps are boundaries, not a reason to connect the good points on either side.
    let start = 0;
    while (start < points.length) {
      if (points[start].excluded) {
        start++;
        continue;
      }
      let end = start + 1;
      while (end < points.length && !points[end].excluded) end++;
      const section = points.slice(start, end),
        reasons = flags.slice(start, end);
      removeSpikes(rawSegments[segment].slice(start, end), section, reasons, config);
      // A new fast excursion is held until subsequent fixes establish whether it returns.
      // Once a return is available, removeSpikes above can recover it without a gap.
      const orderedTime = section.every(
        (point, i) => Number.isFinite(point.time) && (!i || point.time > section[i - 1].time),
      );
      for (let i = 1; i < section.length; i++) {
        const a = section[i - 1],
          b = section[i];
        if (
          orderedTime &&
          config.maxSpeedMps &&
          Number.isFinite(a.time) &&
          Number.isFinite(b.time) &&
          b.time > a.time &&
          distance(a, b) >= config.spikeLegM &&
          distance(a, b) / ((b.time - a.time) / 1000) > config.maxSpeedMps
        ) {
          b.excluded = true;
          b.elevation = null;
          reasons[i].push('unconfirmed-position-jump');
        }
      }
      let from = 0;
      while (from < section.length) {
        if (section[from].excluded) {
          from++;
          continue;
        }
        let to = from + 1;
        while (to < section.length && !section[to].excluded) to++;
        const usable = section.slice(from, to),
          usableFlags = reasons.slice(from, to);
        removeStationaryDrift(usable, usableFlags, config);
        smoothHorizontal(usable, usableFlags, config.horizontalToleranceM);
        smoothElevation(usable, usableFlags, config);
        from = to;
      }
      start = end;
    }
    flags.forEach((reasons, sourceIndex) => {
      if (reasons.length) diagnostics.push({ segment, sourceIndex, reasons });
    });
  });
  const points = indexTrack(correctedSegments);
  return {
    version: TRACK_FILTER_VERSION,
    options: config,
    rawSegments,
    rawStats: trackStats(rawSegments),
    correctedSegments,
    points,
    stats: trackStats(correctedSegments),
    diagnostics,
  };
}
