import { parseGpx } from '../gpx/parser.js';
import { recordingFix } from '../recording/analysis.js';
import { routeNetwork, trustedRerouteFix } from './rerouting.js';
import { canonicalLocation, smartHome, smartLocations, visitedStations } from './smart-location.js';
import { createSmartPlanner, startsAtSmartLocation, smartRequests } from './smart-routing.js';
import { smartSummary } from './smart-summary.js';

export function createSmartRerouteController({
  state,
  recordingRoute,
  planFor,
  compatible,
  acceptedPosition,
  referenceVersion,
  activate,
  render,
  yieldTask = () => new Promise((r) => setTimeout(r, 0)),
}) {
  const networks = new WeakMap(),
    parsed = new WeakMap();
  let generation = 0,
    disposed = false,
    session = null,
    reviewed = null;
  function sourceFor(file) {
    if (!file.rerouted) {
      const original = state.library.find((f) => f.id === file.id);
      if (original) return original;
      if (file.direction !== 'reverse') return file;
    } else {
      const embedded = state.gps.navigation?.active?.sourceRoute;
      if (embedded) return embedded;
      const id = state.gps.navigation?.active?.provenance?.[0]?.routeId;
      const original = state.library.find((f) => f.id === id);
      if (original) return original;
      const old = state.gps.navigation?.original?.file;
      if (old?.id === id && old.direction !== 'reverse') return old;
    }
    if (!parsed.has(file)) {
      if (!file.raw) throw new Error('找不到原始 GPX，無法可靠建立方案。');
      const id = state.gps.navigation?.active?.provenance?.[0]?.routeId ?? file.id;
      parsed.set(file, {
        ...parseGpx(file.raw, file.fileName ?? 'original.gpx'),
        id,
        raw: file.raw,
        kind: 'route',
        name: file.name,
      });
    }
    return parsed.get(file);
  }
  function context(preferred = null, requirePreferred = false) {
    const gps = state.gps,
      fix = recordingFix(gps),
      now = Date.now(),
      file = recordingRoute();
    if (!trustedRerouteFix(gps, fix, now))
      throw new Error('需要目前可信 GPS：請恢復定位，並取得 60 秒內、精度 50m 以內的位置。');
    if (!gps.sourceRouteId && !gps.navigation?.active)
      throw new Error('請先使用一份 GPX 作為參考路線，才能自動改道。');
    const plan = planFor(file),
      source = sourceFor(file);
    if (!plan || !source?.points?.length) throw new Error('目前沒有可規劃的原始 GPX 與站點資料。');
    let cached = networks.get(source);
    if (!cached) {
      const network = routeNetwork(source, planFor);
      cached = { network, planner: createSmartPlanner(network) };
      networks.set(source, cached);
    }
    const locations = smartLocations(
      file,
      plan,
      compatible() ? gps.itinerary : null,
      fix,
      compatible() ? acceptedPosition() : null,
    );
    const picked = preferred && locations.find((p) => p.id === preferred);
    if (requirePreferred && !picked) throw new Error('目前路段已改變，請重新預覽智慧改道方案。');
    const position = picked ?? (locations.length === 1 ? locations[0] : null);
    const location =
      position && canonicalLocation(file, plan, position, gps.navigation?.active?.provenance);
    const origin = gps.navigation?.original ?? { file, plan };
    const home = smartHome(
      source,
      planFor(source),
      origin.file,
      origin.plan ?? planFor(origin.file),
    );
    return {
      ...cached,
      gps,
      file,
      source,
      fix,
      now,
      locations,
      position,
      location,
      home,
      visited: visitedStations(gps, plan),
      starts: location ? startsAtSmartLocation(cached.network, fix, location) : [],
    };
  }
  const factor = () => state.gps.itinerary?.factor ?? state.itinerary.factor;
  function invalidated() {
    generation++;
    reviewed = null;
    session = null;
    delete state.itinerary.smart;
  }
  async function load(locationId = null) {
    const token = ++generation;
    reviewed = null;
    session = null;
    state.itinerary.smart = { busy: true, options: [], locations: [] };
    render();
    try {
      await yieldTask();
      if (disposed || token !== generation) return;
      const env = context(locationId);
      const guard = () =>
        !disposed &&
        generation === token &&
        state.gps === env.gps &&
        recordingRoute().id === env.file.id;
      session = {
        recordingId: env.gps.id,
        routeId: env.file.id,
        referenceVersion,
        locationId: env.position?.id ?? null,
      };
      if (!env.position) {
        state.itinerary.smart = {
          busy: false,
          options: [],
          locations: env.locations,
          error: env.locations.length
            ? '定位有多種可能，請先確認你所在的步道。'
            : 'GPS 偏離原 GPX 或沒有可信路段；無法自動改道。',
        };
        render();
        return;
      }
      const options = [];
      for (const request of smartRequests(env.network, env.home)) {
        await yieldTask();
        if (!guard()) return;
        let item;
        try {
          const variants = env.planner({
            request,
            starts: env.starts,
            location: env.location,
            home: env.home,
            visited: env.visited,
            now: env.now,
          });
          item = {
            ...request,
            available: true,
            paths: variants.length,
            summary: variants.length === 1 ? smartSummary(variants[0], factor(), env.now) : null,
          };
        } catch (error) {
          item = { ...request, available: false, reason: error.message };
        }
        options.push(item);
      }
      if (!guard()) return;
      if (!trustedRerouteFix(state.gps, recordingFix(state.gps)))
        throw new Error('規劃期間 GPS 已中斷或過期，請恢復定位後重試。');
      state.itinerary.smart = { busy: false, options, locations: [], asOf: env.fix.time };
      render();
      return options;
    } catch (error) {
      if (!disposed && token === generation) {
        state.itinerary.smart = { busy: false, options: [], locations: [], error: error.message };
        render();
      }
    }
  }
  function prepare(requestId, selectedPath = null, requireLocation = false) {
    if (
      !session ||
      session.recordingId !== state.gps.id ||
      session.routeId !== recordingRoute().id ||
      session.referenceVersion !== referenceVersion
    )
      throw new Error('原計畫已改變，請重新取得智慧改道選項。');
    const env = context(session.locationId, requireLocation);
    if (!env.position) throw new Error('目前位置有歧義，請重新確認步道。');
    const request = smartRequests(env.network, env.home).find((r) => r.id === requestId);
    if (!request) throw new Error('目的地已不可用，請重新取得選項。');
    const variants = env.planner({
      request,
      starts: env.starts,
      location: env.location,
      home: env.home,
      visited: env.visited,
      now: env.now,
      id: reviewed?.id,
    });
    if (selectedPath && !variants.some((p) => p.routeKey === selectedPath))
      throw new Error('原先預覽的路徑已不可用，請重新預覽。');
    return {
      env,
      request,
      variants,
      selected: selectedPath
        ? variants.find((p) => p.routeKey === selectedPath)
        : variants.length === 1
          ? variants[0]
          : null,
    };
  }
  function preview(requestId, path = null) {
    reviewed = null;
    if (state.itinerary.smart) {
      delete state.itinerary.smart.preview;
      delete state.itinerary.smart.alternatives;
      delete state.itinerary.smart.error;
    }
    const { env, request, variants, selected } = prepare(requestId, path);
    if (!selected) {
      state.itinerary.smart.alternatives = variants.map((p) => ({
        requestId,
        routeKey: p.routeKey,
        file: p.file,
        via: p.plan.rows.slice(1).map((r) => r.station.name),
        summary: smartSummary(p, factor(), env.now),
      }));
      render();
      return null;
    }
    session.locationId = env.position.id;
    reviewed = {
      requestId: request.id,
      routeKey: selected.routeKey,
      id: selected.file.id,
      locationId: env.position.id,
    };
    state.itinerary.smart.preview = {
      ...selected,
      summary: smartSummary(selected, factor(), env.now),
    };
    render();
    return selected;
  }
  function apply() {
    if (!reviewed) throw new Error('請先選擇並預覽智慧改道方案。');
    const selection = reviewed;
    const { env, selected } = prepare(selection.requestId, selection.routeKey, true);
    if (!selected?.plan.geometryComplete) throw new Error('路段無法可靠銜接，不能套用。');
    selected.file.id = selection.id;
    activate(
      {
        ...selected,
        smartRequest: { requestId: selection.requestId, routeKey: selection.routeKey },
        sourceRoute: env.source,
      },
      env.source,
    );
    invalidated();
    state.itinerary.smart = { applied: true, options: [], locations: [] };
    render();
    return true;
  }
  return {
    canApply: () =>
      Boolean(
        reviewed &&
        session?.recordingId === state.gps.id &&
        session?.routeId === recordingRoute().id &&
        trustedRerouteFix(state.gps, recordingFix(state.gps)),
      ),
    load,
    preview,
    apply,
    invalidate: invalidated,
    dispose() {
      disposed = true;
      invalidated();
    },
  };
}
