import { esc } from '../../ui/html.js';

export function timingIssuesPanel(data) {
  const issues = data.rows.flatMap((row, index) =>
    row.reason && index
      ? [{ from: data.rows[index - 1].station.name, to: row.station.name, reason: row.reason }]
      : [],
  );
  if (!issues.length) return '';
  return `<details class="soft-notice timing-issues"><summary>待核對的時間路段（${issues.length}）</summary><ul>${issues.map((issue) => `<li><strong>${esc(issue.from)} → ${esc(issue.to)}</strong><br>${esc(issue.reason)}</li>`).join('')}</ul><p class="small">這些路段確認前，後續 ETA 與日夜塗色可能仍有缺口。</p></details>`;
}
