import { button, esc } from '../../ui/html.js';
export function createRecordingActions({ state, recording, estimates, feedback }) {
  const { modal } = feedback;
  return {
    'gps-start': () => recording.start(),
    'gps-direct': () => recording.start(true),
    'gps-pause': recording.pause,
    'gps-resume': recording.resume,
    'gps-finish': recording.finish,
    'gps-finish-confirm': recording.finish,
    'gps-save': recording.save,
    'gps-no-save': recording.discard,
    'gps-download': recording.download,
    'gps-save-retry': recording.retrySave,
    'gps-reset': recording.reset,
    'gps-discard': () =>
      modal(
        '放棄這次紀錄？',
        '<p>會刪除此份尚未完成的草稿與軌跡，無法復原。需要保留時請先下載備份。</p>',
        button('放棄紀錄', 'gps-discard-confirm', 'primary'),
      ),
    'gps-discard-confirm': recording.discard,
    'calibration-start': estimates.begin,
    'calibration-end': () => {
      const active = state.gps.calibration?.active;
      if (!active) return;
      modal(
        '確認已到達路段終點？',
        `<p>${esc(active.label)} · 上河 1.0：${active.baseMinutes} 分鐘</p><p>請確認已走完同一段路線，且行走方向與基準一致。</p>`,
        button('已完成相同路段', 'calibration-end-confirm', 'primary'),
      );
    },
    'calibration-end-confirm': estimates.complete,
    'calibration-cancel': estimates.cancel,
    'estimate-update': estimates.update,
  };
}
