import { esc } from '../../ui/html.js';
import { arrival } from './views.js';

export function itineraryMarkers(data) {
  if (!data) return [];
  const points = new Map();
  for (const row of data.rows.filter((row) => row.visible)) {
    if (points.has(row.station.stationId)) continue;
    points.set(row.station.stationId, {
      ...row.station,
      label: esc(row.station.name),
      arrivalLabel: data.active ? arrival(row.arrivalUtcMs) : '',
      next: row.station.stationId === data.next?.station.stationId,
    });
  }
  return [...points.values()];
}
export function createStationLayer(leaflet, map, stations) {
  if (!stations.length) return null;
  const group = leaflet.featureGroup().addTo(map);
  for (const station of stations)
    leaflet
      .circleMarker([station.lat, station.lon], {
        radius: station.next ? 8 : 6,
        color: '#fff',
        weight: 2,
        fillColor: station.next ? '#b87930' : '#326753',
        fillOpacity: 1,
      })
      .bindTooltip(
        `${station.label}${station.arrivalLabel ? ' · ' + esc(station.arrivalLabel) : ''}`,
        { direction: 'top' },
      )
      .addTo(group);
  return group;
}
