import { recordingSnapshot } from './model.js';
export function createRecordingPersistence({
  state,
  repository,
  gpsActive,
  onStatus = () => {},
  captureCheckpoint = () => Promise.resolve(null),
  navigator = globalThis.navigator,
}) {
  let saveQueue = Promise.resolve(),
    saveTimer = null,
    releaseRecordingLock = null,
    saveRevision = 0,
    disposed = false;
  async function acquireRecordingLock() {
    if (disposed) return false;
    if (releaseRecordingLock) return true;
    if (!navigator.locks?.request) {
      state.recordingBlocked =
        '此瀏覽器無法安全協調紀錄保存，請用新版 Chrome、Edge 或 Safari，由 HTTPS 或 localhost 開啟。';
      return false;
    }
    return new Promise((resolve) => {
      navigator.locks
        .request('ridgewise-recording-writer', { ifAvailable: true }, async (lock) => {
          if (disposed) {
            resolve(false);
            return;
          }
          if (!lock) {
            state.recordingBlocked =
              '另一個分頁正在處理紀錄，請回到原分頁，或關閉原分頁後重新整理。';
            resolve(false);
            return;
          }
          const held = new Promise((release) => {
            releaseRecordingLock = release;
          });
          state.recordingBlocked = '';
          resolve(true);
          await held;
        })
        .catch(() => {
          state.recordingBlocked = '無法取得紀錄保存權限，請重新整理後再試。';
          resolve(false);
        });
    });
  }
  function saveDraft() {
    clearTimeout(saveTimer);
    saveTimer = null;
    const gps = state.gps;
    if (disposed || !gps.id || !gpsActive() || ['finishing', 'discarding'].includes(gps.status))
      return Promise.resolve(false);
    const snapshot = recordingSnapshot(gps),
      revision = ++saveRevision;
    // Capture engine state in the same turn as the GPS snapshot, before asynchronous hashing/writes.
    let captured = Promise.resolve(null);
    try {
      captured = Promise.resolve(captureCheckpoint(gps, snapshot)).catch(() => null);
    } catch {
      // Source/checkpoint failures must not lose the raw recording.
    }
    delete snapshot.liveFactorCheckpoint;
    gps.saving = true;
    onStatus();
    const write = saveQueue.then(async () => {
      try {
        const sealed = await captured;
        if (sealed) snapshot.liveFactorCheckpoint = sealed;
        await repository.saveDraft(snapshot);
        if (state.gps === gps) {
          gps.savedAt = snapshot.updatedAt;
          gps.saveError = '';
        }
        return true;
      } catch {
        if (state.gps === gps)
          gps.saveError = '自動保存失敗，最新紀錄僅在此分頁。請下載備份，再按「重試保存」。';
        return false;
      } finally {
        if (state.gps === gps && revision === saveRevision) {
          gps.saving = false;
          onStatus();
        }
      }
    });
    saveQueue = write.then(() => {});
    return write;
  }
  function scheduleSave() {
    if (!disposed && !saveTimer)
      saveTimer = setTimeout(() => {
        saveTimer = null;
        saveDraft();
      }, 2000);
  }
  function saveStatus() {
    const gps = state.gps;
    if (gps.saveError) return gps.saveError;
    if (gps.saving) return '正在保存…';
    if (saveTimer) return '新資料待保存（最多兩秒）';
    return gps.savedAt
      ? `草稿已保留 · ${new Date(gps.savedAt).toLocaleTimeString('zh-TW', { timeZone: 'Asia/Taipei' })}`
      : '等待保存';
  }
  function releaseWriter() {
    releaseRecordingLock?.();
    releaseRecordingLock = null;
  }
  function cancelScheduled() {
    clearTimeout(saveTimer);
    saveTimer = null;
  }
  async function dispose() {
    disposed = true;
    cancelScheduled();
    await saveQueue;
    releaseWriter();
  }

  return {
    save: saveDraft,
    schedule: scheduleSave,
    status: saveStatus,
    acquireLock: acquireRecordingLock,
    releaseLock: releaseWriter,
    cancelScheduled,
    settle: () => saveQueue,
    dispose,
  };
}
