import { predictEta } from '../../../../packages/prediction-engine/eta.js';
import { mapTimeNodes } from './data.js';
import { matchItinerary, DISPLAY_TYPES } from './matching.js';
import { createTimeGraph } from './time-path.js';
import { stationMembers } from './station-groups.js';
import { resolveTimeLeg } from './leg-resolution.js';
import { buildShangheTimeModel } from './time-interpolation.js';
export { shangheTimeAt, shangheSecondsAt } from './time-interpolation.js';

export function buildItinerary(resources, file, { slopeOptions = {} } = {}) {
  const ids = mapTimeNodes(resources.stations, resources.adapter);
  const graph = createTimeGraph(resources.database);
  const matched = matchItinerary(resources.stations, file, { ids, graph });
  const matchedIds = new Set(
    matched.occurrences.flatMap((point) => stationMembers(point.station).map((s) => s.stationId)),
  );
  const nodes = new Map((resources.database?.nodes ?? []).map((node) => [node.id, node]));
  const nodePlaces = new Map(
    resources.stations
      .filter((s) => s.coordinateStatus === 'located' && s.placeId)
      .map((s) => [ids.get(s.stationId), s.placeId]),
  );
  const excluded = new Set(
    resources.stations
      .filter((s) => s.coordinateStatus === 'located' && !matchedIds.has(s.stationId))
      .map((s) => ids.get(s.stationId))
      .filter(Boolean),
  );
  const rows = matched.occurrences.map((point, index) => ({
    ...point,
    index,
    nodeId: ids.get(point.station.stationId),
    nodeBindings: stationMembers(point.station)
      .map((s) => ({ id: ids.get(s.stationId), area: s.area }))
      .filter((binding) => binding.id),
    visible: DISPLAY_TYPES.has(point.station.type),
  }));
  const segments = [];
  rows.forEach((row, index) => {
    if (!index) {
      row.baselineSeconds = 0;
      row.incoming = [];
      return;
    }
    const previous = rows[index - 1];
    const result = resources.adapter
      ? resolveTimeLeg({
          previous,
          row,
          rows,
          excluded,
          graph,
          adapter: resources.adapter,
          nodes,
          nodePlaces,
        })
      : { reason: '尚未載入上河時間資料' };
    row.reason = result.reason;
    row.incoming = [];
    if (result.segments) {
      row.incoming = result.segments.map((segment, leg) => ({
        ...segment,
        id: `visit-${index}-leg-${leg}`,
      }));
      row.timeNodeNames = result.names;
      row.referenceAreas = result.referenceAreas;
      row.referenceSources = result.referenceSources;
    }
    if (!row.incoming.length)
      row.incoming = [
        {
          id: `visit-${index}-unavailable`,
          fromWaypointId: previous.station.placeId ?? previous.nodeId ?? previous.station.stationId,
          toWaypointId: row.station.placeId ?? row.nodeId ?? row.station.stationId,
          baselineMoveSeconds: null,
          timeStatus: 'missing',
          mode: 'walk',
          sourceIds: [],
        },
      ];
    row.baselineSeconds = row.reason
      ? null
      : row.incoming.reduce((sum, s) => sum + s.baselineMoveSeconds, 0);
    row.gap = previous.segmentIndex !== row.segmentIndex;
    segments.push(...row.incoming);
  });
  return { ...matched, rows, segments, timeModel: buildShangheTimeModel(file, rows, slopeOptions) };
}
export function forecastItinerary(plan, factor, departure, journey) {
  const rows = plan.rows.map((row) => ({ ...row, arrivalUtcMs: null, cumulativeSeconds: null }));
  if (rows.length < 2)
    return { ...plan, rows, totalSeconds: null, complete: false, observedFactor: null };
  const base = predictEta({
    segments: plan.segments,
    multiplier: factor,
    departureUtcMs: departure ?? 0,
  });
  const legs = new Map(base.segments.map((segment) => [segment.segmentId, segment]));
  rows.forEach((row, index) => {
    const leg = legs.get(row.incoming.at(-1)?.id);
    row.cumulativeSeconds = index === 0 ? 0 : (leg?.cumulativeSeconds ?? null);
    row.arrivalUtcMs =
      departure === null || !plan.startCovered
        ? null
        : index === 0
          ? departure
          : (leg?.predictedArrivalUtcMs ?? null);
  });
  const arrivals = journey?.arrivals ?? {};
  const anchors = Object.keys(arrivals)
    .map(Number)
    .filter((index) => Number.isInteger(index) && rows[index] && Number.isFinite(arrivals[index]))
    .sort((a, b) => a - b);
  const anchor = anchors.at(-1);
  if (anchor !== undefined) {
    const remaining = rows.slice(anchor + 1).flatMap((row) => row.incoming);
    const updated = remaining.length
      ? predictEta({ segments: remaining, multiplier: factor, departureUtcMs: arrivals[anchor] })
      : null;
    const updatedLegs = new Map(
      updated?.segments.map((segment) => [segment.segmentId, segment]) ?? [],
    );
    rows.forEach((row, index) => {
      if (index < anchor) row.arrivalUtcMs = arrivals[index] ?? row.arrivalUtcMs;
      else if (index === anchor) row.arrivalUtcMs = arrivals[anchor];
      else
        row.arrivalUtcMs = updatedLegs.get(row.incoming.at(-1)?.id)?.predictedArrivalUtcMs ?? null;
    });
  }
  let observedFactor = null;
  if (anchors.length > 1) {
    const first = anchors[0],
      last = anchors.at(-1),
      range = rows.slice(first + 1, last + 1);
    if (range.every((row) => row.baselineSeconds !== null)) {
      const reference = range.reduce((sum, row) => sum + row.baselineSeconds, 0);
      if (reference > 0) observedFactor = (arrivals[last] - arrivals[first]) / 1000 / reference;
    }
  }
  return {
    ...plan,
    rows,
    totalSeconds:
      base.complete && plan.startCovered && plan.endCovered ? base.totalPredictedSeconds : null,
    complete: base.complete && plan.startCovered && plan.endCovered,
    observedFactor,
  };
}
