import { recordingStats } from './analysis.js';
import { button, esc } from '../../ui/html.js';
import { elapsedLabel } from '../../domain/track.js';
export function completionView(gps, elapsed) {
  const stats = recordingStats(gps),
    busy = ['stopping', 'finishing', 'discarding'].includes(gps.status);
  return `<section class="completion-sheet" aria-labelledby="completion-title"><div class="sheet-handle"></div><span class="eyebrow">這次山行已結束</span><h2 id="completion-title">要保存這次紀錄嗎？</h2><p>GPS 已停止。你可以決定是否留下這段軌跡。</p><div class="completion-stats"><div><small>紀錄時間</small><strong>${elapsedLabel(elapsed)}</strong></div><div><small>校正距離</small><strong>${stats.km.toFixed(2)} <small>km</small></strong></div></div>${gps.saveError ? `<p id="gps-save-status" class="error-message" role="status">${esc(gps.saveError)}</p>` : '<p id="gps-save-status" class="small muted">尚未加入「我的 GPX」</p>'}${button(busy ? '處理中…' : '保存至我的 GPX', 'gps-save', 'primary', 'folder', busy || !stats.points ? 'disabled' : '')}${button('不保存，返回', 'gps-no-save', '', '', busy ? 'disabled' : '')}${stats.points ? button('下載 GPX 備份', 'gps-download', 'ghost', 'download', busy ? 'disabled' : '') : '<p class="small muted">未取得座標，沒有可以保存的軌跡。</p>'}<p class="small muted">不保存只會移除這次紀錄，已匯入與已保存的資料會保留。</p></section>`;
}
