import { button, esc } from '../../ui/html.js';
import { timeOriginFor, timeOriginLabel } from '../../domain/time-origin.js';

export function timeSourcePanel(file, { locked = false, error = '' } = {}) {
  const origin = timeOriginFor(file);
  const confirmed = origin.assurance === 'user-confirmed';
  const local = origin.assurance === 'ridgewise-local';
  const disabled = locked || file.direction === 'reverse';
  const edges = (file.timeWeights?.intervals ?? []).filter((i) => i.status !== 'segment-break');
  const good = edges.filter(
    (i) => ['moving', 'stationary'].includes(i.status) && !i.issues.length,
  ).length;
  return `<section class="panel panel-body stack" id="gpx-time-source" aria-label="GPX 時間來源">
    <h2>GPX 時間來源</h2><p class="small" data-time-assurance="${origin.assurance}">${esc(timeOriginLabel(origin))}</p>
    <details id="gpx-time-source-details"><summary>時間品質與分配方式</summary><div class="stack">
    <p class="small muted">${local ? `來源：本機錄製紀錄 ${esc(origin.recordingId)}。可追溯到錄製方式與原始內容，不代表衛星定位或裝置未被模擬。` : '使用者確認只是你的聲明，不等於來源已驗證；本程式不驗證外部 GPX 的真實性。'}</p>
    <p class="small muted">時間品質可用區間 ${good} / ${edges.length}。只在同方向、完整且品質通過的站間使用移動比例；異常、缺漏時改用坡度加權，無完整高度則用距離。未知上河路段與 GPX 中斷不補時間。</p></div></details>
    ${file.direction === 'reverse' ? '<p class="soft-notice">來源設定只適用 GPX 原向。反向不借用正向移動比例，仍使用反向坡度／距離模型。</p>' : ''}
    ${origin.reason === 'nonrecorded-gpx-time' ? '<p class="soft-notice">此檔含規劃、合成或補寫時間標記，確認不會解除這項限制；仍使用坡度／距離模型。</p>' : ''}
    ${origin.reason === 'time-source-content-mismatch' ? '<p class="soft-notice">內容與原有來源設定不一致，已停用時間比例；請重新核對後再確認。</p>' : ''}
    ${
      local || confirmed
        ? confirmed
          ? button(
              '撤回時間來源確認',
              'time-source-revoke',
              'ghost',
              '',
              `data-id="${esc(file.id)}" ${disabled ? 'disabled' : ''}`,
            )
          : ''
        : `
      <label class="small"><input type="checkbox" id="gpx-actual-gps" ${disabled ? 'disabled' : ''}> 我確認這份 GPX 是實際 GPS 軌跡紀錄</label>
      <label class="small"><input type="checkbox" id="gpx-original-time" ${disabled ? 'disabled' : ''}> 我確認時間戳不是人工產生或補寫</label>
      ${button('確認並使用有效時間比例', 'time-source-confirm', '', '', `data-id="${esc(file.id)}" ${disabled ? 'disabled' : ''}`)}`
    }
    ${error ? `<p class="error-message" role="status">${esc(error)}</p>` : ''}
    <p class="small muted">不修改原始 GPX 或上河基準；設定僅保存在此裝置，下載後重新匯入的檔案需重新確認。${locked ? '錄製或保存設定期間不能變更來源。' : ''}</p>
    </section>`;
}
