import { prepareTrack, trackStats } from '../../domain/track.js';
import { inheritTimeOrigin } from '../../domain/time-origin.js';
const reversedRoutes = new WeakMap();
const reverseSegments = (segments) =>
  segments
    .slice()
    .reverse()
    .map((segment) => segment.slice().reverse());
export const normalizeDirection = (value) => (value === 'reverse' ? 'reverse' : 'forward');
// The library always owns the original GPX; this is a cached planning view only.
export function routeForDirection(file, direction) {
  if (!file || file.kind === 'recording' || normalizeDirection(direction) === 'forward')
    return file;
  if (!reversedRoutes.has(file)) {
    const rawSegments = file.rawSegments && reverseSegments(file.rawSegments);
    const segments = reverseSegments(file.segments).map((segment) =>
      segment.map((point) =>
        Number.isInteger(point.rawSegment)
          ? {
              ...point,
              rawSegment: file.rawSegments.length - 1 - point.rawSegment,
              rawIndex: file.rawSegments[point.rawSegment].length - 1 - point.rawIndex,
            }
          : point,
      ),
    );
    reversedRoutes.set(file, {
      ...file,
      segments,
      ...prepareTrack(segments, {
        timeWeights: !!file.timeWeights,
        timeWeightOptions: { source: 'reverse-planning' },
      }),
      ...(file.processing && file.stats.excludedPoints
        ? {
            stats: {
              ...file.stats,
              up: file.stats.down,
              down: file.stats.up,
              segments: segments.length,
            },
          }
        : {}),
      ...(rawSegments
        ? {
            rawSegments,
            rawStats: trackStats(rawSegments),
            processing: {
              ...file.processing,
              diagnostics: (file.processing?.diagnostics ?? []).map((item) => ({
                ...item,
                segment: file.rawSegments.length - 1 - item.segment,
                sourceIndex: file.rawSegments[item.segment].length - 1 - item.sourceIndex,
              })),
            },
          }
        : {}),
      direction: 'reverse',
    });
    inheritTimeOrigin(file, reversedRoutes.get(file));
  }
  return reversedRoutes.get(file);
}
