import { LOAD_VARIANTS, failure } from './contracts.js';

function minutesToSeconds(minutes) {
  const [mantissa, exponent = '0'] = String(minutes).toLowerCase().split('e');
  const [whole, fraction = ''] = mantissa.split('.');
  return Number(`${BigInt(whole + fraction) * 60n}e${Number(exponent) - fraction.length}`);
}

export function selectDirectedTime(pairs, area, from, to, profile) {
  const group = pairs.get(JSON.stringify([area, from.id, to.id])) ?? [];
  if (!group.length) return failure('missing_directed_edge');
  if (group.some(r => r.imageVerification === 'image_text_difference')) return failure('image_text_difference', group);
  if (group.some(r => r.sourceAccessRestriction)) return failure('source_access_restriction', group);
  let chosen = group.filter(r => r.mode === 'walk' || (profile.mode === 'walking' && r.mode === 'road_walk'));
  if (!chosen.length) return failure('mode_excluded', group, { modes: [...new Set(group.map(r => r.mode))] });
  if (new Set(chosen.map(r => r.mode)).size > 1) return failure('transport_choice_required', chosen);
  if (chosen.some(r => r.load === 'unknown')) return failure('unknown_condition', chosen);
  const loads = [...new Set(chosen.map(r => r.load).filter(load => load !== 'unspecified'))];
  if (loads.length) {
    if (!loads.includes(profile.load)) return failure('load_unavailable', chosen, { availableLoads: loads });
    if (chosen.some(r => r.load === 'unspecified')) return failure('load_applicability_ambiguous', chosen);
    chosen = chosen.filter(r => r.load === profile.load);
  }
  if (chosen.some(r => (r.speedVariant !== null && !['fast', 'slow'].includes(r.speedVariant))
    || (r.timeVariant !== null && !['fast', 'slow'].includes(r.timeVariant) && !LOAD_VARIANTS.has(r.timeVariant)))) {
    return failure('unknown_condition', chosen);
  }
  if (chosen.some(r => (LOAD_VARIANTS.has(r.timeVariant) && LOAD_VARIANTS.get(r.timeVariant) !== r.load)
    || (['fast', 'slow'].includes(r.timeVariant) && r.timeVariant !== r.speedVariant))) {
    return failure('condition_metadata_conflict', chosen);
  }
  const variants = [...new Set(chosen.map(r => r.speedVariant).filter(value => value !== null))];
  if (variants.length) {
    if (profile.speed === null) return failure('time_variant_required', chosen, { availableSpeeds: variants });
    if (!variants.includes(profile.speed)) return failure('time_variant_unavailable', chosen, { availableSpeeds: variants });
    if (chosen.some(r => r.speedVariant === null)) return failure('variant_applicability_ambiguous', chosen);
    chosen = chosen.filter(r => r.speedVariant === profile.speed);
  }
  const values = new Set(chosen.map(r => JSON.stringify([r.baselineMinutes, r.distanceM, r.timeStatus, r.restIncluded])));
  if (values.size > 1 || chosen.some(r => r.dataStatus === 'conflict')) return failure('conflicting_directed_edge', chosen);
  if (chosen.some(r => r.baselineMinutes === null || r.timeStatus !== 'known')) return failure('missing_time', chosen);
  const seconds = minutesToSeconds(chosen[0].baselineMinutes);
  if (!Number.isFinite(seconds) || seconds <= 0) return failure('time_conversion_out_of_range', chosen);
  return { records: chosen, seconds };
}
