import { createOfflineRenderer } from '../offline-map/map.js';
import { createStationLayer } from '../itinerary/markers.js';
import { createTerrain3dController } from './terrain-3d.js';
export const MAP_SOURCES = {
  standard: {
    label: 'OSM 標準地圖',
    url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
    options: {
      minZoom: 1,
      maxNativeZoom: 19,
      maxZoom: 19,
      detectRetina: false,
      referrerPolicy: 'strict-origin-when-cross-origin',
      attribution:
        '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    },
  },
  opentopo: {
    label: 'OpenTopo 地形底圖',
    url: 'https://tile.opentopomap.org/{z}/{x}/{y}.png',
    options: {
      minZoom: 1,
      maxNativeZoom: 17,
      maxZoom: 19,
      detectRetina: false,
      attribution:
        'Map data: &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors | DEM: <a href="https://viewfinderpanoramas.org/">SRTM</a>, <a href="https://sonny.4lima.de/">Sonny</a> | Map style: &copy; <a href="https://opentopomap.org/">OpenTopoMap</a> (<a href="https://creativecommons.org/licenses/by-sa/3.0/">CC-BY-SA</a>)',
    },
  },
};

// The map owns its DOM node, which survives the application's full-page renders.
// Only an explicit fit action changes the view after the first route display.
export function createTerrainMapController({
  leaflet = globalThis.L,
  onStatus = () => {},
  onCamera = () => {},
  load3d,
  offlineMaps,
} = {}) {
  let terrainMap = null,
    canvas = null,
    routeKey = null,
    overlay = null,
    liveOverlay = null,
    stationOverlay = null,
    tiles = null;
  let currentFile = null,
    currentLive = [],
    mapMode = 'plain',
    attempt = 0,
    tileTimer = null;
  let status = { kind: 'off', message: '單純軌跡模式，不載入底圖。' };
  let offlineTarget = null,
    hasCoordinates = false;
  const views = new Map();
  let requestedMode = 'plain',
    terrainContext = null;
  const report = (kind, message) => {
    status = { kind, message };
    onStatus(status);
  };
  const terrain3d = createTerrain3dController({
    onStatus,
    onCamera,
    ...(load3d ? { load: load3d } : {}),
    onFallback: (context) => {
      if (requestedMode !== 'terrain' || !context.slot) return;
      mount(context.slot, context.file, context.live, 'plain', context.stations);
      requestedMode = 'terrain';
      report('error', context.message);
    },
  });
  let usingOffline = false,
    offlineFailed = false,
    lastContext;
  const offlineRenderer = createOfflineRenderer({
    onStatus,
    onFallback: (context) => {
      offlineFailed = true;
      usingOffline = false;
      if (context.slot) mount(context.slot, context.file, context.live, 'plain', context.stations);
      requestedMode = 'standard';
    },
  });
  const clearTileTimer = () => {
    if (tileTimer !== null) clearTimeout(tileTimer);
    tileTimer = null;
  };

  function removeTiles() {
    attempt++;
    clearTileTimer();
    if (tiles) {
      terrainMap?.removeLayer(tiles);
      tiles.off();
      tiles = null;
    }
  }
  function offline() {
    if (!terrainMap || mapMode === 'plain') return;
    removeTiles();
    report('error', '目前沒有網路，GPX 路線仍可查看；恢復連線後可重試底圖。');
  }
  function startTiles() {
    removeTiles();
    const source = MAP_SOURCES[mapMode];
    if (!terrainMap || !source) return;
    // file:// pages cannot send the Referer required by OSM's tile service.
    if (mapMode === 'standard' && globalThis.location?.protocol === 'file:') {
      report('error', 'OSM 標準地圖請由本機預覽網站開啟；目前仍可查看 GPX 軌跡。');
      return;
    }
    if (globalThis.navigator?.onLine === false) {
      offline();
      return;
    }
    const thisAttempt = attempt;
    let failed = false,
      loaded = 0;
    const active = () => terrainMap && mapMode !== 'plain' && attempt === thisAttempt;
    const timeout = () => {
      clearTileTimer();
      tileTimer = setTimeout(() => {
        if (!active()) return;
        failed = true;
        report('error', `${source.label}載入逾時，GPX 路線仍可查看；可按重試重新載入。`);
      }, 15000);
      tileTimer.unref?.();
    };
    report('loading', `正在載入${source.label}…`);
    tiles = leaflet.tileLayer(source.url, { ...source.options });
    tiles.on('loading', () => {
      if (!active()) return;
      loaded = 0;
      if (!failed) report('loading', `正在載入${source.label}…`);
      timeout();
    });
    tiles.on('tileload', () => {
      if (active()) loaded++;
    });
    tiles.on('tileerror', () => {
      if (!active()) return;
      failed = true;
      report('error', `部分${source.label}無法載入，GPX 路線仍可查看；可按重試重新載入。`);
    });
    tiles.on('load', () => {
      if (!active()) return;
      clearTileTimer();
      if (failed) return;
      if (loaded) report('ready', `${source.label}已載入。`);
      else report('error', `尚未取得${source.label}，GPX 路線仍可查看；可按重試重新載入。`);
    });
    timeout();
    tiles.addTo(terrainMap);
  }

  function coordinates(segment) {
    const reference = currentFile.points[0]?.lon ?? currentLive.flat()[0]?.lon ?? 121;
    return segment
      .filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lon))
      .map((point) => [point.lat, reference + ((point.lon - reference + 540) % 360) - 180]);
  }
  function allCoordinates() {
    return [...currentFile.segments, ...currentLive].flatMap(coordinates);
  }
  function path(segment, color, weight, group) {
    const points = coordinates(segment);
    if (points.length > 1)
      leaflet.polyline(points, { color, weight, opacity: 1, interactive: false }).addTo(group);
  }
  function marker(point, color, label, group, radius = 6) {
    const coordinate = coordinates([point])[0];
    if (!coordinate) return;
    leaflet
      .circleMarker(coordinate, {
        radius,
        color: '#ffffff',
        weight: 3,
        fillColor: color,
        fillOpacity: 1,
      })
      .bindTooltip(label, { direction: 'top' })
      .addTo(group);
  }
  function drawRoute() {
    if (overlay) terrainMap.removeLayer(overlay);
    overlay = leaflet.featureGroup().addTo(terrainMap);
    for (const segment of currentFile.segments) path(segment, '#ffffff', 8, overlay);
    for (const segment of currentFile.segments) path(segment, '#326753', 4, overlay);
    if (currentFile.points.length) {
      marker(currentFile.points[0], '#183e35', 'GPX 起點', overlay);
      marker(currentFile.points.at(-1), '#8daa64', 'GPX 終點', overlay);
    }
  }
  function drawLive() {
    if (liveOverlay) terrainMap.removeLayer(liveOverlay);
    liveOverlay = leaflet.featureGroup().addTo(terrainMap);
    for (const segment of currentLive) path(segment, '#4388b7', 4, liveOverlay);
    const lastLive = currentLive.findLast((segment) => segment.length)?.at(-1);
    if (lastLive) marker(lastLive, '#d88d55', '最新 GPS 紀錄位置', liveOverlay, 8);
  }
  function fit() {
    if (usingOffline) {
      offlineRenderer.fit();
      return;
    }
    if (requestedMode === 'terrain' && !terrain3d.unavailable()) {
      terrain3d.fit();
      return;
    }
    if (!terrainMap || !currentFile) return;
    const points = allCoordinates();
    if (points.length)
      terrainMap.fitBounds(leaflet.latLngBounds(points), {
        padding: [30, 30],
        maxZoom: 15,
        animate: false,
      });
  }
  function releaseMap() {
    if (terrainMap) {
      views.set(routeKey, { center: terrainMap.getCenter(), zoom: terrainMap.getZoom() });
      // View history is session-only and bounded even after many GPX imports.
      if (views.size > 20) views.delete(views.keys().next().value);
    }
    removeTiles();
    offlineTarget?.removeEventListener('offline', offline);
    offlineTarget = null;
    terrainMap?.remove();
    canvas?.remove();
    terrainMap = canvas = overlay = liveOverlay = stationOverlay = routeKey = currentFile = null;
    currentLive = [];
    hasCoordinates = false;
    mapMode = 'plain';
    status = { kind: 'off', message: '單純軌跡模式，不載入底圖。' };
  }
  function beforeRender() {
    canvas?.remove();
    terrain3d.beforeRender();
    offlineRenderer.beforeRender();
  }
  function mount(slot, file, live = [], mode = 'standard', stations = []) {
    requestedMode = mode;
    lastContext = { slot, file, live, mode, stations };
    if (!slot || !file || (!file.points?.length && !file.recording)) {
      releaseMap();
      offlineRenderer.mount(null, null);
      usingOffline = false;
      offlineFailed = false;
      terrain3d.mount(null, null);
      terrainContext = null;
      return;
    }
    const key = file.id ?? file;
    const offlinePack = mode === 'standard' && !offlineFailed ? offlineMaps?.forRoute(file) : null;
    if (offlinePack) {
      const center = terrainMap?.getCenter();
      const camera =
        terrainMap && routeKey === key
          ? {
              key,
              center: [center.lat ?? center[0], center.lng ?? center[1]],
              zoom: terrainMap.getZoom(),
            }
          : terrain3d.view()?.key === key
            ? terrain3d.view()
            : views.has(key)
              ? { ...views.get(key), key }
              : null;
      releaseMap();
      terrain3d.mount(null, null);
      usingOffline = true;
      offlineRenderer.mount(slot, file, live, stations, offlinePack, camera);
      return;
    }
    if (usingOffline) {
      const previous = offlineRenderer.view();
      if (previous?.key) views.set(previous.key, previous);
      offlineRenderer.mount(null, null);
      usingOffline = false;
    }
    if (mode !== 'standard') offlineFailed = false;
    if (mode === 'terrain') terrainContext = { slot, file, live, stations };
    if (mode === 'terrain' && !terrain3d.unavailable()) {
      const center = terrainMap?.getCenter();
      const camera =
        terrainMap && routeKey === key
          ? {
              center: [center.lat ?? center[0], center.lng ?? center[1]],
              zoom: terrainMap.getZoom(),
            }
          : null;
      releaseMap();
      terrain3d.mount(slot, file, live, camera, stations);
      return;
    }
    const from3d = terrain3d.view();
    if (from3d?.key === key) views.set(key, from3d);
    terrain3d.mount(null, null);
    const nextMode = Object.hasOwn(MAP_SOURCES, mode) ? mode : 'plain';
    if (!leaflet?.map) {
      releaseMap();
      report('error', '地圖元件無法載入，目前顯示 GPX 平面軌跡。');
      return;
    }
    if (terrainMap && routeKey !== key) releaseMap();
    const changedRoute = !terrainMap || currentFile !== file;
    const firstFix = terrainMap && !hasCoordinates && live.some((segment) => segment.length);
    currentFile = file;
    currentLive = live;
    if (!terrainMap) {
      routeKey = key;
      canvas = slot.ownerDocument.createElement('div');
      canvas.className = 'terrain-map-canvas';
      canvas.setAttribute('aria-label', 'GPX 路線地圖，可使用方向鍵移動及加減鍵縮放');
      slot.replaceChildren(canvas);
      terrainMap = leaflet.map(canvas, {
        zoomControl: false,
        minZoom: 1,
        maxZoom: 19,
        zoomSnap: 0,
        scrollWheelZoom: true,
        touchZoom: true,
      });
      leaflet.control
        .zoom({
          position: 'topright',
          zoomInTitle: '放大路線圖',
          zoomOutTitle: '縮小路線圖',
          zoomInText: '+',
          zoomOutText: '−',
        })
        .addTo(terrainMap);
      leaflet.control.scale({ imperial: false, position: 'bottomleft' }).addTo(terrainMap);
      const previous = views.get(key);
      if (previous) terrainMap.setView(previous.center, previous.zoom, { animate: false });
      else if (allCoordinates().length) fit();
      else terrainMap.setView([23.7, 121], 7, { animate: false });
      offlineTarget = globalThis.window;
      offlineTarget?.addEventListener('offline', offline);
    } else {
      slot.replaceChildren(canvas);
      terrainMap.invalidateSize({ pan: false, animate: false });
    }
    if (changedRoute) drawRoute();
    drawLive();
    if (stationOverlay) terrainMap.removeLayer(stationOverlay);
    stationOverlay = createStationLayer(leaflet, terrainMap, stations);
    if (firstFix) fit();
    hasCoordinates = Boolean(file.points.length || live.some((segment) => segment.length));
    if (mapMode !== nextMode) {
      mapMode = nextMode;
      if (mapMode !== 'plain') startTiles();
      else {
        removeTiles();
        report('off', '單純軌跡模式，不載入底圖。');
      }
    } else onStatus(status);
    if (mode === 'terrain')
      report('error', '3D 地形目前無法顯示，已保留平面軌跡；可重試或切換標準地圖。');
  }
  function retry() {
    if (usingOffline) {
      offlineRenderer.retry();
      return;
    }
    if (offlineFailed && lastContext) {
      offlineFailed = false;
      mount(lastContext.slot, lastContext.file, lastContext.live, 'standard', lastContext.stations);
      return;
    }
    if (requestedMode === 'terrain') {
      if (terrain3d.unavailable() && terrainContext) {
        terrain3d.resetUnavailable();
        mount(
          terrainContext.slot,
          terrainContext.file,
          terrainContext.live,
          'terrain',
          terrainContext.stations,
        );
      } else terrain3d.retry();
      return;
    }
    if (terrainMap && mapMode !== 'plain') startTiles();
  }
  function destroy() {
    releaseMap();
    terrain3d.destroy();
    offlineRenderer.destroy();
    views.clear();
  }
  return {
    beforeRender,
    mount,
    fit,
    retry,
    destroy,
    pitch: terrain3d.pitch,
    tilt: terrain3d.tilt,
    rotate: terrain3d.rotate,
    north: terrain3d.north,
  };
}
