export function createItineraryActions({
  state,
  itinerary,
  persistence,
  render,
  document = globalThis.document,
}) {
  const run = (operation) => async () => {
    try {
      await operation();
    } catch (error) {
      state.itinerary.reroute ??= {};
      state.itinerary.reroute.error = error.message;
      render();
    }
  };
  const runSmart = (operation) => async () => {
    try {
      return await operation();
    } catch (error) {
      state.itinerary.smart ??= { options: [], locations: [] };
      state.itinerary.smart.error = error.message;
      render();
    }
  };
  return {
    'smart-reroute-open': (target) => {
      const panel = target.closest('#reroute-panel');
      if (panel?.open) return;
      if (panel) panel.open = true;
      return runSmart(() => itinerary.loadSmartOptions())();
    },
    'smart-reroute-refresh': runSmart(() => itinerary.loadSmartOptions()),
    'smart-reroute-location': (target) =>
      runSmart(() => itinerary.loadSmartOptions(target.dataset.location))(),
    'smart-reroute-preview': (target) =>
      runSmart(() => itinerary.previewSmart(target.dataset.option))(),
    'smart-reroute-path': (target) =>
      runSmart(() => {
        const alternative = state.itinerary.smart?.alternatives?.[Number(target.dataset.path)];
        if (!alternative) throw new Error('請重新選擇路徑。');
        return itinerary.previewSmart(alternative.requestId, alternative.routeKey);
      })(),
    'smart-reroute-apply': runSmart(async () => {
      itinerary.applySmart();
      await persistence.save();
    }),
    'reroute-load': run(() =>
      itinerary.rerouteOptions(document.querySelector('#reroute-source')?.value),
    ),
    'reroute-preview': run(() =>
      itinerary.previewReroute({
        startIndex: document.querySelector('#reroute-start')?.value,
        destination: document.querySelector('#reroute-destination')?.value,
        returnTo: document.querySelector('#reroute-return')?.value,
      }),
    ),
    'reroute-apply': run(async () => {
      itinerary.applyReroute();
      await persistence.save();
    }),
    'live-departure-show': () => {
      const details = document.querySelector('#recording-more');
      if (details) details.open = true;
      document.querySelector('#live-departed-here')?.scrollIntoView({ block: 'center' });
    },
    'live-departure-confirm': async () => {
      const confirmed = itinerary.confirmDeparture({
        departedHere: document.querySelector('#live-departed-here')?.checked === true,
        noEarlierTravel: document.querySelector('#live-no-earlier-travel')?.checked === true,
      });
      if (confirmed) await persistence.save();
    },
    'itinerary-arrived': () => {
      itinerary.markNext();
      persistence.schedule();
    },
  };
}
