import { recordingStats } from './analysis.js';
import { normalizeDirection } from '../routes/direction.js';
import { createRecordingCompletion } from './completion.js';
import { recordingGpx, restoreRecording } from './model.js';
import { createGeolocationTracker } from './geolocation.js';
import { createIdleRecording } from '../../core/state.js';
import { downloadGpx } from '../../ui/download.js';
import {
  historyInterruption,
  historyFix,
  historyPause,
  historyResume,
} from '../history/observations.js';
export function createRecordingController({
  state,
  repository,
  persistence,
  current,
  gpsPending,
  render,
  navigate,
  feedback,
  onJourneyStart = () => {},
  onJourneyProgress = () => {},
  onJourneyFix = () => {},
  onJourneyInterruption = () => {},
  onJourneyRestore = async () => {},
  prepareHistory,
  navigator = globalThis.navigator,
  locationProvider,
}) {
  let disposed = false;
  const pending = new Set();
  const { toast } = feedback;
  const saveDraft = persistence.save,
    acquireRecordingLock = persistence.acquireLock,
    releaseWriter = persistence.releaseLock;
  const tracker = createGeolocationTracker({
    getRecording: () => state.gps,
    onChange: () => {
      onJourneyProgress();
      persistence.schedule();
      render();
    },
    onSave: saveDraft,
    onPoint: persistence.schedule,
    onFix: (fix, now) => {
      const live = onJourneyFix(fix, now);
      historyFix(state.gps, fix, now, live);
    },
    onInterruption: (reason) => {
      historyInterruption(
        state.gps,
        reason === 'gps-signal-unavailable' ? 'gps-interrupted' : reason,
      );
      onJourneyInterruption(reason);
    },
    locationProvider,
    onLimit: (message) => {
      pauseGps();
      state.gps.error = message;
      render();
    },
  });
  const stopWatch = tracker.stop;
  function startWatch() {
    const capture = state.gps.captureSource;
    if (capture && capture.provider !== locationProvider?.sourceType) {
      capture.sourceChanged = true;
      capture.provider = 'unknown';
    }
    tracker.start();
  }
  async function restoreDraft(snapshot) {
    if (disposed) return;
    state.gps = restoreRecording(snapshot);
    if (!['review', 'finished'].includes(state.gps.status))
      historyInterruption(state.gps, 'unobserved-reload-interval');
    state.directMap.id = `direct-${snapshot.id}`;
    if (snapshot.sourceRouteId) state.selected = snapshot.sourceRouteId;
    await onJourneyRestore(state.gps);
    if (!disposed) navigate('record');
  }
  async function startGps(direct = false) {
    if (disposed || state.loading || state.starting || state.timeSourceBusy || gpsPending()) return;
    if (!repository.available) {
      state.recordingBlocked =
        '本機資料庫無法使用，無法建立自動保存紀錄。請由本機預覽網站開啟，並允許瀏覽器儲存資料。';
      navigate('record');
      return;
    }
    state.starting = true;
    render();
    try {
      if (!(await acquireRecordingLock())) {
        if (!disposed) navigate('record');
        return;
      }
      if (disposed) return;
      const existing = await repository.getDraft();
      if (disposed) return;
      if (existing) {
        await restoreDraft(existing);
        if (disposed) return;
        render();
        toast('已找回未完成的紀錄，按「繼續紀錄」接續。');
        return;
      }
      const now = Date.now(),
        route = direct || current()?.kind === 'recording' ? null : current();
      state.gps = {
        id: crypto.randomUUID(),
        name: state.recordingName.trim() || `${route?.name || '我的軌跡'} ${state.date}`,
        sourceRouteId: route?.id ?? null,
        sourceRouteDirection: normalizeDirection(route?.direction),
        status: 'requesting',
        segments: [],
        startedAt: now,
        pauseAt: null,
        pausedMs: 0,
        endedAt: null,
        watchId: null,
        accuracy: null,
        error: '',
        calibration: { completed: [], active: null },
        calibrationLabel: '',
        calibrationBase: '',
        remainingBase: '',
        remaining: null,
        savedAt: null,
        saveError: '',
        saving: false,
      };
      state.gps.captureSource = {
        version: 1,
        recordingId: state.gps.id,
        provider: locationProvider?.sourceType ?? 'unknown',
        startedAt: now,
      };
      state.gps.historyObservations = {
        version: 1,
        pauses: [],
        interruptions: [],
        simulated: locationProvider?.sourceType === 'simulation',
      };
      onJourneyStart(state.gps, route);
      state.directMap.id = `direct-${state.gps.id}`;
      const saved = await saveDraft();
      if (disposed) return;
      if (!saved) {
        state.recordingBlocked = state.gps.saveError;
        state.gps.status = 'idle';
        releaseWriter();
        navigate('record');
        return;
      }
      navigator.storage?.persist?.().catch(() => {});
      navigate('record');
      startWatch();
    } catch {
      if (disposed) return;
      state.recordingBlocked = '無法讀取或建立紀錄，請重新整理後再試。';
      releaseWriter();
      navigate('record');
    } finally {
      state.starting = false;
      render();
    }
  }
  function pauseGps() {
    if (!['requesting', 'tracking'].includes(state.gps.status)) return;
    stopWatch();
    state.gps.status = 'paused';
    state.gps.pauseAt = Date.now();
    historyPause(state.gps, state.gps.pauseAt);
    saveDraft();
    render();
  }
  async function resumeGps() {
    if (disposed || !['paused', 'error'].includes(state.gps.status)) return;
    if (!(await acquireRecordingLock())) {
      if (!disposed) toast(state.recordingBlocked);
      return;
    }
    if (disposed) return;
    if (recordingStats(state.gps).points >= 100000) {
      toast('請結束此份紀錄後再開新紀錄。');
      return;
    }
    if (state.gps.segments.filter((segment) => segment.length).length >= 500) {
      toast('已達 500 段，請結束此份紀錄後再開新紀錄。');
      return;
    }
    state.gps.pausedMs += Date.now() - state.gps.pauseAt;
    historyResume(state.gps, Date.now());
    state.gps.pauseAt = null;
    state.gps.endedAt = null;
    state.gps.finalizePending = false;
    startWatch();
  }
  function downloadGps() {
    const segments = state.gps.segments.filter((segment) => segment.length);
    if (!segments.length) {
      toast('尚未取得座標，沒有可下載的軌跡。');
      return;
    }
    downloadGpx(recordingGpx(state.gps), `Ridgewise-${state.date}.gpx`);
  }
  function clearGps() {
    stopWatch();
    persistence.cancelScheduled();
    state.gps = createIdleRecording();
    state.recordingName = '';
    releaseWriter();
  }
  const completion = createRecordingCompletion({
    state,
    repository,
    persistence,
    stopWatch,
    clearGps,
    render,
    navigate,
    feedback,
    prepareHistory,
  });
  function reset() {
    if (!state.library.some((file) => file.id === state.gps.id && file.saved)) {
      toast('請先成功保存這份紀錄。');
      return;
    }
    clearGps();
    state.libraryFilter = 'recordings';
    navigate('library');
  }
  function retrySave() {
    return state.gps.status === 'review' && state.gps.finalizePending
      ? completion.save()
      : saveDraft();
  }
  function track(operation) {
    return (...args) => {
      if (disposed) return Promise.resolve();
      const task = operation(...args);
      pending.add(task);
      task.then(
        () => pending.delete(task),
        () => pending.delete(task),
      );
      return task;
    };
  }
  async function dispose() {
    disposed = true;
    pauseGps();
    stopWatch();
    await Promise.allSettled([...pending]);
  }

  return {
    start: track(startGps),
    pause: pauseGps,
    resume: track(resumeGps),
    finish: track(completion.stop),
    save: track(completion.save),
    download: downloadGps,
    discard: track(completion.discard),
    restore: restoreDraft,
    reset,
    retrySave: track(retrySave),
    stop: stopWatch,
    dispose,
  };
}
