    elapsedSeconds:
      leg.cumulativeStartSeconds === null ? null : leg.cumulativeStartSeconds + legSeconds,
    legSeconds,
    method: leg.method,
    reason: leg.cumulativeStartSeconds === null ? 'unknown-prefix' : null,
    source: leg.source,
