// Device-local provenance and explicit consent are separate from independent verification.
// Runtime bindings are created after hashing the exact raw file, never from GPX XML flags.
const bindings = new WeakMap();
const providers = new Set(['web-geolocation', 'ios-core-location']);
const digestPattern = /^[a-f0-9]{64}$/;
const finite = Number.isFinite;
const forward = (file) => file.direction !== 'reverse';

export async function rawGpxDigest(raw, cryptoApi = globalThis.crypto) {
  if (typeof raw !== 'string' || !cryptoApi?.subtle)
    throw new Error('無法核對 GPX 原始內容，來源設定尚未保存。');
  const bytes = await cryptoApi.subtle.digest('SHA-256', new TextEncoder().encode(raw));
  return Array.from(new Uint8Array(bytes), (b) => b.toString(16).padStart(2, '0')).join('');
}
export async function userConfirmedTimeSource(file, statements, now = Date.now()) {
  if (
    !file.id ||
    !forward(file) ||
    statements.actualGps !== true ||
    statements.originalTime !== true
  )
    throw new Error('請確認是實際 GPS 紀錄，且時間不是人工產生或補寫；確認僅適用 GPX 原向。');
  return {
    version: 1,
    kind: 'user-confirmed',
    recordId: file.id,
    rawSha256: await rawGpxDigest(file.raw),
    direction: 'forward',
    confirmedAt: now,
    actualGps: true,
    originalTime: true,
  };
}
export async function localRecordingTimeSource(file, gps) {
  const capture = gps.captureSource;
  if (
    file.kind !== 'recording' ||
    !capture ||
    capture.version !== 1 ||
    capture.recordingId !== gps.id ||
    file.id !== gps.id ||
    capture.startedAt !== gps.startedAt ||
    !providers.has(capture.provider) ||
    !finite(gps.startedAt) ||
    !finite(gps.endedAt) ||
    gps.endedAt < gps.startedAt
  )
    return null;
  return {
    version: 1,
    kind: 'ridgewise-local',
    recordId: file.id,
    recordingId: gps.id,
    rawSha256: await rawGpxDigest(file.raw),
    direction: 'forward',
    provider: capture.provider,
    startedAt: gps.startedAt,
    endedAt: gps.endedAt,
  };
}
const unknown = (reason = 'unconfirmed-gpx-time') => ({
  assurance: 'unconfirmed',
  verification: 'unverified',
  eligible: false,
  reason,
  limitations: ['unverified-time-source'],
});

// Internal constructor. The caller supplies the digest computed from raw bytes, not an XML claim.
// Always returns a new object so direction/itinerary caches cannot retain an old decision.
export function bindTimeOrigin(file, source, rawDigest) {
  const result = { ...file };
  let origin = unknown();
  if (source) {
    const bound =
      source.version === 1 &&
      source.recordId === file.id &&
      source.direction === 'forward' &&
      digestPattern.test(rawDigest ?? '') &&
      source.rawSha256 === rawDigest;
    if (!bound) origin = unknown('time-source-content-mismatch');
    else if (
      source.kind === 'user-confirmed' &&
      source.actualGps === true &&
      source.originalTime === true &&
      finite(source.confirmedAt) &&
      source.confirmedAt >= 0
    ) {
      origin = {
        assurance: 'user-confirmed',
        verification: 'unverified',
        direction: 'forward',
        confirmedAt: source.confirmedAt,
        limitations: ['user-declaration-only', 'not-independently-verified'],
      };
    } else if (
      source.kind === 'ridgewise-local' &&
      typeof source.recordingId === 'string' &&
      source.recordingId &&
      providers.has(source.provider) &&
      finite(source.startedAt) &&
      finite(source.endedAt) &&
      source.endedAt >= source.startedAt
    ) {
      origin = {
        assurance: 'ridgewise-local',
        verification: 'unverified',
        direction: 'forward',
        recordingId: source.recordingId,
        provider: source.provider,
        startedAt: source.startedAt,
        endedAt: source.endedAt,
        limitations: [
          'device-local-provenance',
          'not-independently-verified',
          'location-provider-may-be-simulated',
        ],
      };
    } else origin = unknown('invalid-time-source');
  }
  const stored = { ...origin, limitations: [...origin.limitations] };
  bindings.set(result, {
    raw: result.raw,
    id: result.id,
    weights: result.timeWeights,
    points: result.points,
    origin: stored,
  });
  return result;
}
export async function hydrateTimeOrigin(file) {
  if (!file.timeSource) return bindTimeOrigin(file, null, null);
  try {
    return bindTimeOrigin(file, file.timeSource, await rawGpxDigest(file.raw));
  } catch {
    return bindTimeOrigin(file, file.timeSource, null);
  }
}
export function inheritTimeOrigin(original, reversed) {
  const binding = bindings.get(original);
  if (
    binding &&
    binding.raw === original.raw &&
    binding.id === original.id &&
    binding.weights === original.timeWeights &&
    binding.points === original.points &&
    reversed.raw === original.raw
  ) {
    bindings.set(reversed, {
      ...binding,
      weights: reversed.timeWeights,
      points: reversed.points,
      origin: { ...binding.origin, limitations: [...binding.origin.limitations] },
    });
  }
  return reversed;
}
export function timeOriginFor(file) {
  const binding = file && bindings.get(file);
  if (
    !binding ||
    binding.raw !== file.raw ||
    binding.id !== file.id ||
    binding.weights !== file.timeWeights ||
    binding.points !== file.points
  )
    return unknown();
  const origin = { ...binding.origin, limitations: [...binding.origin.limitations] };
  if (origin.assurance === 'unconfirmed') return origin;
  if (!forward(file)) return { ...origin, eligible: false, reason: 'gpx-time-direction-mismatch' };
  if (!file.timeWeights) return { ...origin, eligible: false, reason: 'missing-gpx-time' };
  if (
    file.timeWeights.source?.kind !== 'track' ||
    file.timeWeights.source.limitations?.some((code) =>
      ['nonrecorded-time', 'planned-route', 'reverse-planning'].includes(code),
    )
  )
    return { ...origin, eligible: false, reason: 'nonrecorded-gpx-time' };
  if (origin.assurance === 'ridgewise-local') {
    const rawPoints = (file.rawSegments ?? file.segments ?? []).flat();
    if (
      !rawPoints.length ||
      rawPoints.some(
        (point) =>
          finite(point.time) &&
          (point.time < origin.startedAt - 5000 || point.time > origin.endedAt + 5000),
      )
    )
      return { ...origin, eligible: false, reason: 'recording-time-range-mismatch' };
  }
  return { ...origin, eligible: true, reason: null };
}
export const timeOriginLabel = (origin) =>
  origin.assurance === 'ridgewise-local'
    ? 'Ridgewise 本機錄製可追溯（非獨立驗證）'
    : origin.assurance === 'user-confirmed'
      ? '使用者已確認，來源未驗證'
      : '時間來源未確認';

export function timeDistributionLabel(leg) {
  if (!leg || leg.method === 'unavailable') return '不分配：上河路徑或 GPX 連續性未確認';
  if (leg.method === 'gpx-moving-time')
    return 'GPX 移動時間比例 · ' + timeOriginLabel(leg.source.timingOrigin);
  return (
    (leg.method === 'slope-weighted' ? '坡度加權' : '距離內插') + ' · 時間來源未確認或區間品質不足'
  );
}
