export async function prepareOfflineShell({
  navigator = globalThis.navigator,
  document = globalThis.document,
  platform = globalThis.Capacitor?.getPlatform?.(),
} = {}) {
  if (!document?.baseURI) return false;
  const url = new URL('./sw.js', document.baseURI);
  // The native iOS app ships this shell in its bundle; custom schemes cannot register a SW.
  if (platform === 'ios' && url.protocol === 'capacitor:' && url.hostname === 'localhost')
    return true;
  if (!navigator?.serviceWorker || !['http:', 'https:'].includes(url.protocol)) return false;
  // No forced refresh or skipWaiting: an app update must not interrupt GPS recording.
  const existing = await navigator.serviceWorker.getRegistration?.(url.href);
  if (navigator.onLine === false && existing?.active) return true;
  const registration = await navigator.serviceWorker.register(url.href, { scope: './' });
  const worker = registration.installing ?? registration.waiting ?? registration.active;
  if (!worker) return false;
  if (worker.state === 'activated' || worker.state === 'installed') return true;
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      worker.removeEventListener('statechange', change);
      reject(new Error('離線頁面準備逾時。'));
    }, 30000);
    const change = () => {
      if (['activated', 'installed', 'redundant'].includes(worker.state)) {
        clearTimeout(timer);
        worker.removeEventListener('statechange', change);
        if (worker.state === 'redundant') reject(new Error('離線頁面未能準備完成。'));
        else resolve();
      }
    };
    worker.addEventListener('statechange', change);
    change();
  });
  return true;
}
