import { remainingRouteProgress } from './route-progress.js';
import { elevationBetween } from './remaining-elevation.js';
export function remainingRouteMetrics(file, data, gps, now = Date.now()) {
  const progress = remainingRouteProgress(file, data, gps, now);
  const elevation = progress ? elevationBetween(file, progress) : null;
  return {
    distanceM: progress ? Math.max(0, progress.toM - progress.fromM) : null,
    ascentM: elevation?.ascentM ?? null,
    descentM: elevation?.descentM ?? null,
    message: data?.finished
      ? '紀錄已結束，不再顯示剩餘高度。'
      : !data?.next
        ? '尚無可計算的下一站。'
        : !data?.active
          ? '開始紀錄並取得有效定位後顯示。'
          : !progress
            ? '定位無效、過期、偏離路線或 GPX 中斷，暫無法提供剩餘高度。'
            : !elevation
              ? '到下一站的 GPX 高度資料缺漏，暫無法提供爬升／下降。'
              : file?.processing
                ? '依校正後 GPX 路段高度累加；不使用即時 GPS 海拔或上河時間換算。'
                : '依剩餘 GPX 路段高度累加，未經去噪；不使用 GPS 海拔或上河時間換算。',
  };
}

export function remainingJourneyMetrics(file, data, gps, now = Date.now()) {
  const progress = remainingRouteProgress(file, data, gps, now);
  if (!progress) return null;
  let ascentM = 0,
    descentM = 0;
  for (const segmentIndex of new Set(file.points.map((p) => p.segment))) {
    if (segmentIndex < progress.segmentIndex) continue;
    const points = file.points.filter((p) => p.segment === segmentIndex);
    const part = elevationBetween(file, {
      segmentIndex,
      fromM: segmentIndex === progress.segmentIndex ? progress.fromM : points[0].km * 1000,
      toM: points.at(-1).km * 1000,
    });
    if (!part) {
      ascentM = null;
      descentM = null;
      break;
    }
    ascentM += part.ascentM;
    descentM += part.descentM;
  }
  const gap =
    file.reroutePlan?.geometryComplete === false ||
    file.reroutePlan?.rows.some((r) => r.reasonCode === 'gpx-unconnected-join') ||
    (file.reroutePlan?.geometryComplete === undefined &&
      file.reroutePlan?.warnings.some((w) => w.includes('接點')));
  return {
    distanceM: gap ? null : file.stats.km * 1000 - progress.fromM,
    knownDistanceM: file.stats.km * 1000 - progress.fromM,
    ascentM: gap ? null : ascentM,
    descentM: gap ? null : descentM,
  };
}
