import { timingIssuesPanel } from './timing-issues.js';
import { createLiveFactorView, liveFactorReason } from './live-factor-view.js';
import { timeDistributionLabel } from '../../domain/time-origin.js';
import { remainingRouteMetrics, remainingJourneyMetrics } from './remaining-route.js';
import { button, esc, meters } from '../../ui/html.js';

export const duration = (seconds) => {
  if (seconds === null || !Number.isFinite(seconds)) return '尚未提供';
  const minutes = Math.max(0, Math.ceil(seconds / 60));
  return `${Math.floor(minutes / 60)} 小時 ${minutes % 60} 分`;
};
export const arrival = (milliseconds) =>
  milliseconds === null
    ? '—'
    : new Date(milliseconds).toLocaleString('zh-TW', {
        timeZone: 'Asia/Taipei',
        month: 'numeric',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hourCycle: 'h23',
      });
const typeLabels = {
  trailhead: '登山口',
  exit: '出口',
  summit: '山頂',
  hut: '山屋',
  water: '水源',
  camp: '營地',
};
export function createItineraryViews({
  state,
  itinerary,
  gpsPending,
  recordingRoute,
  document = globalThis.document,
}) {
  const liveFactors = createLiveFactorView({ state, itinerary, document });
  function departureNotice() {
    return itinerary.departureStatus?.().canConfirm
      ? `<p class="soft-notice">出發位置與首個定位前的路程尚待核對。${button('核對出發位置', 'live-departure-show', 'ghost')}</p>`
      : '';
  }
  function departurePanel() {
    const info = itinerary.departureStatus?.();
    if (!info?.canConfirm && !info?.confirmed) return '';
    return info.confirmed
      ? '<p class="small muted">出發位置由使用者確認（未獨立驗證）；倍率僅使用該 GPS 錨點之後的已知基準。</p>'
      : `<section class="stack" aria-label="確認倍率出發位置"><strong>核對倍率出發位置</strong><p class="small muted">第一個時間站點：${esc(info.stationName ?? '未命名')}；差距約 ${Math.round(info.distanceM)}m，GPS 精度 ${Math.round(info.gpsAccuracyM)}m。站點座標來源：${esc(info.coordinateSource?.provider ?? '未提供')}；座標誤差未知，接近不代表同一出發點。</p><label class="small"><input type="checkbox" id="live-departed-here"> 按開始紀錄時我就在這個出發位置</label><label class="small"><input type="checkbox" id="live-no-earlier-travel"> 定位前沒有走過未記錄路程，且此位置確在同一 GPX 路徑</label>${button('確認 GPS 出發錨點', 'live-departure-confirm')}<p class="small muted">只採用真實 GPS 錨點以後的已知上河差值，不補未知前綴、不改出發時間；確認是你的聲明，並非定位或站點來源已驗證。</p>${state.itinerary.liveDepartureError ? '<p class="error-message" role="status">' + esc(state.itinerary.liveDepartureError) + '</p>' : ''}</section>`;
  }
  function resourcesPanel() {
    const data = state.itinerary,
      locked = gpsPending();
    return `<section class="panel panel-body stack itinerary-resources"><span class="eyebrow">YOUR PACE</span><h2>設定倍率</h2><p class="small muted">影響 ETA；以上河 1.0 有向時間為基準，依 GPX 比對有來源座標的站點。</p><label for="itinerary-factor">上河時間倍率</label><input id="itinerary-factor" type="number" min="0.01" max="10" step="0.05" value="${data.factor}" ${locked ? 'disabled' : ''}><p class="small muted">1.2 倍＝基準時間增加 20%；不另外加休息時間。</p>${locked ? '<p class="small muted">此趟使用出發時設定的倍率。</p>' : ''}${data.error ? `<p class="error-message" role="status">${esc(data.error)}</p>` : ''}</section>`;
  }
  function stationRow(row, data, number) {
    const passed = data.active && row.index < data.nextIndex;
    const unavailable = (data.active ? row.arrivalUtcMs : row.cumulativeSeconds) === null;
    const status = passed
      ? '已通過'
      : data.active
        ? row.index === data.nextIndex
          ? '下一站 · 未到達'
          : '未到達'
        : '尚未出發';
    return `<li class="${passed ? 'station-passed' : ''}"><div class="station-number">${number}</div><div><strong>${esc(row.station.name)}</strong><span class="small station-status">${status}${unavailable ? ' · 時間資料不足' : ''}</span><span class="small muted">${typeLabels[row.station.type] ?? '站點'} · ${row.gap ? 'GPX 分段間距離未知' : 'GPX 累計 ' + (row.routeProgressM / 1000).toFixed(2) + ' km'}</span>${row.reason ? `<span class="small error-message">${esc(row.reason)}</span>` : ''}<details class="small muted station-timing" id="station-time-${row.index}"><summary>時間依據${row.timeNodeNames?.length > 2 ? ` · 含 ${row.timeNodeNames.length - 2} 個時間中間節點` : ''}</summary><p>${row.index === 0 ? '上河起始站' : `前段基準：${duration(row.baselineSeconds)}`}</p>${row.index && data.timeModel ? `<p data-time-distribution="${data.timeModel.legs[row.index - 1]?.method ?? 'unavailable'}">站間分配：${esc(timeDistributionLabel(data.timeModel.legs[row.index - 1]))}</p>` : ''}${row.timeNodeNames?.length > 2 ? `<p>${row.timeNodeNames.map(esc).join(' → ')}</p><p>中間節點未必已有座標，仍需核對與 GPX 同一路徑。</p>` : ''}</details></div><div class="station-eta"><small>${data.active ? '預估抵達' : '累計耗時'}</small><strong>${data.active ? arrival(row.arrivalUtcMs) : duration(row.cumulativeSeconds)}</strong></div></li>`;
  }
  function stationsPanel() {
    const data = itinerary.snapshot();
    if (!data)
      return `<section class="panel panel-body stack"><h2>沿途站點</h2><p class="small muted">內建資料尚未找到這條 GPX 的對應站點。</p></section>`;
    const rows = data.rows.filter((row) => row.visible);
    return `<section class="panel panel-body stack itinerary-panel"><div><span class="eyebrow">YOUR STOPS</span><h2>沿途站點與 ETA</h2><p class="small muted">${data.active ? '抵達後會重新推算後續時間；往返站點分次顯示。' : '按「開始登山紀錄」後，以實際出發時間顯示抵達時刻。'}</p></div>${!data.compatible ? '<p class="error-message">站點資料已更新；結束目前紀錄後，重新開始才能套用新的 ETA。</p>' : ''}<div class="itinerary-summary"><span>全程預估</span><strong>${duration(data.totalSeconds)}</strong><small>設定倍率 ${data.factor.toFixed(2)} · 影響 ETA</small></div>${!data.startCovered || !data.endCovered ? '<p class="soft-notice">GPX 起點或終點沒有對應時間站點；只顯示有基準的站間時間。</p>' : ''}${rows.length ? `<ol class="station-list">${rows.map((row, index) => stationRow(row, data, index + 1)).join('')}</ol>` : '<p class="small muted">目前 GPX 附近未找到這六類站點，請補齊站點座標。</p>'}${timingIssuesPanel(data)}<p class="small muted">位置接近不代表已進入山屋；水源可用性請另行確認。</p><details id="station-source-details" class="small muted"><summary>站點來源與 ETA 計算限制</summary><p class="small muted">依上河有向時間計算，不以 GPX 歷史時間或距離補時間。缺值或多條可能路徑會保留待補。</p><p class="small muted">站點座標參考：政府公開資料及 <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors（ODbL）</a>，以及 <a href="https://joyhike.com/path/31" target="_blank" rel="noopener noreferrer">Joyhike 地點比對資料</a>。溪源座標由使用者於 OSM 查找提供。</p></details></section>`;
  }
  const heightLabel = (value) => (value === null ? '—' : `${meters(value)} m`);
  const etaReasons = {
    'eta-not-recording': '開始或恢復紀錄並取得有效定位後顯示。',
    'eta-no-next': '沿途站點已完成。',
    'eta-factor-unavailable': '目前沒有有效的即時倍率；上次有效值不供 ETA 使用。',
    'eta-route-position-mismatch': '定位與下一站的路線方向或所在路段無法確認。',
    'eta-unknown-remaining': '到下一站的上河時間或連續路程不明。',
  };
  function nextEtaFields() {
    const data = itinerary.nextEtas?.();
    return Object.fromEntries(
      ['total', 'recent'].flatMap((key) => {
        const metric = data?.[key];
        const usable = Number.isFinite(metric?.arrivalUtcMs);
        return [
          [`itinerary-${key}-arrival`, usable ? arrival(metric.arrivalUtcMs) : '—'],
          [
            `itinerary-${key}-remaining`,
            usable
              ? `${metric.factorBasis === 'configured-fallback' ? '回退設定倍率 · ' : ''}剩餘 ${duration(metric.remainingSeconds)}`
              : '不可用',
          ],
          [
            `itinerary-${key}-eta-reason`,
            usable ? '' : (etaReasons[metric?.reason] ?? liveFactorReason(metric?.reason)),
          ],
        ];
      }),
    );
  }
  function nextEtaPanel() {
    const values = nextEtaFields();
    return `<div class="next-live-etas" role="group" aria-label="下一站即時上河倍率 ETA">${[
      ['total', '全程倍率 ETA'],
      ['recent', '最近 30 分鐘倍率 ETA'],
    ]
      .map(
        ([key, title]) =>
          `<section class="next-live-eta" aria-label="${title}"><h3>${title}</h3><strong id="itinerary-${key}-arrival">${esc(values[`itinerary-${key}-arrival`])}</strong><span id="itinerary-${key}-remaining">${esc(values[`itinerary-${key}-remaining`])}</span><p id="itinerary-${key}-eta-reason" class="small muted" role="status" aria-atomic="true">${esc(values[`itinerary-${key}-eta-reason`])}</p></section>`,
      )
      .join(
        '',
      )}<p class="small muted">預估抵達（台北時間）；以現在加上剩餘上河基準 × 各自即時倍率。含未來休息的耗時推估，僅供參考。</p></div>`;
  }
  function nextCard() {
    const data = itinerary.snapshot(),
      next = data?.next,
      file =
        recordingRoute?.() ?? state.library.find((entry) => entry.id === state.gps.sourceRouteId),
      metrics = remainingRouteMetrics(file, data, state.gps),
      remaining = metrics.distanceM;
    const journeyMetrics = file?.rerouted ? remainingJourneyMetrics(file, data, state.gps) : null;
    const revisedSummary = file?.rerouted
      ? `<p id="reroute-remaining" class="small muted">改道後至終點：${journeyMetrics?.distanceM != null ? (journeyMetrics.distanceM / 1000).toFixed(2) + ' km' : '距離不可用'} · 爬升 ${heightLabel(journeyMetrics?.ascentM ?? null)} ／下降 ${heightLabel(journeyMetrics?.descentM ?? null)}</p>`
      : '';
    return `<section class="panel next-card itinerary-next"><span class="eyebrow">NEXT STOP</span><h2>${next ? esc(next.station.name) : data?.active ? '沿途站點已完成' : '下一站待提供'}</h2><p class="small station-status">${data?.active ? (next ? '未到達' : '已通過全部站點') : '尚未出發'}</p><p class="small">${next ? (typeLabels[next.station.type] ?? '沿途站點') : '選用 GPX 後自動顯示。'}</p><div class="next-metrics"><div><strong id="itinerary-distance">${remaining !== null ? (remaining / 1000).toFixed(2) + ' km' : next ? (next.routeProgressM / 1000).toFixed(2) + ' km' : '—'}</strong><small id="itinerary-distance-label">${remaining !== null ? '沿 GPX 剩餘距離' : 'GPX 累計位置'}</small></div><div><strong id="itinerary-next-arrival">${data?.active && next ? arrival(next.arrivalUtcMs) : '開始後顯示'}</strong><small>設定倍率 ETA（台北時間，比較基準）</small></div></div>${nextEtaPanel()}${revisedSummary}<div class="next-elevation" role="group" aria-label="到下一站的剩餘高度"><div><span>剩餘爬升</span><strong id="itinerary-remaining-ascent" title="${esc(metrics.message)}">${heightLabel(metrics.ascentM)}</strong></div><div><span>剩餘下降</span><strong id="itinerary-remaining-descent" title="${esc(metrics.message)}">${heightLabel(metrics.descentM)}</strong></div></div><p id="itinerary-countdown" class="small"></p>${data?.offRoute ? '<p class="error-message">目前位置偏離預定 GPX，請確認路線。</p>' : ''}${data?.active && next && next.arrivalUtcMs === null ? '<p class="small error-message">設定倍率 ETA 尚無有效時間資料。</p>' : ''}${next?.reason ? `<p class="small error-message">${esc(next.reason)}</p>` : ''}<p id="itinerary-elevation-status" class="small muted">${esc(metrics.message)}</p><details class="next-details" id="next-details"><summary>到站確認與實測倍率</summary>${data?.active && !data.finished && next ? button('已抵達，切換下一站', 'itinerary-arrived', '', '') : ''}<p class="small muted">到站實測倍率：<strong>${data?.observedFactor === null || !data?.observedFactor ? '尚待有效到站紀錄' : data.observedFactor.toFixed(2) + ' 倍'}</strong></p><p class="small muted">到站實測倍率使用已確認到站之間的耗時，包含休息與暫停，與 GPS 即時倍率分開。設定倍率 ETA 保留作比較；即時倍率不會覆寫設定。</p></details></section>`;
  }
  function updateNumbers() {
    const smartConfirm = document.getElementById('smart-reroute-confirm');
    if (smartConfirm && itinerary.canApplySmart) {
      const usable = itinerary.canApplySmart();
      smartConfirm.disabled = !usable;
      const status = document.getElementById('smart-location-status');
      if (status)
        status.textContent = usable ? '' : 'GPS 中斷、過期或路線已變更，請重新定位並更新方案。';
    }
    liveFactors.updateNumbers();
    for (const [id, value] of Object.entries(nextEtaFields())) {
      const field = document.getElementById(id);
      if (field && field.textContent !== value) field.textContent = value;
    }
    const data = itinerary.snapshot(),
      next = data?.next;
    const file =
      recordingRoute?.() ?? state.library.find((entry) => entry.id === state.gps.sourceRouteId);
    const metrics = remainingRouteMetrics(file, data, state.gps);
    const remaining = metrics.distanceM;
    const summary = document.getElementById('reroute-remaining');
    if (summary) {
      const all = remainingJourneyMetrics(file, data, state.gps);
      summary.textContent = `改道後至終點：${all?.distanceM != null ? (all.distanceM / 1000).toFixed(2) + ' km' : '距離不可用'} · 爬升 ${heightLabel(all?.ascentM ?? null)} ／下降 ${heightLabel(all?.descentM ?? null)}`;
    }
    for (const [id, value] of [
      ['itinerary-remaining-ascent', metrics.ascentM],
      ['itinerary-remaining-descent', metrics.descentM],
    ]) {
      const field = document.getElementById(id);
      if (field) {
        field.textContent = heightLabel(value);
        field.title = metrics.message;
      }
    }
    const heightStatus = document.getElementById('itinerary-elevation-status');
    if (heightStatus) heightStatus.textContent = metrics.message;
    const distance = document.getElementById('itinerary-distance');
    const label = document.getElementById('itinerary-distance-label');
    if (distance)
      distance.textContent =
        remaining !== null
          ? (remaining / 1000).toFixed(2) + ' km'
          : next
            ? (next.routeProgressM / 1000).toFixed(2) + ' km'
            : '—';
    if (label) label.textContent = remaining !== null ? '沿 GPX 剩餘距離' : 'GPX 累計位置';
    const element = document.getElementById('itinerary-countdown');
    if (element && data?.finished) {
      element.textContent = '紀錄已結束';
      return;
    }
    if (element)
      element.textContent =
        next?.arrivalUtcMs !== null && Number.isFinite(next?.arrivalUtcMs)
          ? next.arrivalUtcMs > Date.now()
            ? `設定倍率預估剩餘 ${duration((next.arrivalUtcMs - Date.now()) / 1000)}`
            : '設定倍率預估時刻已過，尚未確認抵達'
          : '等待有效時間資料';
  }
  function referenceDuration() {
    const data = itinerary.snapshot();
    return data?.totalSeconds === null || !data
      ? '尚未提供'
      : duration(data.totalSeconds / data.factor);
  }
  return {
    liveFactorsPanel: liveFactors.panel,
    departureNotice,
    departurePanel,
    resourcesPanel,
    stationsPanel,
    nextCard,
    updateNumbers,
    referenceDuration,
    estimatedDuration: () => duration(itinerary.snapshot()?.totalSeconds),
  };
}
