// Public Adapter entry point. Validation and selection stay in internal modules.
import { predictEta } from '../prediction-engine/eta.js';
import { AdapterInputError, id, copy, requireValue, etaStatus } from './internal/contracts.js';
import { validateProfile } from './internal/validation.js';
import { importDatabase } from './internal/database.js';
import { resolveNode } from './internal/nodes.js';
import { selectDirectedTime } from './internal/selection.js';
export { AdapterInputError } from './internal/contracts.js';

/** Explicit local import of schemaVersion 2. No fetch, disk access or name guessing. */
export class RouteTimeAdapter {
  #nodes = new Map();
  #names = new Map();
  #pairs = new Map();

  constructor(database) {
    const index = importDatabase(database);
    this.#nodes = index.nodes;
    this.#names = index.names;
    this.#pairs = index.pairs;
  }

  static fromJson(text) {
    requireValue(typeof text === 'string', 'invalid_json_text');
    let data;
    try { data = JSON.parse(text.replace(/^\uFEFF/, '')); }
    catch { throw new AdapterInputError('invalid_json'); }
    return new RouteTimeAdapter(data);
  }

  /** Browser File/Blob selected by the user, without uploading it. */
  static async fromFile(file) {
    requireValue(file && typeof file.text === 'function', 'invalid_local_file');
    let text;
    try { text = await file.text(); } catch { throw new AdapterInputError('local_file_read_failed'); }
    return RouteTimeAdapter.fromJson(text);
  }

  listAreas() {
    return [...new Set([...this.#nodes.values()].map(node => node.area))].sort();
  }

  listNodes(area = null) {
    requireValue(area === null || id(area), 'invalid_area');
    return [...this.#nodes.values()].filter(node => area === null || node.area === area)
      .map(node => ({ id: node.id, area: node.area, name: node.name }));
  }

  #resolve(value, area) {
    return resolveNode(this.#nodes, this.#names, value, area);
  }

  #select(area, from, to, profile) {
    return selectDirectedTime(this.#pairs, area, from, to, profile);
  }

  buildPath(request) {
    const profile = validateProfile(request);
    let area = profile.area;
    const resolved = request.nodes.map(value => {
      const result = this.#resolve(value, area);
      if (result.node && area === null) area = result.node.area;
      return { requested: value, ...result };
    });
    // An initially ambiguous name cannot be disambiguated by a later node.
    // Require the caller to supply area or explicit IDs.
    const issues = [];
    const warnings = new Set(['reference_times_only', 'current_access_unverified']);
    const segments = [];
    for (let index = 0; index < resolved.length - 1; index++) {
      const from = resolved[index];
      const to = resolved[index + 1];
      const selected = from.error ?? to.error ?? this.#select(area, from.node, to.node, profile);
      const records = selected.records ?? [];
      const sourceIds = records.map(r => r.id);
      const first = records[0];
      const fromWaypointId = from.node?.id ?? `unresolved:${index}`;
      const toWaypointId = to.node?.id ?? `unresolved:${index + 1}`;
      const segmentId = `local-leg-${index}`;
      if (selected.code) issues.push({ code: selected.code, segmentIndex: index, segmentId,
        fromWaypointId, toWaypointId, sourceIds: [...sourceIds], details: copy(selected.details ?? {}) });
      if (records.some(r => r.imageVerification === 'pending_image_verification')) warnings.add('pending_image_verification');
      if (records.some(r => r.load === 'unspecified')) warnings.add('some_load_conditions_unspecified');
      if (!first || records.some(r => r.restIncluded === 'unknown')) warnings.add('rest_inclusion_unknown');
      segments.push({ id: segmentId, fromWaypointId, toWaypointId, sourceIds,
        baselineMoveSeconds: selected.code ? null : selected.seconds,
        timeStatus: selected.code ? etaStatus(selected.code) : 'known',
        mode: first?.mode ?? 'unknown', restIncluded: first?.restIncluded ?? 'unknown',
        area, load: selected.code ? null : first.load,
        speedVariant: selected.code ? null : first.speedVariant,
        adapterReason: selected.code ?? null, provenance: copy(records) });
    }
    return { localOnly: true, complete: issues.length === 0, area,
      requestedProfile: { load: profile.load, speed: profile.speed, mode: profile.mode },
      nodes: resolved.map(item => ({ requested: item.requested, nodeId: item.node?.id ?? null,
        name: item.node?.name ?? null, area: item.node?.area ?? null })),
      segments, issues, warnings: [...warnings] };
  }

  predictPath(request) {
    const route = this.buildPath(request);
    const eta = predictEta({ departureUtcMs: request.departureUtcMs, multiplier: request.multiplier,
      mode: route.requestedProfile.mode, segments: route.segments });
    return { localOnly: true, complete: route.complete && eta.complete, route, eta };
  }
}
