export const MAX_MAP_BYTES = 256 * 1024 * 1024;
export function validateManifest(value) {
  const bounds = value?.bounds;
  if (
    value?.schema !== 1 ||
    value?.format !== 'protomaps-v4' ||
    !Number.isSafeInteger(value.bytes) ||
    value.bytes < 127 ||
    value.bytes > MAX_MAP_BYTES ||
    !/^[a-f0-9]{64}$/.test(value.sha256 ?? '') ||
    !Array.isArray(bounds) ||
    bounds.length !== 4 ||
    !bounds.every(Number.isFinite) ||
    bounds[0] >= bounds[2] ||
    bounds[1] >= bounds[3] ||
    bounds[0] < -180 ||
    bounds[2] > 180 ||
    bounds[1] < -85 ||
    bounds[3] > 85 ||
    !Number.isInteger(value.maxZoom) ||
    value.maxZoom < 0 ||
    value.maxZoom > 15 ||
    typeof value.version !== 'string' ||
    !value.version ||
    typeof value.name !== 'string'
  )
    throw new Error('離線圖資資訊不完整，請稍後再試。');
  return value;
}
export async function downloadMap({
  url,
  manifest,
  signal,
  fetch = globalThis.fetch,
  crypto = globalThis.crypto,
  onProgress = () => {},
}) {
  const response = await fetch(url, { signal, cache: 'no-store' });
  if (!response.ok) throw new Error('無法下載底圖，請確認網路後重試。');
  const reader = response.body?.getReader();
  if (!reader) throw new Error('此瀏覽器不支援地圖下載。');
  const chunks = [];
  let received = 0;
  try {
    while (true) {
      signal.throwIfAborted();
      const { done, value } = await reader.read();
      if (done) break;
      received += value.byteLength;
      if (received > manifest.bytes || received > MAX_MAP_BYTES)
        throw new Error('下載資料大小不符，已取消本次下載。');
      chunks.push(value);
      onProgress(received, manifest.bytes);
    }
  } catch (error) {
    await reader.cancel().catch(() => {});
    throw error;
  } finally {
    reader.releaseLock();
  }
  signal.throwIfAborted();
  if (received !== manifest.bytes) throw new Error('下載中斷或資料不完整，請重試。');
  const blob = new Blob(chunks, { type: 'application/vnd.pmtiles' });
  const digest = await crypto.subtle.digest('SHA-256', await blob.arrayBuffer());
  const checksum = [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
  signal.throwIfAborted();
  if (checksum !== manifest.sha256) throw new Error('底圖完整性驗證失敗，請重新下載。');
  return blob;
}
