import { terrain3dStyle } from '../map/terrain-3d.js';
export function offlineStyle(pack) {
  const overlays = terrain3dStyle();
  overlays.projection = { type: 'mercator' };
  delete overlays.sources.topo;
  delete overlays.sources.height;
  overlays.sources.basemap = {
    type: 'vector',
    tiles: ['pmtiles://ridgewise-standard/{z}/{x}/{y}'],
    minzoom: 0,
    maxzoom: pack.maxZoom,
    bounds: pack.bounds,
    attribution:
      '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors · <a href="https://protomaps.com">Protomaps</a> / Natural Earth',
  };
  const fill = (id, sourceLayer, color) => ({
    id,
    type: 'fill',
    source: 'basemap',
    'source-layer': sourceLayer,
    filter: ['==', ['geometry-type'], 'Polygon'],
    paint: { 'fill-color': color },
  });
  const line = (id, sourceLayer, color, width) => ({
    id,
    type: 'line',
    source: 'basemap',
    'source-layer': sourceLayer,
    filter: ['==', ['geometry-type'], 'LineString'],
    paint: { 'line-color': color, 'line-width': width },
  });
  const roads = line('roads', 'roads', '#c2ac91', [
    'interpolate',
    ['linear'],
    ['zoom'],
    7,
    0.5,
    14,
    2.5,
  ]);
  const paths = {
    ...line('paths', 'roads', '#b47747', 1.6),
    filter: ['==', ['get', 'kind'], 'path'],
    minzoom: 11,
    paint: { 'line-color': '#b47747', 'line-width': 1.6, 'line-dasharray': [2, 2] },
  };
  overlays.layers = [
    { id: 'land', type: 'background', paint: { 'background-color': '#f2f1e7' } },
    fill('landcover', 'landcover', '#e0e9ce'),
    {
      ...fill('forest', 'landuse', '#d4e2bf'),
      filter: [
        'in',
        ['get', 'kind'],
        ['literal', ['forest', 'wood', 'national_park', 'nature_reserve', 'protected_area']],
      ],
    },
    fill('water', 'water', '#a4cfdf'),
    line('waterways', 'water', '#88bdce', 1.5),
    fill('buildings', 'buildings', '#d7ccba'),
    roads,
    paths,
    {
      id: 'poi-points',
      type: 'circle',
      source: 'basemap',
      'source-layer': 'pois',
      minzoom: 11,
      filter: [
        'in',
        ['get', 'kind'],
        [
          'literal',
          [
            'peak',
            'alpine_hut',
            'wilderness_hut',
            'camp_site',
            'drinking_water',
            'water_point',
            'shelter',
          ],
        ],
      ],
      paint: {
        'circle-radius': 3,
        'circle-color': '#687953',
        'circle-stroke-color': '#fff',
        'circle-stroke-width': 1,
      },
    },
    ...overlays.layers.filter((l) => !['land', 'topo'].includes(l.id)),
  ];
  return overlays;
}
