import { RIDGEWISE_GPX_NAMESPACE } from '../../domain/gpx-quality.js';
import { parseGpx } from '../gpx/parser.js';

export function recordingElapsed(gps, now = Date.now()) {
  return gps.startedAt == null
    ? 0
    : Math.max(0, (gps.endedAt ?? gps.pauseAt ?? now) - gps.startedAt - (gps.pausedMs || 0));
}
export function positiveMinutes(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 && number <= 10080 ? number : null;
}
export function shangheFactor(completed = []) {
  if (
    !completed.length ||
    completed.some(
      (item) =>
        !positiveMinutes(item.baseMinutes) || !Number.isFinite(item.actualMs) || item.actualMs <= 0,
    )
  )
    return null;
  return (
    completed.reduce((sum, item) => sum + item.actualMs, 0) /
    (completed.reduce((sum, item) => sum + item.baseMinutes, 0) * 60000)
  );
}
export function remainingEstimate(reference, elapsed) {
  if (
    !reference ||
    !positiveMinutes(reference.baseMinutes) ||
    !Number.isFinite(reference.factor) ||
    reference.factor <= 0
  )
    return null;
  return Math.max(
    0,
    reference.baseMinutes * reference.factor * 60000 - Math.max(0, elapsed - reference.elapsedMs),
  );
}
const xmlText = (value) =>
  String(value).replace(
    /[&<>"']/g,
    (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' })[c],
  );
const qualityXml = (point) => {
  const values = ['accuracy', 'altitudeAccuracy']
    .filter((key) => Number.isFinite(point[key]) && point[key] >= 0)
    .map((key) => '<rw:' + key + '>' + point[key] + '</rw:' + key + '>')
    .join('');
  return values ? '<extensions>' + values + '</extensions>' : '';
};
export function recordingGpx(gps) {
  return `<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Ridgewise" xmlns="http://www.topografix.com/GPX/1/1" xmlns:rw="${RIDGEWISE_GPX_NAMESPACE}"><metadata><name>${xmlText(gps.name || '我的軌跡')}</name><time>${new Date(gps.startedAt).toISOString()}</time></metadata><trk><name>${xmlText(gps.name || '我的軌跡')}</name>${gps.segments
    .filter((segment) => segment.length)
    .map(
      (segment) =>
        `<trkseg>${segment.map((point) => `<trkpt lat="${point.lat}" lon="${point.lon}">${Number.isFinite(point.elevation) ? `<ele>${point.elevation}</ele>` : ''}<time>${new Date(point.time).toISOString()}</time>${qualityXml(point)}</trkpt>`).join('')}</trkseg>`,
    )
    .join('')}</trk></gpx>`;
}
export function recordingSnapshot(gps, now = Date.now()) {
  // Capture a detached snapshot before asynchronous writes; never persist a watch ID.
  const { watchId, saveError, saving, savedAt, ...data } = gps;
  return JSON.parse(
    JSON.stringify({
      ...data,
      slot: 'active',
      elapsedMs: recordingElapsed(gps, now),
      updatedAt: now,
      raw: recordingGpx(gps),
    }),
  );
}
export function restoreRecording(snapshot, now = Date.now()) {
  // Time with the page closed is excluded. Resuming always starts a new segment.
  const finished = snapshot.status === 'finished';
  const stopped =
    finished ||
    ['review', 'stopping', 'finishing'].includes(snapshot.status) ||
    Boolean(snapshot.finalizePending && snapshot.endedAt != null);
  return {
    ...snapshot,
    status: finished ? 'finished' : stopped ? 'review' : 'paused',
    endedAt: stopped ? snapshot.endedAt : null,
    pauseAt: stopped ? snapshot.pauseAt : now,
    pausedMs: stopped
      ? snapshot.pausedMs
      : Math.max(0, now - snapshot.startedAt - snapshot.elapsedMs),
    watchId: null,
    accuracy: null,
    error: '',
    saveError: '',
    saving: false,
    savedAt: snapshot.updatedAt,
  };
}
export function recordedFile(gps, now = Date.now()) {
  return {
    id: gps.id,
    name: gps.name,
    fileName: `Ridgewise-${new Date(gps.startedAt).toISOString().slice(0, 10)}-${gps.id.slice(0, 8)}.gpx`,
    addedAt: now,
    raw: recordingGpx(gps),
    kind: 'recording',
    recording: {
      ...(gps.navigation ? { navigation: structuredClone(gps.navigation) } : {}),
      ...(gps.routeFactorHistory
        ? { routeFactorHistory: structuredClone(gps.routeFactorHistory) }
        : {}),
      ...(gps.captureSource ? { captureSource: { ...gps.captureSource } } : {}),
      ...(gps.historyObservations
        ? { historyObservations: structuredClone(gps.historyObservations) }
        : {}),
      startedAt: gps.startedAt,
      endedAt: gps.endedAt,
      elapsedMs: recordingElapsed(gps),
      sourceRouteId: gps.sourceRouteId ?? null,
      sourceRouteDirection: gps.sourceRouteDirection === 'reverse' ? 'reverse' : 'forward',
      itinerary: gps.itinerary ?? null,
      calibration: gps.calibration,
      remaining: gps.remaining,
    },
  };
}
export function recordedTrack(file) {
  return {
    ...file,
    ...parseGpx(file.raw, file.fileName, globalThis.DOMParser, {
      allowSinglePoint: true,
      timeWeights: !!file.timeSource,
      filter: true,
    }),
  };
}
