import { routeMatcherFor } from './matching.js';
import { nextStopEtas } from './next-eta.js';
import { trustedRerouteFix } from './rerouting.js';

export function rerouteEtas(file, data, live, gps, fix, now) {
  const result = nextStopEtas(file, data, live, now);
  if (!file?.rerouted || !data?.next || !trustedRerouteFix(gps, fix, now)) return result;
  const previous = data.rows[Math.max(0, data.nextIndex - 1)];
  let positions =
    routeMatcherFor(file)
      .match([{ ...fix, stationId: 'configured-eta', coordinateStatus: 'located' }], {
        maxOffsetM: 50,
        mergeWithinM: 25,
      })
      .matches[0]?.routePositions.filter(
        (p) =>
          p.segmentIndex === data.next.segmentIndex &&
          p.routeProgressM >= previous.routeProgressM - 1e-6 &&
          p.routeProgressM <= data.next.routeProgressM + 1e-6,
      ) ?? [];
  const accepted = gps.itinerary?.routePosition;
  if (
    accepted?.revisionId === file.id &&
    accepted.time === fix.time &&
    accepted.segmentIndex === data.next.segmentIndex &&
    accepted.routeProgressM >= previous.routeProgressM - 1e-6 &&
    accepted.routeProgressM <= data.next.routeProgressM + 1e-6
  )
    positions = [accepted];
  if (positions.length !== 1) return result;
  const metric = {
    factor: data.factor,
    reason: null,
    state: 'live',
    asOf: fix.time,
    source: {
      routeId: file.id,
      direction: 'forward',
      modelVersion: data.timeModel.version,
      to: { ...positions[0], time: fix.time },
    },
  };
  const configured = nextStopEtas(
    file,
    data,
    { asOf: fix.time, total: metric, recent: metric },
    now,
  );
  for (const name of ['total', 'recent']) {
    if (result[name].arrivalUtcMs === null && configured[name].arrivalUtcMs !== null)
      result[name] = {
        ...configured[name],
        factorBasis: 'configured-fallback',
        fallbackReason: result[name].reason,
      };
  }
  return result;
}
