export function createMapPresenter({ document }) {
  function updateCamera({ pitch }) {
    const slider = document.getElementById('map-pitch'),
      label = document.getElementById('map-pitch-value');
    if (slider) slider.value = String(Math.round(pitch));
    if (label) label.textContent = `${Math.round(pitch)}°`;
  }
  function updateStatus({ kind, message }) {
    const status = document.getElementById('map-status');
    if (status) {
      status.textContent = message;
      status.dataset.kind = kind;
    }
    const retry = document.getElementById('map-retry');
    if (retry) retry.hidden = kind !== 'error';
  }
  return { updateCamera, updateStatus };
}
