// A physical place can have a separate Shanghe time node on several area maps.
// Only the sourced registry may assign placeId; proximity alone never merges places.
export function groupStations(stations) {
  const groups = new Map();
  for (const station of stations) {
    const key =
      station.coordinateStatus === 'located' && station.placeId
        ? station.placeId
        : station.stationId;
    const group = groups.get(key);
    if (group) {
      if (group.lat !== station.lat || group.lon !== station.lon)
        throw new Error('Conflicting coordinates for one physical station');
      group.members.push(station);
    } else groups.set(key, { ...station, members: [station] });
  }
  return [...groups.values()];
}

export const stationMembers = (station) => station.members ?? [station];
