import { rawGpxDigest } from '../../domain/time-origin.js';
import { recordingGpx } from '../recording/model.js';

// Integrity and session/content binding, not a GPS authenticity certificate.
const routeBindings = new WeakMap();
export function checkpointRouteBinding(file, plan) {
  let saved = routeBindings.get(plan);
  if (!saved) {
    saved = Promise.all([
      rawGpxDigest(file.raw),
      rawGpxDigest(
        JSON.stringify({
          timeModel: plan.timeModel,
          departureStation: plan.rows?.[0]?.station ?? null,
        }),
      ),
    ])
      .then(([routeSha256, modelSha256]) => ({
        routeId: file.id,
        direction: file.direction ?? 'forward',
        routeSha256,
        modelSha256,
      }))
      .catch(() => null);
    routeBindings.set(plan, saved);
  }
  return saved;
}
export async function sealLiveCheckpoint(state, snapshot, binding) {
  if (!state?.last) return null;
  const resolved = await binding;
  if (!resolved) return null;
  const body = {
    version: 1,
    sessionId: snapshot.id,
    startedAt: snapshot.startedAt,
    savedAt: snapshot.updatedAt,
    binding: resolved,
    recordingSha256: await rawGpxDigest(snapshot.raw),
    state,
  };
  return { ...body, sha256: await rawGpxDigest(JSON.stringify(body)) };
}
export async function readLiveCheckpoint(gps, binding, now = Date.now()) {
  const saved = gps.liveFactorCheckpoint;
  if (
    !saved ||
    saved.version !== 1 ||
    typeof saved.sessionId !== 'string' ||
    !saved.sessionId ||
    saved.sessionId !== gps.id ||
    saved.savedAt !== gps.updatedAt ||
    saved.startedAt !== gps.startedAt ||
    !Number.isFinite(saved.savedAt) ||
    saved.savedAt < gps.startedAt ||
    saved.savedAt > now + 5000
  )
    return null;
  try {
    const body = {
      version: saved.version,
      sessionId: saved.sessionId,
      startedAt: saved.startedAt,
      savedAt: saved.savedAt,
      binding: saved.binding,
      recordingSha256: saved.recordingSha256,
      state: saved.state,
    };
    if (
      !(await binding) ||
      JSON.stringify(saved.binding) !== JSON.stringify(await binding) ||
      saved.recordingSha256 !== (await rawGpxDigest(recordingGpx(gps))) ||
      saved.sha256 !== (await rawGpxDigest(JSON.stringify(body)))
    )
      return null;
    return { state: saved.state, savedAt: saved.savedAt };
  } catch {
    return null;
  }
}
