import { haversine } from '../../domain/track.js';

const validPosition = (point) =>
  Number.isFinite(point?.lat) &&
  Math.abs(point.lat) <= 90 &&
  Number.isFinite(point?.lon) &&
  Math.abs(point.lon) <= 180;

// Use the midpoint along GPX distance, not the densest group of GPS samples.
// A segment gap is never filled with a synthetic line or midpoint.
export function routeReferencePoint(file) {
  const points = file.points?.filter(validPosition) ?? [];
  if (!points.length) return null;
  const totalKm = file.stats?.km;
  if (!Number.isFinite(totalKm) || !points.every((point) => Number.isFinite(point.km)))
    return points[Math.floor(points.length / 2)];
  const half = totalKm / 2;
  const index = points.findIndex((point) => point.km >= half);
  if (index <= 0) return points[index] ?? points.at(-1);
  const previous = points[index - 1],
    next = points[index];
  if (
    previous.segment !== next.segment ||
    next.km <= previous.km ||
    Math.abs(next.lon - previous.lon) > 180
  )
    return half - previous.km <= next.km - half ? previous : next;
  const fraction = (half - previous.km) / (next.km - previous.km);
  return {
    lat: previous.lat + (next.lat - previous.lat) * fraction,
    lon: previous.lon + (next.lon - previous.lon) * fraction,
  };
}

export function nearbyDaylightReference(file, locations, maxDistanceKm = 75) {
  const position = routeReferencePoint(file);
  if (!position) return null;
  let nearest = null,
    distanceKm = Infinity;
  for (const point of locations.points) {
    const distance = haversine(position, point);
    if (distance < distanceKm) {
      nearest = point;
      distanceKm = distance;
    }
  }
  // Do not apply Taiwan county tables to an unrelated overseas GPX.
  return nearest && distanceKm <= maxDistanceKm
    ? { ...nearest, distanceKm, routePosition: position }
    : null;
}
