import { button, esc } from '../../ui/html.js';
import { mapSvg } from '../map/thumbnail.js';

const km = (m) => (Number.isFinite(m) ? (m / 1000).toFixed(2) + ' km' : '不可用');
const metres = (m) => (Number.isFinite(m) ? Math.round(m) + ' m' : '未知');
const duration = (s) =>
  Number.isFinite(s)
    ? `${Math.floor(Math.ceil(s / 60) / 60)} 小時 ${Math.ceil(s / 60) % 60} 分`
    : '不可用';
const arrival = (ms) =>
  Number.isFinite(ms)
    ? new Date(ms).toLocaleString('zh-TW', {
        timeZone: 'Asia/Taipei',
        month: 'numeric',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hourCycle: 'h23',
      })
    : '不可用';
const short = (summary) =>
  summary
    ? `${km(summary.distanceM)} · 爬升 ${metres(summary.ascentM)} · 約 ${duration(summary.totalSeconds)}`
    : '';

export function smartPanel(state) {
  const data = state.itinerary.smart;
  if (!data)
    return '<p class="small muted">點開後自動依目前位置找出折返、單一山頂後返回與其他目的地。</p>';
  const card = (
    item,
  ) => `<li class="smart-option"><button type="button" class="button smart-option-button"
    data-action="smart-reroute-preview" data-option="${esc(item.id)}" ${item.available ? '' : 'disabled'}>
    <strong>${esc(item.title)}</strong><span>${esc(item.subtitle)}</span>
    <small>${item.available ? (item.paths > 1 ? '有多條可行路徑，點選後核對' : esc(short(item.summary))) : '目前不可用'}</small>
    </button>${
      !item.available
        ? `<p class="small error-message">${esc(item.reason)}</p>`
        : item.summary?.arrivalUtcMs === null
          ? '<p class="small muted">GPX 路段可用；上河時間不足，ETA 與部分日夜預估不可用。</p>'
          : ''
    }</li>`;
  const featured = data.options?.filter((r) => r.kind !== 'destination') ?? [];
  const others = data.options?.filter((r) => r.kind === 'destination') ?? [];
  const preview = data.preview,
    summary = preview?.summary;
  return `<div class="smart-reroute stack" aria-label="智慧改道方案" aria-busy="${Boolean(data.busy)}">
    <p class="small muted">選想走的目的地，確認剩餘路線後套用。GPS 會持續紀錄。</p>
    ${data.busy ? '<p role="status">正在核對目前位置與可銜接路線…</p>' : ''}
    ${data.error ? `<p role="status" class="error-message">${esc(data.error)}</p>` : ''}
    ${
      data.locations?.length
        ? `<div class="stack"><h3>你目前在哪條步道？</h3>${data.locations
            .map((p, i) =>
              button(
                p.label +
                  (data.locations.filter((other) => other.label === p.label).length > 1
                    ? `（可能位置 ${i + 1}）`
                    : ''),
                'smart-reroute-location',
                '',
                '',
                `data-location="${esc(p.id)}"`,
              ),
            )
            .join('')}</div>`
        : ''
    }
    ${featured.length ? `<ul class="smart-options">${featured.map(card).join('')}</ul>` : ''}
    ${others.length ? `<details id="smart-other-destinations"><summary>其他目的地（${others.length}）</summary><ul class="smart-options">${others.map(card).join('')}</ul></details>` : ''}
    ${
      data.alternatives?.length
        ? `<section class="stack" aria-label="選擇改道路徑"><h3>有不同路徑，請核對路線圖與途經站點</h3><p class="small muted">最多顯示三條已驗證路徑；請核對形狀、站序及距離，無法確認時使用進階模式。</p>${data.alternatives
            .map(
              (p, i) =>
                `<button type="button" class="button smart-path" data-action="smart-reroute-path" data-path="${i}"><strong>方案 ${i + 1} · 經 ${p.via.map(esc).join(' → ')}</strong><small>${esc(short(p.summary))}</small>${mapSvg(p.file, null, [], true)}</button>`,
            )
            .join('')}</section>`
        : ''
    }
    ${
      summary
        ? `<section class="smart-preview stack" aria-label="智慧改道預覽"><h3 id="smart-preview-title" tabindex="-1">${esc(preview.request.title)}</h3>
      <dl class="smart-metrics"><div><dt>剩餘距離</dt><dd>${km(summary.distanceM)}</dd></div><div><dt>爬升／下降</dt><dd>${metres(summary.ascentM)}／${metres(summary.descentM)}</dd></div>
      <div><dt>預估耗時</dt><dd>${duration(summary.totalSeconds)}</dd></div><div><dt>抵達終點（台北時間）</dt><dd>${arrival(summary.arrivalUtcMs)}</dd></div></dl>
      ${mapSvg(preview.file, null, [], true)}
      <p class="small muted">預覽時間：${arrival(summary.departureUtcMs)}。新路線尚無有效即時倍率，回退設定倍率 ${summary.factor.toFixed(2)}；套用後重新累積本版實測倍率。</p>
      <div class="smart-daylight" role="group" aria-label="改道後日夜預估"><strong>日夜預估${summary.daylight.countyName ? ` · ${esc(summary.daylight.countyName)}` : ''}</strong><p>日間 ${km(summary.daylight.dayM)} · 夜間 ${km(summary.daylight.nightM)} · 未知 ${km(summary.daylight.unknownM)}</p>
      ${summary.daylight.reason ? `<p class="small muted">${esc(summary.daylight.reason)}</p>` : ''}<p class="small muted">依官方日出日落與預估時間，不含山形遮蔽、天候變化。</p></div>
      <details id="smart-station-order" open><summary>剩餘站序與 ETA</summary><ol>${summary.rows
        .slice(1)
        .map(
          (r) =>
            `<li><span>${esc(r.station.name)}</span><span>${arrival(r.arrivalUtcMs)}</span>${r.reason ? `<p class="small error-message">${esc(r.reason)}</p>` : ''}</li>`,
        )
        .join('')}</ol></details>
      ${summary.arrivalUtcMs === null ? '<p class="error-message">時間資料不足，完整 ETA 不可用；保留已知 GPX 路線。</p>' : ''}
      <p class="small muted">原始 GPX、已走軌跡、計時、到站與改道歷史都會保留。</p>
      <p id="smart-location-status" class="small error-message" role="status"></p>
      ${button('確認改道，繼續紀錄', 'smart-reroute-apply', 'primary', '', 'id="smart-reroute-confirm"')}
    </section>`
        : ''
    }
    ${data.applied ? '<p role="status">智慧改道已套用，GPS 持續紀錄。</p>' : ''}
    ${button('更新位置與方案', 'smart-reroute-refresh', 'ghost', 'refresh', data.busy ? 'disabled' : '')}
  </div>`;
}
