import { MODES, LOADS, TIME_STATES, DATA_STATES, REST_STATES, id, object, copy, requireValue, AdapterInputError } from './contracts.js';
import { validateJsonValue } from './validation.js';

export function importDatabase(database) {
  const nodes = new Map(), names = new Map(), pairs = new Map();
  requireValue(object(database) && database.schemaVersion === 2, 'unsupported_schema', 'schemaVersion');
  requireValue(object(database.policy) && database.policy.localOnly === true,
    'local_only_policy_required', 'policy.localOnly');
  requireValue(Array.isArray(database.nodes) && Array.isArray(database.records), 'invalid_database');
  validateJsonValue(database);
  let data;
  try { data = copy(database); } catch { throw new AdapterInputError('invalid_database'); }
  for (const [index, node] of data.nodes.entries()) {
    const path = `nodes[${index}]`;
    requireValue(object(node) && [node.id, node.area, node.name].every(id)
      && node.id.startsWith(`${node.area}:`), 'invalid_node', path);
    requireValue(!nodes.has(node.id), 'duplicate_node_id', path);
    nodes.set(node.id, node);
    const named = names.get(node.name) ?? [];
    named.push(node);
    names.set(node.name, named);
  }
  const recordIds = new Set();
  for (const [index, record] of data.records.entries()) {
    const path = `records[${index}]`;
    requireValue(object(record) && [record.id, record.area, record.from, record.to,
      record.fromNodeId, record.toNodeId, record.direction, record.originalBlock].every(id), 'invalid_record', path);
    requireValue(!recordIds.has(record.id), 'duplicate_record_id', path);
    recordIds.add(record.id);
    for (const side of ['from', 'to']) {
      const node = nodes.get(record[`${side}NodeId`]);
      requireValue(node && node.area === record.area && node.name === record[side], 'node_id_mismatch', `${path}.${side}NodeId`);
    }
    requireValue(record.baselineMinutes === null || (typeof record.baselineMinutes === 'number'
      && Number.isFinite(record.baselineMinutes) && record.baselineMinutes > 0), 'invalid_baseline_minutes', path);
    requireValue(MODES.has(record.mode) && LOADS.has(record.load), 'invalid_record_condition', path);
    requireValue(record.speedVariant === null || id(record.speedVariant), 'invalid_speed_variant', path);
    requireValue(record.timeVariant === null || id(record.timeVariant), 'invalid_time_variant', path);
    requireValue(TIME_STATES.has(record.timeStatus) && DATA_STATES.has(record.dataStatus), 'invalid_record_status', path);
    requireValue(REST_STATES.has(record.restIncluded), 'invalid_rest_inclusion', path);
    requireValue(record.distanceM === null || (typeof record.distanceM === 'number'
      && Number.isFinite(record.distanceM) && record.distanceM >= 0), 'invalid_distance', path);
    requireValue(typeof record.sourceAccessRestriction === 'boolean' && id(record.imageVerification), 'invalid_review_metadata', path);
    requireValue(object(record.source) && [record.source.file, record.source.block].every(id)
      && Number.isInteger(record.source.line) && record.source.line > 0
      && Number.isInteger(record.source.endLine) && record.source.endLine >= record.source.line,
    'invalid_provenance', path);
    requireValue(object(record.metadata), 'invalid_metadata', path);
    const key = JSON.stringify([record.area, record.fromNodeId, record.toNodeId]);
    const group = pairs.get(key) ?? [];
    group.push(record);
    pairs.set(key, group);
  }
  return { nodes, names, pairs };
}
