import { sampled } from '../../domain/track.js';
import { icon, esc } from '../../ui/html.js';
import { PHASE_COLORS } from '../daylight/model.js';
export function elevationSvg(file, profile = null) {
  if (!file.stats.withElevation)
    return `<div class="elevation-empty">${icon('mountain')}<div><strong>尚無高度資料</strong><p>取得 GPX 高度資料後，就能查看沿途高低起伏。</p></div></div>`;
  let low = Infinity,
    high = -Infinity,
    peak = null;
  for (const point of file.points)
    if (Number.isFinite(point.elevation)) {
      low = Math.min(low, point.elevation);
      if (point.elevation > high) {
        high = point.elevation;
        peak = point;
      }
    }
  const span = Math.max(high - low, 20),
    floor = Math.floor(low - span * 0.12),
    ceiling = Math.ceil(high + span * 0.12);
  const left = 56,
    right = 620,
    top = 18,
    bottom = 154;
  const y = (value) => bottom - ((value - floor) / (ceiling - floor)) * (bottom - top);
  const distanceX = (km) => left + (km / Math.max(file.stats.km, 0.000001)) * (right - left);
  const x = (point) => distanceX(point.km);
  const groups = [];
  let group = [],
    previous = null;
  for (const point of file.points) {
    if (!Number.isFinite(point.elevation) || previous !== point.segment) {
      if (group.length) groups.push(group);
      group = [];
    }
    if (Number.isFinite(point.elevation)) group.push(point);
    previous = point.segment;
  }
  if (group.length) groups.push(group);
  const shapes = groups.map((segment) => {
    const selection = new Set(sampled(segment)),
      points = segment.filter((point) => selection.has(point) || point === peak);
    const coordinates = points.map(
      (point) => `${x(point).toFixed(2)},${y(point.elevation).toFixed(2)}`,
    );
    if (points.length === 1)
      return {
        area: '',
        line: `<circle cx="${x(points[0])}" cy="${y(points[0].elevation)}" r="3" fill="${profile ? PHASE_COLORS.unknown : '#326753'}"/>`,
      };
    return {
      area: `M${x(points[0]).toFixed(2)},${bottom} L${coordinates.join(' L')} L${x(points.at(-1)).toFixed(2)},${bottom} Z`,
      line: `<polyline points="${coordinates.join(' ')}" fill="none" stroke="#326753" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>`,
    };
  });
  const areas = shapes
    .filter((shape) => shape.area)
    .map(
      (shape) =>
        `<path class="elevation-area" d="${shape.area}" fill="${profile ? '#b8c0bc' : 'url(#elevation-fill)'}" opacity="${profile ? '.55' : '1'}"/>`,
    )
    .join('');
  const clip = shapes
    .filter((shape) => shape.area)
    .map((shape) => `<path d="${shape.area}"/>`)
    .join('');
  const phaseLabels = { day: '白天', night: '夜間', unknown: '時間待補' };
  const timeLabel = (milliseconds) =>
    new Date(milliseconds).toLocaleString('zh-TW', {
      timeZone: 'Asia/Taipei',
      month: 'numeric',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hourCycle: 'h23',
    });
  const colors = (profile?.bands ?? [])
    .map((band) => {
      const start = distanceX(band.fromM / 1000),
        end = distanceX(band.toM / 1000);
      return `<rect class="height-phase-band" data-phase="${band.phase}" data-start="${band.start}" data-end="${band.end}" x="${start.toFixed(2)}" y="${top}" width="${Math.max(0, end - start).toFixed(2)}" height="${bottom - top}" fill="${PHASE_COLORS[band.phase]}"><title>${phaseLabels[band.phase]} · ${esc(timeLabel(band.start))}–${esc(timeLabel(band.end))}</title></rect>`;
    })
    .join('');
  const transitions = (profile?.bands ?? [])
    .flatMap((band, index, all) => {
      const previous = all[index - 1];
      if (!previous || Math.abs(previous.toM - band.fromM) > 0.001 || previous.phase === band.phase)
        return [];
      const position = distanceX(band.fromM / 1000);
      return [
        `<path class="height-phase-boundary" d="M${position.toFixed(2)} ${top}V${bottom}"><title>${phaseLabels[previous.phase]} → ${phaseLabels[band.phase]} · ${esc(timeLabel(band.start))}</title></path>`,
      ];
    })
    .join('');
  const labels = (profile?.bands ?? [])
    .map((band) => {
      const start = distanceX(band.fromM / 1000),
        end = distanceX(band.toM / 1000);
      return end - start >= 70
        ? `<text class="height-phase-label" x="${((start + end) / 2).toFixed(2)}" y="29" text-anchor="middle">${phaseLabels[band.phase]}</text>`
        : '';
    })
    .join('');
  const grid = [0, 1 / 3, 2 / 3, 1]
    .map((ratio) => {
      const value = ceiling - (ceiling - floor) * ratio,
        position = top + (bottom - top) * ratio;
      return `<path d="M${left} ${position}H${right}" stroke="#afc4a1" stroke-opacity=".55" stroke-dasharray="3 5"/><text x="43" y="${position + 4}" text-anchor="end">${Math.round(value).toLocaleString()}</text>`;
    })
    .join('');
  const ticks = [0, 0.5, 1]
    .map((ratio) => {
      const position = left + ratio * (right - left),
        label =
          ratio === 0
            ? '0'
            : (file.stats.km * ratio).toFixed(ratio === 1 || file.stats.km < 10 ? 2 : 1);
      return `<path d="M${position} ${bottom}v5" stroke="#a3b998"/><text x="${position}" y="181" text-anchor="${ratio === 0 ? 'start' : ratio === 1 ? 'end' : 'middle'}">${label} km</text>`;
    })
    .join('');
  return `<div class="elevation-summary"><span>最低高度 <strong>${Math.round(low).toLocaleString()}<small>m</small></strong></span><span>最高高度 <strong>${Math.round(high).toLocaleString()}<small>m</small></strong></span><span class="elevation-distance">全程 <strong>${file.stats.km.toFixed(2)}<small>km</small></strong></span></div><svg class="elevation-chart" viewBox="0 0 640 194" role="img" aria-label="GPX 路線高度剖面${profile ? '，白天暖色、夜間深藍，未知時間灰色' : ''}；缺少高度與分段處不連線"><defs><linearGradient id="elevation-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#5f8c58" stop-opacity=".55"/><stop offset="100%" stop-color="#99b67c" stop-opacity=".12"/></linearGradient><clipPath id="height-profile-clip">${clip}</clipPath></defs><g font-size="11" fill="#61785a">${grid}${ticks}<text class="elevation-axis-unit" x="43" y="5" text-anchor="end">高度 m</text></g>${areas}<g clip-path="url(#height-profile-clip)">${colors}</g>${shapes.map((shape) => shape.line).join('')}${transitions}${labels}<circle cx="${x(peak)}" cy="${y(high)}" r="4.5" fill="#326753" stroke="#eef4e6" stroke-width="2"><title>最高高度 ${Math.round(high)} m · ${peak.km.toFixed(2)} km</title></circle></svg><p class="elevation-caption">${file.processing ? '高度與距離已校正 GPS 抖動' : '高度與距離依 GPX 資料顯示'} · 缺漏處保留空白</p>`;
}
