import { icon, button } from './html.js';
import { navItems } from '../core/navigation.js';
export function shellHeader() {
  return `<header class="app-brand-bar"><a href="#routes" class="app-brand">${icon('mountain')}<span>RIDGEWISE<small>YOUR TRAIL, YOUR PACE</small></span></a>${button('使用說明', 'help', 'ghost help-button', 'help')}</header>`;
}
export function bottomNavigation(view, file) {
  const active = view === 'plan' ? (file?.kind === 'recording' ? 'library' : 'routes') : view;
  return `<nav class="bottom-nav" aria-label="主要導覽">${navItems.map(([id, ic, label]) => `<button data-view="${id}" class="${active === id ? 'active' : ''}" ${active === id ? 'aria-current="page"' : ''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav>`;
}
