import { stationMembers } from './station-groups.js';
import { uniqueTimePath } from './time-path.js';
import { distanceM } from '../../../../packages/route-stations/index.js';

// 100 m produces candidates, not proof of entering a terminal side trail.
// Keep close passes conservatively; a distant candidate needs the branch's
// entry AND return gate occurrences. This is per visit, never per station.
const CLOSE_PASS_M = 25;
export function resolveBranchVisits(candidates, { ids, graph } = {}) {
  if (!ids || !graph) return { occurrences: candidates, bypassedOccurrences: [] };
  const neighbors = new Map();
  for (const [from, targets] of graph)
    for (const to of targets) {
      if (!neighbors.has(from)) neighbors.set(from, new Set());
      if (!neighbors.has(to)) neighbors.set(to, new Set());
      neighbors.get(from).add(to);
      neighbors.get(to).add(from);
    }
  const bindings = (point) => stationMembers(point.station).map((s) => ids.get(s.stationId));
  const places = new Map(candidates.flatMap((p) => bindings(p).map((id) => [id, p.station])));
  const bypassedOccurrences = [];
  const occurrences = candidates.filter((point, index) => {
    if (point.offsetM <= CLOSE_PASS_M) return true;
    const leafIds = bindings(point);
    // All area bindings must agree on a bidirectional terminal branch and a
    // located junction. Unknown or conflicting topology stays unresolved.
    const gates = leafIds.map((id) => {
      const adjacent = [...(neighbors.get(id) ?? [])];
      const gate = adjacent[0];
      return adjacent.length === 1 &&
        graph.get(id)?.has(gate) &&
        graph.get(gate)?.has(id) &&
        neighbors.get(gate)?.size >= 3
        ? places.get(gate)
        : null;
    });
    if (!gates.length || gates.some((gate) => !gate || gate !== gates[0])) return true;
    const gate = gates[0];
    // Overlapping 100 m neighborhoods cannot establish distinct gate visits.
    if (distanceM(gate, point.station) <= 200) return true;
    const before = candidates.slice(0, index).findLast((p) => p.station !== point.station);
    const after = candidates.slice(index + 1).find((p) => p.station !== point.station);
    // Do not infer a return across a GPX interruption or beyond an endpoint.
    if (
      !before ||
      !after ||
      before.segmentIndex !== point.segmentIndex ||
      after.segmentIndex !== point.segmentIndex
    )
      return true;
    if (before.station === gate && after.station === gate) return true;
    if (before.station !== gate && after.station !== gate) return true;
    const mainPath = bindings(before).some((a) =>
      bindings(after).some((b) => uniqueTimePath(graph, a, b, new Set(leafIds)).nodes),
    );
    if (!mainPath) return true;
    bypassedOccurrences.push({
      ...point,
      reason: 'terminal-branch-pass-without-return-gate',
      gateStationId: gate.stationId,
    });
    return false;
  });
  return { occurrences, bypassedOccurrences };
}
