import { rerouteStarts, buildReroute } from './rerouting.js';
import { createConnectedRouter } from './connected-routing.js';

const canonicalM = (file, m) => (file.direction === 'reverse' ? file.stats.km * 1000 - m : m);
export function startsAtSmartLocation(network, fix, location) {
  if (!location || location.sourceId !== network.sourceFile.id) return [];
  const total = network.sourceFile.stats.km * 1000;
  const m =
    location.m ??
    (location.direction === 'reverse' ? total - location.directedM : location.directedM);
  const knownSegment =
    location.segment ??
    (Number.isInteger(location.directedSegment)
      ? location.direction === 'reverse'
        ? network.sourceFile.segments.length - 1 - location.directedSegment
        : location.directedSegment
      : undefined);
  return rerouteStarts(network, fix).filter((edge) => {
    const segment =
      edge.source.direction === 'reverse'
        ? edge.source.segments.length - 1 - edge.segment
        : edge.segment;
    return (
      (knownSegment === undefined || knownSegment === segment) &&
      Math.abs(canonicalM(edge.source, edge.startM) - m) <= 25
    );
  });
}

export function smartRequests(network, home) {
  const requests = [
    {
      id: 'return',
      kind: 'return',
      destination: home?.key ?? null,
      title: '立即原路折返',
      subtitle: home ? `返回${home.name}` : '原計畫起點無法確認',
    },
  ];
  for (const [id, station] of network.destinations) {
    if (station.type === 'summit' && id !== home?.key)
      requests.push({
        id: 'summit:' + id,
        kind: 'summit',
        destination: id,
        title: `只走${station.name}後返回`,
        subtitle: home ? `返回${home.name}` : '原計畫起點無法確認',
      });
  }
  for (const [id, station] of network.destinations) {
    if (id !== home?.key && station.type !== 'summit')
      requests.push({
        id: 'destination:' + id,
        kind: 'destination',
        destination: id,
        title: `前往${station.name}`,
        subtitle: '其他目的地',
      });
  }
  return requests;
}

export function createSmartPlanner(network) {
  const route = createConnectedRouter(network);
  return function plan({
    request,
    starts,
    location,
    home,
    visited = new Set(),
    now,
    id = crypto.randomUUID(),
  }) {
    if (!starts.length) throw new Error('目前定位無法對應原 GPX 的可信路段。');
    if (!request.destination || (request.kind !== 'destination' && !home))
      throw new Error('無法確認原計畫起點，請使用進階模式核對返回地點。');
    const exclude = new Set();
    if (request.kind === 'summit') {
      for (const [key, station] of network.destinations)
        if (station.type === 'summit' && key !== request.destination && key !== home.key)
          exclude.add(key);
    }
    let allow = () => true;
    if (request.kind === 'return') {
      if (home.canonicalM === undefined)
        throw new Error('目前 GPX 與原出發 GPX 不同，無法確認原路，請核對返回路徑。');
      const total = network.sourceFile.stats.km * 1000;
      const currentM =
        location.m ??
        (location.direction === 'reverse' ? total - location.directedM : location.directedM);
      const pair = (edge) => JSON.stringify([edge.fromKey, edge.toKey].sort());
      const prefixPairs = new Set(starts.map(pair));
      for (const edge of network.edges) {
        const from = canonicalM(edge.source, edge.startM),
          to = canonicalM(edge.source, edge.endM);
        if (
          Math.min(from, to) >= Math.min(currentM, home.canonicalM) - 1e-6 &&
          Math.max(from, to) <= Math.max(currentM, home.canonicalM) + 1e-6
        )
          prefixPairs.add(pair(edge));
      }
      // The same physical return corridor may be a later visit in a loop GPX.
      // Returning hikers must continue home, not reverse the entire timeline.
      allow = (edge) => prefixPairs.has(pair(edge));
      for (const [key, station] of network.destinations)
        if (station.type === 'summit' && key !== home.key && !visited.has(key)) exclude.add(key);
    }
    const variants = new Map();
    for (const start of starts) {
      const outward = route(start, request.destination, { exclude, allow });
      for (const path of outward) {
        const returns =
          request.kind === 'summit' ? route(path.at(-1), home.key, { exclude }) : [[path.at(-1)]];
        for (const back of returns) {
          const arcs = request.kind === 'summit' ? [...path.slice(0, -1), ...back] : path;
          const identity = route.pathKey(arcs);
          if (variants.has(identity)) continue;
          const result = buildReroute({
            network,
            arcs,
            destination: request.destination,
            returnTo: request.kind === 'summit' ? home.key : null,
            id,
            now,
          });
          if (!result.plan.geometryComplete) continue;
          result.file.name = request.title;
          variants.set(identity, { ...result, routeKey: identity, request });
        }
      }
    }
    const candidates = [...variants.values()].sort((a, b) => a.file.stats.km - b.file.stats.km);
    const sequence = (result) => JSON.parse(result.routeKey).map((part) => JSON.stringify(part));
    const subsequence = (short, long) => {
      let cursor = 0;
      for (const key of long) if (short[cursor] === key) cursor++;
      return cursor === short.length;
    };
    // Do not ask users to choose an unnecessary repeat of an otherwise equal
    // route. Keep a hut/junction return visit when it is needed for a real join.
    const results = candidates.filter(
      (result) =>
        !candidates.some(
          (other) =>
            other !== result &&
            other.file.stats.km <= result.file.stats.km &&
            other.plan.rows.length < result.plan.rows.length &&
            subsequence(sequence(other), sequence(result)),
        ),
    );
    if (!results.length)
      throw new Error(
        request.kind === 'summit'
          ? '無法以現有 GPX 可靠銜接單一山頂及返回路線；可能須經其他山頂或存在斷軌、未確認接點。'
          : '無法以現有 GPX 可靠銜接目的地；存在斷軌或未確認接點，不補畫道路。',
      );
    return results.slice(0, 3);
  };
}
