import { normalizeLocationFix } from './provider.js';

/**
 * Wire format of the foreground RidgewiseLocation Core Location bridge.
 * native-ios.js implements LocationProvider.watch and translates native errors.
 * timestampSeconds must be CLLocation.timestamp.timeIntervalSince1970, not an
 * Apple reference-date interval. Use CLLocation.ellipsoidalAltitude to match the
 * Web API datum; do not substitute mean-sea-level CLLocation.altitude. If that
 * datum is unavailable, pass null rather than applying an invented offset.
 * @typedef {{latitude: number, longitude: number, ellipsoidalAltitude: number|null,
 *   timestampSeconds: number, horizontalAccuracy: number, verticalAccuracy: number|null}} CoreLocationFix
 * @typedef {import('./provider.js').LocationProvider} IOSLocationProvider
 */

/** @param {CoreLocationFix} location */
export function normalizeCoreLocation(location) {
  if (!location) return null;
  // Core Location declares altitude invalid when vertical accuracy is <= 0.
  const hasAltitude = Number.isFinite(location.verticalAccuracy) && location.verticalAccuracy > 0;
  return normalizeLocationFix({
    lat: location.latitude,
    lon: location.longitude,
    elevation: hasAltitude ? location.ellipsoidalAltitude : null,
    time: Number.isFinite(location.timestampSeconds)
      ? Math.round(location.timestampSeconds * 1000)
      : null,
    accuracy: location.horizontalAccuracy,
    altitudeAccuracy: hasAltitude ? location.verticalAccuracy : null,
    simulated: location.simulated === true,
  });
}
