import { readCoordinateCatalog } from '../../../../packages/route-stations/index.js';
import { RouteTimeAdapter } from '../../../../packages/route-time-adapter/adapter.js';

export function validateResources(catalog, database) {
  const stations = catalog ? readCoordinateCatalog(catalog) : [];
  const adapter = database ? new RouteTimeAdapter(database) : null;
  return { stations, adapter, database };
}
export function mapTimeNodes(stations, adapter) {
  const nodes = adapter?.listNodes() ?? [];
  return new Map(
    stations.map((station) => {
      const names = new Set([station.name, station.originalName, ...(station.nameAliases ?? [])]);
      const candidates = nodes.filter(
        (node) =>
          node.area === station.area &&
          (station.timeNodeId ? node.id === station.timeNodeId : names.has(node.name)),
      );
      return [station.stationId, candidates.length === 1 ? candidates[0].id : null];
    }),
  );
}
