export const MODES = new Set(['walk', 'road_walk', 'drive', 'forest_road', 'road_connector',
  'external_connector', 'road_closed', 'unknown', 'distance_only']);
export const LOADS = new Set(['light', 'heavy', 'unspecified', 'unknown']);
export const TIME_STATES = new Set(['known', 'missing', 'invalid']);
export const DATA_STATES = new Set(['distinct', 'duplicate', 'conflict']);
export const REST_STATES = new Set(['included', 'excluded', 'unknown']);
export const LOAD_VARIANTS = new Map([['light', 'light'], ['heavy', 'heavy'], ['輕裝', 'light'], ['重裝', 'heavy']]);
export const id = value => typeof value === 'string' && value.trim().length > 0;
export const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
export const copy = value => structuredClone(value);

export class AdapterInputError extends TypeError {
  constructor(code, path = null) {
    super(code);
    this.name = 'AdapterInputError';
    this.code = code;
    this.path = path;
  }
}

export function requireValue(condition, code, path) {
  if (!condition) throw new AdapterInputError(code, path);
}

export const failure = (code, records = [], details = {}) => ({ code, records, details });
export const etaStatus = code => code === 'time_variant_required' ? 'variant_required'
  : ['load_unavailable', 'load_applicability_ambiguous'].includes(code) ? 'load_required'
  : code === 'conflicting_directed_edge' ? 'conflict'
  : ['missing_time', 'missing_directed_edge'].includes(code) ? 'missing' : 'unavailable';
