import { directionPanel } from './direction-view.js';
import { button, metric, meters, esc } from '../../ui/html.js';
import { emptyView } from '../../ui/empty-view.js';
import { createCorrectionView } from '../gpx/diagnostics-view.js';
import { timeSourcePanel } from '../gpx/time-source-view.js';
export function createRouteViews({ current, gpsPending, mapPanel, itineraryViews, state }) {
  const correctionPanel = createCorrectionView({ state });
  function routeStats(file) {
    return `<div class="stats">${metric('軌跡距離', file.stats.km.toFixed(2), 'km', 'distance')}${metric('全程預估時間', itineraryViews?.estimatedDuration?.() ?? '尚未提供', '', 'clock')}${metric('累積爬升', meters(file.stats.up), 'm', 'up')}${metric('累積下降', meters(file.stats.down), 'm', 'down')}</div>`;
  }
  function planView() {
    const file = current();
    if (!file) return emptyView();
    return `<div class="content-grid route-plan ${itineraryViews ? 'itinerary-layout' : ''}"><section class="panel route-summary"><div class="route-heading"><span class="eyebrow">YOUR GPX · ${file.stats.points.toLocaleString()} POINTS</span><h2>${esc(file.name)}</h2><p>${esc(file.fileName)} · ${file.direction === 'reverse' ? '反向走（GPX 終點出發）' : '原向走（GPX 起點出發）'}</p></div>${routeStats(file)}${file.warnings.length ? `<div class="panel-body stack">${file.warnings.map((warning) => `<p class="soft-notice">${esc(warning)}</p>`).join('')}</div>` : ''}</section><div class="route-departure">${departurePanel(file)}</div><div class="main-column">${mapPanel(file)}${file.kind === 'recording' ? '' : (itineraryViews?.nextCard() ?? nextCard(file))}${itineraryViews?.stationsPanel() ?? ''}
    ${timeSourcePanel(file, { locked: gpsPending() || state?.starting || state?.timeSourceBusy, error: state?.timeSourceError })}${correctionPanel(file)}<section class="panel panel-body"><details id="route-data-details"><summary>資料完整度與計算限制</summary><div class="stack"><div class="data-checks">
      <div><strong>時間依據</strong><span>上河 1.0 有向時間；缺漏與多路徑原因列在站點清單</span></div>
      <div><strong>海拔資料</strong><span>${file.stats.withElevation.toLocaleString()} / ${file.stats.points.toLocaleString()} 點</span></div>
      <div><strong>軌跡分段</strong><span>${file.segments.length} 段 · 中斷處不連線</span></div>
    </div><p class="small muted">上河 1.0 時間：${itineraryViews?.referenceDuration() ?? '尚未提供'}；全程預估時間依設定倍率，不含額外休息。</p>
    <p class="small muted">${file.processing ? '路線距離與海拔已校正 GPS 抖動，爬升／下降與高度剖面使用相同資料；原始 GPX 保持不變。' : '高度直接取自 GPX，爬升與下降為相鄰點加總，未經去噪。'}站點與上河時間已內建；有基準的相鄰路段會顯示 ETA，無法確認的路段保留待補。日夜塗色依參考縣市官方日出／日落與路段 ETA 顯示；資料不足保留灰色。</p></div></details></section></div>
    <aside class="side-column">${button('更換路線', 'choose-route', '', 'compass', gpsPending() ? 'disabled' : '')}</aside></div>`;
  }
  function departurePanel(file) {
    if (file.kind !== 'recording') return settingsPanel(file) + startPanel();
    return `<section class="panel panel-body stack"><h2>你保存的軌跡</h2>${button('下載 GPX', 'file-download', 'primary', 'download', `data-id="${file.id}"`)}${button('作為參考路線', 'use-recording-route', '', 'route', `data-id="${file.id}" ${gpsPending() || state?.timeSourceBusy ? 'disabled' : ''}`)}<p class="small muted">保留原始 GPX，在此裝置建立參考路線；錄製來源可追溯且時間品質通過時，可用於站間比例。</p></section>`;
  }
  function settingsPanel(_file) {
    return `${directionPanel(_file, { locked: gpsPending() || state?.starting, error: state?.directionError })}${itineraryViews?.resourcesPanel() ?? ''}`;
  }
  function startPanel() {
    return `<section class="panel panel-body stack route-start"><p class="small muted">預估耗時：<strong>${itineraryViews?.estimatedDuration?.() ?? '尚未提供'}</strong>（依設定倍率，不含額外休息）</p>${button(gpsPending() ? '查看 GPS 紀錄' : '開始登山紀錄', gpsPending() ? 'view-record' : 'gps-start', 'primary', 'locate', state?.starting ? 'disabled' : '')}<p class="small muted">依目前方向與倍率出發，開始後請求定位並保留恢復草稿；結束時再選擇是否保存 GPX。</p></section>`;
  }
  function nextCard(file) {
    return `<section class="panel next-card"><span class="eyebrow">ARRIVAL · 抵達時間</span><h2>尚未提供</h2><p class="small">這條 GPX 尚未配對上河路段時間。</p><div class="next-metrics"><div><strong>${file.stats.km.toFixed(2)} km</strong><small>全程軌跡距離</small></div></div><p class="small note-space">山頂、山屋、水源、營地與登山口／出口的路線對應尚未完成。</p></section>`;
  }
  return { planView, settingsPanel, nextCard };
}
