export function createTimeGraph(database) {
  const graph = new Map();
  for (const record of database?.records ?? []) {
    if (record.mode !== 'walk') continue;
    const key = record.fromNodeId;
    if (!graph.has(key)) graph.set(key, new Set());
    graph.get(key).add(record.toNodeId);
  }
  return graph;
}
export function uniqueTimePath(graph, from, to, blocked = new Set()) {
  if (!from || !to) return { nodes: null, reason: '未對應時間節點' };
  const paths = [];
  let visits = 0,
    limit = false;
  function search(node, path) {
    if (++visits > 5000 || path.length > 30) {
      limit = true;
      return;
    }
    if (node === to) {
      paths.push(path);
      return;
    }
    for (const next of graph.get(node) ?? []) {
      if (paths.length > 1) break;
      if (!path.includes(next) && (next === to || !blocked.has(next)))
        search(next, [...path, next]);
    }
  }
  search(from, [from]);
  if (limit) return { nodes: null, reason: '路段資料過於複雜，需核對' };
  if (paths.length !== 1)
    return {
      nodes: null,
      reason: paths.length ? '有多條可能路徑，需核對中間站點' : '缺少相鄰有向路段',
    };
  return { nodes: paths[0], reason: null };
}
