import { haversine } from '../../domain/track-math.js';
import { positionReliable, elevationReliable } from '../../domain/track-filter.js';
import { recordingProcessor, settleRecording } from './analysis.js';
import { normalizeLocationFix } from '../location/provider.js';
export function createGeolocationTracker({
  getRecording,
  onChange,
  onSave,
  onPoint,
  onFix = () => {},
  onInterruption = () => {},
  onLimit,
  locationProvider,
}) {
  let gpsGeneration = 0,
    cancelWatch = null;
  function stop() {
    gpsGeneration++;
    settleRecording(getRecording());
    const cancel = cancelWatch;
    cancelWatch = null;
    getRecording().watchId = null;
    cancel?.();
  }
  function start() {
    stop();
    const generation = gpsGeneration,
      gps = getRecording();
    const isCurrent = () => generation === gpsGeneration && getRecording() === gps;
    const fail = (error) => {
      if (!isCurrent()) return;
      if (['timeout', 'position-unavailable'].includes(error?.code)) {
        gps.status = 'requesting';
        gps.error = '定位訊號暫時中斷，正在等待下一個有效定位。';
        onInterruption('gps-signal-unavailable');
        onChange();
        return;
      }
      stop();
      gps.status = 'error';
      gps.pauseAt = Date.now();
      gps.error =
        error?.code === 'unsupported'
          ? '此瀏覽器不支援定位。請使用支援定位的瀏覽器。'
          : error?.code === 'permission-denied'
            ? error.source === 'ios'
              ? '定位權限未開啟。請到 iOS「設定 → Ridgewise → 定位」允許使用 App 期間定位，再按「繼續紀錄」。'
              : '定位權限未開啟。請允許此網站使用定位後，再按繼續紀錄。'
            : error?.code === 'position-unavailable'
              ? '目前無法取得位置，請到訊號較好的地方再試。'
              : error?.code === 'timeout'
                ? '定位逾時，按繼續紀錄重試。'
                : error?.code === 'foreground-required'
                  ? '定位已在背景停止，請回到 App 後按「繼續紀錄」。'
                  : error?.source === 'ios'
                    ? '無法啟動原生定位，請確認 iOS 定位權限，或重新開啟 App 後重試。'
                    : '無法啟動定位，請確認網站定位權限，並由 HTTPS 或 localhost 開啟。';
      onInterruption('gps-interrupted');
      onSave();
      onChange();
    };
    gps.status = 'requesting';
    gps.error = '';
    const processor = recordingProcessor(gps);
    gps.segments.push([]);
    processor.startSegment();
    const segment = gps.segments.at(-1),
      requestedAt = Date.now();
    // Order every valid callback, including fixes below the raw sampling threshold.
    let latestTimestamp = processor.lastRawPoint()?.time ?? -Infinity;
    try {
      const subscription = locationProvider.watch((fix) => {
        if (!isCurrent()) return;
        const point = normalizeLocationFix(fix);
        if (
          !point ||
          point.time < Math.max(requestedAt - 5000, Date.now() - 60000) ||
          point.time > Date.now() + 5000 ||
          point.time <= latestTimestamp
        ) {
          onInterruption(
            point &&
              (point.time < Math.max(requestedAt - 5000, Date.now() - 60000) ||
                point.time > Date.now() + 5000)
              ? 'gps-time-quality-exclusion'
              : 'rejected-gps-fix',
          );
          return;
        }
        latestTimestamp = point.time;
        gps.accuracy = point.accuracy;
        const last = segment.at(-1);
        if (
          !last ||
          haversine(last, point) >= 0.003 ||
          point.time - last.time >= 30000 ||
          positionReliable(last) !== positionReliable(point) ||
          elevationReliable(last) !== elevationReliable(point)
        ) {
          if (processor.stats().points >= 100000) {
            onLimit('已達 100,000 個紀錄點，請結束此份紀錄後再開新紀錄。');
            return;
          }
          segment.push(point);
          processor.append(point);
          onPoint();
        }
        const latest = processor.latestPoint();
        const reliable = positionReliable(point) && !latest?.excluded;
        gps.status = reliable ? 'tracking' : 'requesting';
        gps.error = !positionReliable(point)
          ? '目前定位精度不足，原始位置已保留，該段暫不計入距離。'
          : latest?.excluded
            ? '位置跳動待確認，原始位置已保留，暫不計入距離。'
            : !elevationReliable(point)
              ? '海拔精度不足，原始高度已保留，爬升資料暫不完整。'
              : '';
        onFix(
          {
            ...point,
            excluded: !reliable,
            qualityReason: !positionReliable(point)
              ? 'horizontal-accuracy'
              : !reliable
                ? 'position-jump'
                : null,
          },
          Date.now(),
        );
        onChange();
      }, fail);
      const attach = (cancel) => {
        if (typeof cancel !== 'function') {
          fail({ code: 'start-failed' });
          return;
        }
        if (isCurrent()) cancelWatch = cancel;
        else cancel();
      };
      if (subscription && typeof subscription.then === 'function')
        subscription.then(attach, () => fail({ code: 'start-failed' }));
      else attach(subscription);
    } catch {
      fail({ code: 'start-failed' });
    }
    if (isCurrent()) {
      onSave();
      onChange();
    }
  }
  return { start, stop };
}
