// Treat each Number's canonical decimal representation as its value. Exact
// decimal sums avoid both binary drift and rounding each leg before addition.
export function decimal(value) {
  const [mantissa, exponentText = '0'] = String(value).toLowerCase().split('e');
  const [whole, fraction = ''] = mantissa.split('.');
  const exponent = Number(exponentText);
  let coefficient = BigInt(whole + fraction);
  let scale = fraction.length - exponent;
  if (scale < 0) {
    coefficient *= 10n ** BigInt(-scale);
    scale = 0;
  }
  return { coefficient, scale };
}

export function add(a, b) {
  const scale = Math.max(a.scale, b.scale);
  return { coefficient: a.coefficient * 10n ** BigInt(scale - a.scale)
    + b.coefficient * 10n ** BigInt(scale - b.scale), scale };
}

export function multiply(a, b) {
  return { coefficient: a.coefficient * b.coefficient, scale: a.scale + b.scale };
}

export function asNumber(value) {
  return Number(`${value.coefficient}e-${value.scale}`);
}

export function roundedMs(seconds) {
  const numerator = seconds.coefficient * 1000n;
  const denominator = 10n ** BigInt(seconds.scale);
  return (numerator * 2n + denominator) / (denominator * 2n);
}
