import { createOfflineMapStore } from './store.js';
import { downloadMap, validateManifest } from './download.js';
import { prepareOfflineShell } from './shell.js';
export function createOfflineMapController({
  store = createOfflineMapStore(),
  document = globalThis.document,
  navigator = globalThis.navigator,
  fetch = globalThis.fetch,
  prepareShell = () => prepareOfflineShell({ navigator, document }),
  downloader = downloadMap,
  onChange = () => {},
  onProgress = () => {},
} = {}) {
  let pack = null,
    manifest = null,
    abort = null,
    job = null,
    disposed = false,
    initializing;
  const lifetime = new AbortController();
  let status = {
    phase: 'checking',
    message: '正在確認離線地圖…',
    received: 0,
    total: 0,
    shellReady: false,
  };
  const update = (values, progress = false) => {
    status = { ...status, ...values };
    if (!disposed) (progress ? onProgress : onChange)(status);
  };
  const assetUrl = (name) => new URL(`./offline-data/${name}`, document.baseURI).href;
  function supports(file) {
    return Boolean(
      pack &&
      file?.points?.length &&
      file.points.every(
        (p) =>
          p.lon >= pack.bounds[0] &&
          p.lon <= pack.bounds[2] &&
          p.lat >= pack.bounds[1] &&
          p.lat <= pack.bounds[3],
      ),
    );
  }
  async function initialize() {
    initializing ??= (async () => {
      try {
        pack = (await store.get()) ?? null;
        if (pack) {
          try {
            validateManifest(pack);
            if (!(pack.blob instanceof Blob) || pack.blob.size !== pack.bytes) throw new Error();
          } catch {
            pack = null;
            await store.remove();
          }
        }
      } catch {
        update({
          phase: 'unavailable',
          message: '此瀏覽器無法儲存離線地圖，請使用一般模式的新版瀏覽器。',
        });
        return;
      }
      if (disposed) return;
      update({
        phase: pack ? 'ready' : 'idle',
        message: pack ? '標準離線底圖已儲存。' : '連線時下載，山上沒有訊號也能看底圖。',
      });
      try {
        update({ shellReady: await prepareShell() });
      } catch {
        update({ shellReady: false });
      }
      if (disposed || navigator?.onLine === false) return;
      try {
        const response = await fetch(assetUrl('manifest.json'), {
          signal: lifetime.signal,
          cache: 'no-store',
        });
        if (!response.ok) throw new Error();
        manifest = validateManifest(await response.json());
        update({ total: manifest.bytes });
      } catch {
        if (!pack) update({ message: '離線圖資尚未就緒，請連線後重試。' });
      }
    })();
    return initializing;
  }
  function download() {
    if (job || disposed || status.phase === 'unavailable') return job;
    abort = new AbortController();
    const signal = abort.signal;
    update({ phase: 'downloading', received: 0, message: '正在準備下載…' });
    job = (async () => {
      try {
        // Refresh source metadata on every attempt; the body is integrity-checked before commit.
        const response = await fetch(assetUrl('manifest.json'), { signal, cache: 'no-store' });
        if (!response.ok) throw new Error('離線圖資尚未就緒，請連線後重試。');
        const next = validateManifest(await response.json());
        manifest = next;
        const estimate = await navigator?.storage?.estimate?.();
        if (estimate?.quota && estimate.quota - estimate.usage < next.bytes * 1.3)
          throw new Error('本機儲存空間不足，請釋放空間後再試。');
        signal.throwIfAborted();
        update({ shellReady: await prepareShell() });
        if (!status.shellReady)
          throw new Error('請從 HTTPS 或本機預覽網站開啟，才能準備離線頁面。');
        update({ total: next.bytes, message: '正在下載台灣標準底圖…' });
        const blob = await downloader({
          url: assetUrl('taiwan.pmtiles'),
          manifest: next,
          signal,
          fetch,
          onProgress: (received, total) => update({ received, total }, true),
        });
        signal.throwIfAborted();
        // Cancellation is disabled once the single atomic IndexedDB transaction begins.
        update({ phase: 'saving', message: '正在儲存並檢查地圖…' });
        const saved = { ...next, id: 'standard', blob, downloadedAt: new Date().toISOString() };
        await store.save(saved);
        pack = saved;
        if (disposed) return;
        let persistent = false;
        try {
          persistent = Boolean(await navigator?.storage?.persist?.());
        } catch {
          /* Best effort only. */
        }
        update({
          phase: 'ready',
          received: next.bytes,
          persistent,
          message: '標準離線底圖已下載，可直接在此 App 使用。',
        });
      } catch (error) {
        if (disposed) return;
        update({
          phase: pack ? 'ready' : 'idle',
          message: signal.aborted
            ? '已取消下載。'
            : error?.name === 'QuotaExceededError'
              ? '本機儲存空間不足，原有地圖保留。'
              : /[\u4e00-\u9fff]/.test(error?.message ?? '')
                ? error.message
                : '下載或儲存失敗，原有地圖保留；請重試。',
        });
      } finally {
        abort = null;
        job = null;
      }
    })();
    return job;
  }
  async function remove() {
    if (job || disposed) return;
    try {
      await store.remove();
      pack = null;
      update({ phase: 'idle', received: 0, message: '離線底圖已刪除，GPX 與 GPS 紀錄保留。' });
    } catch {
      update({ message: '未能刪除地圖，請稍後重試。' });
    }
  }
  return {
    initialize,
    download,
    remove,
    cancel: () => {
      if (status.phase === 'downloading') abort?.abort();
    },
    snapshot: () => ({ ...status, pack, manifest }),
    forRoute: (file) => (supports(file) || (pack && file?.recording) ? pack : null),
    dispose: async () => {
      disposed = true;
      lifetime.abort();
      if (status.phase !== 'saving') abort?.abort();
      await job;
      await initializing;
      await store.close();
    },
  };
}
