import { id, object, requireValue } from './contracts.js';

export function validateJsonValue(value, ancestors = new Set()) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return;
  if (typeof value === 'number' && Number.isFinite(value)) return;
  requireValue(Array.isArray(value) || (object(value)
    && [Object.prototype, null].includes(Object.getPrototypeOf(value))), 'non_json_database');
  requireValue(!ancestors.has(value), 'non_json_database');
  ancestors.add(value);
  for (const item of Array.isArray(value) ? value : Object.values(value)) validateJsonValue(item, ancestors);
  ancestors.delete(value);
}

export function validateProfile(request) {
  requireValue(object(request), 'invalid_request');
  requireValue(Array.isArray(request.nodes) && request.nodes.length >= 2
    && Array.from(request.nodes).every(id), 'route_requires_two_nodes', 'nodes');
  const { area = null, load = 'light', speed = null, mode = 'trail' } = request;
  requireValue(area === null || id(area), 'invalid_area', 'area');
  requireValue(['light', 'heavy'].includes(load), 'invalid_load', 'load');
  requireValue([null, 'fast', 'slow'].includes(speed), 'invalid_speed', 'speed');
  requireValue(['trail', 'walking'].includes(mode), 'invalid_route_mode', 'mode');
  return { area, load, speed, mode };
}
