import { distanceM } from '../../../../packages/route-stations/index.js';
import { prepareTrack } from '../../domain/track.js';
import { routeForDirection } from '../routes/direction.js';
import { routeMatcherFor } from './matching.js';

// All graph arcs carry an actual GPX interval and its independently resolved
// directed time model. A shared station is topology, never a drawn connector.
export const stationKey = (row) => row.station.placeId ?? row.station.stationId;
const EPS = 1e-6;
const wrap = (lon) => ((lon + 540) % 360) - 180;
export function trustedRerouteFix(gps, fix, now = Date.now()) {
  return (
    gps.status === 'tracking' &&
    fix &&
    !fix.excluded &&
    [fix.lat, fix.lon, fix.time, gps.accuracy].every(Number.isFinite) &&
    Math.abs(fix.lat) <= 90 &&
    Math.abs(fix.lon) <= 180 &&
    gps.accuracy >= 0 &&
    gps.accuracy <= 50 &&
    now - fix.time <= 60000 &&
    fix.time <= now + 5000
  );
}

export function routeNetwork(file, planFor) {
  const edges = [],
    destinations = new Map();
  for (const direction of ['forward', 'reverse']) {
    const source = routeForDirection(file, direction),
      plan = planFor(source);
    if (!plan) continue;
    plan.rows.slice(1).forEach((to, i) => {
      const from = plan.rows[i];
      destinations.set(stationKey(from), from.station);
      destinations.set(stationKey(to), to.station);
      // Never route over a GPX break, even if a station-to-station time exists.
      if (from.segmentIndex !== to.segmentIndex || to.routeProgressM <= from.routeProgressM) return;
      edges.push({
        source,
        plan,
        from,
        to,
        fromKey: stationKey(from),
        toKey: stationKey(to),
        startM: from.routeProgressM,
        endM: to.routeProgressM,
        segment: from.segmentIndex,
      });
    });
  }
  return { edges, destinations, sourceFile: file };
}

export function routePointAt(file, segment, m) {
  const points = file.points.filter((p) => p.segment === segment);
  for (let i = 1; i < points.length; i++) {
    const a = points[i - 1],
      b = points[i],
      left = a.km * 1000,
      right = b.km * 1000;
    if (m < left - EPS || m > right + EPS || right <= left) continue;
    const t = Math.max(0, Math.min(1, (m - left) / (right - left)));
    return {
      lat: a.lat + (b.lat - a.lat) * t,
      lon: wrap(a.lon + wrap(b.lon - a.lon) * t),
      elevation: [a.elevation, b.elevation].every(Number.isFinite)
        ? a.elevation + (b.elevation - a.elevation) * t
        : null,
    };
  }
  return null;
}
function geometry(edge) {
  const first = edge.startPoint ?? routePointAt(edge.source, edge.segment, edge.startM),
    last = edge.endPoint ?? routePointAt(edge.source, edge.segment, edge.endM);
  if (!first || !last) return null;
  return [
    first,
    ...edge.source.points
      .filter(
        (p) =>
          p.segment === edge.segment &&
          p.km * 1000 > edge.startM + EPS &&
          p.km * 1000 < edge.endM - EPS,
      )
      .map((p) => ({ lat: p.lat, lon: p.lon, elevation: p.elevation })),
    last,
  ];
}

// Splice only at a real intersection of the two GPX polylines, near their
// shared reference station. No near-point straight connector or time guess.
export function junctionSplice(incoming, outgoing) {
  if (incoming.toKey !== outgoing.fromKey) return null;
  const pointsFor = (edge) => {
    const shape = geometry(edge);
    if (!shape) return [];
    let m = edge.startM;
    return shape.map((point, i) => {
      if (i) m += distanceM(shape[i - 1], point);
      return { ...point, m };
    });
  };
  const left = pointsFor(incoming),
    right = pointsFor(outgoing);
  const cross = (a, b) => a.x * b.y - a.y * b.x;
  const origin = incoming.to.station;
  const xy = (p) => ({ x: wrap(p.lon - origin.lon), y: p.lat - origin.lat });
  let best = null;
  for (let i = left.length - 1; i > 0 && incoming.endM - left[i].m < 150; i--) {
    const a = left[i - 1],
      b = left[i],
      p = xy(a),
      q = xy(b),
      r = { x: q.x - p.x, y: q.y - p.y };
    for (let j = 1; j < right.length && right[j - 1].m - outgoing.startM < 150; j++) {
      const c = right[j - 1],
        d = right[j],
        u = xy(c),
        v = xy(d),
        s = { x: v.x - u.x, y: v.y - u.y };
      const det = cross(r, s);
      if (Math.abs(det) < 1e-18) continue;
      const delta = { x: u.x - p.x, y: u.y - p.y },
        t = cross(delta, s) / det,
        f = cross(delta, r) / det;
      if (t < 0 || t > 1 || f < 0 || f > 1) continue;
      const point = {
        lat: a.lat + (b.lat - a.lat) * t,
        lon: wrap(a.lon + wrap(b.lon - a.lon) * t),
      };
      if (distanceM(point, origin) > 100) continue;
      const incomingM = a.m + (b.m - a.m) * t,
        outgoingM = c.m + (d.m - c.m) * f;
      if (incomingM <= incoming.startM + 1 || outgoingM >= outgoing.endM - 1) continue;
      const heightA = a.elevation + (b.elevation - a.elevation) * t;
      const heightB = c.elevation + (d.elevation - c.elevation) * f;
      // A 2D crossing alone cannot connect grade-separated trails.
      if (
        ![a.elevation, b.elevation, c.elevation, d.elevation].every(Number.isFinite) ||
        Math.abs(heightA - heightB) > 20
      )
        continue;
      const cost = incoming.endM - incomingM + outgoingM - outgoing.startM;
      if (!best || cost < best.cost) best = { incomingM, outgoingM, cost, point, heightA, heightB };
    }
  }
  return best;
}

// Dijkstra chooses among existing GPX arcs by their measured length, not by
// estimating unknown roads or using distance to invent a time baseline.
function pathBetween(edges, start, goal, previousEdge) {
  if (start === goal) return [];
  const pending = [{ node: start, cost: 0, path: [] }],
    best = new Map();
  while (pending.length) {
    pending.sort((a, b) => a.cost - b.cost);
    const item = pending.shift();
    if (best.has(item.node)) continue;
    best.set(item.node, item.cost);
    if (item.node === goal) {
      // The station sequence chooses the branch. Among repeated occurrences of
      // that same sequence, preserve contiguous source intervals instead of
      // independently choosing the shortest noisy visit for every arc.
      let variants = [{ previous: previousEdge, path: [], gaps: 0, cost: 0 }];
      for (const step of item.path) {
        const next = [];
        for (const edge of edges.filter(
          (e) => e.fromKey === step.fromKey && e.toKey === step.toKey,
        )) {
          const options = variants.map((variant) => {
            const end =
              variant.previous &&
              routePointAt(
                variant.previous.source,
                variant.previous.segment,
                variant.previous.endM,
              );
            const begin = routePointAt(edge.source, edge.segment, edge.startM);
            const gap =
              end &&
              begin &&
              distanceM(end, begin) >= 1e-6 &&
              !junctionSplice(variant.previous, edge)
                ? 1
                : 0;
            return {
              previous: edge,
              path: [...variant.path, edge],
              gaps: variant.gaps + gap,
              cost: variant.cost + edge.endM - edge.startM,
            };
          });
          options.sort((a, b) => a.gaps - b.gaps || a.cost - b.cost);
          next.push(options[0]);
        }
        variants = next;
      }
      variants.sort((a, b) => a.gaps - b.gaps || a.cost - b.cost);
      return variants[0].path;
    }
    for (const edge of edges.filter((e) => e.fromKey === item.node))
      if (!best.has(edge.toKey))
        pending.push({
          node: edge.toKey,
          cost: item.cost + edge.endM - edge.startM,
          path: [...item.path, edge],
        });
  }
  return null;
}

export function rerouteStarts(network, fix, context = null) {
  const result = [];
  const matches = new Map();
  for (const edge of network.edges) {
    if (!matches.has(edge.source))
      matches.set(
        edge.source,
        routeMatcherFor(edge.source).match(
          [{ ...fix, stationId: 'reroute-fix', coordinateStatus: 'located' }],
          { maxOffsetM: 50, mergeWithinM: 25 },
        ).matches[0]?.routePositions ?? [],
      );
    for (const position of matches.get(edge.source)) {
      if (
        position.segmentIndex !== edge.segment ||
        position.routeProgressM < edge.startM - EPS ||
        position.routeProgressM >= edge.endM - EPS
      )
        continue;
      if (context && edge.source.id === context.fileId) {
        const total = edge.source.stats.km * 1000;
        const m =
          edge.source.direction === 'reverse'
            ? total - position.routeProgressM
            : position.routeProgressM;
        const canonical = context.direction === 'reverse' ? total - context.toM : context.fromM;
        const upper = context.direction === 'reverse' ? total - context.fromM : context.toM;
        if (m < canonical - 25 || m > upper + 25) continue;
      }
      result.push({ ...edge, startM: Math.max(edge.startM, position.routeProgressM), position });
    }
  }
  return result;
}

export function planReroute({ network, start, destination, returnTo = null, id, now }) {
  if (!start || (!network.edges.includes(start) && !start.position))
    throw new Error('沒有可信的 GPX 起點。');
  const tail = pathBetween(network.edges, start.toKey, destination, start);
  if (!tail) throw new Error('目的地之間沒有連續的既有 GPX 幾何，無法建立路線。');
  const home = returnTo
    ? pathBetween(network.edges, destination, returnTo, tail.at(-1) ?? start)
    : [];
  if (!home) throw new Error('目的地至返回點沒有既有 GPX 幾何。');
  return buildReroute({ network, arcs: [start, ...tail, ...home], destination, returnTo, id, now });
}

export function connectRerouteArcs(incoming, outgoing) {
  if (incoming.toKey !== outgoing.fromKey) return null;
  const end = incoming.endPoint ?? routePointAt(incoming.source, incoming.segment, incoming.endM);
  const begin =
    outgoing.startPoint ?? routePointAt(outgoing.source, outgoing.segment, outgoing.startM);
  if (!end || !begin) return null;
  if (distanceM(end, begin) < 1e-6) return { incoming, outgoing };
  const splice = junctionSplice(incoming, outgoing);
  return splice
    ? {
        incoming: {
          ...incoming,
          endM: splice.incomingM,
          endPoint: { ...splice.point, elevation: splice.heightA },
        },
        outgoing: {
          ...outgoing,
          startM: splice.outgoingM,
          startPoint: { ...splice.point, elevation: splice.heightB },
        },
      }
    : null;
}

export function buildReroute({ network, arcs: input, destination, returnTo = null, id, now }) {
  if (
    !input?.length ||
    input.some(
      (arc) => !Number.isFinite(arc.startM) || !Number.isFinite(arc.endM) || arc.endM <= arc.startM,
    )
  )
    throw new Error('沒有可用的 GPX 路段。');
  const start = input[0];
  const arcs = input.map((arc) => ({ ...arc }));
  for (let i = 1; i < arcs.length; i++) {
    const previous = arcs[i - 1],
      next = arcs[i];
    const joined = connectRerouteArcs(previous, next);
    if (joined) {
      arcs[i - 1] = joined.incoming;
      arcs[i] = joined.outgoing;
    }
  }
  const fragments = arcs.map(geometry);
  if (fragments.some((s) => !s)) throw new Error('GPX 幾何缺漏，無法建立路線。');
  const segments = [],
    spans = [];
  let distance = 0;
  fragments.forEach((fragment) => {
    const previous = segments.at(-1)?.at(-1);
    if (previous && distanceM(previous, fragment[0]) < 1e-6)
      segments.at(-1).push(...fragment.slice(1));
    else segments.push(fragment.slice());
    const length = prepareTrack([fragment]).stats.km * 1000;
    spans.push({ segment: segments.length - 1, fromM: distance, toM: distance + length });
    distance += length;
  });
  const geometryComplete = fragments.every(
    (fragment, i) => !i || distanceM(fragments[i - 1].at(-1), fragment[0]) < 1e-6,
  );
  const file = {
    id,
    geometryComplete,
    name: network.destinations.get(destination)?.name ?? '改道路線',
    kind: 'route',
    direction: 'forward',
    raw: start.source.raw,
    rerouted: true,
    ...prepareTrack(segments),
  };
  const first = file.points[0];
  const rows = [
    {
      index: 0,
      station: {
        stationId: id + '-origin',
        name: '改道起點',
        lat: first.lat,
        lon: first.lon,
        type: 'junction',
      },
      visible: false,
      routeProgressM: 0,
      segmentIndex: 0,
      baselineSeconds: 0,
      incoming: [],
    },
  ];
  const legs = [],
    warnings = [];
  let cumulative = 0;
  arcs.forEach((arc, i) => {
    const { segment, fromM, toM } = spans[i];
    const original = arc.plan.timeModel.legs.find((l) => l.index === arc.to.index - 1);
    const secondsAt = (m) => {
      const piece = original?.pieces.find((p) => m >= p.fromM - EPS && m <= p.toM + EPS);
      return piece
        ? piece.startSeconds +
            ((piece.endSeconds - piece.startSeconds) *
              (Math.max(piece.fromM, Math.min(piece.toM, m)) - piece.fromM)) /
              (piece.toM - piece.fromM)
        : null;
    };
    const a = { legSeconds: secondsAt(arc.startM) },
      b = { legSeconds: secondsAt(arc.endM) };
    const joinGap = i > 0 && distanceM(fragments[i - 1].at(-1), fragments[i][0]) >= 1e-6;
    const usable =
      original?.method !== 'unavailable' &&
      original?.pieces?.length &&
      [a.legSeconds, b.legSeconds].every(Number.isFinite) &&
      !joinGap;
    const seconds = usable ? b.legSeconds - a.legSeconds : null;
    const reason = joinGap
      ? `${arc.from.station.name}：站點不同次經過的 GPX 接點不重合；接續道路及時間未確認。`
      : !usable
        ? '此方向或部分路段沒有可信上河時間：' + (original?.reason ?? a.reason ?? 'missing')
        : null;
    if (reason) warnings.push(reason);
    const scale = (toM - fromM) / (arc.endM - arc.startM);
    const pieces = usable
      ? original.pieces.flatMap((piece) => {
          const left = Math.max(piece.fromM, arc.startM),
            right = Math.min(piece.toM, arc.endM);
          if (right <= left) return [];
          const at = (m) =>
            piece.startSeconds +
            ((piece.endSeconds - piece.startSeconds) * (m - piece.fromM)) /
              (piece.toM - piece.fromM) -
            a.legSeconds;
          return [
            {
              ...piece,
              fromM: fromM + (left - arc.startM) * scale,
              toM: fromM + (right - arc.startM) * scale,
              startSeconds: at(left),
              endSeconds: at(right),
              seconds: at(right) - at(left),
            },
          ];
        })
      : [];
    const source = {
      ...original?.source,
      direction: 'forward',
      originalDirection: arc.source.direction ?? 'forward',
      originalRouteId: arc.source.id,
      originalCanonicalSegment:
        arc.source.direction === 'reverse'
          ? arc.source.segments.length - 1 - arc.segment
          : arc.segment,
      originalFromM: arc.startM,
      originalToM: arc.endM,
    };
    legs.push({
      ...original,
      index: i,
      segmentIndex: segment,
      fromM,
      toM,
      baselineSeconds: seconds,
      cumulativeStartSeconds: cumulative,
      method: usable ? original.method : 'unavailable',
      reason,
      source,
      pieces,
    });
    cumulative = cumulative !== null && seconds !== null ? cumulative + seconds : null;
    rows.push({
      ...arc.to,
      index: i + 1,
      routeProgressM: toM,
      segmentIndex: segment,
      gap: false,
      baselineSeconds: seconds,
      reason,
      reasonCode: joinGap ? 'gpx-unconnected-join' : !usable ? 'shanghe-time-unavailable' : null,
      incoming: [
        {
          id: id + '-leg-' + i,
          fromWaypointId: rows[i].station.stationId,
          toWaypointId: arc.to.station.stationId,
          baselineMoveSeconds: seconds,
          timeStatus: seconds === null ? 'missing' : 'known',
          mode: 'walk',
          sourceIds: source.referenceIds ?? [],
        },
      ],
    });
  });
  const plan = {
    rows,
    segments: rows.slice(1).flatMap((r) => r.incoming),
    occurrences: rows,
    areas: [...new Set(arcs.flatMap((e) => e.plan.areas))],
    totalDistanceM: file.stats.km * 1000,
    startCovered: true,
    endCovered: true,
    rerouted: true,
    geometryComplete,
    warnings,
    timeModel: {
      version: start.plan.timeModel.version,
      originM: 0,
      totalSeconds: cumulative,
      legs,
    },
  };
  return {
    file,
    plan,
    createdAt: now,
    destination,
    returnTo,
    warnings,
    provenance: arcs.map((a) => ({
      routeId: a.source.id,
      direction: a.source.direction ?? 'forward',
      segment: a.segment,
      fromM: a.startM,
      toM: a.endM,
    })),
  };
}
