// Relative inverse walking speed, based on Tobler (1993), NCGIA report 93-1.
// These defaults have not been calibrated or field-validated for Ridgewise routes.
export const SLOPE_TIME_MODEL = 'tobler-relative-v1';
export const SHANGHE_SLOPE_DEFAULTS = Object.freeze({
  uphillRate: 3.5,
  downhillRate: 3.5,
  downhillOptimumGrade: 0.05,
  maxAbsGrade: 1,
});

export function slopeParameters(options = {}) {
  const config = { ...SHANGHE_SLOPE_DEFAULTS, ...options };
  for (const [name, value] of Object.entries(config)) {
    if (!Object.hasOwn(SHANGHE_SLOPE_DEFAULTS, name))
      throw new TypeError('Unknown slope option: ' + name);
    if (!Number.isFinite(value) || value < 0)
      throw new RangeError(name + ' must be finite and non-negative');
  }
  // Numerical guardrails, not claims about which gradients are walkable.
  if (config.maxAbsGrade <= 0 || config.maxAbsGrade > 2)
    throw new RangeError('maxAbsGrade must be in (0, 2]');
  if (config.downhillOptimumGrade > Math.min(0.25, config.maxAbsGrade))
    throw new RangeError('downhillOptimumGrade must not exceed 0.25 or maxAbsGrade');
  if (Math.max(config.uphillRate, config.downhillRate) * config.maxAbsGrade > 20)
    throw new RangeError('slope rate times maxAbsGrade must not exceed 20');
  return config;
}

/** Cost on the existing horizontal GPX distance axis; no terrain classification.
 * Constant-grade subdivision preserves cost. Heights are never filled or modified.
 * Capping is explicit: a very steep edge may be genuine or elevation noise.
 */
export function slopeTimePieces(geometry, config) {
  return geometry.map((piece) => {
    const distanceM = piece.toM - piece.fromM;
    const grade = piece.elevation / distanceM;
    const effectiveGrade = Math.max(-config.maxAbsGrade, Math.min(config.maxAbsGrade, grade));
    const logFactor =
      effectiveGrade >= 0
        ? config.uphillRate * effectiveGrade
        : config.downhillRate *
          (Math.abs(effectiveGrade + config.downhillOptimumGrade) - config.downhillOptimumGrade);
    return {
      ...piece,
      grade,
      effectiveGrade,
      cost: distanceM * Math.exp(logFactor),
    };
  });
}
