import { offlineMapPanel } from '../offline-map/view.js';
import { itineraryMarkers } from '../itinerary/markers.js';
import { recordingAnalysis } from '../recording/analysis.js';
import { button, icon } from '../../ui/html.js';
import { mapSvg } from './thumbnail.js';
import { elevationSvg } from '../elevation/view.js';
export function createMapView({ state, terrainMap, itinerary, heightProfile, offlineMaps }) {
  const directMap = state.directMap;
  function heightPanel(file, _live = []) {
    const plotted =
      file === directMap
        ? {
            ...recordingAnalysis(state.gps),
            id: state.gps.id,
            kind: 'recording',
          }
        : file;
    return `<section class="chart-wrap"><div class="chart-title"><span class="chart-heading">${icon('mountain')}${file === directMap ? '紀錄的' : '路線'}高度剖面</span><span>沿途的高度變化</span></div>${heightProfile?.panel(plotted) ?? elevationSvg(plotted)}</section>`;
  }
  function mapPanel(file, position = null, live = [], { compact = false } = {}) {
    return `<section class="panel ${compact ? 'compact-map' : ''}"><div class="panel-header"><div><h2>${file === directMap ? '我的軌跡' : '路線與地形'}</h2><p>${file === directMap ? '實際 GPS 位置' : file.processing ? '校正後 GPX 路線' : 'GPX 路線'} · ${state.mapMode === 'terrain' ? '可旋轉視角' : '北方朝上'}</p></div><span class="chip">${(file === directMap ? live : file.segments).filter((segment) => segment.length).length} 段軌跡</span></div>
    <div class="terrain-toolbar"><div class="tab-group" role="group" aria-label="地圖模式">${[
      ['standard', '標準'],
      ['terrain', '3D 地形'],
      ['plain', '單純軌跡'],
    ]
      .map(([mode, label]) =>
        button(
          label,
          'map-mode',
          '',
          '',
          `data-mode="${mode}" aria-pressed="${state.mapMode === mode}"`,
        ),
      )
      .join('')}</div>${button('看全程', 'map-fit', '', 'locate')}</div>
    ${state.mapMode === 'terrain' ? `<div class="terrain-camera-controls" role="group" aria-label="3D 視角"><label for="map-pitch">傾斜 <span id="map-pitch-value">${Math.round(terrainMap.pitch())}°</span></label><input id="map-pitch" type="range" min="0" max="75" step="5" value="${Math.round(terrainMap.pitch())}">${button('左轉', 'map-rotate', 'ghost', '', 'data-angle="-30"')}${button('右轉', 'map-rotate', 'ghost', '', 'data-angle="30"')}${button('北向', 'map-north', 'ghost')}</div><p class="terrain-gesture-note">右鍵拖曳可旋轉與傾斜；手機可雙指旋轉、上下滑動，或使用上方視角控制。</p>` : ''}
    <div class="actual-map" id="track-map">${mapSvg(file, position, live, false, itineraryMarkers(itinerary?.snapshot()))}</div>
    <div class="terrain-status-row"><p id="map-status" class="terrain-status" role="status" aria-live="polite">${state.mapMode === 'plain' ? '單純軌跡模式，不載入底圖。' : '正在載入底圖…'}</p>${button('重試底圖', 'map-retry', 'ghost', 'refresh', 'id="map-retry" hidden')}</div>
    <div class="legend">${file === directMap ? '' : `<span><i style="background:#326753"></i>${file.kind === 'recording' ? '保存的 GPS 軌跡' : '應走路線'}</span>`}${live.length ? '<span><i style="background:#4388b7"></i>實際 GPS 紀錄</span>' : ''}<span class="legend-note">中斷處不連線 · 拖曳移動、滾輪或雙指縮放</span></div>
    <p class="terrain-note">${state.mapMode === 'plain' ? '單純軌跡模式不請求底圖，仍可縮放與移動 GPX 路線。' : state.mapMode === 'terrain' ? '登山底圖：OpenTopoMap；立體高程：Mapterhorn，原比例 1×。開啟時會向兩個圖資服務請求瀏覽區域，GPX 不會上傳。尚未提供離線 3D 地圖。' : '已下載時使用本機台灣標準底圖（OSM／Protomaps）；否則使用 OSM 線上底圖。兩種底圖樣式略有不同，GPX 檔案不會上傳。'}</p>
    ${state.mapMode === 'standard' && !compact ? offlineMapPanel(offlineMaps, file) : ''}
    ${compact ? '' : heightPanel(file, live)}</section>`;
  }
  return { mapPanel, heightPanel };
}
