export const MAX_DATE_MS = 8_640_000_000_000_000;
const MODES = new Set(['walk', 'road_walk', 'drive', 'forest_road',
  'road_connector', 'external_connector', 'road_closed', 'unknown', 'distance_only']);
const TIME_STATUSES = new Set(['known', 'missing', 'conflict', 'variant_required',
  'load_required', 'unavailable']);
const REST_STATES = new Set(['included', 'excluded', 'unknown']);
export const STATUS_REASONS = {
  missing: 'baseline_unavailable', conflict: 'conflicting_directed_edge',
  variant_required: 'time_variant_required', load_required: 'load_choice_required',
  unavailable: 'baseline_unavailable',
};

export class EtaInputError extends TypeError {
  constructor(code, segmentIndex = null) {
    super(code);
    this.name = 'EtaInputError';
    this.code = code;
    this.segmentIndex = segmentIndex;
  }
}

const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const isId = value => typeof value === 'string' && value.trim().length > 0;

export function validateInput(request) {
  if (!isObject(request)) throw new EtaInputError('invalid_request');
  const { departureUtcMs, segments, multiplier = 1, mode = 'trail' } = request;
  if (!Number.isSafeInteger(departureUtcMs) || Math.abs(departureUtcMs) > MAX_DATE_MS) {
    throw new EtaInputError('invalid_departure_utc_ms');
  }
  if (typeof multiplier !== 'number' || !Number.isFinite(multiplier) || multiplier <= 0) {
    throw new EtaInputError('invalid_multiplier');
  }
  if (!['trail', 'walking'].includes(mode)) throw new EtaInputError('invalid_route_mode');
  if (!Array.isArray(segments) || segments.length === 0) throw new EtaInputError('route_requires_segments');
  for (const [index, segment] of segments.entries()) {
    if (!isObject(segment) || ![segment.id, segment.fromWaypointId, segment.toWaypointId].every(isId)) {
      throw new EtaInputError('invalid_segment_identity', index);
    }
    if (!MODES.has(segment.mode)) throw new EtaInputError('invalid_segment_mode', index);
    if (!TIME_STATUSES.has(segment.timeStatus)) throw new EtaInputError('invalid_time_status', index);
    if (segment.baselineMoveSeconds !== null && typeof segment.baselineMoveSeconds !== 'number') {
      throw new EtaInputError('invalid_baseline_type', index);
    }
    if (!Array.isArray(segment.sourceIds) || !Array.from(segment.sourceIds).every(isId)) {
      throw new EtaInputError('invalid_source_ids', index);
    }
    if (!REST_STATES.has(segment.restIncluded === undefined ? 'unknown' : segment.restIncluded)) {
      throw new EtaInputError('invalid_rest_inclusion', index);
    }
  }
  return { departureUtcMs, segments, multiplier, mode };
}
