import { recordingFix } from '../recording/analysis.js';
import { distanceM } from '../../../../packages/route-stations/index.js';
import { validateResources } from './data.js';
import { builtinResources } from '../../data/shanghe-reference.js';
import { buildItinerary, forecastItinerary } from './model.js';
import { nearestRouteOffset, routeMatcherFor } from './matching.js';
import { createLiveShangheFactor, LIVE_FACTOR_VERSION } from './live-factor.js';
import { rerouteEtas } from './reroute-eta.js';
import { routeNetwork, rerouteStarts, planReroute, trustedRerouteFix } from './rerouting.js';
import { createSmartRerouteController } from './smart-controller.js';
import { historyInterruption } from '../history/observations.js';
import {
  checkpointRouteBinding,
  sealLiveCheckpoint,
  readLiveCheckpoint,
} from './live-checkpoint.js';

export function createItineraryController({
  state,
  repository,
  current,
  recordingRoute,
  gpsPending,
  render,
  feedback,
  reference = builtinResources,
}) {
  const ui = state.itinerary;
  let resources = validateResources(reference.catalog, reference.database),
    revision = 0,
    disposed = false;
  const plans = new WeakMap();
  const liveSessions = new WeakMap();
  ui.catalog = reference.catalog;
  ui.database = reference.database;
  ui.status = 'ready';
  ui.busy = false;
  ui.error = '';
  ui.referenceVersion = reference.version;
  function activeFile() {
    return gpsPending() ? recordingRoute() : current();
  }
  function planFor(file) {
    if (file?.reroutePlan) return file.reroutePlan;
    if (!file?.points?.length || !resources.stations.length) return null;
    let saved = plans.get(file);
    if (!saved || saved.revision !== revision) {
      saved = { revision, plan: buildItinerary(resources, file) };
      plans.set(file, saved);
    }
    return saved.plan;
  }
  function signature(plan) {
    return JSON.stringify([
      plan.rows.map((row) => [
        row.station.stationId,
        row.station.lat,
        row.station.lon,
        Math.round(row.routeProgressM),
        row.nodeId,
      ]),
      plan.segments.map((segment) => [
        segment.fromWaypointId,
        segment.toWaypointId,
        segment.baselineMoveSeconds,
        segment.timeStatus,
        segment.sourceIds,
      ]),
    ]);
  }
  function snapshot() {
    const file = activeFile(),
      plan = planFor(file),
      journey = state.gps.itinerary;
    if (!plan) return null;
    const active = Boolean(gpsPending() && journey && journey.routeId === file.id);
    const compatible =
      !active ||
      (journey.signature === signature(plan) &&
        (!file.rerouted || file.rerouteReferenceVersion === reference.version));
    const forecast = forecastItinerary(
      plan,
      active ? journey.factor : ui.factor,
      active ? (journey.departureUtcMs ?? state.gps.startedAt) : null,
      active && compatible ? journey : null,
    );
    const nextIndex = active && compatible ? journey.nextIndex : 0;
    if (!compatible) {
      forecast.rows.forEach((row) => {
        row.arrivalUtcMs = null;
      });
      forecast.totalSeconds = null;
      forecast.observedFactor = null;
    }
    return {
      ...forecast,
      active,
      departureUtcMs: active ? (journey.departureUtcMs ?? state.gps.startedAt) : null,
      compatible,
      finished: ['review', 'stopping', 'finishing', 'finished'].includes(state.gps.status),
      nextIndex,
      factor: active ? journey.factor : ui.factor,
      next: forecast.rows.slice(nextIndex).find((row) => row.visible) ?? null,
      offRoute: active ? journey.offRoute : false,
    };
  }
  async function saveResources() {
    if (!repository.saveResources) return;
    try {
      await repository.saveResources({
        referenceVersion: reference.version,
        factor: ui.factor,
      });
      ui.saved = true;
    } catch {
      ui.saved = false;
      ui.error = '倍率設定未能保存；內建站點與時間仍可使用。';
    }
  }
  async function restore() {
    if (!repository.getResources) return;
    try {
      const saved = await repository.getResources();
      if (disposed || !saved) return;
      ui.factor =
        Number.isFinite(saved.factor) && saved.factor > 0 && saved.factor <= 10 ? saved.factor : 1;
      if (!disposed) render();
    } catch {
      if (!disposed) ui.error = '倍率設定無法讀取，先使用 1.0 倍。內建資料仍可使用。';
    }
  }
  async function setFactor(value) {
    if (gpsPending()) return;
    const factor = Number(value);
    if (!Number.isFinite(factor) || factor <= 0 || factor > 10) {
      feedback.toast('請設定大於 0、至多 10 的時間倍率。');
      return;
    }
    ui.factor = factor;
    await saveResources();
    if (!disposed) render();
  }
  function createLiveSession(gps, file, plan, departureAvailable) {
    const station = plan.rows[0]?.station;
    const startStation = station
      ? {
          stationId: station.stationId,
          name: station.name,
          lat: station.lat,
          lon: station.lon,
          coordinateSource: station.coordinateSource ?? null,
        }
      : null;
    const session = {
      file,
      plan,
      binding: checkpointRouteBinding(file, plan),
      engine: createLiveShangheFactor({
        file,
        timeModel: plan.timeModel,
        startedAt: gps.itinerary?.departureUtcMs ?? gps.startedAt,
        departureAvailable,
        startStation,
      }),
    };
    liveSessions.set(gps, session);
    return session;
  }
  async function restoreLiveSession(gps) {
    const session = liveSession();
    if (!session || gps !== state.gps) return;
    const checked = await readLiveCheckpoint(gps, session.binding);
    if (!disposed && gps === state.gps && checked && liveSession() === session)
      session.engine.restoreCheckpoint(checked.state, checked.savedAt);
  }
  function captureLiveCheckpoint(gps, snapshot) {
    const session = liveSessions.get(gps);
    return session
      ? sealLiveCheckpoint(session.engine.checkpoint(), snapshot, session.binding)
      : Promise.resolve(null);
  }
  function departureStatus(now = Date.now()) {
    if (disposed) return { canConfirm: false, confirmed: false };
    return liveSession()?.engine.departureStatus(now) ?? { canConfirm: false, confirmed: false };
  }
  function confirmDeparture(statements, now = Date.now()) {
    if (disposed) return false;
    const session = liveSession();
    const confirmed =
      state.gps.status === 'tracking' && session?.engine.confirmDeparture(statements, now);
    ui.liveDepartureError = confirmed
      ? ''
      : '無法確認：需要出發時的有效定位、已知路段及兩項聲明；不會重設出發時間。';
    render();
    return Boolean(confirmed);
  }
  function liveSession() {
    const gps = state.gps;
    const file = recordingRoute(),
      plan = planFor(file);
    if (
      !gps.itinerary ||
      !file ||
      !plan ||
      gps.itinerary.signature !== signature(plan) ||
      (file.rerouted && file.rerouteReferenceVersion !== reference.version)
    )
      return null;
    let session = liveSessions.get(gps);
    if (!session) {
      // Missing/invalid checkpoints retain an explicitly unavailable departure.
      session = createLiveSession(gps, file, plan, false);
    }
    return session.file === file && session.plan === plan && gps.itinerary.routeId === file.id
      ? session
      : null;
  }
  function updateLiveFactor(fix, now = Date.now()) {
    if (disposed) return;
    const value = liveSession()?.engine.update(fix, { now, status: state.gps.status });
    if (value) {
      state.gps.routeFactorHistory ??= [];
      state.gps.routeFactorHistory.push({
        revisionId: recordingRoute()?.id,
        at: now,
        fixTime: fix.time,
        factors: structuredClone(value),
      });
    }
    return value;
  }
  function liveFactors(now = Date.now()) {
    const session = !disposed && liveSession();
    if (session) return session.engine.snapshot({ now, status: state.gps.status });
    const unavailable = {
      factor: null,
      reason: 'reference-or-session-changed',
      actualSeconds: null,
      baselineSeconds: null,
      source: null,
    };
    return {
      version: LIVE_FACTOR_VERSION,
      asOf: null,
      total: { ...unavailable },
      recent: { ...unavailable },
    };
  }
  function interruptLiveFactor(reason, now = Date.now()) {
    if (!disposed) return liveSession()?.engine.interrupt(reason, now);
  }
  function historyReference(file) {
    if (!file) return null;
    const plan = planFor(file);
    return {
      file,
      timeModel: plan?.timeModel ?? null,
      referenceVersion: reference.version,
      binding: plan ? checkpointRouteBinding(file, plan) : Promise.resolve(null),
    };
  }
  function begin(gps, route) {
    smart.invalidate();
    ui.reroute = undefined;
    ui.rerouteForm = {};
    preview = null;
    rerouteNetwork = null;
    rerouteCandidates = [];
    const plan = planFor(route);
    if (!plan?.rows.length) return;
    createLiveSession(gps, route, plan, true);
    gps.itinerary = {
      routeId: route.id,
      signature: signature(plan),
      factor: ui.factor,
      nextIndex: 0,
      arrivals: {},
      lastFixTime: null,
      deviationNotified: false,
      offRoute: false,
    };
  }
  function progress() {
    const gps = state.gps,
      journey = gps.itinerary;
    if (
      !journey ||
      gps.status !== 'tracking' ||
      !Number.isFinite(gps.accuracy) ||
      gps.accuracy > 50
    )
      return;
    const file = recordingRoute(),
      plan = planFor(file),
      point = recordingFix(gps);
    if (
      !plan ||
      !point ||
      point.time === journey.lastFixTime ||
      journey.signature !== signature(plan)
    )
      return;
    journey.lastFixTime = point.time;
    const target = plan.rows[journey.nextIndex];
    // A station identity is not an occurrence: a return visit cannot be marked
    // while still on the outbound arc or immediately after a route revision.
    const positions =
      file?.rerouted && target && trustedRerouteFix(gps, point)
        ? rerouteProgressPositions(file, point, target)
        : [];
    if (file.rerouted && positions.length === 1)
      journey.routePosition = {
        ...positions[0],
        time: point.time,
        accuracy: gps.accuracy,
        revisionId: file.id,
      };
    if (
      target &&
      distanceM(point, target.station) <= 60 &&
      (!file.rerouted ||
        (positions.length === 1 && positions[0].routeProgressM >= target.routeProgressM - 60))
    ) {
      journey.arrivals[journey.nextIndex] = point.time;
      journey.nextIndex++;
    }
    journey.offRoute = nearestRouteOffset(file, point) > 200;
    if (journey.offRoute && !journey.deviationNotified) {
      journey.deviationNotified = true;
      feedback.toast('目前位置距預定 GPX 超過 200 公尺，請確認路線。');
    }
  }
  function markNext() {
    const data = snapshot(),
      journey = state.gps.itinerary;
    if (
      !data?.active ||
      !data.compatible ||
      !data.next ||
      !['tracking', 'paused'].includes(state.gps.status)
    )
      return;
    const point = recordingFix(state.gps);
    if (
      !point ||
      !trustedRerouteFix(state.gps, point) ||
      !Number.isFinite(state.gps.accuracy) ||
      state.gps.accuracy > 100 ||
      distanceM(point, data.next.station) > 100
    ) {
      feedback.toast('尚未取得下一站附近的有效 GPS，請確認位置後再切換。');
      return;
    }
    // Mark only this visible station; hidden intermediate points are not given invented arrival times.
    journey.arrivals[data.next.index] = Date.now();
    journey.nextIndex = data.next.index + 1;
    delete journey.routePosition;
    render();
  }
  function rerouteProgressPositions(file, fix, target) {
    const journey = state.gps.itinerary;
    const previous = planFor(file).rows[Math.max(0, journey.nextIndex - 1)];
    const anchor = journey.routePosition?.revisionId === file.id ? journey.routePosition : null;
    const elapsed = anchor ? fix.time - anchor.time : null;
    const reach =
      anchor && elapsed >= 0 && elapsed <= 300000
        ? (12 * elapsed) / 1000 + Math.min(50, state.gps.accuracy + anchor.accuracy)
        : Infinity;
    return (
      routeMatcherFor(file)
        .match([{ ...fix, stationId: 'occurrence', coordinateStatus: 'located' }], {
          maxOffsetM: 50,
          mergeWithinM: 25,
        })
        .matches[0]?.routePositions.filter(
          (p) =>
            p.segmentIndex === target.segmentIndex &&
            p.routeProgressM >= previous.routeProgressM - 25 &&
            (!anchor ||
              anchor.segmentIndex !== p.segmentIndex ||
              (elapsed >= 0 &&
                p.routeProgressM >= anchor.routeProgressM - 25 &&
                p.routeProgressM <= anchor.routeProgressM + reach)) &&
            p.routeProgressM <= target.routeProgressM + 25,
        ) ?? []
    );
  }
  let previewStart = null;
  let rerouteNetwork = null,
    rerouteCandidates = [],
    preview = null;
  function rerouteOptions(sourceId) {
    smart.invalidate();
    preview = null;
    ui.reroute = {};
    const file = state.library.find((f) => f.id === sourceId && f.kind !== 'recording');
    if (!file) throw new Error('請選擇一份原始 GPX。');
    rerouteNetwork = routeNetwork(file, planFor);
    const fix = recordingFix(state.gps);
    if (!trustedRerouteFix(state.gps, fix))
      throw new Error('需要 60 秒內、精度 50m 以內的目前 GPS；請先恢復定位。');
    const data = snapshot();
    const context =
      !recordingRoute()?.rerouted &&
      file.id === recordingRoute()?.id &&
      data?.next &&
      data.nextIndex > 0
        ? {
            fileId: file.id,
            direction: recordingRoute().direction ?? 'forward',
            fromM: data.rows[Math.max(0, data.nextIndex - 1)].routeProgressM,
            toM: data.rows[data.nextIndex].routeProgressM,
          }
        : null;
    rerouteCandidates = rerouteStarts(rerouteNetwork, fix, context);
    if (!rerouteCandidates.length && context)
      rerouteCandidates = rerouteStarts(rerouteNetwork, fix);
    preview = null;
    ui.reroute = {
      sourceId,
      destinations: [...rerouteNetwork.destinations].map(([id, station]) => ({
        id,
        name: station.name,
      })),
      starts: rerouteCandidates.map((c, i) => ({
        id: i,
        name: `${c.from.station.name} → ${c.to.station.name} · ${c.source.direction === 'reverse' ? '反向' : '原向'} · GPX ${(c.startM / 1000).toFixed(2)} km`,
      })),
      error: rerouteCandidates.length ? '' : '目前位置附近沒有連續且可信的 GPX 路段。',
    };
    render();
    return ui.reroute;
  }
  function previewReroute({ startIndex, destination, returnTo }) {
    smart.invalidate();
    preview = null;
    if (ui.reroute) delete ui.reroute.preview;
    const fix = recordingFix(state.gps),
      now = Date.now();
    if (!trustedRerouteFix(state.gps, fix, now))
      throw new Error('GPS 已中斷或過期，請恢復定位後重新規劃。');
    const start = rerouteCandidates[Number(startIndex)];
    if (!start) throw new Error('請明確選擇目前所在路段及方向。');
    // Reproject a moving hiker rather than using the fix captured when opening the form.
    const candidates = rerouteStarts(rerouteNetwork, fix).filter(
      (c) =>
        c.source === start.source &&
        c.from.index === start.from.index &&
        c.to.index === start.to.index,
    );
    if (candidates.length !== 1) throw new Error('所在路段已改變或有歧義，請重新載入改道選項。');
    preview = planReroute({
      network: rerouteNetwork,
      start: candidates[0],
      destination,
      returnTo: returnTo || null,
      id: crypto.randomUUID(),
      now,
    });
    previewStart = candidates[0];
    preview.fixTime = fix.time;
    ui.reroute.preview = preview;
    render();
    return preview;
  }
  function applyReroute() {
    const gps = state.gps,
      fix = recordingFix(gps),
      now = Date.now();
    if (!preview || !trustedRerouteFix(gps, fix, now))
      throw new Error('位置已更新，請重新預覽，避免使用舊位置改道。');
    const currentStarts = rerouteStarts(rerouteNetwork, fix).filter(
      (c) =>
        c.source === previewStart.source &&
        c.from.index === previewStart.from.index &&
        c.to.index === previewStart.to.index,
    );
    if (currentStarts.length !== 1) throw new Error('目前路段已改變或有歧義，請重新預覽。');
    preview = planReroute({
      network: rerouteNetwork,
      start: currentStarts[0],
      destination: preview.destination,
      returnTo: preview.returnTo,
      id: preview.file.id,
      now,
    });
    return activateReroute(preview, rerouteNetwork.sourceFile);
  }
  function activateReroute(candidate, sourceRoute) {
    const gps = state.gps,
      now = Date.now(),
      fix = recordingFix(gps);
    if (!trustedRerouteFix(gps, fix, now)) throw new Error('GPS 已中斷或過期，請重新定位。');
    smart.invalidate();
    const oldFile = recordingRoute(),
      oldJourney = structuredClone(gps.itinerary ?? null);
    gps.navigation ??= {
      version: 1,
      original: {
        file: structuredClone(oldFile),
        plan: structuredClone(planFor(oldFile)),
        journey: oldJourney,
      },
      revisions: [],
    };
    gps.navigation.revisions.push({
      endedAt: now,
      file: structuredClone(oldFile),
      plan: structuredClone(planFor(oldFile)),
      journey: oldJourney,
      live: structuredClone(liveFactors(now)),
      checkpoint: liveSessions.get(gps)?.engine.checkpoint() ?? null,
    });
    const { file, plan, ...metadata } = candidate;
    file.reroutePlan = plan;
    file.rerouteReferenceVersion = reference.version;
    gps.navigation.active = { file, ...metadata, sourceRoute: structuredClone(sourceRoute) };
    gps.itinerary = {
      routeId: file.id,
      signature: signature(plan),
      factor: oldJourney?.factor ?? ui.factor,
      departureUtcMs: now,
      nextIndex: 1,
      arrivals: { 0: now },
      lastFixTime: fix.time,
      deviationNotified: false,
      offRoute: false,
      routePosition: {
        revisionId: file.id,
        segmentIndex: 0,
        routeProgressM: 0,
        time: fix.time,
        accuracy: gps.accuracy,
        offsetM: 0,
      },
    };
    gps.sourceRouteId ??= sourceRoute.id;
    gps.remaining = null;
    delete gps.liveFactorCheckpoint;
    liveSessions.delete(gps);
    const session = createLiveSession(gps, file, plan, true);
    // A new revision has its own time origin and sources. Archived factors are
    // retained for inspection only; they never seed this engine or its ETA.
    session.engine.update({ ...fix, accuracy: gps.accuracy }, { now, status: gps.status });
    historyInterruption(gps, 'dynamic-reroute');
    ui.reroute = { applied: true };
    preview = null;
    render();
    return true;
  }
  const smart = createSmartRerouteController({
    state,
    recordingRoute,
    planFor,
    compatible: () => snapshot()?.compatible === true,
    acceptedPosition: () => {
      const position = state.gps.itinerary?.routePosition,
        fix = recordingFix(state.gps);
      return position?.revisionId === recordingRoute().id && position.time === fix?.time
        ? { fix, position }
        : (liveSessions.get(state.gps)?.engine.checkpoint().last ?? null);
    },
    referenceVersion: reference.version,
    activate: activateReroute,
    render,
  });
  return {
    invalidateReroute: () => {
      smart.invalidate();
      preview = null;
      if (ui.reroute) delete ui.reroute.preview;
    },
    loadSmartOptions: smart.load,
    previewSmart: smart.preview,
    applySmart: smart.apply,
    canApplySmart: smart.canApply,
    rerouteOptions,
    previewReroute,
    applyReroute,
    snapshot,
    nextEtas: (now = Date.now()) =>
      rerouteEtas(
        recordingRoute(),
        snapshot(),
        liveFactors(now),
        state.gps,
        recordingFix(state.gps),
        now,
      ),
    restore,
    setFactor,
    begin,
    progress,
    markNext,
    restoreLiveSession,
    captureLiveCheckpoint,
    departureStatus,
    confirmDeparture,
    updateLiveFactor,
    liveFactors,
    interruptLiveFactor,
    historyReference,
    dispose() {
      smart.dispose();
      disposed = true;
    },
  };
}
