import { esc } from '../../ui/html.js';
import { timeDistributionLabel } from '../../domain/time-origin.js';

const reasons = {
  'paused-awaiting-fix': '紀錄已暫停；繼續並取得新定位後再計算，耗時仍包含暫停。',
  'missing-gps-fix': '等待第一個有效 GPS 定位。',
  'stale-gps-fix': '定位已超過 60 秒或時間異常；等待新有效定位。',
  'gps-quality': '定位精度不足或位置跳動；等待可靠定位。',
  'gps-stabilizing': '正在核對連續定位的穩定性；尚未恢復即時值。',
  'gps-signal-unavailable': '定位訊號暫時中斷，正在等待新定位。',
  'missing-reference': '沒有可配對的上河基準路線，無法計算倍率。',
  'reference-or-session-changed': '路線或上河資料已改變；需重新開始紀錄才能計算。',
  'missing-start-fix': '缺少出發時的有效定位，無法計算全程倍率。',
  'start-not-aligned': '出發位置尚未確認；若可核對，請展開「紀錄狀態與更多資訊」。',
  'session-history-unavailable': '草稿缺少可核對的出發紀錄；保留原始軌跡，但全程倍率無法恢復。',
  'restored-awaiting-fix': '草稿已恢復；等待新定位確認與重載前位置連續。',
  'restored-continuity-unconfirmed': '重載期間位置已移動，無法確認路程連續；本趟全程倍率停用。',
  'gps-observation-gap': '定位中斷超過 5 分鐘且位置已移動；本趟全程倍率停用。',
  'window-start-missing': '尚無完整最近 30 分鐘的真實定位端點；中斷或重載後需重新累積。',
  'baseline-too-small': '已走路段的上河基準不足 1 分鐘；請累積更多路程。',
  'progress-too-small': '路程進度尚未超過定位誤差；請累積更多有效路程。',
  'invalid-elapsed-time': '定位經過時間不足或異常，暫時無法計算。',
  'nonmonotonic-gps-time': '定位時間沒有依序前進；等待新有效定位。',
  'off-route': '目前定位偏離參考 GPX；回到路線並取得有效定位後再計算。',
  'unreachable-route-position': '定位無法連接前次路線位置；等待連續且可靠的定位。',
  'abnormal-gps-speed': '定位移動速度異常；等待可靠定位。',
  'ambiguous-route-position': '此處有重疊或往返路徑，尚無法確認所在路段。',
  backtracking: '目前正在折返；回到先前最遠進度附近後再計算，耗時仍包含折返。',
  'unknown-prefix': '出發前段的上河基準不明，無法計算累計倍率。',
  'outside-confirmed-legs': '目前位置沒有已確認的上河路段基準。',
  'unconfirmed-shanghe-leg': '這段上河路徑或時間尚未確認，無法分配基準。',
  'gpx-segment-break': 'GPX 在此分段中斷，無法確認連續路程。',
  'gpx-quality-break': '這段 GPX 品質不足，無法確認連續路程。',
};
const unavailable = '上河基準或路線連續性資料不足，暫時無法計算。';
export const liveFactorReason = (reason) => reasons[reason] ?? unavailable;
const valid = (metric) => Number.isFinite(metric?.factor) && metric.factor > 0;
const span = (seconds) => {
  if (!Number.isFinite(seconds)) return '—';
  const rounded = Math.round(seconds);
  return `${Math.floor(rounded / 60)} 分 ${rounded % 60} 秒`;
};
const fixTime = (time) =>
  Number.isFinite(time)
    ? new Date(time).toLocaleString('zh-TW', {
        timeZone: 'Asia/Taipei',
        month: 'numeric',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hourCycle: 'h23',
      })
    : '尚未取得有效定位（重載後需重新取得）';

// Presentation only: use the phase-three API, never write a factor back into ETA settings.
export function createLiveFactorView({ state, itinerary, document }) {
  let recording, lastFixTime;
  function fields() {
    if (recording !== state.gps) {
      recording = state.gps;
      lastFixTime = null;
    }
    const data = itinerary.liveFactors();
    const times = [data.asOf, data.total?.lastValid?.asOf, data.recent?.lastValid?.asOf].filter(
      Number.isFinite,
    );
    if (times.length) lastFixTime = Math.max(...times);
    const values = { 'live-factor-last-fix': fixTime(lastFixTime) };
    for (const key of ['total', 'recent']) {
      const live = data[key];
      const held = !valid(live) && live?.lastValid?.state === 'stale' && valid(live.lastValid);
      const metric = held ? live.lastValid : live;
      const usable = valid(metric);
      values[`live-factor-${key}-freshness`] = held
        ? '上次有效值・資料已過期'
        : usable
          ? metric.quality === 'limited'
            ? '即時值・GPS 精度受限'
            : '即時值'
          : '';
      const delta = usable ? (metric.factor - 1) * 100 : null;
      values[`live-factor-${key}-value`] = usable ? metric.factor.toFixed(2) + ' 倍' : '—';
      values[`live-factor-${key}-comparison`] = !usable
        ? ''
        : Math.abs(delta) < 0.05
          ? '與上河基準耗時相同（0.0%）'
          : `${held ? '上次：' : ''}耗時較上河${delta > 0 ? '多' : '少'} ${Math.abs(delta).toFixed(1)}%（${delta > 0 ? '較慢' : '較快'}）`;
      values[`live-factor-${key}-reason`] = held
        ? `上次有效定位：${fixTime(metric.asOf)}（台北時間）。資料已過期，非即時值；${reasons[live.reason] ?? '等待新有效定位。'}`
        : usable
          ? ''
          : !state.gps.sourceRouteId
            ? reasons['missing-reference']
            : metric?.reason === 'gps-not-tracking'
              ? state.gps.status === 'error'
                ? '定位已中斷；請繼續紀錄並取得新有效定位。'
                : state.gps.accuracy > 50 || state.gps.error
                  ? reasons['gps-quality']
                  : '等待新有效定位；恢復紀錄後須先確認位置。'
              : (reasons[metric?.reason] ?? unavailable);
      values[`live-factor-${key}-duration`] = usable
        ? `${held ? '上次有效值：' : ''}實際 ${span(metric.actualSeconds)} ／上河基準 ${span(metric.baselineSeconds)}`
        : '目前無有效倍率';
    }
    const sources = [
      data.total?.source ?? data.total?.lastValid?.source,
      data.recent?.source ?? data.recent?.lastValid?.source,
    ].filter(Boolean);
    const labels = sources.flatMap((source) =>
      (source.distributions ?? []).map(timeDistributionLabel),
    );
    values['live-factor-distribution'] = labels.length
      ? [...new Set(labels)].join('；')
      : '尚無可用分配資料；等待有效定位與已知上河路段。';
    values['live-factor-provenance'] = [
      'GPS 與 GPX 時間來源均未獨立驗證；外部 GPX 的時間標記不代表可信。上河有向時間是基準，分配方法不是實測速度。',
      sources.some((source) => source.departureConfirmation)
        ? '出發錨點由使用者聲明確認，站點座標誤差未知。'
        : '',
      sources.some((source) => !source.departureConfirmation && source.startTimeOffsetMs > 0)
        ? '倍率從首個有效定位起算，未將定位前空白當成已觀測路程。'
        : '',
      sources.some((source) => source.restoration)
        ? '已以新定位核對重載前位置；關閉期間未觀測，並非連續 GPS 紀錄。'
        : '',
    ]
      .filter(Boolean)
      .join(' ');
    return values;
  }
  function panel() {
    const values = fields();
    const text = (id) => esc(values[id]);
    return `<section class="live-factors" aria-label="即時上河耗時倍率"><div class="live-factor-grid">${[
      ['total', '本次全程即時倍率'],
      ['recent', '最近 30 分鐘倍率'],
    ]
      .map(
        ([key, title]) =>
          `<section class="live-factor-card" aria-labelledby="live-factor-${key}-title"><h3 id="live-factor-${key}-title">${title}</h3><p class="live-factor-freshness" id="live-factor-${key}-freshness" data-state="${values[`live-factor-${key}-freshness`].startsWith('上次') ? 'stale' : 'live'}">${text(`live-factor-${key}-freshness`)}</p><p class="live-factor-value" id="live-factor-${key}-value">${text(`live-factor-${key}-value`)}</p><p class="live-factor-comparison" id="live-factor-${key}-comparison">${text(`live-factor-${key}-comparison`)}</p><p class="live-factor-reason" id="live-factor-${key}-reason" role="status" aria-atomic="true">${text(`live-factor-${key}-reason`)}</p></section>`,
      )
      .join(
        '',
      )}</div><p class="small">本次觀測僅供參考；下一站分別顯示兩種即時倍率 ETA，並保留設定倍率 ETA 作比較。</p><details id="live-factor-details" class="live-factor-details"><summary id="live-factor-summary">倍率計算與定位來源</summary><p>最後有效定位（台北時間）：<span id="live-factor-last-fix">${text('live-factor-last-fix')}</span></p><p>全程：<span id="live-factor-total-duration">${text('live-factor-total-duration')}</span><br>最近：<span id="live-factor-recent-duration">${text('live-factor-recent-duration')}</span></p><p>倍率＝實際經過時間 ÷ 已走路段的上河基準。快慢百分比比較耗時，1.20 倍代表多用時 20%。全程包含休息與暫停，只在有效定位時更新。</p><p>最近窗採真實定位端點，實際長度為 30 分至 30 分 30 秒；中斷或重載後重新累積，不補造定位。</p><p>上河分配：<span id="live-factor-distribution">${text('live-factor-distribution')}</span></p><p id="live-factor-provenance">${text('live-factor-provenance')}</p><p>設定倍率 ETA 保留作比較；即時倍率不會自動覆寫設定。</p></details></section>`;
  }
  function updateNumbers() {
    if (!document.getElementById('live-factor-total-value')) return;
    for (const [id, value] of Object.entries(fields())) {
      const element = document.getElementById(id);
      if (element && element.textContent !== value) element.textContent = value;
      if (element && id.endsWith('-freshness'))
        if (element.getAttribute('data-state') !== (value.startsWith('上次') ? 'stale' : 'live'))
          element.setAttribute('data-state', value.startsWith('上次') ? 'stale' : 'live');
    }
  }
  return { panel, updateNumbers };
}
