import { icon, button, esc, meters } from '../../ui/html.js';
import { elapsedLabel } from '../../domain/track.js';
import { emptyView } from '../../ui/empty-view.js';
import { mapSvg } from '../map/thumbnail.js';
export function createLibraryViews({ state, gpsPending, personalFactorPanel = () => '' }) {
  function fileCard(file, history = false) {
    return `<article class="panel route-card ${history ? 'library-card' : ''} ${state.selected === file.id && !history ? 'selected-card' : ''}">
      <div class="route-card-main"><div class="route-thumbnail">${mapSvg(file, null, [], true)}</div><div class="route-card-copy">
      <span class="route-origin">${history ? '親自記錄' : '匯入的 GPX'}${state.selected === file.id && !history ? ' · 已選用' : ''}</span>
      <h2>${esc(file.name)}</h2><p class="route-card-summary">${file.stats.km.toFixed(2)} km · 爬升 ${meters(file.stats.up)} m</p>
      ${history && file.recording ? `<p class="small muted">${new Date(file.recording.startedAt).toLocaleDateString('zh-TW', { timeZone: 'Asia/Taipei' })} · ${elapsedLabel(file.recording.elapsedMs)}</p>` : ''}
      </div></div><div class="route-card-actions">
      ${button(history ? '查看軌跡' : state.selected === file.id ? '查看此路線' : '選用路線', 'select', '', 'route', `data-id="${file.id}" ${gpsPending() ? 'disabled' : ''}`)}
      ${history ? button('下載 GPX', 'file-download', 'ghost', 'download', `data-id="${file.id}"`) + button('作為參考路線', 'use-recording-route', '', 'route', `data-id="${file.id}" ${gpsPending() || state.timeSourceBusy ? 'disabled' : ''}`) : ''}
      ${button('移除', 'delete', 'ghost', 'close', `data-id="${file.id}" ${gpsPending() && state.gps.sourceRouteId === file.id ? 'disabled' : ''}`)}
      </div>${!file.saved ? '<p class="small error-message">尚未保存至此裝置，請保留原檔。</p>' : ''}</article>`;
  }
  function libraryView() {
    const files = state.library.filter((file) => file.kind === 'recording');
    return (
      personalFactorPanel() +
      (files.length
        ? `<div class="collection-heading"><span>${files.length} 次留下的山行</span><span>保存在此裝置</span></div><div class="library-list">${files
            .slice()
            .reverse()
            .map((file) => fileCard(file, true))
            .join('')}</div>`
        : `<section class="saved-empty"><div class="empty-art">${icon('mountain')}${icon('route')}</div><span class="eyebrow">YOUR TRAIL STORIES</span><h2>還沒有保存的軌跡</h2><p>結束紀錄後選擇保存，<br>就會出現在這裡。</p>${button(gpsPending() ? '回到紀錄' : '開始紀錄', gpsPending() ? 'view-record' : 'gps-direct', 'primary', 'locate', state.loading || state.starting ? 'disabled' : '')}<span class="small muted">只收藏你親自走過的路</span></section>`)
    );
  }
  function routesView() {
    const files = state.library.filter((file) => file.kind !== 'recording');
    const results = state.results.length
      ? `<details class="import-results"><summary>本次匯入結果 · ${state.results.filter((r) => r.ok).length} 個成功</summary><ul>${state.results.map((r) => `<li class="${r.ok ? 'result-ok' : 'result-error'}"><strong>${esc(r.name)}</strong><span>${esc(r.message)}</span></li>`).join('')}</ul></details>`
      : '';
    return `${results}${state.storageError ? `<p class="error-message">${esc(state.storageError)}</p>` : ''}${files.length ? `<div class="collection-heading"><span>${files.length} 條匯入路線</span><span>選一條，準備出發</span></div><div class="route-grid">${files.map((file) => fileCard(file)).join('')}</div>` : emptyView()}<p class="collection-note">${icon('shield')}GPX 保留在此裝置，不會上傳雲端。</p>`;
  }
  return { libraryView, routesView };
}
