import { reroutePanel } from '../itinerary/reroute-view.js';
import { recordingStats, recordingSegments } from './analysis.js';
import { directionPanel } from '../routes/direction-view.js';
import { completionView } from './completion-view.js';
import { button, meters, esc } from '../../ui/html.js';
import { elapsedLabel } from '../../domain/track.js';
import { shangheFactor, remainingEstimate } from './model.js';
export function createRecordingView({
  state,
  current,
  gpsPending,
  recordingRoute,
  gpsElapsed,
  mapPanel,
  heightPanel,
  itineraryViews,
  persistence,
  document = globalThis.document,
}) {
  const directMap = state.directMap,
    saveStatus = persistence.status;
  function recordView() {
    if (gpsPending()) return gpsView(recordingRoute());
    const candidate = current(),
      file = candidate?.kind === 'recording' ? null : candidate;
    return `<div class="record-ready"><section class="panel panel-body stack"><span class="eyebrow">YOUR NEXT WALK</span><h2>${file ? esc(file.name) : '不匯入路線也能開始紀錄'}</h2><p class="muted">${file ? '參照這條路線，記錄你真正走過的軌跡。' : '允許 GPS 定位，開始今天的山行。'}</p><label for="recording-name">紀錄名稱（選填）</label><input id="recording-name" maxlength="120" placeholder="例如：今天的登山紀錄" value="${esc(state.recordingName)}">${file ? button('開始登山紀錄', 'gps-start', 'primary', 'locate', state.starting ? 'disabled' : '') : button(state.starting ? '準備紀錄…' : '直接開始紀錄', 'gps-direct', 'primary', 'locate', state.starting ? 'disabled' : '')}${file ? button('不使用路線，直接紀錄', 'gps-direct', 'ghost') : '<button class="button" data-view="routes">前往我的路線</button>'}<p class="small muted">結束時再選擇是否保存至「我的 GPX」。</p>${state.recordingBlocked || state.storageError ? `<p class="error-message">${esc(state.recordingBlocked || state.storageError)}</p>` : ''}</section>${file ? `${directionPanel(file, { locked: state.starting, error: state.directionError })}${itineraryViews?.resourcesPanel() ?? ''}${mapPanel(file)}` : ''}</div>`;
  }
  function gpsView(file) {
    const gps = state.gps,
      stats = recordingStats(gps);
    const stopped = ['review', 'stopping', 'finishing', 'discarding', 'finished'].includes(
      gps.status,
    );
    const status = {
      requesting: '等待定位',
      tracking: 'GPS 紀錄中',
      paused: '已暫停',
      error: '定位已中斷',
      stopping: '正在結束',
      review: '已結束',
      finishing: '保存 GPX 中',
      discarding: '移除草稿中',
      finished: '紀錄完成',
    }[gps.status];
    const locationStatus = stopped
      ? '定位已停止；地圖顯示本次已記錄軌跡。'
      : {
          requesting: '等待有效定位；地圖上的已記錄位置不代表目前位置。',
          tracking: '正在接收 GPS 定位並記錄軌跡。',
          paused: '已暫停定位；地圖顯示已記錄軌跡，不代表目前位置。',
          error: '定位已中斷；地圖僅顯示先前軌跡，最後紀錄位置不代表目前位置。',
        }[gps.status];
    const currentAccuracy = gps.status === 'tracking' && Number.isFinite(gps.accuracy);
    return `<section data-status="${esc(gps.status)}" class="recording-scene ${stopped ? 'recording-stopped' : ''}"><header class="recording-heading"><div><span class="eyebrow">${stopped ? 'YOUR WALK' : gps.status === 'tracking' ? 'LIVE GPS' : 'GPS STATUS'}${gps.sourceRouteId ? (gps.sourceRouteDirection === 'reverse' ? ' · 反向走' : ' · 原向走') : ''}</span><h2>${esc(gps.name || file.name)}</h2></div><span class="record-status" data-status="${esc(gps.status)}" role="status" aria-live="polite">${status}</span></header><p id="gps-location-status" class="recording-location-status"${stopped ? ' hidden' : ''}>${locationStatus}</p><div class="recording-map" aria-describedby="gps-location-status">${mapPanel(file, null, recordingSegments(gps), { compact: true })}</div>${stopped ? completionView(gps, gpsElapsed()) : `<section class="recording-sheet"><div class="sheet-handle"></div>${itineraryViews?.liveFactorsPanel?.() ?? ''}${itineraryViews && gps.sourceRouteId ? itineraryViews.nextCard() : '<div class="direct-next"><span class="eyebrow">記下自己的路</span><h2>自由紀錄</h2><p class="small muted">藍線是已記錄軌跡，目前未使用預定路線。</p></div>'}<div class="live-stats"><div><small>紀錄時間</small><strong id="gps-clock">${elapsedLabel(gpsElapsed())}</strong></div><div><small>校正距離</small><strong id="gps-distance">${stats.km.toFixed(2)} <small>km</small></strong></div><div><small>GPS 精度</small><strong>${currentAccuracy ? `${Math.round(gps.accuracy)} <small>m</small>` : '—'}</strong></div></div>${gps.error ? `<p class="error-message" role="status">${esc(gps.error)}</p>` : ''}${reroutePanel(state)}${itineraryViews?.departureNotice?.() ?? ''}<div class="live-controls">${button(['paused', 'error'].includes(gps.status) ? '繼續紀錄' : '暫停紀錄', ['paused', 'error'].includes(gps.status) ? 'gps-resume' : 'gps-pause', '', ['paused', 'error'].includes(gps.status) ? 'play' : 'pause')}${button('結束紀錄', 'gps-finish', 'end-recording', 'stop')}</div><details class="recording-more" id="recording-more"><summary>紀錄狀態與更多資訊</summary><div class="stack">${itineraryViews?.departurePanel?.() ?? ''}<p id="gps-save-status" class="small muted" role="status">${esc(saveStatus())}</p>${button('重試保存', 'gps-save-retry', '', 'refresh', `id="gps-save-retry" ${gps.saveError ? '' : 'hidden'}`)}<p class="small muted">請保持分頁開啟；鎖屏與背景定位可能中斷。草稿只供恢復，不會自動加入「我的 GPX」。距離與高度會隨後續定位校正，原始 GPX 保留。</p>${button('下載備份', 'gps-download', 'ghost', 'download')}${button(stats.points ? '放棄這次紀錄' : '取消空白紀錄', 'gps-discard', 'ghost', 'close')}<p class="small muted">已保留 ${stats.points} 個原始點 · ${gps.segments.filter((segment) => segment.length).length} 段軌跡</p><p class="small muted">校正爬升 <span id="gps-ascent">${meters(stats.up)}</span> m ／下降 <span id="gps-descent">${meters(stats.down)}</span> m · 平均速度 <span id="gps-average">—</span></p></div></details></section>`}</section>${heightPanel ? `<details class="recording-height-profile" id="recording-height-profile"><summary>路線高度剖面・日夜路段</summary>${heightPanel(file, recordingSegments(gps))}</details>` : ''}${!stopped && file === directMap ? `<details class="manual-reference" id="manual-reference"><summary>進階：手動上河路段計時</summary>${shanghePanel()}</details>` : ''}`;
  }
  function shanghePanel(readonly = false) {
    const gps = state.gps,
      calibration = gps.calibration || { completed: [] },
      active = calibration.active,
      factor = shangheFactor(calibration.completed);
    return `<section class="panel panel-body stack shanghe-panel"><span class="eyebrow">SHANGHE · MANUAL REFERENCE</span><h2>上河時間倍率</h2><div class="shanghe-value">${factor === null ? '尚未計算' : `${factor.toFixed(2)} <small>倍</small>`}</div><p class="small muted">倍率＝已確認路段的實際時間總和 ÷ 上河 1.0 時間總和。1.2 倍表示耗時增加 20%，不含手動暫停。</p>
    ${(calibration.completed || []).length ? `<ul class="calibration-history">${calibration.completed.map((item) => `<li><strong>${esc(item.label)}</strong><span>基準 ${item.baseMinutes} 分 · 實際 ${elapsedLabel(item.actualMs)}</span></li>`).join('')}</ul>` : ''}
    ${readonly ? '' : active ? `<div class="soft-notice">${esc(active.label)} · 基準 ${active.baseMinutes} 分<br>路段計時 <strong id="calibration-clock">${elapsedLabel(gpsElapsed() - active.startElapsed)}</strong></div><p class="small muted">到達此路段終點時按「確認路段完成」。基準方向必須與實際走法一致。</p>${button('確認路段完成', 'calibration-end', 'primary', '', ['tracking', 'paused'].includes(gps.status) ? '' : 'disabled')}${button('取消這段計時', 'calibration-cancel', 'ghost')}` : `<label for="calibration-label">路段與方向</label><input id="calibration-label" maxlength="120" type="text" placeholder="例如：登山口 → 山屋" value="${esc(gps.calibrationLabel || '')}"><label for="calibration-base">這段上河 1.0 時間（分鐘）</label><input id="calibration-base" type="number" inputmode="decimal" min="0.1" max="10080" step="any" value="${esc(gps.calibrationBase || '')}">${button('在路段起點開始計時', 'calibration-start', 'primary', 'clock', gps.status !== 'tracking' ? 'disabled' : '')}`}
    ${readonly ? '' : `<hr><label for="remaining-base">從現在到目的地的上河 1.0 時間（分鐘）</label><input id="remaining-base" type="number" inputmode="decimal" min="0.1" max="10080" step="any" value="${esc(gps.remainingBase || '')}">${button('更新剩餘時間', 'estimate-update', '', 'refresh', factor === null ? 'disabled' : '')}`}
    <div class="estimate-result"><span class="small muted">預估剩餘時間</span><strong id="remaining-time">—</strong><span class="small muted">預估抵達（台北時間）</span><strong id="arrival-time">—</strong></div><p class="small muted">尚無 GPS 與上河路段自動配對，基準由你確認。估算套用已走路段倍率並按紀錄時間倒數；暫停會順延。更新剩餘基準可校正進度；地形與路況變化可能造成誤差。</p></section>`;
  }
  function updateRecordingNumbers() {
    const gps = state.gps,
      elapsed = gpsElapsed(),
      set = (id, value) => {
        const el = document.getElementById(id);
        if (el) el.textContent = value;
      };
    itineraryViews?.updateNumbers();
    set('gps-clock', elapsedLabel(elapsed));
    if (gps.status !== 'review') set('gps-save-status', saveStatus());
    set(
      'gps-average',
      `${elapsed > 0 ? (recordingStats(gps).km / (elapsed / 3600000)).toFixed(2) : '—'} km/h`,
    );
    if (gps.calibration?.active)
      set('calibration-clock', elapsedLabel(elapsed - gps.calibration.active.startElapsed));
    const remaining = remainingEstimate(gps.remaining, elapsed),
      finished = ['review', 'stopping', 'finished', 'finishing'].includes(gps.status);
    set(
      'remaining-time',
      finished
        ? '紀錄已結束'
        : remaining === null
          ? '需先完成基準路段並更新剩餘時間'
          : remaining === 0
            ? '估算時間已過，請更新基準'
            : elapsedLabel(remaining),
    );
    set(
      'arrival-time',
      finished || remaining === null || remaining === 0
        ? '—'
        : new Date(Date.now() + remaining).toLocaleString('zh-TW', {
            timeZone: 'Asia/Taipei',
            month: 'numeric',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
          }),
    );
  }
  function updateSaveStatus() {
    const element = document.getElementById('gps-save-status');
    if (element) {
      element.textContent = saveStatus();
      element.className = `small ${state.gps.saveError ? 'error-message' : 'muted'}`;
    }
    if (state.gps.saveError) {
      const details = document.getElementById('recording-more');
      if (details) details.open = true;
    }
    const retry = document.getElementById('gps-save-retry');
    if (retry) retry.hidden = !state.gps.saveError;
  }

  return { recordView, updateNumbers: updateRecordingNumbers, updateSaveStatus };
}
