import { routeMatcherFor } from './matching.js';
import { stationKey } from './rerouting.js';

export function smartLocations(file, plan, journey, fix, accepted = null) {
  if (!file?.points?.length || !plan) return [];
  const matched =
    routeMatcherFor(file).match(
      [{ ...fix, stationId: 'smart-reroute-origin', coordinateStatus: 'located' }],
      { maxOffsetM: 50, mergeWithinM: 25 },
    ).matches[0]?.routePositions ?? [];
  const locked =
    accepted?.fix?.time === fix.time && !accepted.fix.excluded
      ? matched.filter(
          (p) =>
            p.segmentIndex === accepted.position?.segmentIndex &&
            Math.abs(p.routeProgressM - accepted.position.routeProgressM) < 1e-6,
        )
      : [];
  let candidates = locked.length === 1 ? locked : matched;
  if (locked.length !== 1 && journey) {
    const next = plan.rows[journey.nextIndex];
    const previous = plan.rows[Math.max(0, journey.nextIndex - 1)];
    if (previous && next) {
      const corridor = matched.filter(
        (p) =>
          (p.segmentIndex === previous.segmentIndex || p.segmentIndex === next.segmentIndex) &&
          p.routeProgressM >= previous.routeProgressM - 25 &&
          p.routeProgressM <= next.routeProgressM + (journey.nextIndex === 0 ? 50 : 25),
      );
      if (corridor.length) candidates = corridor;
    }
  }
  return candidates.map((position) => {
    const target = plan.rows.find(
      (row) =>
        row.routeProgressM >= position.routeProgressM - 1e-6 &&
        row.segmentIndex === position.segmentIndex &&
        row.index > 0,
    );
    const previous = target && plan.rows[target.index - 1];
    return {
      ...position,
      id: JSON.stringify([file.id, position.segmentIndex, previous?.index, target?.index]),
      label:
        previous && target
          ? `${previous.station.name}與${target.station.name}之間`
          : 'GPX 起終點附近',
      fromM: previous?.routeProgressM ?? position.routeProgressM,
      toM: target?.routeProgressM ?? position.routeProgressM,
    };
  });
}

export function canonicalLocation(file, plan, location, provenance = []) {
  if (!file.rerouted)
    return {
      sourceId: file.id,
      m:
        file.direction === 'reverse'
          ? file.stats.km * 1000 - location.routeProgressM
          : location.routeProgressM,
      segment:
        file.direction === 'reverse'
          ? file.segments.length - 1 - location.segmentIndex
          : location.segmentIndex,
    };
  const leg = plan.timeModel.legs.find(
    (l) =>
      l.segmentIndex === location.segmentIndex &&
      location.routeProgressM >= l.fromM - 1e-6 &&
      location.routeProgressM <= l.toM + 1e-6,
  );
  if (!leg || !leg.source?.originalRouteId || leg.toM <= leg.fromM) return null;
  const source = leg.source;
  return {
    sourceId: source.originalRouteId,
    direction: source.originalDirection,
    segment: source.originalCanonicalSegment,
    directedSegment: provenance[leg.index]?.segment,
    directedM:
      source.originalFromM +
      ((source.originalToM - source.originalFromM) * (location.routeProgressM - leg.fromM)) /
        (leg.toM - leg.fromM),
  };
}

export function smartHome(source, plan, originalFile, originalPlan) {
  const row = originalPlan?.rows[0];
  if (!row) return null;
  const result = { key: stationKey(row), name: row.station.name, sourceId: originalFile.id };
  if (source.id === originalFile.id) {
    result.canonicalM =
      originalFile.direction === 'reverse'
        ? source.stats.km * 1000 - row.routeProgressM
        : row.routeProgressM;
  }
  // A switched GPX can return to an original station only if that station is
  // actually present in its own geometry/reference plan.
  return plan.rows.some((r) => stationKey(r) === result.key) ? result : null;
}

export function visitedStations(gps, plan) {
  const keys = new Set();
  for (const version of [...(gps.navigation?.revisions ?? []), { plan, journey: gps.itinerary }]) {
    for (const [index, time] of Object.entries(version.journey?.arrivals ?? {})) {
      const row = version.plan?.rows?.[Number(index)];
      if (row && Number.isFinite(time)) keys.add(stationKey(row));
    }
  }
  return keys;
}
