import { LIVE_FACTOR_DEFAULTS } from './live-factor.js';
import { shangheTimeAt } from './time-interpolation.js';

const missing = (reason) => ({
  factor: null,
  baselineSeconds: null,
  remainingSeconds: null,
  arrivalUtcMs: null,
  reason,
  source: null,
});

// Consume the live engine's accepted occurrence. Never rematch GPS against a
// next-station corridor: on an out-and-back that can select the wrong visit.
export function nextStopEtas(file, data, live, now = Date.now()) {
  const direction = file?.direction === 'reverse' ? 'reverse' : 'forward';
  const next = data?.next;
  const previous = data?.rows?.[Math.max(0, data.nextIndex - 1)];
  const unavailable = (reason) => ({
    asOf: now,
    total: missing(reason),
    recent: missing(reason),
  });
  if (!data?.active || data.finished) return unavailable('eta-not-recording');
  if (!next) return unavailable('eta-no-next');
  if (!file || !data.compatible || !data.timeModel)
    return unavailable('reference-or-session-changed');

  function estimate(metric) {
    // v3 has no state; v4 (#30) explicitly labels live vs stale. lastValid is
    // display-only and is deliberately never read here.
    if (
      !Number.isFinite(metric?.factor) ||
      metric.factor <= 0 ||
      metric.reason ||
      (metric.state !== undefined && metric.state !== 'live')
    )
      return missing(metric?.reason ?? 'eta-factor-unavailable');
    const source = metric.source;
    const position = source?.to;
    if (
      !position ||
      !Number.isFinite(now) ||
      !Number.isFinite(position.time) ||
      now - position.time > LIVE_FACTOR_DEFAULTS.maxAgeMs ||
      position.time > now + LIVE_FACTOR_DEFAULTS.futureToleranceMs ||
      live.asOf !== position.time ||
      (metric.asOf !== undefined && metric.asOf !== position.time)
    )
      return missing('stale-gps-fix');
    if (
      source.routeId !== file.id ||
      source.direction !== direction ||
      source.modelVersion !== data.timeModel.version ||
      !Number.isInteger(position.segmentIndex) ||
      position.segmentIndex !== next.segmentIndex ||
      !Number.isFinite(position.routeProgressM) ||
      !Number.isFinite(next.routeProgressM) ||
      next.gap ||
      !previous ||
      !Number.isFinite(previous.routeProgressM) ||
      (!file.rerouted && previous.segmentIndex !== position.segmentIndex) ||
      position.routeProgressM < previous.routeProgressM ||
      position.routeProgressM > next.routeProgressM
    )
      return missing('eta-route-position-mismatch');

    const fromM = position.routeProgressM,
      toM = next.routeProgressM,
      model = data.timeModel;
    let cursor = fromM;
    // Validate every remaining leg, even when the target is a known boundary
    // beside an unknown leg. No distance-proportional fallback or gap bridging.
    for (const leg of model.legs) {
      const left = Math.max(fromM, leg.fromM),
        right = Math.min(toM, leg.toM);
      if (right <= left) continue;
      if (
        Math.abs(left - cursor) > 1e-6 ||
        leg.segmentIndex !== position.segmentIndex ||
        leg.source.direction !== direction ||
        leg.method === 'unavailable'
      )
        return missing(leg.reason ?? 'eta-unknown-remaining');
      cursor = right;
    }
    if (Math.abs(cursor - toM) > 1e-6) return missing('eta-unknown-remaining');
    const options = { segmentIndex: position.segmentIndex };
    const from = shangheTimeAt(model, fromM, options),
      to = shangheTimeAt(model, toM, options);
    if (![from.elapsedSeconds, to.elapsedSeconds].every(Number.isFinite))
      return missing(from.reason ?? to.reason ?? 'eta-unknown-remaining');
    const baselineSeconds = to.elapsedSeconds - from.elapsedSeconds,
      remainingSeconds = baselineSeconds * metric.factor,
      arrivalUtcMs = now + remainingSeconds * 1000;
    if (
      baselineSeconds < 0 ||
      !Number.isFinite(remainingSeconds) ||
      !Number.isFinite(arrivalUtcMs) ||
      Math.abs(arrivalUtcMs) > 8640000000000000
    )
      return missing('eta-unknown-remaining');
    return {
      factor: metric.factor,
      baselineSeconds,
      remainingSeconds,
      arrivalUtcMs,
      reason: null,
      source: {
        direction,
        segmentIndex: position.segmentIndex,
        fromM,
        toM,
        fixTime: position.time,
      },
    };
  }
  return { asOf: now, total: estimate(live?.total), recent: estimate(live?.recent) };
}
