const DAY_MS = 86400000;
const TAIPEI_OFFSET_MS = 8 * 3600000;
export const PHASE_COLORS = { day: '#e6b45b', night: '#536588', unknown: '#b8c0bc' };
export const taipeiDate = (milliseconds) =>
  new Date(milliseconds + TAIPEI_OFFSET_MS).toISOString().slice(0, 10);
export const midnight = (date) => Date.parse(`${date}T00:00:00+08:00`);

export function solarDay(reference, county, date) {
  const times = reference.days[county]?.[date];
  if (
    !Array.isArray(times) ||
    times.length !== 2 ||
    times.some((m) => !Number.isInteger(m) || m < 0 || m >= 1440) ||
    times[0] >= times[1]
  )
    return null;
  const base = midnight(date);
  return { date, sunrise: base + times[0] * 60000, sunset: base + times[1] * 60000 };
}

// Boundaries are computed in Taipei civil dates, including every midnight.
// A missing official day remains unknown; never substitute another year's table.
export function splitSolarLeg(reference, county, leg) {
  const { fromM, toM, start, end } = leg;
  if (
    ![fromM, toM, start, end].every(Number.isFinite) ||
    toM <= fromM ||
    end <= start ||
    end - start > 366 * DAY_MS
  )
    return [];
  const boundaries = [start, end];
  for (let day = midnight(taipeiDate(start)); day <= end; day += DAY_MS) {
    if (day > start && day < end) boundaries.push(day);
    const sun = solarDay(reference, county, taipeiDate(day));
    if (sun)
      for (const event of [sun.sunrise, sun.sunset])
        if (event > start && event < end) boundaries.push(event);
  }
  boundaries.sort((a, b) => a - b);
  const unique = [...new Set(boundaries)];
  return unique.slice(1).map((time, index) => {
    const begin = unique[index],
      middle = (begin + time) / 2;
    const sun = solarDay(reference, county, taipeiDate(middle));
    const phase = !sun ? 'unknown' : middle >= sun.sunrise && middle < sun.sunset ? 'day' : 'night';
    return {
      fromM: fromM + ((toM - fromM) * (begin - start)) / (end - start),
      toM: fromM + ((toM - fromM) * (time - start)) / (end - start),
      start: begin,
      end: time,
      phase,
      date: taipeiDate(middle),
    };
  });
}

export function itineraryLegs(data, departure, totalDistanceM = data?.totalDistanceM) {
  if (
    !data ||
    data.compatible === false ||
    (!data.active && !data.startCovered) ||
    !Number.isFinite(departure)
  )
    return [];
  const at = (row) =>
    data.active
      ? row.arrivalUtcMs
      : row.cumulativeSeconds == null
        ? null
        : departure + row.cumulativeSeconds * 1000;
  return data.rows.slice(1).flatMap((row, index) => {
    const previous = data.rows[index];
    const start = at(previous),
      end = at(row);
    if (
      row.reason ||
      row.baselineSeconds == null ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    )
      return [];
    // Known station-to-station Shanghe time remains valid across track fragments.
    // The cumulative distance excludes gaps; the SVG still clips each segment separately.
    const fromM = index === 0 && data.startCovered ? 0 : previous.routeProgressM;
    const toM =
      index === data.rows.length - 2 && data.endCovered && Number.isFinite(totalDistanceM)
        ? totalDistanceM
        : row.routeProgressM;
    return [{ fromM, toM, start, end }];
  });
}

export function recordedLegs(file) {
  // Only a saved/live app recording uses its actual timestamps. Imported GPX never does.
  if (file.kind !== 'recording') return [];
  return file.points.slice(1).flatMap((point, index) => {
    const previous = file.points[index];
    return point.segment === previous.segment &&
      Number.isFinite(point.time) &&
      Number.isFinite(previous.time) &&
      point.time > previous.time &&
      point.km > previous.km
      ? [{ fromM: previous.km * 1000, toM: point.km * 1000, start: previous.time, end: point.time }]
      : [];
  });
}

export function buildDaylightProfile(reference, county, file, data, now = Date.now()) {
  const actual = file.kind === 'recording';
  const departure = data?.active ? data.departureUtcMs : now;
  const legs = actual ? recordedLegs(file) : itineraryLegs(data, departure, file.stats?.km * 1000);
  const rawBands = county ? legs.flatMap((leg) => splitSolarLeg(reference, county, leg)) : [];
  const bands = [];
  // Merge adjacent identical phases so large real recordings do not create one SVG node per fix.
  for (const band of rawBands) {
    const previous = bands.at(-1);
    if (
      previous &&
      previous.phase === band.phase &&
      previous.date === band.date &&
      Math.abs(previous.toM - band.fromM) < 0.001 &&
      previous.end === band.start
    ) {
      previous.toM = band.toM;
      previous.end = band.end;
    } else bands.push({ ...band });
  }
  const dates = [...new Set(rawBands.map((band) => band.date))];
  if (!dates.length) dates.push(taipeiDate(Number.isFinite(departure) ? departure : now));
  const days = dates.map((date) => ({ date, sun: solarDay(reference, county, date) }));
  return {
    bands,
    days,
    county,
    mode: actual ? 'recorded' : data?.active ? 'forecast' : 'preview',
    hasTiming: legs.length > 0,
    hasUnknownSegments:
      bands
        .filter((band) => band.phase !== 'unknown')
        .reduce((total, band) => total + band.toM - band.fromM, 0) <
      (file.stats?.km ?? 0) * 1000 - 1,
    hasUnknownDays: county && days.some((day) => !day.sun),
  };
}
