import { sampled } from '../../domain/track.js';
import { esc } from '../../ui/html.js';
export function mapSvg(file, position = null, live = [], small = false, stations = []) {
  const all = [...file.points, ...live.flat()],
    origin = all[0];
  if (!all.length)
    return '<div class="map-waiting">等待第一個 GPS 位置；可先縮放與切換底圖。</div>';
  const cos = Math.max(0.01, Math.cos((origin.lat * Math.PI) / 180));
  const raw = (point) => ({
    x: (((point.lon - origin.lon + 540) % 360) - 180) * cos,
    y: -point.lat,
  });
  let minX = Infinity,
    maxX = -Infinity,
    minY = Infinity,
    maxY = -Infinity;
  all.forEach((point) => {
    const p = raw(point);
    minX = Math.min(minX, p.x);
    maxX = Math.max(maxX, p.x);
    minY = Math.min(minY, p.y);
    maxY = Math.max(maxY, p.y);
  });
  const width = 640,
    height = small ? 220 : 330,
    pad = 35,
    scale = Math.min(
      (width - pad * 2) / Math.max(maxX - minX, 0.0001),
      (height - pad * 2) / Math.max(maxY - minY, 0.0001),
    );
  const project = (point) => {
    const p = raw(point);
    return {
      x: width / 2 + (p.x - (minX + maxX) / 2) * scale,
      y: height / 2 + (p.y - (minY + maxY) / 2) * scale,
    };
  };
  const line = (segment, color, size) =>
    `<polyline points="${sampled(
      segment,
      Math.max(20, Math.floor(4000 / Math.max(1, file.segments.length + live.length))),
    )
      .map((point) => {
        const p = project(point);
        return `${p.x.toFixed(2)},${p.y.toFixed(2)}`;
      })
      .join(
        ' ',
      )}" fill="none" stroke="${color}" stroke-width="${size}" stroke-linecap="round" stroke-linejoin="round"/>`;
  const dot = (point, color, r = 6) => {
    const p = project(point);
    return `<circle cx="${p.x}" cy="${p.y}" r="${r}" fill="${color}" stroke="white" stroke-width="3"/>`;
  };
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(file.name)}的 GPX 軌跡圖" class="gpx-map"><rect width="${width}" height="${height}" fill="#edf3ed"/>
    <g stroke="#dce5dc" stroke-width="1">${[80, 160, 240, 320, 400, 480, 560].map((x) => `<path d="M${x} 0V${height}"/>`).join('')}${[70, 140, 210, 280].map((y) => `<path d="M0 ${y}H640"/>`).join('')}</g>
    ${file.segments.map((segment) => line(segment, 'white', 8)).join('')}${file.segments.map((segment) => line(segment, '#326753', 4)).join('')}
    ${live.map((segment) => line(segment, '#4388b7', 3)).join('')}
    ${file.points.length ? dot(file.points[0], '#183e35') + dot(file.points.at(-1), '#8daa64') : ''}
    ${position ? dot(position, '#d3a34c', 9) : ''}${live.at(-1)?.length ? dot(live.at(-1).at(-1), '#4388b7', 8) : ''}
    ${stations
      .map((station) => {
        const p = project(station);
        return `<g>${dot(station, station.next ? '#b87930' : '#326753', 7)}<title>${esc(station.name)} ${esc(station.arrivalLabel || '')}</title><text x="${p.x + 10}" y="${p.y - 7}" fill="#183e35" font-size="12">${esc(station.name)}</text></g>`;
      })
      .join('')}
    <text x="20" y="27" fill="#527062" font-size="13">N ↑</text></svg>`;
}
