import { uniqueTimePath } from './time-path.js';

export function resolveTimeLeg({
  previous,
  row,
  rows,
  excluded,
  graph,
  adapter,
  nodes,
  nodePlaces,
}) {
  if (!previous.nodeBindings.length || !row.nodeBindings.length)
    return { reason: '未對應時間節點' };
  const candidates = [],
    failures = [];
  for (const from of previous.nodeBindings) {
    for (const to of row.nodeBindings) {
      if (from.area !== to.area) continue;
      const blocked = new Set([
        ...excluded,
        ...rows
          .filter((other) => other !== previous && other !== row)
          .flatMap((other) => other.nodeBindings.map((binding) => binding.id)),
      ]);
      for (const endpoint of [...previous.nodeBindings, ...row.nodeBindings])
        blocked.delete(endpoint.id);
      const path = uniqueTimePath(graph, from.id, to.id, blocked);
      if (!path.nodes) {
        failures.push(path.reason);
        continue;
      }
      if (path.nodes.length === 1) {
        failures.push('站點對應相同時間節點，需核對');
        continue;
      }
      const result = adapter.buildPath({ area: to.area, nodes: path.nodes, mode: 'trail' });
      if (result.issues.length) {
        failures.push('路段時間缺漏、衝突或版本尚待核對');
        continue;
      }
      candidates.push({
        area: to.area,
        nodes: path.nodes,
        segments: result.segments,
        names: path.nodes.map((id) => nodes.get(id)?.name),
        sequence: path.nodes.map((id) => nodePlaces.get(id) ?? `name:${nodes.get(id)?.name}`),
        signature: JSON.stringify([
          path.nodes.map((id) => nodePlaces.get(id)).filter(Boolean),
          result.segments.reduce((total, segment) => total + segment.baselineMoveSeconds, 0),
        ]),
      });
    }
  }
  if (!candidates.length)
    return { reason: failures[0] ?? '兩站沒有共用的上河時間圖，需核對連接路段' };
  if (failures.some((reason) => /多條|同時間節點|複雜|衝突/.test(reason)))
    return { reason: '共用地點的上河時間圖仍有歧義或衝突，需核對' };
  if (candidates.some((candidate) => candidate.signature !== candidates[0].signature))
    return { reason: '不同上河圖的路徑或有向時間不一致，需核對' };
  const subsequence = (short, long) => {
    let cursor = 0;
    for (const id of long) if (id === short[cursor]) cursor++;
    return cursor === short.length;
  };
  for (const candidate of candidates)
    for (const other of candidates)
      if (
        !subsequence(candidate.sequence, other.sequence) &&
        !subsequence(other.sequence, candidate.sequence)
      )
        return { reason: '不同上河圖的中間路徑不一致，需核對' };
  const selected = candidates[0];
  return {
    ...selected,
    reason: null,
    referenceAreas: [...new Set(candidates.map((candidate) => candidate.area))],
    referenceSources: [
      ...new Set(
        candidates.flatMap((candidate) =>
          candidate.segments.flatMap((segment) => segment.sourceIds),
        ),
      ),
    ],
    segments: selected.segments.map((segment) => ({
      ...segment,
      fromTimeNodeId: segment.fromWaypointId,
      toTimeNodeId: segment.toWaypointId,
      fromWaypointId: nodePlaces.get(segment.fromWaypointId) ?? segment.fromWaypointId,
      toWaypointId: nodePlaces.get(segment.toWaypointId) ?? segment.toWaypointId,
    })),
  };
}
