import { Capacitor, registerPlugin } from '@capacitor/core';
import { createWebLocationProvider } from './web.js';
import { createIOSLocationProvider } from './native-ios.js';

export function createLocationProvider({
  navigator = globalThis.navigator,
  capacitor = Capacitor,
  register = registerPlugin,
} = {}) {
  if (capacitor.isNativePlatform() && capacitor.getPlatform() === 'ios')
    return createIOSLocationProvider({ plugin: register('RidgewiseLocation') });
  return createWebLocationProvider({ navigator });
}
