/**
 * A source-independent raw fix. Coordinates are WGS84 degrees, elevation is metres
 * above the WGS84 ellipsoid (null when unknown), time is Unix epoch milliseconds and
 * both accuracy values are metres (altitudeAccuracy may be null).
 * @typedef {{lat: number, lon: number, elevation: number|null, time: number,
 *   accuracy: number, altitudeAccuracy: number|null, simulated?: boolean}} LocationFix
 * @typedef {{code: 'permission-denied'|'position-unavailable'|'timeout'|'unsupported'|'start-failed'|'foreground-required', source?: 'ios'}} LocationError
 * @typedef {() => void} StopLocationWatch
 * @typedef {Object} LocationProvider
 * @property {'web-geolocation'|'ios-core-location'|'simulation'} [sourceType] App-local provider identity; never independent GPS verification.
 * @property {(onFix: (fix: LocationFix) => void, onError: (error: LocationError) => void)
 *   => StopLocationWatch|Promise<StopLocationWatch>} watch
 * Start only on watch(). Stop must be idempotent, release the subscription and not throw.
 * A future native provider may resolve its stop function asynchronously; the
 * tracker cancels late subscriptions and ignores callbacks from stopped watches.
 */

/** Copy valid fixes without coercing missing values into zero or inventing quality. */
export function normalizeLocationFix(fix) {
  if (
    !fix ||
    !Number.isFinite(fix.lat) ||
    Math.abs(fix.lat) > 90 ||
    !Number.isFinite(fix.lon) ||
    Math.abs(fix.lon) > 180 ||
    !Number.isFinite(fix.time) ||
    !Number.isFinite(fix.accuracy) ||
    fix.accuracy < 0
  )
    return null;
  return {
    lat: fix.lat,
    lon: fix.lon,
    elevation: Number.isFinite(fix.elevation) ? fix.elevation : null,
    time: fix.time,
    accuracy: fix.accuracy,
    altitudeAccuracy:
      Number.isFinite(fix.altitudeAccuracy) && fix.altitudeAccuracy >= 0
        ? fix.altitudeAccuracy
        : null,
    ...(fix.simulated === true ? { simulated: true } : {}),
  };
}
