import { indexTrack, trackStats } from './track-math.js';
import { filterTrack } from './track-filter.js';
import { prepareTimeWeights } from './track-time.js';
export { haversine, trackStats } from './track-math.js';

function qualitySegments(segments) {
  const result = [];
  segments.forEach((segment, rawSegment) => {
    let run = [];
    segment.forEach((point, rawIndex) => {
      if (point.excluded) {
        if (run.length) result.push(run);
        run = [];
      } else run.push({ ...point, rawSegment, rawIndex });
    });
    if (run.length) result.push(run);
  });
  return result.length ? result : [[]];
}

// Raw preparation remains available for live GPS. GPX imports opt into batch correction.
export function prepareTrack(
  segments,
  { filter = false, filterOptions = {}, timeWeights = false, timeWeightOptions = {} } = {},
) {
  const analysis = filter ? filterTrack(segments, filterOptions) : null;
  const geometry = analysis?.stats.excludedPoints
    ? qualitySegments(analysis.correctedSegments)
    : (analysis?.correctedSegments ?? segments);
  const points = analysis?.stats.excludedPoints
    ? indexTrack(geometry)
    : (analysis?.points ?? indexTrack(geometry));
  const timedPoints = analysis?.points ?? points;
  const completeTime =
    timedPoints.length > 1 && timedPoints.every((point) => Number.isFinite(point.time));
  const orderedTime =
    completeTime &&
    timedPoints.every((point, index) => !index || point.time > timedPoints[index - 1].time);
  const recordedMs = orderedTime ? timedPoints.at(-1).time - timedPoints[0].time : null;
  return {
    segments: geometry,
    points,
    stats: analysis ? { ...analysis.stats, segments: geometry.length } : trackStats(segments),
    ...(analysis
      ? {
          rawSegments: analysis.rawSegments,
          rawStats: analysis.rawStats,
          processing: {
            version: analysis.version,
            options: analysis.options,
            diagnostics: analysis.diagnostics,
          },
        }
      : {}),
    ...(timeWeights
      ? {
          timeWeights: prepareTimeWeights(segments, {
            indexedPoints: analysis?.points ?? indexTrack(segments),
            diagnostics: analysis?.diagnostics,
            filterOptions: analysis?.options,
            ...timeWeightOptions,
          }),
        }
      : {}),
    recordedMs,
    timeStatus: orderedTime ? 'complete' : completeTime ? 'unordered' : 'missing',
  };
}
export function elapsedLabel(ms) {
  const seconds = Math.max(0, Math.floor(ms / 1000));
  return [Math.floor(seconds / 3600), Math.floor(seconds / 60) % 60, seconds % 60]
    .map((value) => String(value).padStart(2, '0'))
    .join(':');
}

export function sampled(segment, limit = 1600) {
  const step = Math.max(1, Math.ceil(segment.length / limit));
  return segment.filter((_, index) => index % step === 0 || index === segment.length - 1);
}
