import { parseGpx } from './parser.js';
import { recordedTrack } from '../recording/model.js';
import {
  hydrateTimeOrigin,
  timeOriginFor,
  userConfirmedTimeSource,
} from '../../domain/time-origin.js';

// Persist original content and local source settings only; never persist computed trust or geometry.
export function storedGpxRecord(file, timeSource) {
  return {
    id: file.id,
    raw: file.raw,
    fileName: file.fileName,
    addedAt: file.addedAt,
    ...(file.name ? { name: file.name } : {}),
    ...(file.kind ? { kind: file.kind } : {}),
    ...(file.recording ? { recording: file.recording } : {}),
    ...(timeSource ? { timeSource } : {}),
  };
}
export function createTimeSourceController({
  state,
  repository,
  gpsPending,
  render,
  feedback,
  selectFile,
}) {
  let disposed = false;
  const locked = () => disposed || state.timeSourceBusy || gpsPending() || state.starting;
  async function change(id, makeRecord, select = false) {
    if (locked()) {
      feedback.toast('請先結束錄製或等待來源設定保存完成。');
      return false;
    }
    const file = state.library.find((item) => item.id === id);
    if (!file) return false;
    state.timeSourceBusy = true;
    state.timeSourceError = '';
    render();
    try {
      const record = await makeRecord(file);
      if (disposed || !state.library.includes(file)) return false;
      if (!repository.available)
        throw new Error('無法保存來源設定，維持原有時間來源；請確認本機儲存可用。');
      const prepared =
        record.kind === 'recording' ? recordedTrack(record) : parseGpx(record.raw, record.fileName);
      const entry = await hydrateTimeOrigin({ ...record, ...prepared, saved: true });
      if (disposed || !state.library.includes(file)) return false;
      if (gpsPending() || state.starting) throw new Error('錄製期間不能變更時間來源。');
      if (record.timeSource && timeOriginFor(entry).assurance === 'unconfirmed')
        throw new Error('無法核對 GPX 內容與來源設定，維持原有來源。');
      try {
        await repository.putFile(record);
      } catch {
        throw new Error('來源設定保存失敗，維持原有來源；請稍後重試。');
      }
      if (disposed) return false;
      const index = state.library.findIndex((item) => item.id === record.id);
      if (index < 0) state.library.push(entry);
      else state.library[index] = entry;
      state.correctionPage = null;
      if (select) selectFile(record.id);
      return true;
    } catch (error) {
      if (!disposed) state.timeSourceError = error?.message || '來源設定保存失敗，尚未套用。';
      return false;
    } finally {
      state.timeSourceBusy = false;
      if (!disposed) render();
    }
  }
  return {
    confirmTimeSource: (id, statements) =>
      change(id, async (file) => {
        if (state.routeDirections?.[id] === 'reverse')
          throw new Error('請在 GPX 原向確認時間來源。');
        if (timeOriginFor(file).assurance === 'ridgewise-local')
          throw new Error('此軌跡已有本機錄製來源。');
        return storedGpxRecord(file, await userConfirmedTimeSource(file, statements));
      }),
    revokeTimeSource: (id) =>
      change(id, async (file) => {
        if (
          state.routeDirections?.[id] === 'reverse' ||
          file.direction === 'reverse' ||
          timeOriginFor(file).assurance !== 'user-confirmed'
        )
          throw new Error('請在原向路線撤回使用者確認。');
        return storedGpxRecord(file, null);
      }),
    useRecordingAsRoute: (id) =>
      change(
        id,
        async (file) => {
          if (file.kind !== 'recording') throw new Error('只能從已保存的紀錄建立參考路線。');
          const existing = state.library.find(
            (item) => item.kind !== 'recording' && item.raw === file.raw,
          );
          const routeId = existing?.id ?? crypto.randomUUID();
          const local = timeOriginFor(file).assurance === 'ridgewise-local';
          return {
            id: routeId,
            raw: file.raw,
            fileName: file.fileName,
            name: file.name,
            addedAt: existing?.addedAt ?? Date.now(),
            ...(local
              ? { timeSource: { ...file.timeSource, recordId: routeId } }
              : existing?.timeSource
                ? { timeSource: existing.timeSource }
                : {}),
          };
        },
        true,
      ),
    dispose() {
      disposed = true;
    },
  };
}
