import { createItineraryActions } from '../features/itinerary/actions.js';
import { createLibraryActions } from '../features/gpx/actions.js';
import { createMapActions } from '../features/map/actions.js';
import { createRecordingActions } from '../features/recording/actions.js';
// Shared navigation and feature action registration only.
export function createActions(context) {
  const { document, navigate, feedback } = context;
  const { toast } = feedback;
  return {
    'personal-factor-refresh': () => context.personalFactorView.refresh(),
    'route-direction': (target) => context.direction.set(target.dataset.direction),
    ...createItineraryActions(context),
    ...createLibraryActions(context),
    ...createMapActions(context),
    ...createRecordingActions(context),
    upload: () => document.querySelector('#gpx-input').click(),
    'choose-route': () => navigate('routes'),
    'view-record': () => navigate('record'),
    'dialog-close': feedback.close,
    help: feedback.showHelp,
    onError: () => toast('操作未完成，請稍後重試。'),
  };
}
