import { recordingFix } from '../recording/analysis.js';
import { routeMatcherFor } from './matching.js';
// Use the current occurrence of a leg, rather than the earlier outbound visit.
export function remainingRouteProgress(file, data, gps, now = Date.now()) {
  const next = data?.next;
  const fix = gps ? recordingFix(gps) : null;
  if (
    !file ||
    (file.rerouted && gps?.status !== 'tracking') ||
    !data?.active ||
    !data.compatible ||
    data.finished ||
    !next ||
    next.gap ||
    !fix ||
    !Number.isFinite(fix.lat) ||
    Math.abs(fix.lat) > 90 ||
    !Number.isFinite(fix.lon) ||
    Math.abs(fix.lon) > 180 ||
    !Number.isFinite(gps.accuracy) ||
    gps.accuracy < 0 ||
    gps.accuracy > 50 ||
    !Number.isFinite(fix.time) ||
    !Number.isFinite(now) ||
    now - fix.time > 60000 ||
    fix.time > now + 5000
  )
    return null;
  const previous = data.rows[Math.max(0, data.nextIndex - 1)];
  if (
    !previous ||
    (!file.rerouted && previous.segmentIndex !== next.segmentIndex) ||
    !Number.isFinite(previous.routeProgressM) ||
    !Number.isFinite(next.routeProgressM)
  )
    return null;
  const found = routeMatcherFor(file).match(
    [{ ...fix, stationId: 'live-progress', coordinateStatus: 'located' }],
    { maxOffsetM: 100, mergeWithinM: 25 },
  );
  const candidates =
    found.matches[0]?.routePositions.filter(
      (point) =>
        point.segmentIndex === next.segmentIndex &&
        point.routeProgressM >= previous.routeProgressM - 25 &&
        point.routeProgressM <= next.routeProgressM + 25,
    ) ?? [];
  const accepted = gps.itinerary?.routePosition;
  if (
    file.rerouted &&
    accepted?.revisionId === file.id &&
    accepted.time === fix.time &&
    accepted.segmentIndex === next.segmentIndex &&
    accepted.routeProgressM >= previous.routeProgressM - 25 &&
    accepted.routeProgressM <= next.routeProgressM + 25
  ) {
    return {
      segmentIndex: next.segmentIndex,
      fromM: Math.min(
        next.routeProgressM,
        Math.max(previous.routeProgressM, accepted.routeProgressM),
      ),
      toM: next.routeProgressM,
    };
  }
  candidates.sort((a, b) => a.offsetM - b.offsetM);
  if (!candidates.length) return null;
  if (file.rerouted && candidates.length !== 1) return null;
  return {
    segmentIndex: next.segmentIndex,
    fromM: Math.min(
      next.routeProgressM,
      Math.max(previous.routeProgressM, candidates[0].routeProgressM),
    ),
    toM: next.routeProgressM,
  };
}
