import { esc } from '../../ui/html.js';
import { elevationSvg } from '../elevation/view.js';

const hhmm = (time) =>
  new Date(time).toLocaleTimeString('zh-TW', {
    timeZone: 'Asia/Taipei',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  });
export function createHeightProfileView({ daylight, document = globalThis.document }) {
  let displayedFile = null,
    lastMinute = null;
  function body(file) {
    const profile = daylight.snapshot(file);
    const notice = !profile.county
      ? '目前 GPX 附近尚無可用的政府日照參考。'
      : !profile.hasTiming
        ? profile.mode === 'recorded'
          ? '尚無可對應時間的軌跡區段，暫不判定日夜。'
          : '尚無有效站間 ETA，灰色路段暫不判定日夜。'
        : profile.hasUnknownDays
          ? '部分日期尚未取得官方時刻，對應路段保留灰色。'
          : profile.mode === 'recorded'
            ? '依自己紀錄的實際時刻顯示日夜。'
            : profile.mode === 'forecast'
              ? '依本次出發與到站 ETA 動態更新。'
              : '以現在出發預覽；開始紀錄後依實際出發與到站 ETA 更新。';
    return `<div class="daylight-reference" data-county="${esc(profile.county)}"><span>日夜自動參考</span><strong>${profile.nearby ? esc(profile.nearby.name) : '附近參考尚未提供'}</strong>${profile.nearby ? `<small>路線中段附近 ${profile.nearby.distanceKm.toFixed(1)} km · 採${esc(profile.countyName)}官方時刻</small>` : ''}</div>${elevationSvg(file, profile)}<div class="daylight-legend" aria-label="日夜塗色圖例"><span><i class="phase-day"></i>白天（日出至日落）</span><span><i class="phase-night"></i>夜間</span>${profile.hasUnknownSegments || profile.hasUnknownDays || !profile.hasTiming || !profile.county ? '<span><i class="phase-unknown"></i>時間待補</span>' : ''}</div><p class="daylight-notice" role="status">${notice}${profile.hasTiming && profile.hasUnknownSegments ? ' 灰色路段尚無可確認的經過時刻。' : ''}</p>${
      profile.county
        ? `<div class="solar-days">${profile.days
            .slice(0, 3)
            .map(
              (day) =>
                `<div><strong>${esc(day.date)}</strong><span>日出 ${day.sun ? hhmm(day.sun.sunrise) : '待補'}</span><span>日落 ${day.sun ? hhmm(day.sun.sunset) : '待補'}</span></div>`,
            )
            .join('')}${
            profile.days.length > 3
              ? `<details class="solar-extra" id="solar-extra"><summary>更多日期</summary>${profile.days
                  .slice(3)
                  .map(
                    (day) =>
                      `<div><strong>${esc(day.date)}</strong><span>日出 ${day.sun ? hhmm(day.sun.sunrise) : '待補'}</span><span>日落 ${day.sun ? hhmm(day.sun.sunset) : '待補'}</span></div>`,
                  )
                  .join('')}</details>`
              : ''
          }</div>`
        : ''
    }<p class="daylight-method">${profile.mode === 'recorded' ? '軌跡點間依實際時間內插。' : '站間時刻沿已有 GPX 片段按距離比例內插，中斷處不連線。'}縣市時刻未含山形遮蔽與天候影響。</p><a class="daylight-source" href="${profile.reference.sourcePage}" target="_blank" rel="noopener noreferrer">資料來源：交通部中央氣象署</a>`;
  }
  function panel(file) {
    displayedFile = file;
    lastMinute = Math.floor(Date.now() / 60000);
    return `<div id="height-profile-body">${body(file)}</div>`;
  }
  function update() {
    const element = document.getElementById('height-profile-body');
    const minute = Math.floor(Date.now() / 60000);
    if (!element || !displayedFile || minute === lastMinute) return;
    lastMinute = minute;
    const open = element.querySelector?.('.solar-extra')?.open;
    element.innerHTML = body(displayedFile);
    if (open) {
      const extra = element.querySelector?.('.solar-extra');
      if (extra) extra.open = true;
    }
  }
  return { panel, update };
}
