import { button, esc } from '../../ui/html.js';
import { correctionReport, DIAGNOSTIC_PAGE_SIZE } from './diagnostics.js';

const value = (number, unit) =>
  number === null
    ? '未知'
    : `${unit === 'km' ? number.toFixed(2) : Math.round(number).toLocaleString('zh-TW')} ${unit}`;
const percent = (number) => {
  if (number === null) return '未知';
  const rounded = Number(number.toFixed(1));
  return `${rounded > 0 ? '+' : ''}${rounded.toFixed(1)}%`;
};
const position = (point) =>
  point?.position ? `${point.position.lat.toFixed(6)}, ${point.position.lon.toFixed(6)}` : '未知';
const time = (point) =>
  point?.time == null
    ? '未知'
    : new Date(point.time).toLocaleString('zh-TW', {
        timeZone: 'Asia/Taipei',
        hourCycle: 'h23',
      }) + '（台灣時間）';

export function createCorrectionView({ state = {} } = {}) {
  const reports = new WeakMap();
  return function correctionPanel(file) {
    if (!reports.has(file)) reports.set(file, correctionReport(file));
    const report = reports.get(file);
    const pages = Math.max(1, Math.ceil(report.entries.length / DIAGNOSTIC_PAGE_SIZE));
    const requested = state.correctionPage?.file === file ? state.correctionPage.page : 0;
    const page = Number.isInteger(requested) ? Math.max(0, Math.min(pages - 1, requested)) : 0;
    const offset = page * DIAGNOSTIC_PAGE_SIZE;
    const entries = report.entries.slice(offset, offset + DIAGNOSTIC_PAGE_SIZE);
    const qualityWarnings = report.reasons.filter((reason) =>
      [
        'unconfirmed-position-jump',
        'suspect-spike-without-time',
        'low-horizontal-accuracy',
        'low-altitude-accuracy',
      ].includes(reason.code),
    );
    return `<section class="panel panel-body stack correction-panel" aria-labelledby="correction-heading">
      <div><h2 id="correction-heading">GPX 校正診斷</h2><p class="small muted">原始 GPX 保持不變。以下依目前行走方向比較，校正結果供路線分析使用。</p></div>
      ${qualityWarnings.length ? `<p class="soft-notice correction-quality-warning" role="status">GPX 品質提醒：${qualityWarnings.map((reason) => `${esc(reason.label)} ${reason.count.toLocaleString('zh-TW')} 點`).join('、')}。請展開診斷核對位置與限制。</p>` : ''}
      ${!report.processed ? '<p class="soft-notice">此軌跡尚無校正資料，無法比較校正結果。</p>' : ''}
      <details id="correction-overview"><summary>統計比較與校正明細</summary><div class="stack">
      <table class="correction-comparison"><caption class="small">原始與校正後的統計比較</caption><thead><tr><th scope="col">項目</th><th scope="col">原始</th><th scope="col">校正後</th><th scope="col">差異</th></tr></thead><tbody>${report.metrics.map((row) => `<tr data-metric="${row.key}"><th scope="row">${row.label}</th><td data-value="original">${value(row.original, row.unit)}</td><td data-value="corrected">${value(row.corrected, row.unit)}</td><td data-value="percent">${percent(row.percent)}</td></tr>`).join('')}</tbody></table>
      <p class="small muted">差異＝（校正後 − 原始）÷ 原始 × 100%，以未取整數值計算。原始為 0 或資料不足時，百分比顯示未知。</p>
      <details id="correction-details"><summary>處理原因與位置 · ${report.knownReasons ? `${report.entries.length.toLocaleString('zh-TW')} 個標記點` : '未知'}</summary>
      <p class="small muted">以下為濾波判定，並非現地量測。清單依目前行走方向編號，同時附上原始 GPX 點位；同一點可有多個原因。缺乏可靠時間的疑似跳點會保留原位置。</p>
      ${report.reasons.length ? `<ul class="correction-reasons">${report.reasons.map((reason) => `<li>${esc(reason.label)} <strong>${reason.count.toLocaleString('zh-TW')} 點</strong></li>`).join('')}</ul>` : `<p class="correction-empty">${report.knownReasons ? '未標記需要處理或提醒的點。' : '未提供處理原因，顯示未知。'}</p>`}
      <ol class="correction-points" start="${offset + 1}">${entries
        .map(
          (
            entry,
          ) => `<li data-segment="${entry.segment ?? ''}" data-point="${entry.sourceIndex ?? ''}"><div class="correction-point-heading"><strong>${entry.segment === null ? '位置索引未知' : `第 ${entry.segment + 1} 段 · 第 ${entry.sourceIndex + 1} 點`}</strong><span>${entry.reasons.map((reason) => esc(reason.label)).join('、') || '處理原因未知'}</span></div>
      <p class="small muted">原始 GPX 點位：${entry.gpxSegment === null ? '未知' : `第 ${entry.gpxSegment + 1} 段 · 第 ${entry.gpxIndex + 1} 點`}</p>
      <p class="small">${entry.reasons.map((reason) => esc(reason.description)).join(' ')}</p>
      <dl class="correction-locations"><div><dt>原始位置（緯度、經度）</dt><dd>${position(entry.original)}</dd></div><div><dt>校正後位置（緯度、經度）</dt><dd>${entry.excluded ? '不納入分析' : position(entry.corrected)}</dd></div><div><dt>海拔：原始 → 校正後</dt><dd>${value(entry.original?.elevation ?? null, 'm')} → ${value(entry.corrected?.elevation ?? null, 'm')}</dd></div><div><dt>原始時間</dt><dd>${esc(time(entry.original))}</dd></div></dl></li>`,
        )
        .join('')}</ol>
      ${pages > 1 ? `<nav class="correction-pagination" aria-label="診斷分頁">${button('上一頁', 'correction-page', 'ghost', '', `data-page="${page - 1}" ${page === 0 ? 'disabled' : ''}`)}<span role="status">第 ${page + 1} / ${pages} 頁 · ${offset + 1}–${offset + entries.length} 點</span>${button('下一頁', 'correction-page', 'ghost', '', `data-page="${page + 1}" ${page === pages - 1 ? 'disabled' : ''}`)}</nav>` : ''}
      </details>
      ${typeof file.raw === 'string' && file.id ? button('下載原始 GPX', 'file-download', 'ghost', 'download', `data-id="${esc(file.id)}"`) : ''}
      </div></details>
    </section>`;
  };
}
