import { daylightReference } from '../../data/daylight-reference.js';
import { daylightLocations } from '../../data/daylight-locations.js';
import { buildDaylightProfile } from './model.js';
import { nearbyDaylightReference } from './location.js';

// Derive the reference from coordinates every time a new GPX geometry is used.
// Legacy manual preferences and recording.daylightCounty are deliberately ignored.
export function createDaylightController({
  itinerary,
  reference = daylightReference,
  locations = daylightLocations,
}) {
  const nearbyCache = new WeakMap();
  function snapshot(file, now = Date.now()) {
    if (!nearbyCache.has(file)) nearbyCache.set(file, nearbyDaylightReference(file, locations));
    const nearby = nearbyCache.get(file);
    const county = nearby?.county ?? '';
    return {
      ...buildDaylightProfile(reference, county, file, itinerary.snapshot(), now),
      reference,
      nearby,
      locationSource: locations.source,
      countyName: reference.counties.find((entry) => entry.id === county)?.name ?? null,
    };
  }
  return { snapshot, dispose() {} };
}
