import { rawGpxDigest, hydrateTimeOrigin, timeOriginFor } from '../../domain/time-origin.js';
import { TRACK_FILTER_VERSION, TRACK_FILTER_DEFAULTS } from '../../domain/track-filter.js';
import { parseGpx } from '../gpx/parser.js';
import { routeForDirection } from '../routes/direction.js';
import {
  evaluatePersonalHistory,
  PERSONAL_HISTORY_VERSION,
  PERSONAL_HISTORY_RULES,
  unavailableStatistics,
} from './model.js';

const localCapture = (file) => {
  const recording = file.recording,
    capture = recording?.captureSource;
  return (
    file.kind === 'recording' &&
    typeof file.id === 'string' &&
    file.id.length > 0 &&
    capture?.version === 1 &&
    capture.recordingId === file.id &&
    capture.startedAt === recording.startedAt &&
    ['web-geolocation', 'ios-core-location'].includes(capture.provider) &&
    capture.sourceChanged !== true &&
    capture.simulated !== true &&
    recording.historyObservations?.simulated !== true
  );
};
const hash = (value) => rawGpxDigest(JSON.stringify(value));
const copy = (value) => structuredClone(value);

// The candidate is embedded in its saved file: finalization, retries, replacement and deletion
// use the same IndexedDB transaction/primary key as the original GPX. No automatic draft/import backfill.
export function createPersonalHistoryController({
  repository,
  recordingRoute,
  referenceFor,
  onChange = () => {},
}) {
  async function prepare(file, entry) {
    if (!localCapture(file)) return null;
    const recording = copy(file.recording),
      reference = referenceFor(recordingRoute()),
      result = evaluatePersonalHistory(entry, recording, reference, recording.historyObservations);
    let binding = null,
      rawSha256 = null,
      recordingSha256 = null,
      sourceSha256 = null;
    try {
      [binding, rawSha256, recordingSha256, sourceSha256] = await Promise.all([
        reference?.binding ?? null,
        rawGpxDigest(file.raw),
        hash(recording),
        hash(file.timeSource ?? null),
      ]);
      if (timeOriginFor(entry).assurance !== 'ridgewise-local')
        result.exclusionReasons.push('local-time-source-unavailable');
      if (recording.sourceRouteId && !binding)
        result.exclusionReasons.push('reference-binding-unavailable');
    } catch {
      result.exclusionReasons.push('hash-unavailable');
    }
    if (result.exclusionReasons.length) {
      result.status = 'unavailable';
      result.statistics = unavailableStatistics();
    }
    const stoppedAt = recording.historyObservations?.stoppedAt ?? recording.endedAt;
    const body = {
      version: PERSONAL_HISTORY_VERSION,
      recordingId: file.id,
      explicitlySavedAt: file.addedAt,
      rawSha256,
      recordingSha256,
      sourceSha256,
      route: {
        id: recording.sourceRouteId ?? null,
        direction: recording.sourceRouteDirection,
        binding,
        referenceVersion: reference?.referenceVersion ?? null,
      },
      recordingRange: {
        startedAt: recording.startedAt,
        endedAt: recording.endedAt,
        stoppedAt,
        sessionWallSeconds:
          Number.isFinite(stoppedAt) &&
          Number.isFinite(recording.startedAt) &&
          stoppedAt >= recording.startedAt
            ? (stoppedAt - recording.startedAt) / 1000
            : null,
      },
      ...result,
      source: {
        kind: 'ridgewise-local-explicit-save',
        provider: recording.captureSource.provider,
        verification: 'unverified',
        coverage: 'actual-gps-endpoints-only',
        distributions: result.distributions,
        limitations: [
          'device-local-provenance-not-independently-verified',
          'location-provider-may-be-simulated-without-reporting',
          'unobserved-start-and-end-not-extrapolated',
          ...(result.quality.acceptedPauseBoundaries
            ? ['manual-pause-boundaries-compatible-not-continuous-gps']
            : []),
        ],
      },
    };
    delete body.distributions;
    try {
      return { ...body, sha256: await hash(body) };
    } catch {
      return { ...body, sha256: null };
    }
  }
  function row(file, saved, invalidReasons = []) {
    const reasons = [
      ...new Set([
        ...(Array.isArray(saved.exclusionReasons) ? saved.exclusionReasons : []),
        ...invalidReasons,
      ]),
    ];
    return copy({
      version: PERSONAL_HISTORY_VERSION,
      recordingId: file.id,
      rawSha256: saved.rawSha256 ?? null,
      explicitlySavedAt: saved.explicitlySavedAt ?? null,
      route: saved.route ?? null,
      recordingRange: saved.recordingRange ?? null,
      status: reasons.length ? 'unavailable' : saved.status,
      statistics: reasons.length ? unavailableStatistics() : saved.statistics,
      exclusionReasons: reasons,
      quality: saved.quality ?? null,
      source: { ...saved.source, verification: 'unverified' },
    });
  }
  async function list({ routeId, direction, status } = {}) {
    if (direction !== undefined && !['forward', 'reverse'].includes(direction))
      throw new TypeError('Unknown history direction');
    if (status !== undefined && !['available', 'unavailable'].includes(status))
      throw new TypeError('Unknown history status');
    const files = await repository.listFiles(),
      byId = new Map(files.map((file) => [file.id, file])),
      references = new Map(),
      results = [],
      seen = new Set();
    async function referenceForSaved(saved) {
      const route = byId.get(saved.route?.id);
      if (!route) return null;
      const key = JSON.stringify([route.id, saved.route.direction]);
      if (!references.has(key)) {
        references.set(
          key,
          (async () => {
            const prepared = await hydrateTimeOrigin({
              ...route,
              ...parseGpx(route.raw, route.fileName),
            });
            return referenceFor(routeForDirection(prepared, saved.route.direction));
          })(),
        );
      }
      return references.get(key);
    }
    for (const file of files
      .filter((file) => file.personalHistory && localCapture(file))
      .sort((a, b) => a.addedAt - b.addedAt || a.id.localeCompare(b.id))) {
      const saved = file.personalHistory,
        reasons = [];
      if (
        !['available', 'unavailable'].includes(saved.status) ||
        !Array.isArray(saved.exclusionReasons) ||
        !saved.statistics ||
        typeof saved.route?.direction !== 'string' ||
        !saved.source
      )
        reasons.push('history-schema-invalid');
      if (
        saved.version !== PERSONAL_HISTORY_VERSION ||
        saved.recordingId !== file.id ||
        saved.quality?.processingVersion !== TRACK_FILTER_VERSION
      )
        reasons.push('history-version-or-session-mismatch');
      if (
        JSON.stringify(saved.quality?.rules) !== JSON.stringify(PERSONAL_HISTORY_RULES) ||
        JSON.stringify(saved.quality?.filterOptions) !== JSON.stringify(TRACK_FILTER_DEFAULTS)
      )
        reasons.push('history-quality-rules-changed');
      try {
        const { sha256, ...body } = saved;
        if (!sha256 || sha256 !== (await hash(body))) reasons.push('history-integrity-mismatch');
        if (saved.rawSha256 !== (await rawGpxDigest(file.raw)))
          reasons.push('recording-content-changed');
        if (saved.recordingSha256 !== (await hash(file.recording)))
          reasons.push('recording-metadata-changed');
        if (
          saved.sourceSha256 !== (await hash(file.timeSource ?? null)) ||
          file.timeSource?.kind !== 'ridgewise-local' ||
          file.timeSource.recordingId !== file.id ||
          file.timeSource.recordId !== file.id ||
          file.timeSource.rawSha256 !== saved.rawSha256 ||
          file.timeSource.provider !== file.recording.captureSource.provider ||
          file.timeSource.startedAt !== file.recording.startedAt ||
          file.timeSource.endedAt !== file.recording.endedAt
        )
          reasons.push('local-time-source-changed');
        if (
          saved.route?.id !== (file.recording.sourceRouteId ?? null) ||
          saved.route?.direction !== file.recording.sourceRouteDirection
        )
          reasons.push('recording-route-changed');
        if (saved.route?.id) {
          const reference = await referenceForSaved(saved);
          if (!reference) reasons.push('reference-route-deleted');
          else if (
            JSON.stringify(saved.route.binding) !== JSON.stringify(await reference.binding) ||
            saved.route.referenceVersion !== reference.referenceVersion
          )
            reasons.push('reference-content-or-model-changed');
        }
      } catch {
        reasons.push('history-validation-unavailable');
      }
      const duplicateKey = saved.rawSha256;
      if (duplicateKey && seen.has(duplicateKey)) reasons.push('duplicate-recording-content');
      if (duplicateKey && !reasons.length) seen.add(duplicateKey);
      const result = row(file, saved, reasons);
      if (
        (routeId === undefined || result.route?.id === routeId) &&
        (direction === undefined || result.route?.direction === direction) &&
        (status === undefined || result.status === status)
      )
        results.push(result);
    }
    return results;
  }
  return {
    prepare,
    api: {
      list,
      get: async (recordingId) =>
        (await list()).find((item) => item.recordingId === recordingId) ?? null,
      remove: async (recordingId) => {
        await repository.removePersonalHistory(recordingId);
        await onChange();
      },
    },
  };
}
