import { recordingSegments } from '../features/recording/analysis.js';
import { shellHeader, bottomNavigation } from './navigation-view.js';
import { itineraryMarkers } from '../features/itinerary/markers.js';
import { icon, button } from './html.js';
import { titles } from '../core/navigation.js';
export function createRenderer({
  state,
  document,
  terrainMap,
  current,
  gpsPending,
  recordingRoute,
  views,
  recordingView,
  itinerary,
  personalFactorView,
}) {
  const { libraryView, routesView, planView, recordView } = views;
  let lastRecordingStatus, lastDetailsScope;
  // UI-only disclosure preferences, scoped to the page and route/recording.
  const detailsStates = new Map();
  function render() {
    const focused = document.activeElement,
      focusId = focused?.id,
      focusAction = focused?.dataset?.action;
    const selection =
      focused?.tagName === 'INPUT' && focused.type === 'text'
        ? [focused.selectionStart, focused.selectionEnd]
        : null;
    const focusedMapControl = focused?.closest?.('.terrain-map-canvas') ? focused : null;
    if (lastDetailsScope) {
      const saved = detailsStates.get(lastDetailsScope) ?? new Map();
      for (const element of document.querySelectorAll?.('details[id]') ?? [])
        saved.set(element.id, element.open);
      detailsStates.set(lastDetailsScope, saved);
    }
    const detailsScope =
      state.view +
      ':' +
      (state.view === 'plan'
        ? (current()?.id ?? '')
        : state.view === 'record'
          ? (state.gps.id ?? current()?.id ?? '')
          : '');
    terrainMap.beforeRender();
    const [title, subtitle] = titles[state.view];
    document.title = `${title} · Ridgewise`;
    document.querySelector('#app').innerHTML = `
    <div class="workspace ${state.view === 'record' && gpsPending() ? 'live-workspace' : ''}">${shellHeader()}
    <main id="main" tabindex="-1">${state.view === 'record' && gpsPending() ? '' : `<div class="page-heading"><div>${state.view === 'plan' ? '<button class="back-link" data-view="routes">← 我的路線</button>' : ''}<h1>${title}</h1><p>${subtitle}</p></div><div class="page-actions">${state.view === 'routes' ? button(state.importing ? '匯入中…' : '匯入 GPX', 'upload', 'primary', 'plus', state.loading || state.importing ? 'disabled' : '') : ''}</div></div>`}
      ${gpsPending() && state.view !== 'record' ? `<div class="soft-notice ongoing-notice">${icon('activity')}<span>${['review', 'stopping', 'finishing', 'finished'].includes(state.gps.status) ? '紀錄已停止，請選擇是否保存。' : 'GPS 紀錄進行中，選用路線暫時鎖定。'}</span>${button('查看', 'view-record', 'ghost')}</div>` : ''}
      ${state.loading ? '<section class="panel empty-state" role="status"><h2>正在讀取你的 GPX…</h2></section>' : { library: libraryView, routes: routesView, plan: planView, record: recordView }[state.view]()}
      </main>${bottomNavigation(state.view, current())}</div>`;
    const savedDetails = detailsStates.get(detailsScope);
    for (const element of document.querySelectorAll?.('details[id]') ?? []) {
      if (savedDetails?.has(element.id)) element.open = savedDetails.get(element.id);
    }
    lastDetailsScope = detailsScope;
    terrainMap.mount(
      document.getElementById('track-map'),
      state.view === 'record' && gpsPending() ? recordingRoute() : current(),
      state.view === 'record' ? recordingSegments(state.gps) : [],
      state.mapMode,
      itineraryMarkers(itinerary?.snapshot()),
    );
    if (focusedMapControl?.isConnected) focusedMapControl.focus({ preventScroll: true });
    else if (focusId && focusId !== 'main') {
      const replacement = document.getElementById(focusId);
      replacement?.focus({ preventScroll: true });
      if (selection) replacement?.setSelectionRange?.(...selection);
    } else if (focusAction)
      document.querySelector(`#app [data-action="${focusAction}"]`)?.focus({ preventScroll: true });
    if (state.view === 'record' && gpsPending()) recordingView.updateNumbers();
    if (
      state.view === 'record' &&
      ['review', 'idle'].includes(state.gps.status) &&
      lastRecordingStatus !== state.gps.status
    )
      document.defaultView?.scrollTo({ top: 0, behavior: 'instant' });
    lastRecordingStatus = state.gps.status;
    void personalFactorView?.refresh();
  }

  return { render };
}
