import { connectRerouteArcs, routePointAt } from './rerouting.js';

const edgeId = (edge) =>
  JSON.stringify([
    edge.source.id,
    edge.source.direction ?? 'forward',
    edge.segment,
    edge.from.index,
    edge.to.index,
  ]);
// Intern the actual full edge geometry, so equal station/time chains on
// physically different trails remain choices. Rounding only removes sub-cm
// floating point noise; it never creates a join. Use the uncut edge for stable
// identity while the GPS origin moves within that edge.
function createPathKey(network) {
  const shapes = new Map(),
    tokens = new WeakMap();
  const token = (edge) => {
    let rows = tokens.get(edge.source);
    if (!rows) {
      rows = new Map();
      tokens.set(edge.source, rows);
    }
    const rowKey = JSON.stringify([edge.segment, edge.from.index, edge.to.index]);
    if (!rows.has(rowKey)) {
      const fromM = edge.from.routeProgressM,
        toM = edge.to.routeProgressM;
      const points = [
        routePointAt(edge.source, edge.segment, fromM),
        ...edge.source.points.filter(
          (p) =>
            p.segment === edge.segment && p.km * 1000 > fromM + 1e-6 && p.km * 1000 < toM - 1e-6,
        ),
        routePointAt(edge.source, edge.segment, toM),
      ];
      const shape = JSON.stringify(
        points.map(
          (p) =>
            p && [
              Number(p.lat.toFixed(7)),
              Number(p.lon.toFixed(7)),
              Number.isFinite(p.elevation) ? Number(p.elevation.toFixed(3)) : null,
            ],
        ),
      );
      if (!shapes.has(shape)) shapes.set(shape, shapes.size);
      rows.set(rowKey, shapes.get(shape));
    }
    return rows.get(rowKey);
  };
  // Initialize in fixed network order, independent of destination search order.
  network.edges.forEach(token);
  return (arcs) =>
    JSON.stringify(
      arcs.map((edge) => [
        edge.toKey,
        edge.to.incoming.flatMap((part) => part.sourceIds ?? []).sort(),
        token(edge),
      ]),
    );
}

/** Search only proven GPX joins. Neither station proximity nor a time-network
 * connection creates a geometry edge. Bounds fail closed, never guess a path. */
export function connectedPaths(
  network,
  start,
  goal,
  {
    exclude = new Set(),
    allow = () => true,
    limit = 3,
    maxStates = 4000,
    blockFrom = false,
    join = connectRerouteArcs,
    key = createPathKey(network),
  } = {},
) {
  if (!start || exclude.has(start.toKey) || !allow(start)) return [];
  const pending = [
    {
      arcs: [start],
      cost: start.endM - start.startM,
      visited: new Set([edgeId(start)]),
    },
  ];
  const best = new Map(),
    found = new Map();
  let states = 0;
  while (pending.length) {
    if (++states > maxStates)
      throw new Error('可行路徑過多，無法可靠自動判斷，請使用進階模式核對。');
    pending.sort((a, b) => a.cost - b.cost);
    const item = pending.shift(),
      previous = item.arcs.at(-1);
    const identity = JSON.stringify([edgeId(previous), previous.startM]),
      signature = key(item.arcs);
    const known = best.get(identity) ?? [];
    if (known.includes(signature) || known.length >= limit) continue;
    best.set(identity, [...known, signature]);
    if (previous.toKey === goal) {
      if (!found.has(signature)) found.set(signature, item.arcs);
      if (found.size >= limit) break;
      continue;
    }
    for (const next of network.edges) {
      if (
        next.fromKey !== previous.toKey ||
        item.visited.has(edgeId(next)) ||
        (blockFrom && next.toKey === start.fromKey) ||
        exclude.has(next.toKey) ||
        !allow(next)
      )
        continue;
      const joined = join(previous, next);
      if (!joined) continue;
      pending.push({
        arcs: [...item.arcs.slice(0, -1), joined.incoming, joined.outgoing],
        cost: item.cost + next.endM - next.startM,
        visited: new Set([...item.visited, edgeId(next)]),
      });
    }
  }
  return [...found.values()];
}

// Joins on uncut network edges are reusable across destination searches. An
// origin trimmed at the current GPS must always be checked against that cut.
export function createConnectedRouter(network) {
  const cache = new WeakMap(),
    key = createPathKey(network);
  function join(previous, next) {
    let targets = cache.get(previous);
    if (!targets) {
      targets = new WeakMap();
      cache.set(previous, targets);
    }
    if (!targets.has(next)) targets.set(next, connectRerouteArcs(previous, next));
    return targets.get(next);
  }
  const route = (start, goal, options = {}) =>
    connectedPaths(network, start, goal, { ...options, join, key });
  route.pathKey = key;
  return route;
}
