// Optional device-local cache. The original file remains the user's backup.
export function openGpxStore() {
  return new Promise((resolve, reject) => {
    if (!globalThis.indexedDB) {
      reject(new Error('此瀏覽器不提供本機儲存'));
      return;
    }
    let blocked = false;
    const request = indexedDB.open('ridgewise-gpx-library', 2);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains('files'))
        request.result.createObjectStore('files', { keyPath: 'id' });
      if (!request.result.objectStoreNames.contains('drafts'))
        request.result.createObjectStore('drafts', { keyPath: 'slot' });
    };
    request.onerror = () => reject(request.error);
    request.onblocked = () => {
      blocked = true;
      reject(new Error('本機儲存被另一個分頁鎖定'));
    };
    request.onsuccess = () => {
      // A blocked upgrade may finish later, after its caller has already handled rejection.
      if (blocked) {
        request.result.close();
        return;
      }
      request.result.onversionchange = () => request.result.close();
      resolve(request.result);
    };
  });
}
export function gpxStoreAction(db, action, value) {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction('files', action === 'getAll' ? 'readonly' : 'readwrite');
    const request = transaction.objectStore('files')[action](value);
    transaction.oncomplete = () => resolve(request.result);
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error || new Error('儲存已中止'));
  });
}

export function draftAction(db, action, value) {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction('drafts', action === 'get' ? 'readonly' : 'readwrite');
    const request = transaction.objectStore('drafts')[action](value ?? 'active');
    transaction.oncomplete = () => resolve(request.result);
    transaction.onerror = transaction.onabort = () =>
      reject(transaction.error || new Error('紀錄儲存失敗'));
  });
}
export function finishRecordingStore(db, file) {
  return new Promise((resolve, reject) => {
    // GPX insertion and draft removal commit together, so reload cannot duplicate a finished trip.
    const transaction = db.transaction(['files', 'drafts'], 'readwrite');
    transaction.objectStore('files').put(file);
    transaction.objectStore('drafts').delete('active');
    transaction.oncomplete = () => resolve();
    transaction.onerror = transaction.onabort = () =>
      reject(transaction.error || new Error('GPX 儲存失敗'));
  });
}

export function removePersonalHistoryStore(db, id) {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction('files', 'readwrite'),
      store = transaction.objectStore('files'),
      request = store.get(id);
    request.onsuccess = () => {
      if (!request.result?.personalHistory) return;
      const file = request.result;
      delete file.personalHistory;
      store.put(file);
    };
    transaction.oncomplete = () => resolve();
    transaction.onerror = transaction.onabort = () =>
      reject(transaction.error || new Error('歷史資料移除失敗'));
  });
}
