import { routeForDirection } from '../features/routes/direction.js';
export function createIdleRecording() {
  return {
    status: 'idle',
    segments: [],
    startedAt: null,
    pauseAt: null,
    pausedMs: 0,
    endedAt: null,
    watchId: null,
    accuracy: null,
    error: '',
  };
}
export function createState() {
  const date = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Taipei',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());
  return {
    view: 'routes',
    library: [],
    selected: null,
    routeDirections: {},
    directionError: '',
    correctionPage: null,
    loading: true,
    importing: false,
    results: [],
    storageError: '',
    timeSourceBusy: false,
    timeSourceError: '',
    mapMode: 'standard',
    libraryFilter: 'all',
    recordingName: '',
    recordingBlocked: '',
    starting: false,
    date,
    itinerary: {
      catalog: null,
      database: null,
      factor: 1,
      status: 'empty',
      busy: false,
      saved: false,
      error: '',
    },
    gps: createIdleRecording(),
    directMap: {
      id: 'direct-recording',
      name: '我的軌跡',
      recording: true,
      segments: [],
      points: [],
      stats: { points: 0, withElevation: 0, km: 0 },
    },
  };
}
export const currentFile = (state) => {
  const source = state.library.find((file) => file.id === state.selected);
  const direction =
    gpsPending(state) && state.gps.sourceRouteId === source?.id
      ? state.gps.sourceRouteDirection
      : state.routeDirections?.[source?.id];
  return routeForDirection(source, direction);
};
export const recordingRoute = (state) =>
  state.gps.navigation?.active?.file ??
  routeForDirection(
    state.library.find((file) => file.id === state.gps.sourceRouteId),
    state.gps.sourceRouteDirection,
  ) ??
  state.directMap;
export const gpsActive = (state) =>
  [
    'requesting',
    'tracking',
    'paused',
    'error',
    'review',
    'stopping',
    'finishing',
    'discarding',
  ].includes(state.gps.status);
export const gpsPending = (state) => gpsActive(state) || state.gps.status === 'finished';
