import { button } from './html.js';
export function createFeedback({ document }) {
  let toastTimer;
  function toast(message) {
    const el = document.querySelector('#toast');
    el.textContent = message;
    el.classList.add('visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove('visible'), 4500);
  }
  function modal(title, body, actions = '') {
    const dialog = document.querySelector('#dialog');
    dialog.setAttribute('aria-labelledby', 'dialog-title');
    dialog.innerHTML = `<div class="dialog-content"><h2 id="dialog-title" tabindex="-1" autofocus>${title}</h2>${body}<div class="dialog-actions">${button('關閉', 'dialog-close')}${actions}</div></div>`;
    if (!dialog.open) dialog.showModal();
    dialog.scrollTop = 0;
  }
  function showHelp() {
    modal(
      '使用你的 GPX',
      '<p>1. 按「直接開始紀錄」，不需要匯入路線；也可先匯入 GPX，再選用路線開始紀錄。</p><p>2. 切換「標準」、「3D 地形」或「單純軌跡」；拖曳、滾輪、＋／－或雙指縮放，按「看全程」查看全部軌跡。</p><p>3. 新座標會自動保留為恢復草稿。按結束會先停止 GPS，再選擇「保存至我的 GPX」或「不保存，返回」。我的路線只顯示匯入檔；我的 GPX 只顯示親自紀錄且選擇保存的軌跡。已結束的草稿重新開啟後仍停在保存選擇，不會啟動 GPS。</p><p>4. 上河 1.0 有向時間與站點已內建。匯入 GPX 並設定自己的倍率後，開始紀錄即可查看各站 ETA；GPS 到站後切換下一站並重新推算。缺漏或多條可能路徑會標示待補。不需要上傳站點或時間資料。自由紀錄另保留手動基準工具。</p><p>標準 2D 地圖：先完成「下載離線地圖」，即可在已下載的台灣範圍內離線使用。同一裝置、同一瀏覽器保留底圖，出發前請試開；首次下載需要網路，未下載時使用線上底圖。</p><p>3D 地形需要網路，會向圖資服務請求瀏覽區域，目前不提供離線 3D 地圖。單純軌跡不請求底圖；GPX 不會上傳。</p><p>請由 HTTPS 或 localhost 開啟並允許定位。資料只保存在同一瀏覽器、同一網站位址；請下載備份，清除網站資料也會移除離線地圖。瀏覽器背景或鎖屏時可能中斷定位，突然關閉可能遺失尚未提交的最新資料。</p>',
    );
  }
  return {
    toast,
    modal,
    showHelp,
    close: () => document.querySelector('#dialog').close(),
    dispose: () => clearTimeout(toastTimer),
  };
}
