import { normalizeCoreLocation } from './ios.js';

const errorCodes = new Set([
  'permission-denied',
  'position-unavailable',
  'timeout',
  'foreground-required',
]);
const nativeError = (error) => ({
  code: errorCodes.has(error?.code) ? error.code : 'start-failed',
  source: 'ios',
});

/**
 * App-local RidgewiseLocation bridge. Listener registration precedes native start;
 * a caller-generated ID also makes stop safe while authorization/start is pending.
 * @returns {import('./ios.js').IOSLocationProvider}
 */
export function createIOSLocationProvider({ plugin, newWatchId = () => crypto.randomUUID() }) {
  return {
    sourceType: 'ios-core-location',
    watch(onFix, onError) {
      const watchId = newWatchId();
      let active = true,
        listener = null;
      const stopNative = () =>
        Promise.resolve()
          .then(() => plugin.stop({ watchId }))
          .catch(() => {});
      const removeListener = () => {
        const handle = listener;
        listener = null;
        if (handle)
          void Promise.resolve()
            .then(() => handle.remove())
            .catch(() => {});
      };
      const stop = () => {
        if (!active) return;
        active = false;
        removeListener();
        void stopNative();
      };
      const fail = (error) => {
        if (!active) return;
        stop();
        onError(nativeError(error));
      };
      void (async () => {
        try {
          listener = await plugin.addListener('location', (event) => {
            if (!active || event?.watchId !== watchId) return;
            if (event.error) {
              const error = nativeError(event.error);
              if (['timeout', 'position-unavailable'].includes(error.code)) onError(error);
              else fail(event.error);
              return;
            }
            const fix = normalizeCoreLocation(event.location);
            if (fix) onFix(fix);
          });
          if (!active) {
            removeListener();
            return;
          }
          await plugin.start({ watchId });
          if (!active) await stopNative();
        } catch (error) {
          fail(error);
        }
      })();
      return stop;
    },
  };
}
