export const navItems = [
  ['routes', 'compass', '我的路線'],
  ['record', 'activity', '紀錄'],
  ['library', 'folder', '我的 GPX'],
];
export const titles = {
  plan: ['路線資訊', '確認這次要走的 GPX 路線。'],
  routes: ['我的路線', '選好路線，照自己的節奏出發。'],
  record: ['登山紀錄', '直接記錄軌跡，或參照選定的 GPX 路線。'],
  library: ['我的 GPX', '每一段親自走過、選擇留下的山行。'],
};
export const validView = (value) => (Object.hasOwn(titles, value) ? value : 'routes');
export function createNavigation({ state, render, window }) {
  const location = window.location;
  function navigate(view) {
    const changed = state.view !== view;
    state.view = validView(view);
    if (location.hash !== `#${state.view}`) location.hash = state.view;
    render();
    if (changed) window.scrollTo({ top: 0, behavior: 'instant' });
  }
  return {
    navigate,
    readInitial: () => {
      state.view = validView(location.hash.slice(1));
    },
    onHashChange: () => {
      const view = location.hash.slice(1);
      if (view !== 'main' && view !== state.view) navigate(view);
    },
  };
}
