import { normalizeLocationFix } from '../location/provider.js';
import { LIVE_FACTOR_DEFAULTS } from '../itinerary/live-factor.js';
import { routeMatcherFor } from '../itinerary/matching.js';
import { shangheTimeAt } from '../itinerary/time-interpolation.js';
import { distanceM } from '../../../../packages/route-stations/index.js';
import { TRACK_FILTER_VERSION } from '../../domain/track-filter.js';

export const PERSONAL_HISTORY_VERSION = 1;
export const unavailableStatistics = () => ({
  effectiveDistanceM: null,
  matchedDistanceM: null,
  baselineSeconds: null,
  actualWallSeconds: null,
  observedFrom: null,
  observedTo: null,
});
const config = LIVE_FACTOR_DEFAULTS;
export const PERSONAL_HISTORY_RULES = Object.freeze({
  maxAccuracyM: config.maxAccuracyM,
  maxOffsetM: config.maxOffsetM,
  mergeWithinM: config.mergeWithinM,
  maxSpeedMps: config.maxSpeedMps,
  maxObservationGapMs: config.maxObservationGapMs,
  pauseFixMaxAgeMs: config.maxAgeMs,
  futureToleranceMs: config.futureToleranceMs,
  progressToleranceM: config.progressToleranceM,
  minBaselineSeconds: config.minBaselineSeconds,
  minProgressM: config.minProgressM,
});
const pauseBoundary = (a, b, observations) => {
  const pauses = (observations?.pauses ?? []).filter(
    (pause) =>
      pause?.beforeFixTime === a.time &&
      Number.isFinite(pause.pausedAt) &&
      Number.isFinite(pause.resumedAt) &&
      a.time <= pause.pausedAt &&
      pause.pausedAt <= pause.resumedAt &&
      pause.resumedAt <= b.time &&
      pause.pausedAt - a.time <= config.maxAgeMs &&
      b.time - pause.resumedAt <= config.maxAgeMs,
  );
  return pauses.length === 1 && distanceM(a, b) <= Math.max(5, a.accuracy + b.accuracy);
};

/** Bounded, observed-only history statistics. No multiplier, ETA, or invented GPS endpoints. */
export function evaluatePersonalHistory(entry, recording, reference, observations) {
  const segments = entry.rawSegments ?? [],
    rawPoints = segments.flat(),
    reasons = new Set(Array.isArray(observations?.interruptions) ? observations.interruptions : []),
    diagnostics = entry.processing?.diagnostics ?? [];
  const quality = {
    processingVersion: entry.processing?.version ?? null,
    rawPointCount: rawPoints.length,
    excludedPointCount: entry.stats?.excludedPoints ?? 0,
    diagnostics: [...new Set(diagnostics.flatMap((item) => item.reasons))],
    manualPauseCount: Array.isArray(observations?.pauses) ? observations.pauses.length : 0,
    acceptedPauseBoundaries: 0,
    filterOptions: entry.processing?.options ?? null,
    rules: { ...PERSONAL_HISTORY_RULES },
    verification: 'unverified',
  };
  const finish = (statistics = unavailableStatistics(), distributions = []) => ({
    status: reasons.size ? 'unavailable' : 'available',
    statistics: reasons.size ? unavailableStatistics() : statistics,
    exclusionReasons: [...reasons].sort(),
    quality,
    distributions,
  });
  if (
    observations?.version !== 1 ||
    !Array.isArray(observations?.pauses) ||
    !Array.isArray(observations?.interruptions) ||
    observations.interruptions.some((item) => typeof item !== 'string')
  )
    reasons.add('observation-history-unavailable');
  if (entry.processing?.version !== TRACK_FILTER_VERSION) reasons.add('quality-version-mismatch');
  if (rawPoints.length < 2) reasons.add('insufficient-gps-points');
  if (!reference?.file || !reference?.timeModel?.legs?.length) reasons.add('missing-reference');
  if (
    !Number.isFinite(recording.startedAt) ||
    !Number.isFinite(recording.endedAt) ||
    recording.endedAt < recording.startedAt
  )
    reasons.add('invalid-recording-range');
  if (
    quality.excludedPointCount ||
    quality.diagnostics.some((code) =>
      [
        'isolated-position-spike',
        'unconfirmed-position-jump',
        'suspect-spike-without-time',
      ].includes(code),
    )
  )
    reasons.add('gps-quality-exclusion');
  if (reasons.size) return finish();

  const matcher = routeMatcherFor(reference.file),
    model = reference.timeModel;
  let first = null,
    previous = null,
    peakM = -Infinity;
  for (let segmentIndex = 0; segmentIndex < segments.length; segmentIndex++) {
    for (const raw of segments[segmentIndex]) {
      const fix = normalizeLocationFix(raw);
      if (!fix || fix.accuracy > config.maxAccuracyM || raw.excluded) {
        reasons.add('gps-quality-exclusion');
        return finish();
      }
      if (
        fix.time < recording.startedAt ||
        fix.time > recording.endedAt ||
        (previous && fix.time <= previous.fix.time)
      ) {
        reasons.add('invalid-gps-time');
        return finish();
      }
      const boundary = previous && segmentIndex !== previous.segmentIndex;
      if (boundary) {
        if (!pauseBoundary(previous.fix, fix, observations)) {
          reasons.add('unobserved-segment-boundary');
          return finish();
        }
        quality.acceptedPauseBoundaries++;
      } else if (previous && fix.time - previous.fix.time > config.maxObservationGapMs) {
        reasons.add('gps-observation-gap');
        return finish();
      }
      const found = matcher.match([{ ...fix, stationId: 'history', coordinateStatus: 'located' }], {
        maxOffsetM: config.maxOffsetM,
        mergeWithinM: config.mergeWithinM,
      });
      const match = found.matches[0];
      let candidates = (match?.routePositions ?? []).filter(
        (position) => position.offsetM <= match.nearestTrackDistanceM + fix.accuracy,
      );
      if (!candidates.length) {
        reasons.add('off-route');
        return finish();
      }
      if (previous) {
        const reach =
          (config.maxSpeedMps * (fix.time - previous.fix.time)) / 1000 +
          previous.fix.accuracy +
          fix.accuracy;
        candidates = candidates.filter(
          (position) =>
            position.segmentIndex === previous.position.segmentIndex &&
            Math.abs(position.routeProgressM - previous.position.routeProgressM) <= reach,
        );
        if (distanceM(previous.fix, fix) > reach) candidates = [];
      }
      if (candidates.length !== 1) {
        reasons.add(candidates.length ? 'ambiguous-route-position' : 'unreachable-route-position');
        return finish();
      }
      const position = candidates[0];
      if (
        position.routeProgressM <
        peakM - Math.max(config.progressToleranceM, fix.accuracy + (previous?.fix.accuracy ?? 0))
      ) {
        reasons.add('backtracking');
        return finish();
      }
      if (
        boundary &&
        Math.abs(position.routeProgressM - previous.position.routeProgressM) >
          Math.max(5, fix.accuracy + previous.fix.accuracy)
      ) {
        reasons.add('unobserved-pause-movement');
        return finish();
      }
      const baseline = shangheTimeAt(model, position.routeProgressM, {
        segmentIndex: position.segmentIndex,
      });
      if (!Number.isFinite(baseline.elapsedSeconds)) {
        reasons.add(baseline.reason ?? 'unknown-shanghe-time');
        return finish();
      }
      const sample = { fix, position, baseline, segmentIndex };
      first ??= sample;
      previous = sample;
      peakM = Math.max(peakM, position.routeProgressM);
    }
  }
  const baselineSeconds = previous.baseline.elapsedSeconds - first.baseline.elapsedSeconds,
    matchedDistanceM = previous.position.routeProgressM - first.position.routeProgressM,
    actualWallSeconds = (previous.fix.time - first.fix.time) / 1000;
  if (baselineSeconds < config.minBaselineSeconds) reasons.add('baseline-too-small');
  if (matchedDistanceM <= Math.max(config.minProgressM, first.fix.accuracy + previous.fix.accuracy))
    reasons.add('progress-too-small');
  if (!(actualWallSeconds > 0)) reasons.add('invalid-elapsed-time');
  const distributions = model.legs
    .filter(
      (leg) =>
        Math.min(previous.position.routeProgressM, leg.toM) -
          Math.max(first.position.routeProgressM, leg.fromM) >
        1e-6,
    )
    .map((leg) => ({ index: leg.index, method: leg.method, source: leg.source }));
  return finish(
    {
      effectiveDistanceM: entry.stats.km * 1000,
      matchedDistanceM,
      baselineSeconds,
      actualWallSeconds,
      observedFrom: first.fix.time,
      observedTo: previous.fix.time,
    },
    distributions,
  );
}
