// DOM text uses device fonts, so offline labels never request remote glyphs/sprites.
export function createOfflineLabels({ library, map, document }) {
  let markers = [];
  let signature;
  function clear() {
    for (const marker of markers) marker.remove();
    markers = [];
  }
  function draw(stations = []) {
    const pois = map.getZoom() >= 11 ? map.queryRenderedFeatures({ layers: ['poi-points'] }) : [];
    const places = map.querySourceFeatures('basemap', { sourceLayer: 'places' });
    const nextSignature = JSON.stringify([
      map.getBounds().toArray(),
      map.getZoom(),
      stations,
      [...pois, ...places].map((f) => [f.geometry, f.properties.name]),
    ]);
    if (nextSignature === signature) return;
    clear();
    signature = nextSignature;
    const bounds = map.getBounds();
    const used = new Set();
    const occupied = [];
    const add = (coordinates, name, station = null) => {
      if (!name || !bounds.contains(coordinates)) return;
      const key = `${name}:${coordinates.map((v) => v.toFixed(4)).join(':')}`;
      if (used.has(key)) return;
      used.add(key);
      const point = map.project(coordinates);
      if (
        !station &&
        occupied.some((p) => Math.abs(p.x - point.x) < 80 && Math.abs(p.y - point.y) < 26)
      )
        return;
      occupied.push(point);
      const element = document.createElement('span');
      element.className = `offline-map-label${station ? ' station-label' : ''}${station?.next ? ' next-label' : ''}`;
      element.textContent = station?.arrivalLabel ? `${name} · ${station.arrivalLabel}` : name;
      markers.push(
        new library.Marker({ element, anchor: 'bottom', offset: [0, -10] })
          .setLngLat(coordinates)
          .addTo(map),
      );
    };
    for (const station of stations) add([station.lon, station.lat], station.name, station);
    for (const feature of [...pois, ...places]) {
      if (markers.length >= 45) break;
      if (feature.geometry.type !== 'Point' || (feature.properties.min_zoom ?? 0) > map.getZoom())
        continue;
      const p = feature.properties;
      add(feature.geometry.coordinates, p['name:zh-Hant'] ?? p['name:zh'] ?? p.name);
    }
  }
  return { draw, clear };
}
