import { createDirectionController } from '../features/routes/direction-controller.js';
import { createOfflineMapController } from '../features/offline-map/controller.js';
import { updateOfflineProgress } from '../features/offline-map/view.js';
import { createDaylightController } from '../features/daylight/controller.js';
import { createHeightProfileView } from '../features/daylight/view.js';
import { createState, currentFile, gpsActive, gpsPending, recordingRoute } from './state.js';
import { createNavigation } from './navigation.js';
import { bindBrowserEvents } from './browser-events.js';
import { createGpxRepository } from '../storage/repository.js';
import { parseGpx } from '../features/gpx/parser.js';
import { hydrateTimeOrigin } from '../domain/time-origin.js';
import { createLibraryController } from '../features/gpx/controller.js';
import { createLibraryViews } from '../features/gpx/views.js';
import { createRecordingPersistence } from '../features/recording/persistence.js';
import { createRecordingController } from '../features/recording/controller.js';
import { createLocationProvider } from '../features/location/select.js';
import { createEstimateController } from '../features/recording/estimates.js';
import { createRecordingView } from '../features/recording/view.js';
import { recordedTrack, recordingElapsed } from '../features/recording/model.js';
import { createTerrainMapController } from '../features/map/controller.js';
import { createMapPresenter } from '../features/map/presenter.js';
import { createMapView } from '../features/map/view.js';
import { createRouteViews } from '../features/routes/views.js';
import { createFeedback } from '../ui/feedback.js';
import { createActions } from '../ui/actions.js';
import { createRenderer } from '../ui/renderer.js';
import { createItineraryController } from '../features/itinerary/controller.js';
import { createItineraryViews } from '../features/itinerary/views.js';
import { createPersonalHistoryController } from '../features/history/controller.js';
import { createPersonalFactorController } from '../features/personal-factor/controller.js';
import { createPersonalFactorView } from '../features/personal-factor/view.js';
import { registerWebMcp } from '../integrations/web-mcp.js';

// The composition root connects modules; feature logic remains in features/.
export function createApplication({
  document = globalThis.document,
  window = globalThis.window,
  navigator = globalThis.navigator,
  locationProvider = createLocationProvider({ navigator }),
  repository = createGpxRepository(),
  state = createState(),
} = {}) {
  let renderer,
    recordingView,
    personalFactorView,
    unbind,
    mcp,
    startPromise,
    disposed = false;
  const render = () => {
    if (!disposed) renderer?.render();
  };
  const selectors = {
    current: () => currentFile(state),
    gpsActive: () => gpsActive(state),
    gpsPending: () => gpsPending(state),
    recordingRoute: () => recordingRoute(state),
    gpsElapsed: () => recordingElapsed(state.gps),
  };
  const feedback = createFeedback({ document });
  const direction = createDirectionController({
    state,
    current: selectors.current,
    gpsPending: selectors.gpsPending,
    repository,
    render,
    feedback,
  });
  const navigation = createNavigation({ state, render, window });
  const { navigate } = navigation;
  const itinerary = createItineraryController({
    state,
    repository,
    ...selectors,
    render,
    feedback,
  });
  const itineraryViews = createItineraryViews({
    state,
    itinerary,
    gpsPending: selectors.gpsPending,
    recordingRoute: selectors.recordingRoute,
    document,
  });
  const history = createPersonalHistoryController({
    repository,
    recordingRoute: selectors.recordingRoute,
    referenceFor: itinerary.historyReference,
    onChange: () => personalFactorView?.refresh(),
  });
  const personalFactors = createPersonalFactorController({ history: history.api });
  personalFactorView = createPersonalFactorView({ personalFactors, document });
  const offlineMaps = createOfflineMapController({
    document,
    navigator,
    onChange: () => {
      // Offline status affects maps, not the route list or idle recording form.
      // Keep their buttons connected while background initialization completes.
      if (document.getElementById('track-map')) render();
    },
    onProgress: (status) => updateOfflineProgress(document, status),
  });
  const presenter = createMapPresenter({ document });
  const map = createTerrainMapController({
    offlineMaps,
    onStatus: presenter.updateStatus,
    onCamera: presenter.updateCamera,
  });
  const persistence = createRecordingPersistence({
    state,
    repository,
    gpsActive: selectors.gpsActive,
    navigator,
    onStatus: () => recordingView?.updateSaveStatus(),
    captureCheckpoint: itinerary.captureLiveCheckpoint,
  });
  const recording = createRecordingController({
    locationProvider,
    onJourneyStart: itinerary.begin,
    onJourneyProgress: itinerary.progress,
    onJourneyFix: itinerary.updateLiveFactor,
    onJourneyInterruption: itinerary.interruptLiveFactor,
    onJourneyRestore: itinerary.restoreLiveSession,
    prepareHistory: history.prepare,
    state,
    repository,
    persistence,
    ...selectors,
    render,
    navigate,
    feedback,
    navigator,
  });
  const library = createLibraryController({
    state,
    repository,
    gpsPending: selectors.gpsPending,
    render,
    navigate,
    feedback,
  });
  const estimates = createEstimateController({
    state,
    ...selectors,
    saveDraft: persistence.save,
    render,
    feedback,
  });
  const daylight = createDaylightController({ itinerary });
  const heightProfile = createHeightProfileView({ daylight, document });
  const { mapPanel, heightPanel } = createMapView({
    state,
    terrainMap: map,
    offlineMaps,
    itinerary,
    heightProfile,
  });
  const routeViews = createRouteViews({ ...selectors, mapPanel, itineraryViews, state });
  recordingView = createRecordingView({
    itineraryViews,
    state,
    ...selectors,
    mapPanel,
    heightPanel,
    settingsPanel: routeViews.settingsPanel,
    persistence,
    document,
  });
  const views = {
    ...createLibraryViews({
      state,
      gpsPending: selectors.gpsPending,
      personalFactorPanel: () => (selectors.gpsPending() ? '' : personalFactorView.panel()),
    }),
    ...routeViews,
    recordView: recordingView.recordView,
  };
  renderer = createRenderer({
    itinerary,
    state,
    document,
    terrainMap: map,
    ...selectors,
    views,
    recordingView,
    personalFactorView,
  });
  const actions = createActions({
    state,
    current: selectors.current,
    document,
    render,
    navigate,
    library,
    recording,
    estimates,
    itinerary,
    persistence,
    map,
    offlineMaps,
    direction,
    feedback,
    personalFactorView,
  });
  async function initialize() {
    navigation.readInitial();
    render();
    try {
      await repository.open();
      if (disposed) return;
      await itinerary.restore();
      if (disposed) return;
      const records = await repository.listFiles();
      if (disposed) return;
      for (const record of records.sort((a, b) => a.addedAt - b.addedAt)) {
        try {
          const entry = await hydrateTimeOrigin({
            ...record,
            ...(record.kind === 'recording'
              ? recordedTrack(record)
              : parseGpx(record.raw, record.fileName)),
            saved: true,
          });
          if (disposed) return;
          state.library.push(entry);
        } catch {
          state.results.push({
            ok: false,
            name: record.fileName,
            message: '已儲存的檔案無法讀取，請重新匯入原始 GPX。',
          });
        }
      }
      await direction.restore();
      if (disposed) return;
      const draft = await repository.getDraft();
      if (draft && !disposed && (await persistence.acquireLock())) {
        if (disposed) persistence.releaseLock();
        else await recording.restore(draft);
      }
    } catch {
      state.storageError = '此瀏覽器無法使用本機儲存。仍可匯入與查看路線，但重新整理後需再次匯入。';
    }
    if (disposed) return;
    state.selected =
      state.gps.sourceRouteId ??
      state.library.find((file) => file.kind !== 'recording')?.id ??
      null;
    state.loading = false;
    render();
    void offlineMaps.initialize();
    mcp = registerWebMcp({
      state,
      gpsPending: selectors.gpsPending,
      selectFile: library.selectFile,
      document,
      navigator,
    });
  }
  function start() {
    if (disposed) throw new Error('Application has been disposed');
    if (!startPromise) {
      unbind = bindBrowserEvents({
        state,
        document,
        window,
        actions,
        itinerary,
        navigation,
        library,
        persistence,
        map,
        recordingView,
        heightProfile,
        personalFactorView,
        ...selectors,
      });
      startPromise = initialize();
    }
    return startPromise;
  }
  async function dispose() {
    if (disposed) return;
    disposed = true;
    personalFactorView.dispose();
    unbind?.();
    library.dispose();
    itinerary.dispose();
    await direction.dispose();
    await daylight.dispose();
    await recording.dispose();
    await persistence.save();
    await persistence.dispose();
    await startPromise;
    await mcp?.dispose();
    map.destroy();
    await offlineMaps.dispose();
    feedback.dispose();
    repository.close();
  }
  return {
    start,
    dispose,
    state,
    render,
    navigate,
    controllers: {
      library,
      recording,
      estimates,
      itinerary,
      daylight,
      offlineMaps,
      direction,
      history: history.api,
      personalFactors,
    },
  };
}
