export const DIAGNOSTIC_PAGE_SIZE = 20;

const REASONS = {
  'isolated-position-spike': ['GPS 跳點', '依相鄰位置與時間內插校正。'],
  'unconfirmed-position-jump': ['未確認的 GPS 跳點', '暫不納入分析，在此處中斷軌跡。'],
  'suspect-spike-without-time': ['疑似 GPS 跳點', '缺乏可靠時間，保留原位置供核對。'],
  'stationary-drift': ['停留時的水平漂移', '將停留範圍內的往返漂移收斂至中心。'],
  'horizontal-smoothing': ['水平雜訊', '沿路線平滑細小的位置起伏。'],
  'elevation-median': ['高度雜訊', '以鄰近高度的中位數抑制雜訊。'],
  'elevation-hysteresis': ['高度小幅反覆', '抑制小幅往返起伏，保留持續升降。'],
  'low-horizontal-accuracy': ['水平精度不足', '不納入分析，在此處中斷軌跡。'],
  'low-altitude-accuracy': ['高度精度不足', '高度保留未知，不補算爬升或下降。'],
};
const nonnegative = (value) => (Number.isFinite(value) && value >= 0 ? value : null);
const sourceKey = (segment, index) => `${segment}:${index}`;
const validIndex = (value) => Number.isInteger(value) && value >= 0;
function snapshot(point) {
  if (!point) return null;
  const located =
    Number.isFinite(point.lat) &&
    Number.isFinite(point.lon) &&
    Math.abs(point.lat) <= 90 &&
    Math.abs(point.lon) <= 180;
  return {
    position: located ? { lat: point.lat, lon: point.lon } : null,
    elevation: Number.isFinite(point.elevation) ? point.elevation : null,
    time:
      Number.isFinite(point.time) && Math.abs(point.time) <= 8640000000000000 ? point.time : null,
  };
}
function metric(stats, key) {
  if (stats?.points === 0 || (stats?.points > 0 && stats.points === stats.excludedPoints))
    return null;
  return nonnegative(stats?.[key]);
}
export function comparison(original, corrected) {
  original = nonnegative(original);
  corrected = nonnegative(corrected);
  const percent =
    original !== null && original > 0 && corrected !== null
      ? ((corrected - original) / original) * 100
      : null;
  return { original, corrected, percent: Number.isFinite(percent) ? percent : null };
}

// Presentation-only snapshots. No filtering, persistence, or changes to source point indices.
export function correctionReport(file) {
  const processed = !!file?.processing;
  const diagnostics = file?.processing?.diagnostics;
  const knownReasons = Array.isArray(diagnostics);
  const points = new Map();
  for (const point of file?.points ?? []) {
    points.set(
      sourceKey(point.rawSegment ?? point.segment, point.rawIndex ?? point.sourceIndex),
      point,
    );
  }
  const counts = new Map();
  const entries = (knownReasons ? diagnostics : []).map((item) => {
    const reasons = [...new Set(item.reasons ?? [])].map((code) => {
      counts.set(code, (counts.get(code) ?? 0) + 1);
      const [label, description] = REASONS[code] ?? ['其他處理', String(code)];
      return { code, label, description };
    });
    const located = validIndex(item.segment) && validIndex(item.sourceIndex);
    const original = located ? file.rawSegments?.[item.segment]?.[item.sourceIndex] : null;
    const corrected = located ? points.get(sourceKey(item.segment, item.sourceIndex)) : null;
    return {
      segment: located ? item.segment : null,
      sourceIndex: located ? item.sourceIndex : null,
      gpxSegment: original
        ? file.direction === 'reverse'
          ? file.rawSegments.length - 1 - item.segment
          : item.segment
        : null,
      gpxIndex: original
        ? file.direction === 'reverse'
          ? file.rawSegments[item.segment].length - 1 - item.sourceIndex
          : item.sourceIndex
        : null,
      original: snapshot(original),
      corrected: snapshot(corrected),
      excluded: reasons.some((reason) =>
        ['low-horizontal-accuracy', 'unconfirmed-position-jump'].includes(reason.code),
      ),
      reasons,
    };
  });
  entries.sort(
    (a, b) =>
      (a.segment ?? Infinity) - (b.segment ?? Infinity) ||
      (a.sourceIndex ?? Infinity) - (b.sourceIndex ?? Infinity),
  );
  return {
    processed,
    knownReasons,
    metrics: [
      ['km', '距離', 'km'],
      ['up', '爬升', 'm'],
      ['down', '下降', 'm'],
    ].map(([key, label, unit]) => ({
      key,
      label,
      unit,
      ...comparison(metric(file?.rawStats, key), processed ? metric(file?.stats, key) : null),
    })),
    reasons: [...counts].map(([code, count]) => ({
      code,
      label: REASONS[code]?.[0] ?? '其他處理',
      count,
    })),
    entries,
  };
}
