export const PERSONAL_FACTOR_VERSION = 1;
export const MIN_PERSONAL_RECORDINGS = 3;
const directions = ['forward', 'reverse'];
const digest = (value) => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const positive = (value) => Number.isFinite(value) && value > 0;

export function personalFactorScope(options = {}) {
  if (!options || typeof options !== 'object' || Array.isArray(options))
    throw new TypeError('Expected a personal factor scope');
  const { routeId, direction } = options;
  if (routeId !== undefined && (typeof routeId !== 'string' || !routeId.trim()))
    throw new TypeError('Expected a nonempty routeId');
  if (direction !== undefined && !directions.includes(direction))
    throw new TypeError('Unknown personal factor direction');
  return {
    kind:
      routeId === undefined
        ? direction === undefined
          ? 'global'
          : 'direction'
        : direction === undefined
          ? 'route'
          : 'route-direction',
    routeId: routeId ?? null,
    direction: direction ?? null,
  };
}

function eligibility(row) {
  const reasons = new Set(Array.isArray(row?.exclusionReasons) ? row.exclusionReasons : []);
  if (row?.status !== 'available') reasons.add('history-unavailable');
  if (
    row?.source?.kind !== 'ridgewise-local-explicit-save' ||
    !['web-geolocation', 'ios-core-location'].includes(row?.source?.provider) ||
    row?.source?.verification !== 'unverified' ||
    row?.source?.simulated === true ||
    row?.source?.coverage !== 'actual-gps-endpoints-only'
  )
    reasons.add('invalid-local-source');
  if (typeof row?.recordingId !== 'string' || !row.recordingId || !digest(row?.rawSha256))
    reasons.add('invalid-recording-identity');
  if (
    typeof row?.route?.id !== 'string' ||
    !row.route.id ||
    !directions.includes(row?.route?.direction)
  )
    reasons.add('missing-route-or-direction');
  const stats = row?.statistics;
  if (
    !stats ||
    !['actualWallSeconds', 'baselineSeconds', 'effectiveDistanceM', 'matchedDistanceM'].every(
      (key) => positive(stats[key]),
    ) ||
    !Number.isFinite(stats.observedFrom) ||
    !Number.isFinite(stats.observedTo) ||
    stats.observedTo <= stats.observedFrom ||
    Math.abs((stats.observedTo - stats.observedFrom) / 1000 - stats.actualWallSeconds) > 0.001 ||
    !positive(stats.actualWallSeconds / stats.baselineSeconds)
  )
    reasons.add('incomplete-history-statistics');
  return [...reasons];
}

function summary(samples) {
  const totalActualWallSeconds = samples.reduce(
      (sum, item) => sum + item.statistics.actualWallSeconds,
      0,
    ),
    totalBaselineSeconds = samples.reduce((sum, item) => sum + item.statistics.baselineSeconds, 0),
    finite =
      Number.isFinite(totalActualWallSeconds) &&
      Number.isFinite(totalBaselineSeconds) &&
      (!samples.length || positive(totalActualWallSeconds / totalBaselineSeconds)),
    sufficient = samples.length >= MIN_PERSONAL_RECORDINGS;
  return {
    sampleCount: samples.length,
    minimumSamples: MIN_PERSONAL_RECORDINGS,
    factor: sufficient && finite ? totalActualWallSeconds / totalBaselineSeconds : null,
    totalActualWallSeconds: finite ? totalActualWallSeconds : null,
    totalBaselineSeconds: finite ? totalBaselineSeconds : null,
    factorRange: samples.length
      ? samples.reduce(
          (range, item) => ({
            min: Math.min(range.min, item.factor),
            max: Math.max(range.max, item.factor),
          }),
          { min: Infinity, max: -Infinity },
        )
      : null,
    reasons: [
      ...(!sufficient ? ['insufficient-independent-recordings'] : []),
      ...(!finite ? ['aggregate-overflow'] : []),
    ],
  };
}

// Only validated history API rows enter this read-only reduction. No ETA/live-factor dependency.
export function calculatePersonalFactor(rows, options = {}) {
  const scope = personalFactorScope(options),
    samples = [],
    excludedSamples = [],
    seenIds = new Set(),
    seenDigests = new Set();
  let matchedCandidateCount = 0;
  for (const row of [...rows].sort(
    (a, b) =>
      (a?.explicitlySavedAt ?? 0) - (b?.explicitlySavedAt ?? 0) ||
      String(a?.recordingId).localeCompare(String(b?.recordingId)),
  )) {
    const reasons = eligibility(row),
      matches =
        (scope.routeId === null || row?.route?.id === scope.routeId) &&
        (scope.direction === null || row?.route?.direction === scope.direction);
    if (matches) matchedCandidateCount++;
    // Establish independence across the complete history before selecting a narrower scope.
    if (!reasons.length) {
      if (seenIds.has(row.recordingId) || seenDigests.has(row.rawSha256))
        reasons.push('duplicate-recording');
      else {
        seenIds.add(row.recordingId);
        seenDigests.add(row.rawSha256);
      }
    }
    if (!matches) reasons.push('outside-requested-scope');
    if (reasons.length) {
      excludedSamples.push({
        recordingId: row?.recordingId ?? null,
        route: structuredClone(row?.route ?? null),
        historyStatus: row?.status ?? null,
        reasons,
      });
    } else {
      samples.push(
        structuredClone({
          ...row,
          factor: row.statistics.actualWallSeconds / row.statistics.baselineSeconds,
        }),
      );
    }
  }
  const grouped = new Map();
  for (const sample of samples) {
    const key = JSON.stringify([sample.route.id, sample.route.direction]);
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(sample);
  }
  return {
    version: PERSONAL_FACTOR_VERSION,
    scope,
    ...summary(samples),
    candidateCount: rows.length,
    matchedCandidateCount,
    samples,
    excludedSamples,
    groups: [...grouped.values()].map((items) => ({
      routeId: items[0].route.id,
      direction: items[0].route.direction,
      ...summary(items),
      recordingIds: items.map((item) => item.recordingId),
    })),
    source: {
      kind: 'ridgewise-personal-history',
      verification: 'unverified',
      formula: 'sum(actualWallSeconds) / sum(baselineSeconds)',
      weighting: 'baseline-duration',
      coverage: 'actual-gps-endpoints-only',
      limitations: [
        'local-recordings-not-independently-verified',
        'longer-baseline-has-more-weight',
        'rests-and-compatible-pauses-included',
        'different-routes-and-directions-may-be-mixed',
        'no-outlier-trimming',
        'not-applied-to-eta',
      ],
    },
  };
}
