import { recordingStats } from './analysis.js';
import { recordedFile, recordedTrack } from './model.js';
import { localRecordingTimeSource, hydrateTimeOrigin } from '../../domain/time-origin.js';

// Stopping GPS and explicitly saving a file are separate operations.
export function createRecordingCompletion({
  state,
  repository,
  persistence,
  stopWatch,
  clearGps,
  render,
  navigate,
  feedback,
  prepareHistory = async () => null,
}) {
  const busy = () => ['stopping', 'finishing', 'discarding'].includes(state.gps.status);
  async function stop() {
    const gps = state.gps;
    if (!gps.id || busy() || ['review', 'finished'].includes(gps.status)) return;
    feedback.close();
    if (typeof gps.historyObservations === 'object' && gps.historyObservations)
      gps.historyObservations.stoppedAt = Date.now();
    stopWatch();
    gps.endedAt = gps.pauseAt ?? Date.now();
    gps.pauseAt = gps.endedAt;
    gps.status = 'stopping';
    persistence.cancelScheduled();
    render();
    await persistence.settle();
    // Persist a stopped draft, never a library file, before presenting choices.
    await persistence.save();
    gps.status = 'review';
    render();
  }
  async function save() {
    const gps = state.gps;
    if (!gps.id || gps.status !== 'review') return;
    if (!recordingStats(gps).points) {
      feedback.toast('尚未取得 GPS 座標，無法保存 GPX；可以選擇不保存返回。');
      return;
    }
    feedback.close();
    gps.status = 'finishing';
    gps.finalizePending = true;
    persistence.cancelScheduled();
    render();
    await persistence.settle();
    try {
      const file = recordedFile(gps);
      // Failure to create provenance must never lose a saved recording.
      try {
        file.timeSource = await localRecordingTimeSource(file, gps);
      } catch {
        /* source stays unknown */
      }
      const entry = await hydrateTimeOrigin(recordedTrack(file));
      // Derived history cannot prevent saving the user's original GPX.
      try {
        const candidate = await prepareHistory(file, entry);
        if (candidate) {
          file.personalHistory = candidate;
          entry.personalHistory = candidate;
        }
      } catch {
        // Missing history remains unavailable; never manufacture a fallback statistic.
      }
      try {
        await repository.finishRecording(file);
      } catch (error) {
        if (!file.personalHistory && !file.recording.historyObservations) throw error;
        // A larger derived snapshot must not be the reason a raw recording cannot be saved.
        const { personalHistory: _history, ...rawOnly } = file;
        const { historyObservations: _observations, ...recording } = rawOnly.recording;
        rawOnly.recording = recording;
        await repository.finishRecording(rawOnly);
        delete entry.personalHistory;
        entry.recording = recording;
      }
      entry.saved = true;
      state.library = state.library.filter((item) => item.id !== file.id);
      state.library.push(entry);
      clearGps();
      navigate('library');
      feedback.toast('已保存至「我的 GPX」。');
    } catch {
      gps.status = 'review';
      await persistence.save();
      gps.saveError = 'GPX 保存失敗。GPS 已停止，請下載備份或重試保存。';
      render();
    }
  }
  async function discard() {
    if (!state.gps.id || busy()) return;
    feedback.close();
    stopWatch();
    const gps = state.gps,
      previousStatus = gps.status;
    gps.pauseAt ??= Date.now();
    gps.status = 'discarding';
    persistence.cancelScheduled();
    render();
    await persistence.settle();
    try {
      // Only the active draft is deleted. Imported and saved files remain intact.
      await repository.deleteDraft();
      clearGps();
      navigate('record');
    } catch {
      gps.status = previousStatus === 'review' ? 'review' : 'paused';
      gps.saveError = '無法移除草稿，請稍後重試。';
      render();
    }
  }
  return { stop, save, discard };
}
