import { calculatePersonalFactor, personalFactorScope } from './model.js';

export function createPersonalFactorController({ history }) {
  return {
    async query(options = {}) {
      const scope = personalFactorScope(options),
        requested = {
          ...(scope.routeId === null ? {} : { routeId: scope.routeId }),
          ...(scope.direction === null ? {} : { direction: scope.direction }),
        };
      // Always revalidate history, including deletions, provenance and reference-model changes.
      const rows = await history.list();
      return { ...calculatePersonalFactor(rows, requested), queriedAt: Date.now() };
    },
  };
}
