// Small recording metadata; raw fixes remain in the original GPX, never a second track.
import { LIVE_FACTOR_DEFAULTS } from '../itinerary/live-factor.js';

const routeFailures = new Set([
  'off-route',
  'ambiguous-route-position',
  'unreachable-route-position',
  'abnormal-gps-speed',
  'backtracking',
]);
const observations = (gps) => {
  const value = gps.historyObservations;
  return value?.version === 1 && Array.isArray(value.interruptions) && Array.isArray(value.pauses)
    ? value
    : null;
};
export function historyInterruption(gps, reason) {
  const history = observations(gps);
  if (history && !history.interruptions.includes(reason)) history.interruptions.push(reason);
}
export function historyFix(gps, fix, now, live) {
  if (fix.excluded) historyInterruption(gps, 'gps-quality-exclusion');
  if (
    !Number.isFinite(now) ||
    fix.time > now + LIVE_FACTOR_DEFAULTS.futureToleranceMs ||
    now - fix.time > LIVE_FACTOR_DEFAULTS.maxAgeMs
  )
    historyInterruption(gps, 'gps-time-quality-exclusion');
  if (routeFailures.has(live?.total?.reason)) historyInterruption(gps, live.total.reason);
  if (fix.simulated) {
    if (gps.captureSource) gps.captureSource.simulated = true;
    if (typeof gps.historyObservations === 'object' && gps.historyObservations)
      gps.historyObservations.simulated = true;
  }
}
export function historyPause(gps, now) {
  const history = observations(gps);
  if (!history) return;
  history.pauses.push({
    pausedAt: now,
    resumedAt: null,
    beforeFixTime: gps.segments.findLast((segment) => segment.length)?.at(-1)?.time ?? null,
  });
}
export function historyResume(gps, now) {
  const pause = observations(gps)?.pauses.at(-1);
  if (pause && pause.resumedAt === null) pause.resumedAt = now;
}
