// A separate database: removing basemaps never touches GPX files or GPS drafts.
export function createOfflineMapStore({ indexedDB = globalThis.indexedDB } = {}) {
  let database;
  let opening;
  async function open() {
    if (database) return database;
    opening ??= new Promise((resolve, reject) => {
      if (!indexedDB) return reject(new Error('此瀏覽器無法儲存離線地圖。'));
      let blocked = false;
      const request = indexedDB.open('ridgewise-offline-maps', 1);
      request.onupgradeneeded = () => request.result.createObjectStore('packs', { keyPath: 'id' });
      request.onerror = () => reject(request.error);
      request.onblocked = () => {
        blocked = true;
        reject(new Error('請先關閉其他 Ridgewise 分頁再試。'));
      };
      request.onsuccess = () => {
        if (blocked) {
          request.result.close();
          return;
        }
        database = request.result;
        database.onversionchange = () => {
          database.close();
          database = undefined;
          opening = undefined;
        };
        resolve(database);
      };
    }).catch((error) => {
      opening = undefined;
      throw error;
    });
    return opening;
  }
  async function transact(mode, operation) {
    const db = await open();
    return new Promise((resolve, reject) => {
      const tx = db.transaction('packs', mode);
      const request = operation(tx.objectStore('packs'));
      tx.oncomplete = () => resolve(request.result);
      tx.onabort = tx.onerror = () =>
        reject(tx.error ?? request.error ?? new Error('離線地圖未能儲存。'));
    });
  }
  return {
    get: () => transact('readonly', (store) => store.get('standard')),
    save: (pack) => transact('readwrite', (store) => store.put({ ...pack, id: 'standard' })),
    remove: () => transact('readwrite', (store) => store.delete('standard')),
    close: async () => {
      await opening?.catch(() => {});
      database?.close();
      database = undefined;
      opening = undefined;
    },
  };
}
