export function bindBrowserEvents({
  state,
  document,
  window,
  actions,
  navigation,
  library,
  persistence,
  map,
  recordingView,
  itinerary,
  heightProfile,
  personalFactorView,
  gpsActive,
  gpsPending,
}) {
  const cleanups = [];
  function listen(target, type, handler) {
    target.addEventListener(type, handler);
    cleanups.push(() => target.removeEventListener(type, handler));
  }
  listen(document, 'click', (event) => {
    const nav = event.target.closest?.('[data-view]');
    if (nav) {
      navigation.navigate(nav.dataset.view);
      return;
    }
    const target = event.target.closest?.('[data-action]');
    if (!target || target.disabled) return;
    const action = actions[target.dataset.action];
    if (action) {
      try {
        Promise.resolve(action(target)).catch(actions.onError);
      } catch {
        actions.onError();
      }
    }
  });
  listen(document, 'input', (event) => {
    const input = event.target;
    if (input.id === 'map-pitch') {
      map.tilt(Number(input.value));
      return;
    }
    if (input.id === 'recording-name') {
      state.recordingName = input.value;
      return;
    }
    if (!gpsActive() || state.gps.status === 'finishing') return;
    const field = {
      'calibration-label': 'calibrationLabel',
      'calibration-base': 'calibrationBase',
      'remaining-base': 'remainingBase',
    }[input.id];
    if (field) {
      state.gps[field] = input.value;
      persistence.schedule();
    }
  });
  listen(document.querySelector('#gpx-input'), 'change', (event) => {
    const files = Array.from(event.target.files);
    event.target.value = '';
    library.importFiles(files).catch(actions.onError);
  });
  listen(document, 'change', (event) => {
    if (event.target.id.startsWith('reroute-')) {
      state.itinerary.rerouteForm ??= {};
      state.itinerary.rerouteForm[event.target.id] = event.target.value;
      itinerary?.invalidateReroute?.();
    }
    if (event.target.id === 'itinerary-factor')
      itinerary?.setFactor(event.target.value).catch(actions.onError);
  });
  for (const type of ['dragover', 'dragleave', 'drop'])
    listen(document, type, (event) => {
      const drop = event.target.closest?.('#dropzone');
      if (!drop) return;
      if (type === 'dragover') {
        event.preventDefault();
        drop.classList.add('drag-over');
      } else {
        drop.classList.remove('drag-over');
        if (type === 'drop') {
          event.preventDefault();
          library.importFiles(event.dataTransfer.files).catch(actions.onError);
        }
      }
    });
  listen(window, 'hashchange', navigation.onHashChange);
  listen(window, 'focus', () => personalFactorView?.refresh());
  listen(window, 'beforeunload', (event) => {
    if (gpsActive() || state.importing) {
      event.preventDefault();
      event.returnValue = '';
    }
  });
  listen(window, 'pagehide', () => {
    persistence.save();
  });
  listen(document, 'visibilitychange', () => {
    if (document.visibilityState === 'hidden') persistence.save();
    else void personalFactorView?.refresh();
  });
  const clock = window.setInterval(() => {
    heightProfile?.update();
    if (state.view === 'record' && gpsPending()) recordingView.updateNumbers();
  }, 1000);
  const autosave = window.setInterval(() => {
    if (['requesting', 'tracking'].includes(state.gps.status)) persistence.save();
  }, 10000);
  cleanups.push(() => {
    window.clearInterval(clock);
    window.clearInterval(autosave);
  });
  return () => {
    for (const cleanup of cleanups.splice(0)) cleanup();
  };
}
