import { button, esc } from '../../ui/html.js';
export function directionPanel(file, { locked = false, error = '' } = {}) {
  if (!file || file.kind === 'recording' || file.recording) return '';
  const direction = file.direction === 'reverse' ? 'reverse' : 'forward';
  return `<section class="panel panel-body stack route-direction"><span class="eyebrow">YOUR DIRECTION</span><h2>行走方向</h2>
    <div class="tab-group" role="group" aria-label="行走方向">${[
      ['forward', '原向走'],
      ['reverse', '反向走'],
    ]
      .map(([value, label]) =>
        button(
          label,
          'route-direction',
          '',
          '',
          `data-direction="${value}" aria-pressed="${direction === value}" ${locked ? 'disabled' : ''}`,
        ),
      )
      .join('')}</div>
    <p class="small muted">${direction === 'reverse' ? '從 GPX 終點出發，沿原路線反向走。' : '從 GPX 起點出發，依原始軌跡順序走。'}站序、起終點、上河時間與日夜預估一起更新；原始 GPX 保留。</p>
    <p class="small muted">${locked ? '此趟使用出發時的方向，結束紀錄後才可更改。' : '反向使用上河反向路段時間，缺資料保留待補。環狀路線的順／逆時針依 GPX 幾何決定。'}</p>
    ${error ? `<p class="error-message" role="status">${esc(error)}</p>` : ''}</section>`;
}
