import { positiveMinutes, shangheFactor } from './model.js';
export function createEstimateController({
  state,
  gpsActive,
  gpsElapsed,
  saveDraft,
  render,
  feedback,
}) {
  const { toast } = feedback;
  function beginCalibration() {
    const gps = state.gps,
      baseMinutes = positiveMinutes(gps.calibrationBase),
      label = (gps.calibrationLabel || '').trim();
    if (gps.status !== 'tracking' || gps.calibration?.active) return;
    if (!baseMinutes || !label) {
      toast('請填入路段、行走方向，以及大於 0 的上河基準分鐘。');
      return;
    }
    gps.calibration.active = { label, baseMinutes, startElapsed: gpsElapsed() };
    saveDraft();
    render();
  }
  function endCalibration() {
    const gps = state.gps,
      active = gps.calibration?.active;
    if (!active || !['tracking', 'paused'].includes(gps.status)) return;
    const actualMs = gpsElapsed() - active.startElapsed;
    if (actualMs <= 0) {
      toast('尚未累積路段行走時間，請稍後再確認。');
      return;
    }
    gps.calibration.completed.push({ ...active, actualMs, completedAt: Date.now() });
    gps.calibration.active = null;
    gps.remaining = null;
    gps.remainingBase = '';
    feedback.close();
    saveDraft();
    render();
    toast('已更新上河倍率。請填入從現在到目的地的剩餘基準。');
  }
  function updateEstimate() {
    const gps = state.gps,
      baseMinutes = positiveMinutes(gps.remainingBase),
      factor = shangheFactor(gps.calibration?.completed);
    if (!gpsActive() || gps.status === 'finishing') return;
    if (baseMinutes === null || factor === null) {
      toast('請先完成一段基準路段，並輸入有效的剩餘基準分鐘。');
      return;
    }
    gps.remaining = { baseMinutes, factor, elapsedMs: gpsElapsed(), updatedAt: Date.now() };
    saveDraft();
    render();
  }
  function cancel() {
    if (state.gps.calibration?.active) {
      state.gps.calibration.active = null;
      saveDraft();
      render();
    }
  }

  return { begin: beginCalibration, complete: endCalibration, update: updateEstimate, cancel };
}
