import { button, esc } from '../../ui/html.js';
import { elapsedLabel } from '../../domain/track.js';

export const personalFactorReason = (reason) =>
  ({
    'insufficient-independent-recordings': '至少需要 3 筆獨立有效錄製，目前資料不足。',
    'aggregate-overflow': '總時間超出可計算範圍，無法提供建議。',
    'history-unavailable': '歷史資料目前不可用',
    'invalid-local-source': '來源不符合本機實測條件',
    'invalid-recording-identity': '錄製識別或內容雜湊不完整',
    'missing-route-or-direction': '缺少路線或方向',
    'incomplete-history-statistics': '歷史統計不完整',
    'duplicate-recording': '重複錄製或相同原始內容',
    'duplicate-recording-content': '重複的原始錄製內容',
    'reference-route-deleted': '參考路線已刪除',
    'reference-content-or-model-changed': '參考路線或上河模型已變更',
    'recording-content-changed': '錄製原始內容已變更',
    'recording-metadata-changed': '錄製資料已變更',
    'local-time-source-changed': '本機錄製來源已失效',
    'gps-interrupted': '定位曾中斷',
    'unobserved-reload-interval': '錄製重載期間缺少觀測',
    'dynamic-reroute': '途中改道；保留各版本紀錄，不以單一路線計算完整山行倍率',
    'gps-quality-exclusion': 'GPS 品質不符合條件',
    'gps-observation-gap': 'GPS 觀測有長時間缺口',
    'missing-reference': '缺少可用的上河參考路線',
    'outside-requested-scope': '不在指定路線或方向範圍',
  })[reason] ?? `歷史資料未通過品質或完整性核對（${reason}）`;

const duration = (seconds) => (seconds === null ? '—' : elapsedLabel(seconds * 1000));
const range = (value) => (value ? `${value.min.toFixed(2)}–${value.max.toFixed(2)} 倍` : '—');

export function createPersonalFactorView({ personalFactors, document }) {
  let revision = 0,
    disposed = false;
  function panel() {
    return `<section id="personal-factor-panel" class="panel panel-body stack personal-factor-panel" aria-labelledby="personal-factor-title"><h2 id="personal-factor-title">個人歷史倍率</h2><p class="small muted">僅供參考，不自動套用 ETA。全域歷史包含不同路線與方向的已觀測範圍。</p><div role="status" aria-live="polite">正在核對本機歷史資料…</div><details id="personal-factor-details"><summary>時間、樣本範圍與來源限制</summary><div data-personal-factor-details></div></details>${button('重新核對歷史資料', 'personal-factor-refresh', 'ghost')}</section>`;
  }
  async function refresh() {
    const ticket = ++revision,
      root = document.getElementById('personal-factor-panel');
    if (!root || disposed) return;
    root.setAttribute('aria-busy', 'true');
    root.querySelector('[role="status"]').textContent = '正在核對本機歷史資料…';
    // Clear old numbers before awaiting storage: stale recommendations are never retained on failure.
    root.querySelector('[data-personal-factor-details]').replaceChildren();
    try {
      const result = await personalFactors.query();
      if (disposed || ticket !== revision || document.getElementById(root.id) !== root) return;
      const names = new Map();
      for (const item of result.excludedSamples)
        for (const reason of item.reasons) names.set(reason, (names.get(reason) ?? 0) + 1);
      root.querySelector('[role="status"]').innerHTML =
        `<strong class="personal-factor-value" data-personal-factor>${result.factor === null ? '—' : `${result.factor.toFixed(2)} 倍`}</strong><p data-personal-factor-count>有效樣本 ${result.sampleCount} 筆獨立錄製</p><p>${result.factor === null ? result.reasons.map(personalFactorReason).map(esc).join(' ') : '已達建議樣本門檻；僅供參考，尚未套用 ETA。'}</p>`;
      root.querySelector('[data-personal-factor-details]').innerHTML =
        `<p class="small muted">${result.groups.length} 組路線／方向；全域倍率不代表同一路線的實績。手動設定倍率保持不變。</p><div class="stack small"><p>總實際耗時 ${duration(result.totalActualWallSeconds)} ／總上河基準 ${duration(result.totalBaselineSeconds)}<br>個別樣本倍率範圍 ${range(result.factorRange)}</p><p>倍率＝總實際耗時 ÷ 總上河基準。上河基準較長的樣本權重較大，包含休息與可確認的暫停，不任意排除極端值。</p><p>僅採明確保存的 Ridgewise 本機錄製，來源未獨立驗證；只涵蓋實際 GPS 端點之間，不代表走完路線全程。</p>${result.groups.length ? `<ul>${result.groups.map((group) => `<li>路線 ${esc(group.routeId)} · ${group.direction === 'reverse' ? '反向' : '原向'}：${group.sampleCount} 筆，基準 ${duration(group.totalBaselineSeconds)}</li>`).join('')}</ul>` : ''}<p>排除 ${result.excludedSamples.length} 筆歷史候選${names.size ? '（同一筆可能有多個原因）' : '。'}</p>${names.size ? `<ul>${[...names].map(([reason, count]) => `<li>${esc(personalFactorReason(reason))}：${count} 筆</li>`).join('')}</ul>` : ''}</div>`;
    } catch {
      if (!disposed && ticket === revision && document.getElementById(root.id) === root)
        root.querySelector('[role="status"]').innerHTML =
          '<strong class="personal-factor-value">—</strong><p>無法讀取或驗證歷史資料，暫不提供個人倍率。</p>';
    } finally {
      if (ticket === revision && document.getElementById(root.id) === root)
        root.removeAttribute('aria-busy');
    }
  }
  return {
    panel,
    refresh,
    dispose() {
      disposed = true;
      revision++;
    },
  };
}
