import {
  openGpxStore,
  gpxStoreAction,
  draftAction,
  finishRecordingStore,
  removePersonalHistoryStore,
} from './database.js';
// This is the only storage interface consumed by feature controllers.
export function createGpxRepository() {
  let database = null;
  function requireDatabase() {
    if (!database) throw new Error('本機資料庫無法使用');
    return database;
  }
  return {
    get available() {
      return database !== null;
    },
    async open() {
      database = await openGpxStore();
    },
    listFiles: () => gpxStoreAction(requireDatabase(), 'getAll'),
    putFile: (file) => gpxStoreAction(requireDatabase(), 'put', file),
    removeFile: (id) => gpxStoreAction(requireDatabase(), 'delete', id),
    getRouteDirections: () => draftAction(requireDatabase(), 'get', 'route-directions'),
    saveRouteDirections: (value) =>
      draftAction(requireDatabase(), 'put', { ...value, slot: 'route-directions' }),
    getResources: () => draftAction(requireDatabase(), 'get', 'route-resources'),
    saveResources: (value) =>
      draftAction(requireDatabase(), 'put', { ...value, slot: 'route-resources' }),
    getDraft: () => draftAction(requireDatabase(), 'get'),
    saveDraft: (snapshot) => draftAction(requireDatabase(), 'put', snapshot),
    deleteDraft: () => draftAction(requireDatabase(), 'delete'),
    finishRecording: (file) => finishRecordingStore(requireDatabase(), file),
    removePersonalHistory: (id) => removePersonalHistoryStore(requireDatabase(), id),
    close() {
      database?.close();
      database = null;
    },
  };
}
