import { GPX_MAX_BYTES, parseGpx } from './parser.js';
import { createTimeSourceController } from './time-source-controller.js';
export function createLibraryController({
  state,
  repository,
  gpsPending,
  render,
  navigate,
  feedback,
}) {
  const { toast } = feedback;
  async function importFiles(files) {
    if (state.importing || state.loading) return;
    const batch = Array.from(files);
    if (!batch.length) return;
    state.importing = true;
    state.results = [];
    navigate('routes');
    if (batch.length > 20) {
      state.results = [
        { ok: false, name: '未匯入', message: '一次最多加入 20 個檔案，請分批匯入。' },
      ];
      state.importing = false;
      render();
      return;
    }
    for (const file of batch) {
      try {
        if (!/\.gpx$/i.test(file.name)) throw new Error('請選擇副檔名為 .gpx 的檔案。');
        if (file.size > GPX_MAX_BYTES) throw new Error('超過 10 MB，請先分割檔案。');
        const raw = await file.text();
        if (state.library.some((entry) => entry.kind !== 'recording' && entry.raw === raw)) {
          state.results.push({
            ok: true,
            name: file.name,
            message: '相同內容已匯入，保留原有檔案。',
          });
          continue;
        }
        const parsed = parseGpx(raw, file.name);
        const record = { id: crypto.randomUUID(), raw, fileName: file.name, addedAt: Date.now() };
        const entry = { ...record, ...parsed, saved: false };
        if (repository.available) {
          try {
            await repository.putFile(record);
            entry.saved = true;
          } catch {
            state.storageError = '本機儲存失敗，未保存的檔案僅留在此分頁，請保留原始 GPX。';
          }
        }
        state.library.push(entry);
        if (!state.selected) state.selected = entry.id;
        state.results.push({
          ok: true,
          name: file.name,
          message: entry.saved ? '匯入完成，已保存在此瀏覽器。' : '匯入完成，僅此分頁可用。',
        });
      } catch (error) {
        state.results.push({
          ok: false,
          name: file.name,
          message: error.message || '檔案無法讀取。',
        });
      }
      render();
    }
    state.importing = false;
    render();
    toast('匯入處理完成，請查看各檔案的結果。');
  }
  async function removeFile(id) {
    if (state.timeSourceBusy) {
      toast('請等待來源設定保存完成。');
      return;
    }
    if (gpsPending() && id === state.gps.sourceRouteId) return;
    const file = state.library.find((entry) => entry.id === id);
    if (!file) return;
    if (file.saved) {
      try {
        await repository.removeFile(id);
      } catch {
        toast('移除失敗，請稍後重試。');
        return;
      }
    }
    state.library = state.library.filter((entry) => entry.id !== id);
    if (id === state.selected)
      state.selected = state.library.find((entry) => entry.kind !== 'recording')?.id ?? null;
    feedback.close();
    render();
    toast(
      file.kind === 'recording'
        ? '已移除此瀏覽器中的錄製 GPX；如有先前下載的備份，可重新匯入。'
        : '已移除此瀏覽器內的 GPX 副本，裝置上另外保存的來源檔不受影響。',
    );
  }
  function selectFile(id) {
    if (gpsPending()) {
      toast('請先完成並關閉 GPS 紀錄，再更換路線。');
      return;
    }
    if (!state.library.some((entry) => entry.id === id)) return;
    state.correctionPage = null;
    state.timeSourceError = '';
    state.selected = id;
    navigate('plan');
  }
  return {
    importFiles,
    removeFile,
    selectFile,
    ...createTimeSourceController({ state, repository, gpsPending, render, feedback, selectFile }),
  };
}
