export function createMapActions({ state, map, render, offlineMaps }) {
  return {
    'map-mode': (target) => {
      if (['standard', 'terrain', 'plain'].includes(target.dataset.mode)) {
        state.mapMode = target.dataset.mode;
        render();
      }
    },
    'offline-download': () => offlineMaps.download(),
    'offline-cancel': () => offlineMaps.cancel(),
    'offline-delete': () => offlineMaps.remove(),
    'map-fit': map.fit,
    'map-retry': map.retry,
    'map-rotate': (target) => map.rotate(Number(target.dataset.angle)),
    'map-north': map.north,
  };
}
