import { icon } from './icons.js';
export const esc = (value) =>
  String(value).replace(
    /[&<>"']/g,
    (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
export const button = (label, action, kind = '', ic = '', extra = '') =>
  `<button class="button ${kind}" data-action="${action}" ${extra}>${ic ? icon(ic) : ''}${label}</button>`;
export const metric = (label, value, unit = '', ic = '') =>
  `<div class="stat"><div class="stat-label">${ic ? icon(ic) : ''}${label}</div><div class="stat-value">${value}<small>${unit}</small></div></div>`;
export const meters = (value) => (value === null ? '—' : Math.round(value).toLocaleString());
export { icon };
